    function warehouse_stock($warehouse = NULL) {
        $this->sma->checkPermissions('warehouse-stock-report', TRUE);
        $data['error'] = (validation_errors()) ? validation_errors() : $this->session->flashdata('error');
        if ($this->input->get('warehouse')) {
            $warehouse = $this->input->get('warehouse');
        }

        $this->data['stock'] = $warehouse ? $this->reports_model->getWarehouseStockValue($warehouse) : $this->reports_model->getStockValue();
        $this->data['warehouses'] = $this->site->getAllWarehouses();
        $this->data['warehouse_id'] = $warehouse;
        $this->data['warehouse'] = $warehouse ? $this->site->getWarehouseByID($warehouse) : NULL;
        $this->data['totals'] = $this->reports_model->getWarehouseTotals($warehouse);
        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => '#', 'page' => lang('reports')));
        $meta = array('page_title' => lang('reports'), 'bc' => $bc);
        $this->page_construct('reports/warehouse_stock', $meta, $this->data);
    }

    function expiry_alerts($warehouse_id = NULL) {
        $this->sma->checkPermissions('expiry_alerts');
        $this->data['error'] = (validation_errors()) ? validation_errors() : $this->session->flashdata('error');

        if ($this->Owner || $this->Admin || !$this->session->userdata('warehouse_id')) {
            $this->data['warehouses'] = $this->site->getAllWarehouses();
            $this->data['warehouse_id'] = $warehouse_id;
            $this->data['warehouse'] = $warehouse_id ? $this->site->getWarehouseByID($warehouse_id) : NULL;
        } else {
            $user = $this->site->getUser();
            $this->data['warehouses'] = $this->site->getAllWarehouses();
            $this->data['warehouse_id'] = ($warehouse_id == NULL) ? $this->session->userdata('warehouse_id') : $warehouse_id;

            $this->data['warehouse'] = $user->warehouse_id ? $this->site->getWarehouseByID($warehouse_id) : NULL;
        }

        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('product_expiry_alerts')));
        $meta = array('page_title' => lang('product_expiry_alerts'), 'bc' => $bc);
        $this->page_construct('reports/expiry_alerts', $meta, $this->data);
    }

    function getExpiryAlerts($warehouse_id = NULL, $pdf = NULL, $xls = NULL, $img = NULL) {
        $this->sma->checkPermissions('expiry_alerts', TRUE);
        $date = date('Y-m-d', strtotime('+3 months'));

        if (!$this->Owner && !$warehouse_id) {
            $user = $this->site->getUser();
            $warehouse_id = $user->warehouse_id;
        }
        if ($pdf || $xls || $img) {
            // --- DATA QUERY ---
            if ($warehouse_id) {
                $getwarehouse = str_replace("_", ",", $warehouse_id);
                $this->db->select("
                    image,
                    product_code,
                    product_name,
                    product_variants.name as variants,
                    " . (($this->Settings->product_batch_setting == 1 || $this->Settings->product_batch_setting == 2) ? "batch_number," : "") . "
                    quantity_balance,
                    warehouses.name,
                    expiry
                ", FALSE)
                ->from('purchase_items')
                ->join('products', 'products.id=purchase_items.product_id', 'left')
                ->join('warehouses', 'warehouses.id=purchase_items.warehouse_id', 'left')
                ->join('product_variants', 'product_variants.id=purchase_items.option_id', 'left')
                ->where('warehouse_id IN(' . $getwarehouse . ')')
                ->where('expiry !=', NULL)
                ->where('expiry !=', '0000-00-00')
                ->where('expiry <', $date);
            } else {
                $this->db->select("
                    image,
                    product_code,
                    product_name,
                    product_variants.name as variants,
                    " . (($this->Settings->product_batch_setting == 1 || $this->Settings->product_batch_setting == 2) ? "batch_number," : "") . "
                    quantity_balance,
                    warehouses.name,
                    expiry
                ", FALSE)
                ->from('purchase_items')
                ->join('products', 'products.id=purchase_items.product_id', 'left')
                ->join('warehouses', 'warehouses.id=purchase_items.warehouse_id', 'left')
                ->join('product_variants', 'product_variants.id=purchase_items.option_id', 'left')
                ->where('expiry !=', NULL)
                ->where('expiry !=', '0000-00-00')
                ->where('expiry <', $date);
            }
            $q = $this->db->get();
            $data = ($q->num_rows() > 0) ? $q->result() : NULL;
        
            // --- EXCEL / PDF EXPORT ---
            if (!empty($data)) {
                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);
                $sheet = $this->excel->getActiveSheet();
        
                $sheet->setTitle(lang('product_expiry_alerts'));
                $sheet->mergeCells('A1:G1');
                $sheet->SetCellValue('A1', 'Product Expiry Alerts (All Warehouses)');

                $sheet->getStyle('A1')->applyFromArray([
                    'alignment' => [
                        'horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,
                    ],
                    'font' => [
                        'color' => ['rgb' => 'FF0000'], // Red
                        'bold'  => true,
                        'size'  => 14,
                    ],
                ]);
                // === Dynamic Column Headers ===
                $col = 'A';
                $sheet->SetCellValue($col++ . '2', lang('product_code'));
                $sheet->SetCellValue($col++ . '2', lang('product_name'));
                $sheet->SetCellValue($col++ . '2', lang('variants'));
        
                $show_batch = ($this->Settings->product_batch_setting == 1 || $this->Settings->product_batch_setting == 2);
                if ($show_batch) {
                    $sheet->SetCellValue($col++ . '2', lang('batch_no'));
                }
        
                $sheet->SetCellValue($col++ . '2', lang('quantity'));
                $sheet->SetCellValue($col++ . '2', lang('warehouse'));
                $sheet->SetCellValue($col++ . '2', lang('expiry'));
        
                // === Fill Data Rows ===
                $row = 3;
                $total_qty = 0; // accumulate overall quantity for totals row
                foreach ($data as $d) {
                    $col = 'A';
                    $cell = $col . $row;

                    // Force product code as text + left align
                    $sheet->setCellValueExplicit($cell, $d->product_code, PHPExcel_Cell_DataType::TYPE_STRING);
                    $sheet->getStyle($cell)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);

                    $col++;

                    $sheet->getStyle('A1')->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);
                    $sheet->SetCellValue($col++ . $row, $d->product_name);
                    $sheet->SetCellValue($col++ . $row, $d->variants);
        
                    if ($show_batch) {
                        $sheet->setCellValueExplicit($col . $row, ($d->batch_number ?: ''), PHPExcel_Cell_DataType::TYPE_STRING);
                        $sheet->getStyle($col . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                        $col++;
                    }
        
                    $cell = $col . $row;
                    $qty_val = (float)$d->quantity_balance;
                    $total_qty += $qty_val;
                    $sheet->SetCellValue($cell, $this->sma->formatQuantity($qty_val));
                    $sheet->getStyle($cell)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                    $col++;
                    $sheet->SetCellValue($col++ . $row, $d->name);
                    $sheet->SetCellValue($col++ . $row, $d->expiry);
                    $row++;
                }

                // === Totals Row (show overall quantity at end of quantity column) ===
                // Determine the quantity column letter based on whether batch number column is shown.
                $qtyColumnLetter = $show_batch ? 'E' : 'D';
                $sheet->SetCellValue($qtyColumnLetter . $row, 'Total = ' . $this->sma->formatQuantity($total_qty));
                $sheet->getStyle($qtyColumnLetter . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                // Make totals row text bold for emphasis
                $sheet->getStyle($qtyColumnLetter . $row)->getFont()->setBold(true);
        
                // === Column Widths ===
                $sheet->getColumnDimension('A')->setWidth(25);
                $sheet->getColumnDimension('B')->setWidth(35);
                $sheet->getColumnDimension('C')->setWidth(25);
                if ($show_batch) $sheet->getColumnDimension('D')->setWidth(20);
                $sheet->getColumnDimension($show_batch ? 'E' : 'D')->setWidth(15);
                $sheet->getColumnDimension($show_batch ? 'F' : 'E')->setWidth(20);
                $sheet->getColumnDimension($show_batch ? 'G' : 'F')->setWidth(20);
        
                $filename = 'product_expiry_alerts';
                $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);
                $lastColumn = $sheet->getHighestColumn();
                $lastRow    = $sheet->getHighestRow();
                // === PDF / XLS / IMG Export Blocks (same as before) ===
                if ($pdf) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    // $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $sheet->getStyle('A2:' . $lastColumn . $lastRow)->applyFromArray(['borders' => ['allborders' => ['style' => PHPExcel_Style_Border::BORDER_THIN]]]);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . 'MPDF';
                    PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath);
                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');
                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($xls) {
                    ob_clean();
                    header('Content-Type: application/vnd.ms-excel');
                    header('Content-Disposition: attachment;filename="' . $filename . '.xls"');
                    header('Cache-Control: max-age=0');
                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($img) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    // $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $sheet->getStyle('A2:' . $lastColumn . $lastRow)->applyFromArray(['borders' => ['allborders' => ['style' => PHPExcel_Style_Border::BORDER_THIN]]]);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . 'MPDF';
                    PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath);
                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');
                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save(str_replace(__FILE__, 'assets/mdata/'.$this->Customer_assets.'/uploads/pdf/product_expiry_alerts.pdf', __FILE__));
                    redirect("reports/create_image/product_expiry_alerts.pdf");
                    exit();
                }
            }
        
            // --- No data found ---
            $this->session->set_flashdata('error', lang('nothing_found'));
            redirect($_SERVER["HTTP_REFERER"]);
        }
         else {
            $this->load->library('datatables');
            $show_batch = ($this->data['Settings']->product_batch_setting == 1 ||
            $this->data['Settings']->product_batch_setting == 2);

            if ($warehouse_id) {
                $getwarehouse = str_replace("_", ",", $warehouse_id);
            }

            $select = "
                products.image AS image,
                purchase_items.product_code,
                purchase_items.product_name,
                product_variants.name AS variants,
            ";

            if ($show_batch) {
                // fetch batch only when enabled
                $select .= "purchase_items.batch_number AS batch_number,";
            }

            $select .= "
                purchase_items.quantity_balance,
                warehouses.name AS warehouse,
                purchase_items.expiry
            ";

            $this->datatables->select($select, FALSE)
                ->from('purchase_items')
                ->join('products', 'products.id=purchase_items.product_id', 'left')
                ->join('warehouses', 'warehouses.id=purchase_items.warehouse_id', 'left')
                ->join('product_variants', 'product_variants.id=purchase_items.option_id', 'left')
                ->where('purchase_items.expiry IS NOT NULL')
                ->where('purchase_items.expiry !=', '0000-00-00')
                ->where('purchase_items.expiry <', $date);

            if ($warehouse_id) {
                $this->datatables->where("purchase_items.warehouse_id IN($getwarehouse)");
            }
            echo $this->datatables->generate();
        }
    }

