     function quantity_alerts($warehouse_id = NULL) {
        $this->sma->checkPermissions('quantity_alerts');
        $this->data['error'] = (validation_errors()) ? validation_errors() : $this->session->flashdata('error');

        if ($this->Owner || $this->Admin || !$this->session->userdata('warehouse_id')) {
            $this->data['warehouses'] = $this->site->getAllWarehouses();
            $this->data['warehouse_id'] = $warehouse_id;
            $this->data['warehouse'] = $warehouse_id ? $this->site->getWarehouseByID($warehouse_id) : NULL;
        } else {
            $user = $this->site->getUser();
            $this->data['warehouses'] = $this->site->getAllWarehouses();
            $this->data['warehouse_id'] = ($warehouse_id == NULL) ? $user->warehouse_id : $warehouse_id;
            $this->data['warehouse'] = $user->warehouse_id ? $this->site->getWarehouseByID($warehouse_id) : NULL;
        }
        // Load suppliers
        $this->load->model('companies_model');
        // $this->data['suppliers'] = $this->companies_model->getAllSupplierCompanies('supplier');
        $this->data['suppliers'] = $this->site->getAllCompanies('supplier');

        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('product_quantity_alerts')));
        $meta = array('page_title' => lang('product_quantity_alerts'), 'bc' => $bc);
        $this->page_construct('reports/quantity_alerts', $meta, $this->data);
    }

    function getQuantityAlerts($warehouse_id = NULL, $pdf = NULL, $xls = NULL, $img = NULL) {
        $this->sma->checkPermissions('quantity_alerts', TRUE);
        if (!$this->Owner && !$warehouse_id) {
            $user = $this->site->getUser();
            $warehouse_id = $user->warehouse_id;
        }
        $warehouse_id = $this->input->get('warehouse') ? $this->input->get('warehouse') : $warehouse_id; 
        $stock_alert = $this->input->get('stock_alert') ? $this->input->get('stock_alert') : NULL;
        $supplier_id = $this->input->get('supplier') ? $this->input->get('supplier') : NULL;
        // Cast supplier_id to integer for safety (company ID)
        $supplier_id_int = $supplier_id ? (int) $supplier_id : NULL;
        
        // Get selected items for export (if any checkboxes were selected)
        $selected_items_json = $this->input->get('selected_items');
        $selected_items = NULL;
        if ($selected_items_json) {
            $selected_items = json_decode($selected_items_json, TRUE);
            if (!is_array($selected_items) || empty($selected_items)) {
                $selected_items = NULL;
            }
        }
        if ($pdf || $xls || $img) { 

            // if ($warehouse_id) {
            //     $getwarehouse = str_replace("_", ",", $warehouse_id);

            //     $warehouse_name = $this->site->getWarehouseByID($getwarehouse);

            //     $this->db->select('products.image as image, products.code, products.name,sma_product_variants.name AS variant_name, products.alert_quantity, warehouses_products.quantity')
            //     ->from('products')
            //     ->join('warehouses_products', 'warehouses_products.product_id=products.id', 'left')
            //     ->join('sma_categories', 'sma_categories.id = products.category_id', 'left')
            //     ->where('alert_quantity > warehouses_products.quantity', NULL)
            //     ->where('warehouse_id IN (' . $getwarehouse . ')')
            //     ->where('track_quantity', 1)
            //     ->order_by('products.code desc');
            // } else {
            //     $this->db->select('products.image, products.code, products.name,sma_product_variants.name AS variant_name, products.alert_quantity, sma_product_variants.quantity')
            //     ->from('products')
            //     ->join('sma_categories', 'sma_categories.id = products.category_id', 'left')
            //     ->join('sma_product_variants', 'sma_product_variants.product_id = products.id', 'left') // Use products.id
            //     ->where('alert_quantity > quantity', NULL)
            //     ->where('track_quantity', 1)
            //     ->order_by('code desc');
            // }

            // $q = $this->db->get();
            if ($warehouse_id) {
                $getwarehouse = str_replace("_", ",", $warehouse_id);
                
                // Query to show products with and without variants
                // Column order must match JavaScript expectations: 0=product_id, 1=image, 2=code, 3=category, 4=product_name, 5=variant_name, 6=supplier_name, 7=alert_qty, 8=stock_qty, 9=variant_id
                // Business Logic: Products have supplier1, supplier2, supplier3, supplier4, supplier5 fields
                // We use supplier1 as the primary supplier for display purposes
                $select = "sma_products.id AS product_id,
                    sma_products.image AS image, 
                    sma_products.code AS code, 
                    sma_categories.name AS category_name, 
                    CONCAT(sma_products.name, ' (', IFNULL(sma_units.name, ''), ')') AS product_name, 
                    IFNULL(sma_product_variants.name, '') AS variant_name,
                    IFNULL(sma_companies.name, '') AS supplier_name,
                    sma_products.alert_quantity AS product_alert_quantity, 
                    COALESCE(sma_warehouses_products_variants.quantity, sma_warehouses_products.quantity, 0) AS total_variant_quantity,
                    IFNULL(sma_product_variants.id, 0) AS variant_id";

                $this->db->select($select, FALSE)
                    ->from('sma_products')
                    ->join('sma_categories', 'sma_categories.id = sma_products.category_id', 'left')
                    ->join('sma_companies', 'sma_companies.id = sma_products.supplier1', 'left')
                    // Only variants with group_id = 1
                    ->join(
                        'sma_product_variants',
                        'sma_product_variants.product_id = sma_products.id 
                         AND sma_product_variants.group_id = 1',
                        'left'
                    )
                    ->join(
                        'sma_warehouses_products_variants',
                        'sma_warehouses_products_variants.option_id = sma_product_variants.id 
                         AND sma_warehouses_products_variants.warehouse_id IN (' . $getwarehouse . ')',
                        'left',
                        FALSE
                    )
                    ->join(
                        'sma_warehouses_products',
                        'sma_warehouses_products.product_id = sma_products.id 
                         AND sma_warehouses_products.warehouse_id IN (' . $getwarehouse . ')',
                        'left',
                        FALSE
                    )
                    ->join('sma_units', 'sma_units.id = sma_products.unit', 'left');
                $this->db->where('sma_products.track_quantity', 1)
                    ->where('sma_products.alert_quantity >', 0)
                    // Only show products that have stock records in the selected location
                    ->where('(sma_warehouses_products_variants.warehouse_id IS NOT NULL OR sma_warehouses_products.warehouse_id IS NOT NULL)', NULL, FALSE);
                
                // Add supplier filter if provided
                // Business Logic: Filter by any of the 5 supplier fields (supplier1..supplier5)
                if ($supplier_id_int) {
                    $supplier_where = "(sma_products.supplier1 = {$supplier_id_int}"
                                    . " OR sma_products.supplier2 = {$supplier_id_int}"
                                    . " OR sma_products.supplier3 = {$supplier_id_int}"
                                    . " OR sma_products.supplier4 = {$supplier_id_int}"
                                    . " OR sma_products.supplier5 = {$supplier_id_int})";
                    $this->db->where($supplier_where, NULL, FALSE);
                }
                
                // Add selected items filter if checkboxes were selected
                if ($selected_items && is_array($selected_items)) {
                    $item_conditions = array();
                    foreach ($selected_items as $item) {
                        $product_id = isset($item['product_id']) ? (int)$item['product_id'] : 0;
                        $variant_id = isset($item['variant_id']) ? (int)$item['variant_id'] : 0;
                        
                        if ($product_id > 0) {
                            if ($variant_id > 0) {
                                // Product with variant
                                $item_conditions[] =
                                    "(sma_products.id = {$product_id} 
                                    AND IFNULL(sma_product_variants.id, 0) = {$variant_id})";
                            } else {
                                // Product without variant
                                $item_conditions[] =
                                    "(sma_products.id = {$product_id} 
                                    AND IFNULL(sma_product_variants.id, 0) = 0)";
                            }
                        }
                    }
                    
                    if (!empty($item_conditions)) {
                        $items_where = "(" . implode(" OR ", $item_conditions) . ")";
                        $this->db->where($items_where, NULL, FALSE);
                    }
                }
                
                // Show all products with alert quantity (no stock filtering)
                
                $this->db->group_by('sma_product_variants.id');
            } else {
                $select = "sma_products.id AS product_id, sma_products.code AS code, sma_categories.name AS category_name, CONCAT(sma_products.name, ' (', IFNULL(sma_units.name, ''), ')') AS product_name, sma_product_variants.name AS variant_name,IFNULL(sc.name, '') AS supplier_name, sma_products.alert_quantity AS product_alert_quantity, COALESCE(sma_product_variants.quantity, sma_products.quantity, 0) AS total_variant_quantity";

                $this->db->select($select, FALSE)
                    ->from('sma_products')
                    ->join('sma_categories', 'sma_categories.id = sma_products.category_id', 'left')
                    ->join('sma_product_variants', 'sma_product_variants.product_id = sma_products.id AND sma_product_variants.group_id = 1', 'left')
                    ->join(
                        'sma_purchase_items',
                        'sma_purchase_items.product_id = products.id
                        AND sma_purchase_items.option_id = sma_product_variants.id',
                        'left'
                    )
                    ->join(
                        'sma_companies sc',
                        'sc.id = CASE
                            WHEN sma_products.supplier1 = ' . (int)$supplier_id_int . ' THEN sma_products.supplier1
                            WHEN sma_products.supplier2 = ' . (int)$supplier_id_int . ' THEN sma_products.supplier2
                            WHEN sma_products.supplier3 = ' . (int)$supplier_id_int . ' THEN sma_products.supplier3
                            WHEN sma_products.supplier4 = ' . (int)$supplier_id_int . ' THEN sma_products.supplier4
                            WHEN sma_products.supplier5 = ' . (int)$supplier_id_int . ' THEN sma_products.supplier5
                            ELSE sma_products.supplier1
                        END',
                        'left',
                        FALSE
                    )
                    ->join('sma_units', 'sma_units.id = sma_products.unit', 'left');
                $this->db->where('sma_products.track_quantity', 1)
                    ->where('sma_products.alert_quantity >', 0);

                // Add supplier filter if provided
                // Business Logic: Filter by any of the 5 supplier fields (supplier1..supplier5)
                if ($supplier_id_int) {
                    $supplier_where = "(sma_products.supplier1 = {$supplier_id_int}"
                                    . " OR sma_products.supplier2 = {$supplier_id_int}"
                                    . " OR sma_products.supplier3 = {$supplier_id_int}"
                                    . " OR sma_products.supplier4 = {$supplier_id_int}"
                                    . " OR sma_products.supplier5 = {$supplier_id_int})";
                    $this->db->where($supplier_where, NULL, FALSE);
                }
                
                // Add selected items filter if checkboxes were selected
                if ($selected_items && is_array($selected_items)) {
                    $item_conditions = array();
                    foreach ($selected_items as $item) {
                        $product_id = isset($item['product_id']) ? (int)$item['product_id'] : 0;
                        $variant_id = isset($item['variant_id']) ? (int)$item['variant_id'] : 0;
                        
                        if ($product_id > 0) {
                            if ($variant_id > 0) {
                                // Product with variant
                                $item_conditions[] = "(sma_products.id = {$product_id} AND IFNULL(sma_product_variants.id, 0) = {$variant_id})";
                            } else {
                                // Product without variant
                                $item_conditions[] = "(sma_products.id = {$product_id} AND IFNULL(sma_product_variants.id, 0) = 0)";
                            }
                        }
                    }
                    
                    if (!empty($item_conditions)) {
                        $items_where = "(" . implode(" OR ", $item_conditions) . ")";
                        $this->db->where($items_where, NULL, FALSE);
                    }
                }
                
                // Show all products with alert quantity (no stock filtering)
                
                $this->db->group_by('sma_products.id, sma_product_variants.id');
            }

            $q = $this->db->get();
            if ($q->num_rows() > 0) {
                foreach (($q->result()) as $row) {
                    $data[] = $row;
                }
            } else {
                $data = NULL;
            }

            if (!empty($data)) {
                $report_name = 'Product Quantity Alerts (' . (isset($warehouse_name) ? $warehouse_name[$getwarehouse]->name : "All Warehouses") . ')';
                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);
                $style = array('alignment' => array('horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,), 'font' => array('name' => 'Arial', 'color' => array('rgb' => 'FF0000')), 'borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_NONE, 'color' => array('rgb' => 'FF0000'))));

                // Title
                $this->excel->getActiveSheet()->getStyle("A1:G1")->applyFromArray($style);

                // Base headers
                $colA = 'A';
                $this->excel->getActiveSheet()->SetCellValue($colA++ . '2', lang('product_code'));
                $this->excel->getActiveSheet()->SetCellValue($colA++ . '2', lang('Category_Name'));
                $this->excel->getActiveSheet()->SetCellValue($colA++ . '2', lang('product_name'));
                $this->excel->getActiveSheet()->SetCellValue($colA++ . '2', lang('Variant_Name'));
                $this->excel->getActiveSheet()->SetCellValue($colA++ . '2', lang('supplier'));
                $this->excel->getActiveSheet()->SetCellValue($colA++ . '2', lang('alert_quantity'));
                $this->excel->getActiveSheet()->SetCellValue($colA++ . '2', lang('quantity'));

                $totalAlertQty  = 0;
                $totalStockQty  = 0;

                $row = 3;

                foreach ($data as $data_row) {
                    // Code (Left Align)
                    $this->excel->getActiveSheet()->SetCellValue('A' . $row, $data_row->code);
                    $this->excel->getActiveSheet()->getStyle('A' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    // Category Name (Left Align)
                    $this->excel->getActiveSheet()->SetCellValue('B' . $row, $data_row->category_name);
                    $this->excel->getActiveSheet()->getStyle('B' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    // Product Name (Left Align)
                    $this->excel->getActiveSheet()->SetCellValue('C' . $row, $data_row->product_name);
                    $this->excel->getActiveSheet()->getStyle('C' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    // Variant Name (Left Align)
                    $this->excel->getActiveSheet()->SetCellValue('D' . $row, $data_row->variant_name);
                    $this->excel->getActiveSheet()->getStyle('D' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    // Supplier Name (Left Align)
                    $this->excel->getActiveSheet()->SetCellValue('E' . $row, $data_row->supplier_name);
                    $this->excel->getActiveSheet()->getStyle('E' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    // Product Alert Quantity (Right Align and Quantity Formatting as STRING)
                    $formattedQty = $this->sma->formatQuantity($data_row->product_alert_quantity);
                    $this->excel->getActiveSheet()->setCellValueExplicit('F' . $row, $formattedQty, PHPExcel_Cell_DataType::TYPE_STRING);
                    $this->excel->getActiveSheet()->getStyle('F' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                
                    // Total Variant Quantity (Right Align and Quantity Formatting as STRING)
                    $formattedTotalQty = $this->sma->formatQuantity($data_row->total_variant_quantity);
                    $this->excel->getActiveSheet()->setCellValueExplicit('G' . $row, $formattedTotalQty, PHPExcel_Cell_DataType::TYPE_STRING);
                    $this->excel->getActiveSheet()->getStyle('G' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                    $totalAlertQty += (float)$data_row->product_alert_quantity;
                    $totalStockQty += (float)$data_row->total_variant_quantity;

                    $row++;
                }
                // TOTAL ROW
                $this->excel->getActiveSheet()->mergeCells("A{$row}:E{$row}");
                $this->excel->getActiveSheet()->SetCellValue("A{$row}", 'TOTAL');
                $this->excel->getActiveSheet()->getStyle("A{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                // TOTAL Alert Quantity (Column F)
                $formattedTotalAlert = $this->sma->formatQuantity($totalAlertQty);
                $this->excel->getActiveSheet()->setCellValueExplicit(
                    "F{$row}",
                    $formattedTotalAlert,
                    PHPExcel_Cell_DataType::TYPE_STRING
                );
                $this->excel->getActiveSheet()->getStyle("F{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);

                // TOTAL Stock Quantity (Column G)
                $formattedTotalStock = $this->sma->formatQuantity($totalStockQty);
                $this->excel->getActiveSheet()->setCellValueExplicit(
                    "G{$row}",
                    $formattedTotalStock,
                    PHPExcel_Cell_DataType::TYPE_STRING
                );
                $this->excel->getActiveSheet()->getStyle("G{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);

                // Make TOTAL row bold
                $this->excel->getActiveSheet()->getStyle("A{$row}:G{$row}")
                    ->getFont()->setBold(true);

                $row++;


                $this->excel->getActiveSheet()->getColumnDimension('A')->setWidth(35);
                $this->excel->getActiveSheet()->getColumnDimension('B')->setWidth(35);
                $this->excel->getActiveSheet()->getColumnDimension('C')->setWidth(25);
                $this->excel->getActiveSheet()->getColumnDimension('D')->setWidth(25);
                $this->excel->getActiveSheet()->getColumnDimension('E')->setWidth(25);
                $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN,'color' => array('rgb' => '000000'))));
                $lastRow = $row - 1;
                $this->excel->getActiveSheet()->getStyle("A2:G{$lastRow}")->applyFromArray($styleArray);

                $filename = 'product_quantity_alerts';
                $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);
                if ($pdf) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($xls) {
                    ob_clean();
                    header('Content-Type: application/vnd.ms-excel');
                    header('Content-Disposition: attachment;filename="' . $filename . '.xls"');
                    header('Cache-Control: max-age=0');
                    ob_clean();
                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($img) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save(str_replace(__FILE__, 'assets/uploads/pdf/product_quantity_alerts.pdf', __FILE__));
                    redirect("reports/create_image/product_quantity_alerts.pdf");
                    exit();
                }
            }
            $this->session->set_flashdata('error', lang('nothing_found'));
            redirect($_SERVER["HTTP_REFERER"]);
        } else {
            $this->load->library('datatables');
            if ($warehouse_id) {

                $getwarehouse = str_replace("_", ",", $warehouse_id);
                
                // Query to show products with and without variants
                // Column order must match JavaScript expectations: 0=product_id, 1=image, 2=code, 3=category, 4=product_name, 5=variant_name, 6=supplier_name, 7=alert_qty, 8=stock_qty, 9=variant_id
                // Business Logic: Products have supplier1, supplier2, supplier3, supplier4, supplier5 fields
                // We use supplier1 as the primary supplier for display purposes
                $select = "sma_products.id AS product_id,
                    sma_products.image AS image, 
                    sma_products.code AS code, 
                    sma_categories.name AS category_name, 
                    CONCAT(sma_products.name, ' (', IFNULL(sma_units.name, ''), ')') AS product_name, 
                    IFNULL(sma_product_variants.name, '') AS variant_name,
                    IFNULL(sma_companies.name, '') AS supplier_name,
                    sma_products.alert_quantity AS product_alert_quantity, 
                    COALESCE(sma_warehouses_products_variants.quantity, sma_warehouses_products.quantity, 0) AS total_variant_quantity,
                    IFNULL(sma_product_variants.id, 0) AS variant_id";

                $this->datatables->select($select, FALSE)
                    ->from('sma_products')
                    ->join('sma_categories', 'sma_categories.id = sma_products.category_id', 'left')
                    ->join('sma_companies', 'sma_companies.id = sma_products.supplier1', 'left')
                    // Only variants with group_id = 1
                    ->join(
                        'sma_product_variants',
                        'sma_product_variants.product_id = sma_products.id 
                         AND sma_product_variants.group_id = 1',
                        'left'
                    )
                    ->join(
                        'sma_warehouses_products_variants',
                        'sma_warehouses_products_variants.option_id = sma_product_variants.id 
                         AND sma_warehouses_products_variants.warehouse_id IN (' . $getwarehouse . ')',
                        'left',
                        FALSE
                    )
                    ->join(
                        'sma_warehouses_products',
                        'sma_warehouses_products.product_id = sma_products.id 
                         AND sma_warehouses_products.warehouse_id IN (' . $getwarehouse . ')',
                        'left',
                        FALSE
                    )
                ->join('sma_units', 'sma_units.id = sma_products.unit', 'left');
                $this->datatables->where('sma_products.track_quantity', 1)
                    ->where('sma_products.alert_quantity >', 0)
                    // Only show products that have stock records in the selected location
                    ->where('(sma_warehouses_products_variants.warehouse_id IS NOT NULL OR sma_warehouses_products.warehouse_id IS NOT NULL)', NULL, FALSE);
                
                // Add supplier filter if provided
                // Business Logic: Filter by any of the 5 supplier fields (supplier1..supplier5)
                if ($supplier_id_int) {
                    $supplier_where = "(sma_products.supplier1 = {$supplier_id_int}"
                                    . " OR sma_products.supplier2 = {$supplier_id_int}"
                                    . " OR sma_products.supplier3 = {$supplier_id_int}"
                                    . " OR sma_products.supplier4 = {$supplier_id_int}"
                                    . " OR sma_products.supplier5 = {$supplier_id_int})";
                    $this->datatables->where($supplier_where, NULL, FALSE);
                }
               
                // Group by to ensure each variant appears as a separate row
                $this->datatables->group_by('sma_products.id, sma_product_variants.id');
            }
            else {
                // Query to show products with and without variants
                // Column order must match JavaScript expectations: 0=product_id, 1=image, 2=code, 3=category, 4=product_name, 5=variant_name, 6=supplier_name, 7=alert_qty, 8=stock_qty, 9=variant_id
                // Business Logic: Products have supplier1, supplier2, supplier3, supplier4, supplier5 fields
                // We use supplier1 as the primary supplier for display purposes
                $select = "sma_products.id AS product_id,
                    sma_products.image AS image,
                    sma_products.code AS code,
                    sma_categories.name AS category_name,
                    CONCAT(sma_products.name, ' (', IFNULL(sma_units.name, ''), ')') AS product_name,
                    IFNULL(sma_product_variants.name, '') AS variant_name,
                    IFNULL(sma_companies.name, '') AS supplier_name,
                    sma_products.alert_quantity AS product_alert_quantity,
                    COALESCE(sma_product_variants.quantity, sma_products.quantity, 0) AS total_variant_quantity,
                    IFNULL(sma_product_variants.id, 0) AS variant_id";

                $this->datatables->select($select, FALSE)
                    ->from('sma_products')
                    ->join('sma_categories', 'sma_categories.id = sma_products.category_id', 'left')
                    ->join('sma_companies', 'sma_companies.id = sma_products.supplier1', 'left')
                    // Only use variants of group_id = 1 - LEFT JOIN to include products without variants
                    ->join(
                        'sma_product_variants',
                        'sma_product_variants.product_id = sma_products.id
                         AND sma_product_variants.group_id = 1',
                        'left'
                    )
                    ->join(
                        'sma_purchase_items',
                        'sma_purchase_items.product_id = sma_products.id
                        AND (
                                sma_purchase_items.option_id = sma_product_variants.id
                                OR sma_purchase_items.option_id IS NULL
                            )','left' )
                    ->join('sma_units', 'sma_units.id = sma_products.unit', 'left');

                $this->datatables->where('sma_products.track_quantity', 1)
                    ->where('sma_products.alert_quantity >', 0);
                
                // Add supplier filter if provided
                // Business Logic: Filter by any of the 5 supplier fields (supplier1..supplier5)
                if ($supplier_id_int) {
                    $supplier_where = "(sma_products.supplier1 = {$supplier_id_int}"
                                    . " OR sma_products.supplier2 = {$supplier_id_int}"
                                    . " OR sma_products.supplier3 = {$supplier_id_int}"
                                    . " OR sma_products.supplier4 = {$supplier_id_int}"
                                    . " OR sma_products.supplier5 = {$supplier_id_int})";
                    $this->datatables->where($supplier_where, NULL, FALSE);
                }

                // Group by to ensure each variant appears as a separate row
                $this->datatables->group_by('sma_products.id, sma_product_variants.id');
            }
            echo $this->datatables->generate();
        }
    }
    function suggestions() {
        $term = $this->input->get('term', TRUE);
        if (strlen($term) < 1) {
            die();
        }

        $rows = $this->reports_model->getProductNames($term);
        if ($rows) {
            foreach ($rows as $row) {
                $pr[] = array('id' => $row->id, 'label' => $row->name . " (" . $row->code . ")");
            }
            $this->sma->send_json($pr);
        } else {
            echo FALSE;
        }
    }

    public function best_sellers($warehouse_id = 0, $yr = null, $mmt = null) {
        $monthget = null;
        $wareget = $this->data['wareget'] = $this->uri->segment(3);
        $yearget = $this->data['yearget'] = $this->uri->segment(4);
        $monthget = $this->data['monthget'] = $this->uri->segment(5);

        $warehouse_id = $this->uri->segment(3);

        $this->sma->checkPermissions('products');

        $mt = ($mmt) ? $mmt + 1 : NULL;
        $mtla = ($mmt != 12) ? $mmt + 1 : 1; //use for last graph show 6/2/2020
        $y = date('Y');
        $this->data['error'] = (validation_errors() ? validation_errors() : $this->session->flashdata('error'));
        $y1 = ($yr) ? ($mt > 1 ? $yr : ( $yr - 1 ) ) : date('Y', strtotime('-1 month'));

        $m1 = ($mt) ? ($mt > 1 ? $mt - 1 : (12 + $mt) - 1 ) : date('m', strtotime('-1 month'));

        $month = $this->data['months'] = array(1 => 'Jan', 2 => 'Feb', 3 => 'Mar', 4 => 'Apr', 5 => 'May', 6 => 'Jun', 7 => 'Jul', 8 => 'Aug', 9 => 'Sep', 10 => 'Oct', 11 => 'Nov', 12 => 'Dec');
        $year = $this->data['years'] = array(1 => $y, 2 => ($y - 1));
        $m1sdate = $y1 . '-' . $m1 . '-01 00:00:00';
        $m1edate = $y1 . '-' . $m1 . '-' . days_in_month($m1, $y1) . ' 23:59:59';
        $this->data['m1'] = date('M Y', strtotime($y1 . '-' . $m1));
        $this->data['m1bs'] = $this->reports_model->getBestSeller($m1sdate, $m1edate, $warehouse_id, $monthget);
        $y2 = ($yr) ? ($mt > 2 ? $yr : ( $yr - 1 ) ) : date('Y', strtotime('-2 months'));
        $m2 = ($mt) ? ($mt > 2 ? $mt - 2 : (12 + $mt) - 2 ) : date('m', strtotime('-2 months'));
        $m2sdate = $y2 . '-' . $m2 . '-01 00:00:00';
        $m2edate = $y2 . '-' . $m2 . '-' . days_in_month($m2, $y2) . ' 23:59:59';
        $this->data['m2'] = date('M Y', strtotime($y2 . '-' . $m2));
        $this->data['m2bs'] = $this->reports_model->getBestSeller($m2sdate, $m2edate, $warehouse_id, $monthget);
        $y3 = ($yr) ? ($mt > 3 ? $yr : ( $yr - 1)) : date('Y', strtotime('-3 months'));
        $m3 = ($mt) ? ($mt > 3 ? $mt - 3 : (12 + $mt) - 3 ) : date('m', strtotime('-3 months'));
        $m3sdate = $y3 . '-' . $m3 . '-01 23:59:59';
        $this->data['m3'] = date('M Y', strtotime($y3 . '-' . $m3)) . ' - ' . $this->data['m1'];
        $this->data['m3bs'] = $this->reports_model->getBestSeller($m3sdate, $m1edate, $warehouse_id, $monthget);
        $y4 = ($yr) ? $yr - 1 : date('Y', strtotime('-12 months'));
        $m4 = ($mtla) ? $mtla : date('m', strtotime('-12 months'));
        $m4sdate = $y4 . '-' . $m4 . '-01 23:59:59';
        $this->data['m4'] = date('M Y', strtotime($y4 . '-' . $m4)) . ' - ' . $this->data['m1'];
        $this->data['m4bs'] = $this->reports_model->getBestSeller($m4sdate, $m1edate, $warehouse_id, $monthget);
        $this->data['warehouses'] = $this->site->getAllWarehouses();
        $this->data['warehouse'] = $warehouse_id ? $this->site->getWarehouseByID($warehouse_id) : NULL;
        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('best_sellers')));
        $meta = array('page_title' => lang('best_sellers'), 'bc' => $bc);
        $this->page_construct('reports/best_sellers', $meta, $this->data);
    }

    function products() {
        $this->sma->checkPermissions();
        $this->data['error'] = (validation_errors() ? validation_errors() : $this->session->flashdata('error'));
        $this->data['categories'] = $this->site->getAllCategories();
        $this->data['brands'] = $this->site->getAllBrands();
        $this->data['warehouses'] = $this->site->getAllWarehouses();
        if ($this->input->post('start_date')) {
            $dt = "From " . $this->input->post('start_date') . " to " . $this->input->post('end_date');
        } else {
            $dt = "Till " . $this->input->post('end_date');
        }
        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('products_report')));
        $meta = array('page_title' => lang('products_report'), 'bc' => $bc);
        $this->page_construct('reports/products', $meta, $this->data);
    }
    
    function getProductsReport($pdf = NULL, $xls = NULL, $img = NULL) {
        $this->sma->checkPermissions('products', TRUE);

        $product = $this->input->get('product') ? $this->input->get('product') : NULL;
        $category = $this->input->get('category') ? $this->input->get('category') : NULL;
        $brand = $this->input->get('brand') ? $this->input->get('brand') : NULL;
        $subcategory = $this->input->get('subcategory') ? $this->input->get('subcategory') : NULL;
        $warehouse = $this->input->get('warehouse') ? $this->input->get('warehouse') : NULL;
        $cf1 = $this->input->get('cf1') ? $this->input->get('cf1') : NULL;
        $cf2 = $this->input->get('cf2') ? $this->input->get('cf2') : NULL;
        $cf3 = $this->input->get('cf3') ? $this->input->get('cf3') : NULL;
        $cf4 = $this->input->get('cf4') ? $this->input->get('cf4') : NULL;
        $cf5 = $this->input->get('cf5') ? $this->input->get('cf5') : NULL;
        $cf6 = $this->input->get('cf6') ? $this->input->get('cf6') : NULL;
        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;
        $with_or_without_gst = $this->input->get('with_or_without_gst') ? $this->input->get('with_or_without_gst') : NULL;
        if ($pdf || $xls || $img) {

            $purchase_conditions = [];
            $sales_conditions = [];
            $product_conditions = [];
            $stock_conditions = [];
        
            // ------------------ FILTER HANDLING ------------------ //
            if ($start_date || $warehouse) {
                if ($start_date) {
                    $start_date = $this->sma->fld($start_date);
                    $end_date = $end_date ? $this->sma->fld($end_date) : date('Y-m-d');
                    $purchase_conditions[] = "DATE(pi.date) BETWEEN '{$start_date}' AND '{$end_date}'";
                    $sales_conditions[] = "DATE(s.date) BETWEEN '{$start_date}' AND '{$end_date}'";
                }
                if ($warehouse) {
                    $getwarehouse = str_replace("_", ",", $warehouse);
                    $purchase_conditions[] = "pi.warehouse_id IN ({$getwarehouse})";
                    $stock_conditions[] = "warehouse_id IN ({$getwarehouse})";
                    $sales_conditions[] = "si.warehouse_id IN ({$getwarehouse})";
        
                    $user = $this->site->getUser();
					
                    if (!$this->Owner && !$this->Admin && !$user->view_right) {
                        $purchase_conditions[] = "pu.created_by = " . $this->session->userdata('user_id');
                        $sales_conditions[] = "s.created_by = " . $this->session->userdata('user_id');
                    }
                }
            }
        
            // product filters
            // if ($this->data['Settings']->display_zero_sale_for_product_report == 0) {
            //     $product_conditions_sale = "AND PSales.soldQty != 0";
            // }
            if ($product) $product_conditions[] = "p.id = {$product}";
            if ($cf1) $product_conditions[] = "p.cf1 = '{$cf1}'";
            if ($cf2) $product_conditions[] = "p.cf2 = '{$cf2}'";
            if ($cf3) $product_conditions[] = "p.cf3 = '{$cf3}'";
            if ($cf4) $product_conditions[] = "p.cf4 = '{$cf4}'";
            if ($cf5) $product_conditions[] = "p.cf5 = '{$cf5}'";
            if ($cf6) $product_conditions[] = "p.cf6 = '{$cf6}'";
            if ($category) $product_conditions[] = "p.category_id = {$category}";
            if ($subcategory) $product_conditions[] = "p.subcategory_id = {$subcategory}";
            if ($brand) $product_conditions[] = "p.brand = {$brand}";
        
            // Combine filters
            $purchase_where = !empty($purchase_conditions) ? 'WHERE ' . implode(' AND ', $purchase_conditions) : '';
            $sales_where = !empty($sales_conditions) ? 'WHERE ' . implode(' AND ', $sales_conditions) : '';
            $product_where = !empty($product_conditions) ? 'WHERE ' . implode(' AND ', $product_conditions) : '';
        
            // ------------------ QUERY SELECTION ------------------ //
            $batch_enabled = ($this->data['Settings']->product_batch_setting == 1 || $this->data['Settings']->product_batch_setting == 2);
        
            // add Batch column dynamically
            $batch_select = $batch_enabled ? "GROUP_CONCAT(DISTINCT pi.batch_number SEPARATOR ', ') AS batch_no," : "NULL AS batch_no,";
        
            if ($this->data['Settings']->other_category_for_product == 0) {
                $query = "
                    SELECT 
                        p.code, p.name, p.id AS id,
                        pv.name AS pv_name,
                        pv_color.name AS color_name,
                        c.name AS sale_category_name,
                        b.name AS brand_name,
                        {$batch_select}
                        IF(PCosts.purchasedQty, ROUND(PCosts.purchasedQty, 2), 0) AS purchase_qty, 
                        PCosts.totalPurchase AS purchased,
                        IF(PSales.soldQty, ROUND(PSales.soldQty, 2), 0) AS sold_qty, 
                        PSales.totalSale AS sold,
                        (COALESCE(PSales.totalSale, 0) - COALESCE(PCosts.totalPurchase, 0)) AS Profit,
                        IF(PBalance.balanceQty, ROUND(PBalance.balanceQty, 2), 0) AS balance_qty,
                        IF(PBalance.balanceValue, PBalance.balanceValue, (ROUND(PBalance.balanceQty, 2) * PCosts.purchasedQty)) AS balance
                    FROM sma_products AS p
                    LEFT JOIN sma_product_variants AS pv ON p.id = pv.product_id AND pv.group_id = 1
                    LEFT JOIN sma_product_variants AS pv_color ON p.id = pv_color.product_id AND pv_color.group_id = 2
                    LEFT JOIN sma_categories AS c ON c.id = p.category_id
                    " . ($batch_enabled ? "
                        LEFT JOIN {$this->db->dbprefix('purchase_items')} pi 
                        ON ((pv.id IS NOT NULL AND pv.id = pi.option_id) OR (pv.id IS NULL AND p.id = pi.product_id))
                    " : "") . "
                    LEFT JOIN (
                        SELECT 
                            pi.product_id,
                            IFNULL(pi.option_id,0) AS option_id,
                            SUM(CASE WHEN pi.purchase_id IS NOT NULL THEN pi.quantity ELSE 0 END) AS purchasedQty,
                            SUM(pi.quantity_balance) AS balanceQty,
                            SUM(pi.unit_cost * pi.quantity_balance) AS balanceValue,
                            SUM(CASE WHEN pi.purchase_id IS NOT NULL THEN pi.subtotal ELSE 0 END) AS totalPurchase
                        FROM {$this->db->dbprefix('purchase_items')} pi
                        LEFT JOIN {$this->db->dbprefix('purchases')} pu 
                            ON pu.id = pi.purchase_id
                        {$purchase_where}
                        GROUP BY pi.product_id, IFNULL(pi.option_id,0)
                    ) AS PCosts
                    ON p.id = PCosts.product_id
                    AND IFNULL(pv.id,0) = PCosts.option_id
                     LEFT JOIN (
                        SELECT 
                            product_id, option_id,
                            SUM(quantity_balance) AS balanceQty,
                            SUM(unit_cost * quantity_balance) AS balanceValue
                        FROM sma_purchase_items
                        " . (!empty($stock_conditions) ? "WHERE " . implode(' AND ', $stock_conditions) : "") . "
                        GROUP BY product_id, option_id
                    ) AS PBalance
                    ON ((pv.id IS NOT NULL AND pv.id = PBalance.option_id)
                    OR (pv.id IS NULL AND p.id = PBalance.product_id))
                    LEFT JOIN sma_brands b ON b.id = p.brand
                    LEFT JOIN (
                        SELECT si.product_id, IFNULL(NULLIF(si.option_id,0), 0) AS option_id,
                               SUM(si.quantity) AS soldQty,
                               SUM(si.subtotal) AS totalSale
                        FROM {$this->db->dbprefix('sales')} s
                        JOIN {$this->db->dbprefix('sale_items')} si ON s.id = si.sale_id
                        {$sales_where}
                        GROUP BY si.product_id, IFNULL(NULLIF(si.option_id,0), 0)
                    ) AS PSales ON ((pv.id IS NOT NULL AND pv.id = PSales.option_id) OR (pv.id IS NULL AND p.id = PSales.product_id))
                    {$product_conditions_sale}
                    {$product_where}
                    GROUP BY p.id, pv.id
                ";
            } else {
                // (You can re-use the advanced other_category version from previous logic here.)
                $query = "
                    SELECT 
                        p.code, p.name, p.id AS id,
                        pv.name AS pv_name,
                        pv_color.name AS color_name,
                        c.name AS sale_category_name,
                        {$batch_select}
                        IF(PCosts.purchasedQty, ROUND(PCosts.purchasedQty, 2), 0) AS purchase_qty,
                        PCosts.totalPurchase AS purchased,
                        b.name AS brand_name,
                        IF(PSales.soldQty, ROUND(PSales.soldQty, 2), 0) AS sold_qty,
                        PSales.totalSale AS sold,
                        (COALESCE(PSales.totalSale, 0) - COALESCE(PCosts.totalPurchase, 0)) AS Profit,
                        IF(PBalance.balanceQty, ROUND(PBalance.balanceQty, 2), 0) AS balance_qty,
                        IF(PBalance.balanceValue, PBalance.balanceValue, (ROUND(PBalance.balanceQty, 2) * PCosts.purchasedQty)) AS balance
                    FROM sma_products AS p
                    LEFT JOIN sma_product_variants AS pv ON p.id = pv.product_id AND pv.group_id = 1
                    LEFT JOIN sma_product_variants AS pv_color ON p.id = pv_color.product_id AND pv_color.group_id = 2
                    LEFT JOIN sma_categories AS c ON c.id = p.category_id
                    " . ($batch_enabled ? "
                        LEFT JOIN {$this->db->dbprefix('purchase_items')} pi 
                        ON ((pv.id IS NOT NULL AND pv.id = pi.option_id) OR (pv.id IS NULL AND p.id = pi.product_id))
                    " : "") . "
                    LEFT JOIN (
                        SELECT 
                            pi.product_id,
                            IFNULL(pi.option_id,0) AS option_id,
                            SUM(CASE WHEN pi.purchase_id IS NOT NULL THEN pi.quantity ELSE 0 END) AS purchasedQty,
                            SUM(pi.quantity_balance) AS balanceQty,
                            SUM(pi.unit_cost * pi.quantity_balance) AS balanceValue,
                            SUM(CASE WHEN pi.purchase_id IS NOT NULL THEN pi.subtotal ELSE 0 END) AS totalPurchase
                        FROM {$this->db->dbprefix('purchase_items')} pi
                        LEFT JOIN {$this->db->dbprefix('purchases')} pu 
                            ON pu.id = pi.purchase_id
                        {$purchase_where}
                        GROUP BY pi.product_id, IFNULL(pi.option_id,0)
                    ) AS PCosts
                    ON p.id = PCosts.product_id
                    AND IFNULL(pv.id,0) = PCosts.option_id
                     LEFT JOIN (
                        SELECT 
                            product_id, option_id,
                            SUM(quantity_balance) AS balanceQty,
                            SUM(unit_cost * quantity_balance) AS balanceValue
                        FROM sma_purchase_items
                        " . (!empty($stock_conditions) ? "WHERE " . implode(' AND ', $stock_conditions) : "") . "
                        GROUP BY product_id, option_id
                    ) AS PBalance
                    ON ((pv.id IS NOT NULL AND pv.id = PBalance.option_id)
                    OR (pv.id IS NULL AND p.id = PBalance.product_id))
                    LEFT JOIN sma_brands b ON b.id = p.brand
                    LEFT JOIN (
                        SELECT si.product_id, IFNULL(NULLIF(si.option_id,0), 0) AS option_id,
                               SUM(si.quantity) AS soldQty,
                               SUM(si.subtotal) AS totalSale
                        FROM {$this->db->dbprefix('sales')} s
                        JOIN {$this->db->dbprefix('sale_items')} si ON s.id = si.sale_id
                        {$sales_where}
                        GROUP BY si.product_id, IFNULL(NULLIF(si.option_id,0), 0)
                    ) AS PSales ON ((pv.id IS NOT NULL AND pv.id = PSales.option_id) OR (pv.id IS NULL AND p.id = PSales.product_id))
                    {$product_conditions_sale}
                    {$product_where}
                    GROUP BY p.id, pv.id
                ";
            }
        
            $q = $this->db->query($query)->result();
                        if ($this->data['Settings']->display_zero_sale_for_product_report == 0 && (!$this->Owner && !$this->Admin)) {
                    $q = array_filter($q, function ($row) {
                        return floatval($row->sold_qty) != 0;
                    });
                }
            // ------------------ EXCEL GENERATION ------------------ //
            if (!empty($q)) {
                $this->load->library('excel');
                $sheet = $this->excel->setActiveSheetIndex(0);
                $sheet->setTitle(lang('products_report'));
                $this->excel->getActiveSheet()->mergeCells('A1:N1');
                $sheet->setCellValue('A1', 'Products Report');

                // Apply center alignment + red text
                $sheet->getStyle('A1')->applyFromArray([
                    'alignment' => [
                        'horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER
                    ],
                    'font' => [
                        'bold' => true,
                        'color' => ['rgb' => 'FF0000']
                    ]
                ]);

        
                // Define headers
                $headers = ['Product Code', 'Product Name', 'Variant', 'Color'];
                if ($batch_enabled) $headers[] = 'Batch No';
                $headers = array_merge($headers, ['Category', 'Brand', 'Purchased Qty', 'Purchased Amt', 'Sold Qty', 'Sold Amt', 'Profit/Loss', 'Stock Qty', 'Stock Amt']);
        
                $col = 'A';
                foreach ($headers as $header) {
                    $sheet->setCellValue($col . '2', $header);
                    $sheet->getStyle($col . '2')->getFont()->setBold(true);
                    $col++;
                }
                // Generate column letters dynamically (A, B, C... Z, AA, AB...)
                $colLetters = [];
                for ($i = 0; $i < count($headers); $i++) {
                    $colLetters[] = PHPExcel_Cell::stringFromColumnIndex($i);
                }
                $idx = 0;
                $col_product_code  = $colLetters[$idx++];
                $col_product_name  = $colLetters[$idx++];
                $col_variant       = $colLetters[$idx++];
                $col_color         = $colLetters[$idx++];

                if ($batch_enabled) {
                    $col_batch_no = $colLetters[$idx++];
                }

                $col_category      = $colLetters[$idx++];
                $col_brand         = $colLetters[$idx++];
                $col_pur_qty       = $colLetters[$idx++];
                $col_pur_amt       = $colLetters[$idx++];
                $col_sold_qty      = $colLetters[$idx++];
                $col_sold_amt      = $colLetters[$idx++];
                $col_profit        = $colLetters[$idx++];
                $col_stock_qty     = $colLetters[$idx++];
                $col_stock_amt     = $colLetters[$idx++];
                $row = 3;
                $tmp = $this->sma->formatMoney(1);
                $currencySymbol = trim(str_replace(['1', '.', '0'], '', $tmp));
                $total_pur_qty   = 0;
                $total_pur_amt   = 0;
                $total_sold_qty  = 0;
                $total_sold_amt  = 0;
                $total_profit    = 0;
                $total_stock_qty = 0;
                $total_stock_amt = 0;

                foreach ($q as $r) {
                    $total_pur_qty   += $r->purchase_qty;
                    $total_pur_amt   += $r->purchased;
                    $total_sold_qty  += $r->sold_qty;
                    $total_sold_amt  += $r->sold;
                    $total_profit    += $r->Profit;
                    $total_stock_qty += $r->balance_qty;
                    $total_stock_amt += $r->balance;

                    $col = 'A';
                    $sheet->setCellValue($col++ . $row, $r->code);
                    $sheet->setCellValue($col++ . $row, $r->name);
                    $sheet->setCellValue($col++ . $row, $r->pv_name);
                    $sheet->setCellValue($col++ . $row, $r->color_name);
                
                    if ($batch_enabled) {
                        $sheet->setCellValue($col++ . $row, $r->batch_no);
                    }
                
                    $sheet->setCellValue($col++ . $row, $r->sale_category_name);
                    $sheet->setCellValue($col++ . $row, $r->brand_name);
                
                    // Purchased Qty (center)
                    $sheet->setCellValueExplicit(
                        $col . $row,
                        $this->sma->formatQuantity($r->purchase_qty),
                        PHPExcel_Cell_DataType::TYPE_STRING
                    );
                    $sheet->getStyle($col . $row)
                        ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                    $col++;
                
                    // Purchased Amount
                    // $sheet->setCellValue($col++ . $row, $this->sma->formatMoney($r->purchased));
                    $sheet->setCellValue($col . $row, (float)$r->purchased);

                    $sheet->getStyle($col . $row)
                        ->getNumberFormat()
                        ->setFormatCode('"'.$currencySymbol.'" #,##0.00');

                    $sheet->getStyle($col . $row)
                        ->getAlignment()
                        ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $col++;
                
                    // Sold Qty (center)
                    $sheet->setCellValueExplicit(
                        $col . $row,
                        $this->sma->formatQuantity($r->sold_qty),
                        PHPExcel_Cell_DataType::TYPE_STRING
                    );
                    $sheet->getStyle($col . $row)
                        ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                    $col++;
                
                    // Sold Amount
                    // $sheet->setCellValue($col++ . $row, $this->sma->formatMoney($r->sold));
                    $sheet->setCellValue($col . $row, (float)$r->sold);

                    $sheet->getStyle($col . $row)
                        ->getNumberFormat()
                        ->setFormatCode('"'.$currencySymbol.'" #,##0.00');

                    $sheet->getStyle($col . $row)
                        ->getAlignment()
                        ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $col++;
                
                    // Profit
                    // $sheet->setCellValue($col++ . $row, $this->sma->formatMoney($r->Profit));
                    $sheet->setCellValue($col . $row, (float)$r->Profit);

                    $sheet->getStyle($col . $row)
                        ->getNumberFormat()
                        ->setFormatCode('"'.$currencySymbol.'" #,##0.00');

                    $sheet->getStyle($col . $row)
                        ->getAlignment()
                        ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $col++;
                
                    // Balance Qty (center)
                    $sheet->setCellValueExplicit(
                        $col . $row,
                        $this->sma->formatQuantity($r->balance_qty),
                        PHPExcel_Cell_DataType::TYPE_STRING
                    );
                    $sheet->getStyle($col . $row)
                        ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                    $col++;
                
                    // Balance Amount
                    // $sheet->setCellValue($col++ . $row, $this->sma->formatMoney($r->balance));
                    $sheet->setCellValue($col . $row, (float)$r->balance);

                    $sheet->getStyle($col . $row)
                        ->getNumberFormat()
                        ->setFormatCode('"'.$currencySymbol.'" #,##0.00');

                    $sheet->getStyle($col . $row)
                        ->getAlignment()
                        ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $col++;
                
                    $row++;
                }                
        
                // Formatting: text left, qty center, money right
                $highestCol = chr(ord('A') + count($headers) - 1);
                // Align text columns (left)
                $sheet->getStyle("{$col_product_code}3:{$col_category}{$row}")
                ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);

                // Purchased Qty (G), Sold Qty (I), Stock Qty (L) = center align
                $sheet->getStyle("{$col_pur_qty}3:{$col_pur_qty}{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);

                $sheet->getStyle("{$col_sold_qty}3:{$col_sold_qty}{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);

                $sheet->getStyle("{$col_stock_qty}3:{$col_stock_qty}{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);


                                // Purchased Amt (H), Sold Amt (J), Profit (K), Stock Amt (M) = right align
                                $sheet->getStyle("{$col_pur_amt}3:{$col_pur_amt}{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $sheet->getStyle("{$col_sold_amt}3:{$col_sold_amt}{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $sheet->getStyle("{$col_profit}3:{$col_profit}{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $sheet->getStyle("{$col_stock_amt}3:{$col_stock_amt}{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                $footerRow = $row;

                // Label
                $sheet->setCellValue($col_product_name . $footerRow, 'TOTAL');
                $sheet->getStyle($col_product_name . $footerRow)->getFont()->setBold(true);
                // Purchased Qty (center)
                $sheet->setCellValueExplicit(
                    $col_pur_qty . $footerRow,
                    $this->sma->formatQuantity($total_pur_qty),
                    PHPExcel_Cell_DataType::TYPE_STRING
                );
                $sheet->getStyle($col_pur_qty . $footerRow)->applyFromArray([
                    'font' => ['bold' => true],
                    'alignment' => ['horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER]
                ]);

                // Purchased Amount (right)
                // $sheet->setCellValue($col_pur_amt . $footerRow, $this->sma->formatMoney($total_pur_amt));
                $sheet->setCellValue($col_pur_amt . $footerRow, (float)$total_pur_amt);

