                ]);

                // Profit (right)
                // $sheet->setCellValue($col_profit . $footerRow, $this->sma->formatMoney($total_profit));
                $sheet->setCellValue($col_profit . $footerRow, (float)$total_profit);

                $sheet->getStyle($col_profit . $footerRow)
