                ]);

                // Stock Amount (right)
                // $sheet->setCellValue($col_stock_amt . $footerRow, $this->sma->formatMoney($total_stock_amt));
                $sheet->setCellValue($col_stock_amt . $footerRow, (float)$total_stock_amt);

                $sheet->getStyle($col_stock_amt . $footerRow)
