        else {
        
            // Initialize conditions
            $purchase_conditions = [];
            $sales_conditions = [];
            $product_conditions = [];
            $stock_conditions = [];

            // Purchase and sales conditions
            if ($start_date || $warehouse) {
                if ($start_date) {
                    $start_date = $this->sma->fld($start_date);
                    $end_date = $end_date ? $this->sma->fld($end_date) : date('Y-m-d');
                    $purchase_conditions[] = "DATE(pi.date) BETWEEN '{$start_date}' AND '{$end_date}'";
                    $sales_conditions[] = "DATE(s.date) BETWEEN '{$start_date}' AND '{$end_date}'";
                }
                if ($warehouse) {
                    $getwarehouse = str_replace("_", ",", $warehouse);
                    $purchase_conditions[] = "pi.warehouse_id IN ({$getwarehouse})";
                    $sales_conditions[] = "si.warehouse_id IN ({$getwarehouse})";
                    $stock_conditions[] = "warehouse_id IN ({$getwarehouse})";
                    $user = $this->site->getUser();
					
                    if (!$this->Owner && !$this->Admin && !$user->view_right) {
                        $purchase_conditions[] = "pu.created_by = " . $this->session->userdata('user_id');
                        $sales_conditions[] = "s.created_by = " . $this->session->userdata('user_id');
                    }
                }
            }

            // Product-related conditions
            // if ($this->data['Settings']->display_zero_sale_for_product_report == 0) {
            //     $product_conditions_sale = "AND PSales.soldQty != 0";
            // }
            if ($product) {
                $product_conditions[] = "p.id = {$product}";
            }
            if ($cf1) {
                $product_conditions[] = "p.cf1 = '{$cf1}'";
            }
            if ($cf2) {
                $product_conditions[] = "p.cf2 = '{$cf2}'";
            }
            if ($cf3) {
                $product_conditions[] = "p.cf3 = '{$cf3}'";
            }
            if ($cf4) {
                $product_conditions[] = "p.cf4 = '{$cf4}'";
            }
            if ($cf5) {
                $product_conditions[] = "p.cf5 = '{$cf5}'";
            }
            if ($cf6) {
                $product_conditions[] = "p.cf6 = '{$cf6}'";
            }
            if ($category) {
                $product_conditions[] = "p.category_id = {$category}";
            }
            if ($subcategory) {
                $product_conditions[] = "p.subcategory_id = {$subcategory}";
            }
            if ($brand) {
                $product_conditions[] = "p.brand = {$brand}";
            }

            // Combine conditions into WHERE clauses
            $purchase_where = !empty($purchase_conditions) ? 'WHERE ' . implode(' AND ', $purchase_conditions) : '';
            $sales_where = !empty($sales_conditions) ? 'WHERE ' . implode(' AND ', $sales_conditions) : '';
            $product_where = !empty($product_conditions) ? 'WHERE ' . implode(' AND ', $product_conditions) : '';
            
            // Final query with dynamic conditions applied
            if ($this->data['Settings']->other_category_for_product == 0) {
                $query = "
                    SELECT 
                        p.code, 
                        p.name, 
                        p.id AS id,
                        pv.name AS pv_name,
                        c.name AS sale_category_name,
                        pv_color.name AS variant_color_name,
                        b.name AS brand_name,
                        -- 🟢 Add Batch No column conditionally
                        " . (($this->data['Settings']->product_batch_setting == 1 || $this->data['Settings']->product_batch_setting == 2)
                            ? "GROUP_CONCAT(DISTINCT pi.batch_number SEPARATOR ', ') AS batch_no," 
                            : "NULL AS batch_no,") . "
            
                        IF(PCosts.purchasedQty, ROUND(PCosts.purchasedQty, 2), 0) AS purchase_qty, 
                        PCosts.totalPurchase AS purchased,
                        IF(PSales.soldQty, ROUND(PSales.soldQty, 2), 0) AS sold_qty, 
                        PSales.totalSale AS sold,
                        (COALESCE(PSales.totalSale, 0) - COALESCE(PCosts.totalPurchase, 0)) AS Profit,
                        IF(PBalance.balanceQty, ROUND(PBalance.balanceQty, 2), 0) AS balance_qty,
                        IF(PBalance.balanceValue, PBalance.balanceValue, (ROUND(PBalance.balanceQty, 2) * PCosts.purchasedQty)) AS balance
                    FROM sma_products AS p
                    LEFT JOIN sma_product_variants AS pv ON p.id = pv.product_id AND pv.group_id = 1
                    LEFT JOIN sma_product_variants AS pv_color ON p.id = pv_color.product_id AND pv_color.group_id = 2
            
                    -- 🟢 Add LEFT JOIN to purchase_items for batch numbers
                    " . (($this->data['Settings']->product_batch_setting == 1 || $this->data['Settings']->product_batch_setting == 2)
                        ? "LEFT JOIN {$this->db->dbprefix('purchase_items')} pi 
                            ON ((pv.id IS NOT NULL AND pv.id = pi.option_id) OR (pv.id IS NULL AND p.id = pi.product_id))"
                        : "") . "
            
                    LEFT JOIN (
                        SELECT 
                            pi.product_id,
                            IFNULL(pi.option_id,0) AS option_id,
                            SUM(CASE WHEN pi.purchase_id IS NOT NULL THEN pi.quantity ELSE 0 END) AS purchasedQty,
                            SUM(pi.quantity_balance) AS balanceQty,
                            SUM(pi.unit_cost * pi.quantity_balance) AS balanceValue,
                            SUM(CASE WHEN pi.purchase_id IS NOT NULL THEN pi.subtotal ELSE 0 END) AS totalPurchase
                        FROM {$this->db->dbprefix('purchase_items')} pi
                        LEFT JOIN {$this->db->dbprefix('purchases')} pu 
                            ON pu.id = pi.purchase_id
                        {$purchase_where}
                        GROUP BY pi.product_id, IFNULL(pi.option_id,0)
                    ) AS PCosts
                    ON p.id = PCosts.product_id
                    AND IFNULL(pv.id,0) = PCosts.option_id
                    
                    LEFT JOIN (
                        SELECT 
                            product_id, option_id,
                            SUM(quantity_balance) AS balanceQty,
                            SUM(unit_cost * quantity_balance) AS balanceValue
                        FROM sma_purchase_items
                        " . (!empty($stock_conditions) ? "WHERE " . implode(' AND ', $stock_conditions) : "") . "
                        GROUP BY product_id, option_id
                    ) AS PBalance
                    ON ((pv.id IS NOT NULL AND pv.id = PBalance.option_id)
                    OR (pv.id IS NULL AND p.id = PBalance.product_id))
            
                    LEFT JOIN sma_categories AS c ON c.id = p.category_id
                    LEFT JOIN sma_brands b ON b.id = p.brand
                    LEFT JOIN (
                        SELECT 
                            si.product_id, IFNULL(NULLIF(si.option_id,0), 0) AS option_id,
                            SUM(si.quantity) AS soldQty, 
                            SUM(si.subtotal) AS totalSale
                        FROM {$this->db->dbprefix('sales')} s
                        JOIN {$this->db->dbprefix('sale_items')} si ON s.id = si.sale_id
                        {$sales_where}
                        GROUP BY si.product_id, IFNULL(NULLIF(si.option_id,0), 0)
                    ) AS PSales 
                    ON ((pv.id IS NOT NULL AND pv.id = PSales.option_id)
                        OR (pv.id IS NULL AND p.id = PSales.product_id))
            
                    {$product_conditions_sale}
                    {$product_where}
                    GROUP BY p.id, pv.id
                ";
            
                $product_query = $this->db->query($query);
                $result = $product_query->result();

                if ($this->data['Settings']->display_zero_sale_for_product_report == 0 && (!$this->Owner && !$this->Admin)) {
                    $result = array_filter($product_query->result(), function ($row) {
                        return floatval($row->sold_qty) != 0;
                    });
                }

            }else {
                $query = "
                    SELECT 
                        p.code, p.name, p.id AS id,
                        pv.name AS pv_name,
                        pv_color.name AS color_name,
                        c.name AS sale_category_name,
                        pv_color.name AS variant_color_name,
                        {$batch_select}
                        IF(PCosts.purchasedQty, ROUND(PCosts.purchasedQty, 2), 0) AS purchase_qty,
                        PCosts.totalPurchase AS purchased,
						b.name AS brand_name,
                        IF(PSales.soldQty, ROUND(PSales.soldQty, 2), 0) AS sold_qty,
                        PSales.totalSale AS sold,
                        (COALESCE(PSales.totalSale, 0) - COALESCE(PCosts.totalPurchase, 0)) AS Profit,
                        IF(PBalance.balanceQty, ROUND(PBalance.balanceQty, 2), 0) AS balance_qty,
                        IF(PBalance.balanceValue, PBalance.balanceValue, (ROUND(PBalance.balanceQty, 2) * PCosts.purchasedQty)) AS balance
                    FROM sma_products AS p
                    LEFT JOIN sma_product_variants AS pv ON p.id = pv.product_id AND pv.group_id = 1
                    LEFT JOIN sma_product_variants AS pv_color ON p.id = pv_color.product_id AND pv_color.group_id = 2
                    LEFT JOIN sma_categories AS c ON c.id = p.category_id
                    " . ($batch_enabled ? "
                        LEFT JOIN {$this->db->dbprefix('purchase_items')} pi 
                        ON ((pv.id IS NOT NULL AND pv.id = pi.option_id) OR (pv.id IS NULL AND p.id = pi.product_id))
                    " : "") . "
                    LEFT JOIN (
                        SELECT 
                            pi.product_id,
                            IFNULL(pi.option_id,0) AS option_id,
                            SUM(CASE WHEN pi.purchase_id IS NOT NULL THEN pi.quantity ELSE 0 END) AS purchasedQty,
                            SUM(pi.quantity_balance) AS balanceQty,
                            SUM(pi.unit_cost * pi.quantity_balance) AS balanceValue,
                            SUM(CASE WHEN pi.purchase_id IS NOT NULL THEN pi.subtotal ELSE 0 END) AS totalPurchase
                        FROM {$this->db->dbprefix('purchase_items')} pi
                        LEFT JOIN {$this->db->dbprefix('purchases')} pu 
                            ON pu.id = pi.purchase_id
                        {$purchase_where}
                        GROUP BY pi.product_id, IFNULL(pi.option_id,0)
                    ) AS PCosts
                    ON p.id = PCosts.product_id
                    AND IFNULL(pv.id,0) = PCosts.option_id
                    LEFT JOIN (
                        SELECT 
                            product_id, option_id,
                            SUM(quantity_balance) AS balanceQty,
                            SUM(unit_cost * quantity_balance) AS balanceValue
                        FROM sma_purchase_items
                        " . (!empty($stock_conditions) ? "WHERE " . implode(' AND ', $stock_conditions) : "") . "
                        GROUP BY product_id, option_id
                    ) AS PBalance
                    ON ((pv.id IS NOT NULL AND pv.id = PBalance.option_id)
                    OR (pv.id IS NULL AND p.id = PBalance.product_id))
                    LEFT JOIN sma_brands b ON b.id = p.brand
                    LEFT JOIN (
                        SELECT si.product_id, IFNULL(NULLIF(si.option_id,0), 0) AS option_id,
                               SUM(si.quantity) AS soldQty,
                               SUM(si.subtotal) AS totalSale
                        FROM {$this->db->dbprefix('sales')} s
                        JOIN {$this->db->dbprefix('sale_items')} si ON s.id = si.sale_id
                        {$sales_where}
                        GROUP BY si.product_id, IFNULL(NULLIF(si.option_id,0), 0)
                    ) AS PSales ON ((pv.id IS NOT NULL AND pv.id = PSales.option_id) OR (pv.id IS NULL AND p.id = PSales.product_id))
                    {$product_conditions_sale}
                    {$product_where}
                    GROUP BY p.id, pv.id
                ";
            
                $product_query = $this->db->query($query);
                $result = $product_query->result();
                if ($this->data['Settings']->display_zero_sale_for_product_report == 0 && (!$this->Owner && !$this->Admin)) {
                    $result = array_filter($product_query->result(), function ($row) {
                        return floatval($row->sold_qty) != 0;
                    });
                }
                // 🟢 Apply category match logic
                $result = array_map(function($row) {
                    if ($row->primary_category != $row->sale_category_id) {
                        $row->balance_qty = 0;
                        $row->balance = 0;
                        $row->purchase_qty = 0;
                        $row->purchased = 0;
                        $row->Profit = 0;
                    }
                    return $row;
                }, $result);
            }
            
            $show_other_category = ($this->data['Settings']->other_category_for_product == 1);
            $show_batch = ($this->data['Settings']->product_batch_setting == 1 || $this->data['Settings']->product_batch_setting == 2);
            $datatable = '<div>
            <table id="PrData1" class="table table-striped table-bordered table-condensed table-hover dfTable reports-table" style="margin-bottom:5px;">
                <thead>
                    <tr class="active">
                        <th>' . lang("product_code") . '</th>
                        <th>' . lang("product_name") . '</th>
                        <th>' . lang("Variant_Name") . '</th>
                        <th>' . lang("Color_Name") . '</th>';

            // 🟢 Add Batch column conditionally
            if ($show_batch) {
                $datatable .= '<th>' . lang("Batch No") . '</th>';
            }

            $datatable .= '
                        <th>' . lang("Category Name") . '</th>
                        <th>' . lang("Brand") . '</th>
                        <th>' . lang("Purchased QTY") . '</th>
                        <th>' . lang("Purchased") . '</th>
                        <th>' . lang("Sold QTY") . '</th>
                        <th>' . lang("Sold") . '</th>
                        <th>' . lang("Profit & Loss") . '</th>
                        <th>' . lang("Stock QTY") . '</th>
                        <th>' . lang("Stock (QTY) Amt") . '</th>
                    </tr>
                </thead>

                <tbody>';

            // 🔹 Data rows
            foreach ($result as $row) {
                $purchase_qty_raw = (empty($row->purchase_qty) ? '0.00' : $row->purchase_qty);
                $purchased_raw    = (empty($row->purchased) ? '0.00' : $row->purchased);
                $sold_qty_raw     = (empty($row->sold_qty) ? '0.00' : $row->sold_qty);
                $sold_raw         = (empty($row->sold) ? '0.00' : $row->sold);
                $profit_raw       = (empty($row->Profit) ? '0.00' : $row->Profit);
                $balance_qty_raw  = (empty($row->balance_qty) ? '0.00' : $row->balance_qty);
                $balance_raw      = (empty($row->balance) ? '0.00' : $row->balance);
                
                $purchase_qty = $this->sma->formatQuantity($purchase_qty_raw);
                $purchased    = $this->sma->formatMoney($purchased_raw);
                $sold_qty     = $this->sma->formatQuantity($sold_qty_raw);
                $sold         = $this->sma->formatMoney($sold_raw);
                $profit       = $this->sma->formatMoney($profit_raw);
                $balance_qty  = $this->sma->formatQuantity($balance_qty_raw);
                $balance      = $this->sma->formatMoney($balance_raw);

                $datatable .= '<tr>
                    <td style="text-align:left;">' . htmlspecialchars($row->code) . '</td>
                    <td style="text-align:left;">' . htmlspecialchars($row->name) . '</td>
                    <td style="text-align:left;">' . htmlspecialchars($row->pv_name) . '</td>
                    <td style="text-align:left;">' . htmlspecialchars($row->variant_color_name) . '</td>';

                // 🟢 Conditional Batch Column
                if ($show_batch) {
                    $datatable .= '<td style="text-align:left;">' . (!empty($row->batch_no) ? nl2br(htmlspecialchars($row->batch_no)) : '-') . '</td>';
                }

                $datatable .= '
                    <td style="text-align:left;">' . htmlspecialchars($row->sale_category_name) . '</td>
                    <td style="text-align:left;">' . (!empty($row->brand_name) ? htmlspecialchars($row->brand_name) : '-') . '</td>
                    <td style="text-align:center;" data-order="' . $purchase_qty_raw . '">' . $purchase_qty . '</td>
                    <td style="text-align:right;" data-order="' . $purchased_raw . '">' . $purchased . '</td>
                    <td style="text-align:center;" data-order="' . $sold_qty_raw . '">' . $sold_qty . '</td>
                    <td style="text-align:right;" data-order="' . $sold_raw . '">' . $sold . '</td>
                    <td style="text-align:right;" data-order="' . $profit_raw . '">' . $profit . '</td>
                    <td style="text-align:center;" data-order="' . $balance_qty_raw . '">' . $balance_qty . '</td>
                    <td style="text-align:right;" data-order="' . $balance_raw . '">' . $balance . '</td>
                </tr>';
            }

            $datatable .= '</tbody>
                <tfoot>
                    <tr class="active">
                        <th colspan="' . ($show_batch ? 7 : 6) . '" style="text-align:right;">' . lang("Total") . '</th>
                        <th class="text-center"></th>
                        <th class="text-right"></th>
                        <th class="text-center"></th>
                        <th class="text-right"></th>
                        <th class="text-right"></th>
                        <th class="text-center"></th>
                        <th class="text-right"></th>
                    </tr>
                </tfoot>
            </table>
            </div>';
        
            echo $datatable;
        }
    }
    function categories() {
        $this->sma->checkPermissions('products');
        $this->data['error'] = (validation_errors() ? validation_errors() : $this->session->flashdata('error'));
        $this->data['categories'] = $this->site->getAllCategories();
        $this->data['warehouses'] = $this->site->getAllWarehouses();
        if ($this->input->post('start_date')) {
            $dt = "From " . $this->input->post('start_date') . " to " . $this->input->post('end_date');
        } else {
            $dt = "Till " . $this->input->post('end_date');
        }
        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('categories_report')));
        $meta = array('page_title' => lang('categories_report'), 'bc' => $bc);
        $this->page_construct('reports/categories', $meta, $this->data);
    }

    function getCategoriesReport($pdf = NULL, $xls = NULL, $img = NULL) {
        $this->sma->checkPermissions('products', TRUE);
        $warehouse = $this->input->get('warehouse') ? $this->input->get('warehouse') : NULL;
        $category = $this->input->get('category') ? $this->input->get('category') : NULL;
        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;

        $pp = "( SELECT pp.category_id as category, SUM( pi.quantity ) purchasedQty, SUM( pi.subtotal ) totalPurchase from {$this->db->dbprefix('products')} pp
                left JOIN " . $this->db->dbprefix('purchase_items') . " pi ON pp.id = pi.product_id
                left join " . $this->db->dbprefix('purchases') . " p ON p.id = pi.purchase_id ";
        $sp = "( SELECT sp.category_id as category, SUM( si.quantity ) soldQty, SUM( si.subtotal ) totalSale from {$this->db->dbprefix('products')} sp
                left JOIN " . $this->db->dbprefix('sale_items') . " si ON sp.id = si.product_id
                left join " . $this->db->dbprefix('sales') . " s ON s.id = si.sale_id ";
        if ($start_date || $warehouse) {
            $pp .= " WHERE ";
            $sp .= " WHERE ";
            if ($start_date) {
                $start_date = $this->sma->fld($start_date);
                $end_date = $end_date ? $this->sma->fld($end_date) : date('Y-m-d');
                $pp .= " p.date >= '{$start_date}' AND p.date < '{$end_date}' ";
                $sp .= " s.date >= '{$start_date}' AND s.date < '{$end_date}' ";
                if ($warehouse) {
                    $pp .= " AND ";
                    $sp .= " AND ";
                }
            }
            if ($warehouse) {
                $getwarehouse = str_replace("_", ",", $warehouse);
                $pp .= " pi.warehouse_id IN({$getwarehouse}) ";
                $sp .= " si.warehouse_id IN({$getwarehouse}) ";

                if ($this->session->userdata('view_right') == '0') {
                    $pp .= " AND p.created_by =" . $this->session->userdata('user_id');
                    $sp .= "AND s.created_by  =  " . $this->session->userdata('user_id');
                }
            }
        }
        $pp .= " GROUP BY pp.category_id ) PCosts";
        $sp .= " GROUP BY sp.category_id ) PSales";

        if ($pdf || $xls || $img) {

            $this->db->select($this->db->dbprefix('categories') . ".code, " . $this->db->dbprefix('categories') . ".name,
                    SUM( COALESCE( PCosts.purchasedQty, 0 ) ) as PurchasedQty,
                    SUM( COALESCE( PSales.soldQty, 0 ) ) as SoldQty,
                    SUM( COALESCE( PCosts.totalPurchase, 0 ) ) as TotalPurchase,
                    SUM( COALESCE( PSales.totalSale, 0 ) ) as TotalSales,
                    (SUM( COALESCE( PSales.totalSale, 0 ) )- SUM( COALESCE( PCosts.totalPurchase, 0 ) ) ) as Profit", FALSE)->from('categories')->join($sp, 'categories.id = PSales.category', 'left')->join($pp, 'categories.id = PCosts.category', 'left')->group_by('categories.id, categories.code, categories.name')->order_by('categories.code', 'asc');

            if ($category) {
                $this->db->where($this->db->dbprefix('categories') . ".id", $category);
            }

            $q = $this->db->get();
            if ($q->num_rows() > 0) {
                foreach (($q->result()) as $row) {
                    $data[] = $row;
                }
            } else {
                $data = NULL;
            }

            if (!empty($data)) {

                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);

                $style = array('alignment' => array('horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,), 'font' => array('name' => 'Arial', 'color' => array('rgb' => 'FF0000')), 'borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_NONE, 'color' => array('rgb' => 'FF0000'))));

                $this->excel->getActiveSheet()->getStyle("A1:G1")->applyFromArray($style);
                $this->excel->getActiveSheet()->mergeCells('A1:G1');
                $this->excel->getActiveSheet()->SetCellValue('A1', 'Categories Report');
                $this->excel->getActiveSheet()->setTitle(lang('categories_report'));
                $this->excel->getActiveSheet()->SetCellValue('A2', lang('category_code'));
                $this->excel->getActiveSheet()->SetCellValue('B2', lang('category_name'));
                $this->excel->getActiveSheet()->SetCellValue('C2', lang('purchased'));
                $this->excel->getActiveSheet()->SetCellValue('D2', lang('sold'));
                $this->excel->getActiveSheet()->SetCellValue('E2', lang('purchased_amount'));
                $this->excel->getActiveSheet()->SetCellValue('F2', lang('sold_amount'));
                $this->excel->getActiveSheet()->SetCellValue('G2', lang('profit_loss'));

                $row = 3;
                $sQty = 0;
                $pQty = 0;
                $sAmt = 0;
                $pAmt = 0;
                $pl = 0;
                foreach ($data as $data_row) {
                    $profit = $data_row->TotalSales - $data_row->TotalPurchase;
                    $this->excel->getActiveSheet()->SetCellValue('A' . $row, $data_row->code);
                    $this->excel->getActiveSheet()->SetCellValue('B' . $row, $data_row->name);
                    $this->excel->getActiveSheet()->SetCellValue('C' . $row, $data_row->PurchasedQty);
                    $this->excel->getActiveSheet()->SetCellValue('D' . $row, $data_row->SoldQty);
                    $this->excel->getActiveSheet()->SetCellValue('E' . $row, $data_row->TotalPurchase);
                    $this->excel->getActiveSheet()->SetCellValue('F' . $row, $data_row->TotalSales);
                    $this->excel->getActiveSheet()->SetCellValue('G' . $row, $profit);
                    $pQty += $data_row->PurchasedQty;
                    $sQty += $data_row->SoldQty;
                    $pAmt += $data_row->TotalPurchase;
                    $sAmt += $data_row->TotalSales;
                    $pl += $profit;
                    $row++;
                }
                $this->excel->getActiveSheet()->getStyle("C" . $row . ":G" . $row)->getBorders()->getTop()->setBorderStyle(PHPExcel_Style_Border::BORDER_MEDIUM);
                $this->excel->getActiveSheet()->SetCellValue('C' . $row, $pQty);
                $this->excel->getActiveSheet()->SetCellValue('D' . $row, $sQty);
                $this->excel->getActiveSheet()->SetCellValue('E' . $row, $pAmt);
                $this->excel->getActiveSheet()->SetCellValue('F' . $row, $sAmt);
                $this->excel->getActiveSheet()->SetCellValue('G' . $row, $pl);

                $this->excel->getActiveSheet()->getColumnDimension('A')->setWidth(35);
                $this->excel->getActiveSheet()->getColumnDimension('B')->setWidth(35);
                $this->excel->getActiveSheet()->getColumnDimension('C')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('D')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('E')->setWidth(25);
                $this->excel->getActiveSheet()->getColumnDimension('F')->setWidth(25);
                $this->excel->getActiveSheet()->getColumnDimension('G')->setWidth(25);

                $filename = 'categories_report';
                $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);
                if ($pdf) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));

                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getDefaultStyle('A1')->getAlignment()->applyFromArray(
                            array('horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_LEFT,)
                    );
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($xls) {
