                            $this->excel->getActiveSheet()->SetCellValue('H' . $row, $sales_items_data->quantity);
                            $this->excel->getActiveSheet()->getStyle('H' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                    
