        $user = $this->input->get('user') ? $this->input->get('user') : NULL;
        $supplier = $this->input->get('supplier') ? $this->input->get('supplier') : NULL;
        $warehouse = $this->input->get('warehouse') ? $this->input->get('warehouse') : NULL;
        $reference_no = $this->input->get('reference_no') ? $this->input->get('reference_no') : NULL;
        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;

        if ($start_date) {
            $start_date = $this->sma->fld($start_date);
            $end_date = $this->sma->fld($end_date);
        }
        if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
            $user = $this->session->userdata('user_id');
        }



        $this->db->select("" . $this->db->dbprefix('purchases') . ".date, reference_no, " . $this->db->dbprefix('warehouses') . ".name as wname, supplier, GROUP_CONCAT(CONCAT(" . $this->db->dbprefix('purchase_items') . ".product_name, ' (', " . $this->db->dbprefix('purchase_items') . ".quantity, ')') SEPARATOR '\n') as iname, grand_total, paid, " . $this->db->dbprefix('purchases') . ".status", FALSE)->from('purchases')->join('purchase_items', 'purchase_items.purchase_id=purchases.id', 'left')->join('warehouses', 'warehouses.id=purchases.warehouse_id', 'left')->group_by('purchases.id')->order_by('purchases.date desc');

        if ($this->session->userdata('view_right') == '0') {
            if ($user) {
                $this->db->where('purchases.created_by', $user);
            }
        }
        if ($product) {
            $this->db->where('purchase_items.product_id', $product);
        }
        if ($supplier) {
            $this->db->where('purchases.supplier_id', $supplier);
        }
        if ($warehouse) {
            $getwarehouse = str_replace("_", ",", $warehouse);
            $this->db->where('purchases.warehouse_id IN (' . $getwarehouse . ')');
        }
        if ($reference_no) {
            $this->db->like('purchases.reference_no', $reference_no, 'both');
        }
        if ($start_date) {
            $this->db->where($this->db->dbprefix('purchases') . '.date BETWEEN "' . $start_date . '" and "' . $end_date . '"');
        }

        $q = $this->db->get();
        if ($q->num_rows() > 0) {
            foreach (($q->result()) as $row) {
                $data[] = $row;
            }
        } else {
            $data = NULL;
        }

        if (!empty($data)) {

            $this->load->library('excel');
            $this->excel->setActiveSheetIndex(0);

            $style = array('alignment' => array('horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,), 'font' => array('name' => 'Arial', 'color' => array('rgb' => 'FF0000')), 'borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_NONE, 'color' => array('rgb' => 'FF0000'))));

            $this->excel->getActiveSheet()->getStyle("A1:I1")->applyFromArray($style);
            $this->excel->getActiveSheet()->mergeCells('A1:I1');
            $this->excel->getActiveSheet()->SetCellValue('A1', 'Purchases Report');

            $this->excel->getActiveSheet()->setTitle(lang('purchase_report'));
            $this->excel->getActiveSheet()->SetCellValue('A2', lang('date'));
            $this->excel->getActiveSheet()->SetCellValue('B2', lang('reference_no'));
            $this->excel->getActiveSheet()->SetCellValue('C2', lang('warehouse'));
            $this->excel->getActiveSheet()->SetCellValue('D2', lang('supplier'));
            $this->excel->getActiveSheet()->SetCellValue('E2', lang('product_qty'));
            $this->excel->getActiveSheet()->SetCellValue('F2', lang('grand_total'));
            $this->excel->getActiveSheet()->SetCellValue('G2', lang('paid'));
            $this->excel->getActiveSheet()->SetCellValue('H2', lang('balance'));
            $this->excel->getActiveSheet()->SetCellValue('I2', lang('status'));

            $row = 3;
            $total = 0;
            $paid = 0;
            $balance = 0;
            foreach ($data as $data_row) {
                $this->excel->getActiveSheet()->SetCellValue('A' . $row, $this->sma->hrld($data_row->date));
                $this->excel->getActiveSheet()->SetCellValue('B' . $row, $data_row->reference_no);
                $this->excel->getActiveSheet()->SetCellValue('C' . $row, $data_row->wname);
                $this->excel->getActiveSheet()->SetCellValue('D' . $row, $data_row->supplier);
                $this->excel->getActiveSheet()->SetCellValue('E' . $row, $data_row->iname);
                $this->excel->getActiveSheet()->SetCellValue('F' . $row, $data_row->grand_total);
                $this->excel->getActiveSheet()->SetCellValue('G' . $row, $data_row->paid);
                $this->excel->getActiveSheet()->SetCellValue('H' . $row, ($data_row->grand_total - $data_row->paid));
                $this->excel->getActiveSheet()->SetCellValue('I' . $row, $data_row->status);
                $total += $data_row->grand_total;
                $paid += $data_row->paid;
                $balance += ($data_row->grand_total - $data_row->paid);
                $row++;
            }
            $this->excel->getActiveSheet()->getStyle("F" . $row . ":H" . $row)->getBorders()->getTop()->setBorderStyle(PHPExcel_Style_Border::BORDER_MEDIUM);
            $this->excel->getActiveSheet()->SetCellValue('F' . $row, $total);
            $this->excel->getActiveSheet()->SetCellValue('G' . $row, $paid);
            $this->excel->getActiveSheet()->SetCellValue('H' . $row, $balance);

            $this->excel->getActiveSheet()->getColumnDimension('A')->setWidth(20);
            $this->excel->getActiveSheet()->getColumnDimension('B')->setWidth(20);
            $this->excel->getActiveSheet()->getColumnDimension('C')->setWidth(20);
            $this->excel->getActiveSheet()->getColumnDimension('D')->setWidth(20);
            $this->excel->getActiveSheet()->getColumnDimension('E')->setWidth(30);
            $this->excel->getActiveSheet()->getColumnDimension('F')->setWidth(15);
            $this->excel->getActiveSheet()->getColumnDimension('G')->setWidth(15);
            $this->excel->getActiveSheet()->getColumnDimension('H')->setWidth(15);
            $this->excel->getActiveSheet()->getColumnDimension('I')->setWidth(20);
            $filename = 'purchase_report';
            $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);


            $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
            $this->excel->getDefaultStyle()->applyFromArray($styleArray);
            $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
            require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
            $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
            $rendererLibrary = 'MPDF';
            $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
            if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
            }

            header('Content-Type: application/pdf');
            header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
            header('Cache-Control: max-age=0');

            $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
            //$objWriter->save('php://output');
            $objWriter->save(str_replace(__FILE__, 'assets/mdata/'.$this->Customer_assets.'/uploads/pdf/purchase.pdf', __FILE__));
            redirect("reports/create_image/purchase.pdf");
        }
    }

    function getPurchasesReport($pdf = NULL, $xls = NULL) {
        $this->sma->checkPermissions('purchases', TRUE);

        $product = $this->input->get('product') ? $this->input->get('product') : NULL;
        $user = $this->input->get('user') ? $this->input->get('user') : NULL;
        $supplier = $this->input->get('supplier') ? $this->input->get('supplier') : NULL;
        $warehouse = $this->input->get('warehouse') ? $this->input->get('warehouse') : NULL;
        $reference_no = $this->input->get('reference_no') ? $this->input->get('reference_no') : NULL;
        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;

        if ($start_date) {
            $start_date = $this->sma->fld($start_date);
            $end_date = $this->sma->fld($end_date);
        }
        if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
            $user = $this->session->userdata('user_id');
        }

        if ($pdf || $xls) {

            // $this->db->select("" . $this->db->dbprefix('purchases') . ".date, reference_no, " . $this->db->dbprefix('warehouses') . ".name as wname, supplier, GROUP_CONCAT(CONCAT(" . $this->db->dbprefix('purchase_items') . ".product_name, ' (', " . $this->db->dbprefix('purchase_items') . ".quantity, ')') SEPARATOR '\n') as iname, (grand_total+rounding) as grand_total, paid, " . $this->db->dbprefix('purchases') . ".status", FALSE)->from('purchases')->join('purchase_items', 'purchase_items.purchase_id=purchases.id', 'left')->join('warehouses', 'warehouses.id=purchases.warehouse_id', 'left')->group_by('purchases.id')->order_by('purchases.date desc');

            $this->db->select("
                {$this->db->dbprefix('purchases')}.date,
                reference_no,
                {$this->db->dbprefix('warehouses')}.name as wname,
                supplier,
                /* PRODUCT (with qty in bracket) */
                GROUP_CONCAT(
                    CONCAT(
                        {$this->db->dbprefix('purchase_items')}.product_name,
                        ' (',
                        {$this->db->dbprefix('purchase_items')}.quantity,
                        ')'
                    )
                    ORDER BY {$this->db->dbprefix('purchase_items')}.id
                    SEPARATOR '\n'
                ) AS iname,

                /* PURE QTY LIST (needed for Excel!) */
                GROUP_CONCAT(
                    {$this->db->dbprefix('purchase_items')}.quantity
                    ORDER BY {$this->db->dbprefix('purchase_items')}.id
                    SEPARATOR '\n'
                ) AS qty_list,
                /* NEW: variant names (one per line, same order as iname) */
                GROUP_CONCAT(
                    IF(
                        {$this->db->dbprefix('product_variants')}.name IS NOT NULL
                        AND {$this->db->dbprefix('product_variants')}.name != '',
                        {$this->db->dbprefix('product_variants')}.name,
                        ''
                    )
                    SEPARATOR '\n'
                ) AS variant_list,
                GROUP_CONCAT(
                    DISTINCT NULLIF(NULLIF({$this->db->dbprefix('purchase_items')}.batch_number, ''), 'N/A')
                    ORDER BY {$this->db->dbprefix('purchase_items')}.batch_number SEPARATOR ', '
                ) as batchs,
                (grand_total + rounding) as grand_total,
                paid,
                {$this->db->dbprefix('purchases')}.status
            ", FALSE)
            ->from('purchases')
            ->join('purchase_items', 'purchase_items.purchase_id = purchases.id', 'left')
            ->join('product_variants', 'product_variants.id = purchase_items.option_id', 'left')   // added join
            ->join('warehouses', 'warehouses.id = purchases.warehouse_id', 'left')
            ->group_by('purchases.id')
            ->order_by('purchases.date desc');

            if ($this->Owner || $this->Admin) {
                if ($user) {
                    $this->db->where('purchases.created_by', $user);
                }
            } else {
                if ($this->session->userdata('view_right') == '0') {
                    if ($user) {
                        $this->db->where('purchases.created_by', $user);
                    }
                }
            }
            if ($product) {
                $this->db->where('purchase_items.product_id', $product);
            }
            if ($supplier) {
                $this->db->where('purchases.supplier_id', $supplier);
            }
            if ($warehouse) {
                $getwarehouse = str_replace("_", ",", $warehouse);
                $this->db->where('purchases.warehouse_id IN (' . $getwarehouse . ')');
            }
            if ($reference_no) {
                $this->db->like('purchases.reference_no', $reference_no, 'both');
            }
            if ($start_date) {
                $this->db->where('DATE(' . $this->db->dbprefix('purchases') . '.date) BETWEEN "' . $start_date . '" and "' . $end_date . '"');
            }

            $q = $this->db->get();
            
            if ($q->num_rows() > 0) {
                foreach (($q->result()) as $row) {
                    $data[] = $row;
                }
            } else {
                $data = NULL;
            }
            if (!empty($data)) {

                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);
            
                // Title style
                $style = [
                    'alignment' => ['horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER],
                    'font' => ['name' => 'Arial', 'color' => ['rgb' => 'FF0000']],
                    'borders' => ['allborders' => ['style' => PHPExcel_Style_Border::BORDER_NONE]]
                ];
            
                $this->excel->getActiveSheet()->getStyle("A1:J1")->applyFromArray($style);
                $this->excel->getActiveSheet()->mergeCells('A1:J1');
                $this->excel->getActiveSheet()->SetCellValue('A1', 'Purchases Report');
                $this->excel->getActiveSheet()->setTitle(lang('purchase_report'));
            
                // --- Header Row ---
                $this->excel->getActiveSheet()->SetCellValue('A2', lang('date'));
                $this->excel->getActiveSheet()->SetCellValue('B2', lang('reference_no'));
                $this->excel->getActiveSheet()->SetCellValue('C2', lang('warehouse'));
                $this->excel->getActiveSheet()->SetCellValue('D2', lang('supplier'));
                $this->excel->getActiveSheet()->SetCellValue('E2', lang('product'));
                $this->excel->getActiveSheet()->SetCellValue('F2', 'Variant'); // NEW COLUMN

                // Conditional header layout based on batch setting
                if ($this->Settings->product_batch_setting == 1 || $this->Settings->product_batch_setting == 2) {

                    $this->excel->getActiveSheet()->SetCellValue('G2', lang('Batch_No'));
                    $this->excel->getActiveSheet()->SetCellValue('H2', lang('qty'));
                    $this->excel->getActiveSheet()->SetCellValue('I2', lang('grand_total'));
                    $this->excel->getActiveSheet()->SetCellValue('J2', lang('paid'));
                    $this->excel->getActiveSheet()->SetCellValue('K2', lang('balance'));
                    $this->excel->getActiveSheet()->SetCellValue('L2', lang('status'));
                    $BatchEnabled = true;

                } else {

                    $this->excel->getActiveSheet()->SetCellValue('G2', lang('Qty'));
                    $this->excel->getActiveSheet()->SetCellValue('H2', lang('grand_total'));
                    $this->excel->getActiveSheet()->SetCellValue('I2', lang('paid'));
                    $this->excel->getActiveSheet()->SetCellValue('J2', lang('balance'));
                    $this->excel->getActiveSheet()->SetCellValue('K2', lang('status'));
                    $BatchEnabled = false;
                }
            
                $row = 3;
                $total = 0;
                $paid = 0;
                $balance = 0;
                foreach ($data as $data_row) {

                    // Split product, variant, qty lists
                    $product_arr = explode("\n", $data_row->iname);
                    
                    $variant_arr = explode("\n", $data_row->variant_list);
                    $qty_arr     = explode("\n", $data_row->qty_list);
                
                    $len1 = count($product_arr);
                
                    // Merge static columns
                    $this->excel->getActiveSheet()->mergeCells("A{$row}:A" . ($row + $len1 - 1));
                    $this->excel->getActiveSheet()->SetCellValue("A{$row}", $this->sma->hrld($data_row->date));
                
                    $this->excel->getActiveSheet()->mergeCells("B{$row}:B" . ($row + $len1 - 1));
                    $this->excel->getActiveSheet()->SetCellValue("B{$row}", $data_row->reference_no);
                
                    $this->excel->getActiveSheet()->mergeCells("C{$row}:C" . ($row + $len1 - 1));
                    $this->excel->getActiveSheet()->SetCellValue("C{$row}", $data_row->wname);
                
                    $this->excel->getActiveSheet()->mergeCells("D{$row}:D" . ($row + $len1 - 1));
                    $this->excel->getActiveSheet()->SetCellValue("D{$row}", $data_row->supplier);
                
                    // --- Product / Variant / Batch / Qty Rows ---
                    for ($i = 0; $i < $len1; $i++) {
                
                        $product_name = trim($product_arr[$i]);
                        $variant_name = isset($variant_arr[$i]) ? trim($variant_arr[$i]) : '';
                        $formatted_qty = $this->sma->formatQuantity(trim($qty_arr[$i]));
                
                        // Batch list
                        $batch_list = [];
                        if (!empty($data_row->batchs)) {
                            $batch_list = explode(',', $data_row->batchs);
                        }
                        $batch_value = isset($batch_list[$i]) ? trim($batch_list[$i]) : '';
                
                        // Product
                        $this->excel->getActiveSheet()->SetCellValue('E' . ($row + $i), $product_name);
                        $this->excel->getActiveSheet()->getStyle('E' . ($row + $i))
                            ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                        // Variant (NEW)
                        $this->excel->getActiveSheet()->SetCellValue('F' . ($row + $i), $variant_name);
                        $this->excel->getActiveSheet()->getStyle('F' . ($row + $i))
                            ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                        if ($BatchEnabled) {
                
                            // Batch No
                            $this->excel->getActiveSheet()->SetCellValue('G' . ($row + $i), $batch_value);
                            $this->excel->getActiveSheet()->getStyle('G' . ($row + $i))
                                ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                            // Qty
                            $this->excel->getActiveSheet()->setCellValueExplicit(
                                'H' . ($row + $i),
                                $formatted_qty,
                                PHPExcel_Cell_DataType::TYPE_STRING
                            );
                            $this->excel->getActiveSheet()->getStyle('H' . ($row + $i))
                                ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                
                        } else {
                
                            // Qty (no batch mode)
                            $this->excel->getActiveSheet()->setCellValueExplicit(
                                'G' . ($row + $i),
                                $formatted_qty,
                                PHPExcel_Cell_DataType::TYPE_STRING
                            );
                            $this->excel->getActiveSheet()->getStyle('G' . ($row + $i))
                                ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                        }
                    }
                
                    // Totals / merged columns based on batch setting
                    $grandCol = $BatchEnabled ? 'I' : 'H';
                    $paidCol  = $BatchEnabled ? 'J' : 'I';
                    $balCol   = $BatchEnabled ? 'K' : 'J';
                    $statCol  = $BatchEnabled ? 'L' : 'K';
                
                    $this->excel->getActiveSheet()->mergeCells("{$grandCol}{$row}:{$grandCol}" . ($row + $len1 - 1));
                    // GRAND TOTAL
                    $this->excel->getActiveSheet()->mergeCells("{$grandCol}{$row}:{$grandCol}" . ($row + $len1 - 1));
                    $this->excel->getActiveSheet()->SetCellValue("{$grandCol}{$row}", $this->sma->formatMoney($data_row->grand_total));
                    $this->excel->getActiveSheet()->getStyle("{$grandCol}{$row}")
                        ->getAlignment()
                            ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT)
                            ->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);

                    // PAID
                    $this->excel->getActiveSheet()->mergeCells("{$paidCol}{$row}:{$paidCol}" . ($row + $len1 - 1));
                    $this->excel->getActiveSheet()->SetCellValue("{$paidCol}{$row}", $this->sma->formatMoney($data_row->paid));
                    $this->excel->getActiveSheet()->getStyle("{$paidCol}{$row}")
                        ->getAlignment()
                            ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT)
                            ->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);

                    // BALANCE
                    $this->excel->getActiveSheet()->mergeCells("{$balCol}{$row}:{$balCol}" . ($row + $len1 - 1));
                    $this->excel->getActiveSheet()->SetCellValue("{$balCol}{$row}", $this->sma->formatMoney($data_row->grand_total - $data_row->paid));
                    $this->excel->getActiveSheet()->getStyle("{$balCol}{$row}")
                        ->getAlignment()
                            ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT)
                            ->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);
                    $this->excel->getActiveSheet()->mergeCells("{$statCol}{$row}:{$statCol}" . ($row + $len1 - 1));
                    $this->excel->getActiveSheet()->SetCellValue("{$statCol}{$row}", $data_row->status);
                
                    // Totals accumulation
                    $total += $data_row->grand_total;
                    $paid  += $data_row->paid;
                    $balance += ($data_row->grand_total - $data_row->paid);
                
                    $row += $len1;
                }
                // Final total row
                $gtCol = $BatchEnabled ? 'I' : 'H';
                $pdCol = $BatchEnabled ? 'J' : 'I';
                $blCol = $BatchEnabled ? 'K' : 'J';

                $this->excel->getActiveSheet()->getStyle("{$gtCol}{$row}:{$pdCol}{$row}")
                    ->getBorders()->getTop()->setBorderStyle(PHPExcel_Style_Border::BORDER_MEDIUM);

                $this->excel->getActiveSheet()->SetCellValue("{$gtCol}{$row}", $this->sma->formatMoney($total));
                $this->excel->getActiveSheet()->getStyle("{$gtCol}{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->SetCellValue("{$pdCol}{$row}", $this->sma->formatMoney($paid));
                $this->excel->getActiveSheet()->getStyle("{$pdCol}{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->SetCellValue("{$blCol}{$row}", $this->sma->formatMoney($balance));
                $this->excel->getActiveSheet()->getStyle("{$blCol}{$row}")
                    ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                // --- Column widths ---
                $this->excel->getActiveSheet()->getColumnDimension('A')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('B')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('C')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('D')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('E')->setWidth(30);  // product
                $this->excel->getActiveSheet()->getColumnDimension('F')->setWidth(20);  // variant (NEW)

                if ($BatchEnabled) {
                    $this->excel->getActiveSheet()->getColumnDimension('G')->setWidth(15); // batch
                    $this->excel->getActiveSheet()->getColumnDimension('H')->setWidth(15); // qty
                    $this->excel->getActiveSheet()->getColumnDimension('I')->setWidth(15); // grand_total
                    $this->excel->getActiveSheet()->getColumnDimension('J')->setWidth(15); // paid
                    $this->excel->getActiveSheet()->getColumnDimension('K')->setWidth(20); // balance
                    $this->excel->getActiveSheet()->getColumnDimension('L')->setWidth(20); // status
                } else {
                    $this->excel->getActiveSheet()->getColumnDimension('G')->setWidth(15); // qty
                    $this->excel->getActiveSheet()->getColumnDimension('H')->setWidth(15); // grand_total
                    $this->excel->getActiveSheet()->getColumnDimension('I')->setWidth(20); // paid
                    $this->excel->getActiveSheet()->getColumnDimension('J')->setWidth(20); // balance
                    $this->excel->getActiveSheet()->getColumnDimension('K')->setWidth(20); // status
                }
            
                $filename = 'purchase_report';
                $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);
            
                if ($xls) {
                    $this->excel->getActiveSheet()->getStyle('E2:E' . $row)->getAlignment()->setWrapText(TRUE);
                    ob_clean();
                    header('Content-Type: application/vnd.ms-excel');
                    header('Content-Disposition: attachment;filename="' . $filename . '.xls"');
                    header('Cache-Control: max-age=0');
                    ob_clean();
                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                    $objWriter->save('php://output');
                    exit();
                }
            }
            
            $this->session->set_flashdata('error', lang('nothing_found'));
            redirect($_SERVER["HTTP_REFERER"]);
        } else {

            $pi = "( SELECT 
                {$this->db->dbprefix('purchase_items')}.purchase_id,
                {$this->db->dbprefix('purchase_items')}.product_id,
                {$this->db->dbprefix('purchase_items')}.subtotal,
            
                /* PRODUCT + VARIANT + QTY */
                GROUP_CONCAT(
                    CONCAT(
                        {$this->db->dbprefix('purchase_items')}.product_name,
                        IF({$this->db->dbprefix('product_variants')}.name IS NOT NULL 
                        AND {$this->db->dbprefix('product_variants')}.name != '',
                            CONCAT(' (', {$this->db->dbprefix('product_variants')}.name, ')'),
                            ''
                        ),
                        '__',
                        {$this->db->dbprefix('purchase_items')}.quantity
                    )
                    SEPARATOR '___'
                ) AS item_nane,
            
                /* BATCH NUMBERS */
                GROUP_CONCAT(
                    DISTINCT NULLIF(NULLIF({$this->db->dbprefix('purchase_items')}.batch_number, ''), 'N/A')
                    ORDER BY {$this->db->dbprefix('purchase_items')}.batch_number 
                    SEPARATOR ', '
                ) AS batch_numbers
            
                FROM {$this->db->dbprefix('purchase_items')}
                LEFT JOIN {$this->db->dbprefix('product_variants')}
                    ON {$this->db->dbprefix('product_variants')}.id = {$this->db->dbprefix('purchase_items')}.option_id
            ";
            if ($product) {
                $pi .= " WHERE {$this->db->dbprefix('purchase_items')}.product_id = {$product} ";
            }
            $pi .= " GROUP BY {$this->db->dbprefix('purchase_items')}.purchase_id ) FPI";
        

            $this->load->library('datatables');
            //$this->datatables->select("DATE_FORMAT({$this->db->dbprefix('purchases')}.date, '%Y-%m-%d %T') as date, reference_no, {$this->db->dbprefix('warehouses')}.name as wname, supplier, (FPI.item_nane) as iname, (grand_total+rounding) as grand_total, paid, (grand_total+rounding-paid) as balance, {$this->db->dbprefix('purchases')}.status, {$this->db->dbprefix('purchases')}.id as id", FALSE)->from('purchases')->join($pi, 'FPI.purchase_id=purchases.id', 'left')->join('warehouses', 'warehouses.id=purchases.warehouse_id', 'left');
            // ->group_by('purchases.id');
            $select = "
                    DATE_FORMAT({$this->db->dbprefix('purchases')}.date, '%Y-%m-%d %T') as date,
                    reference_no,
                    {$this->db->dbprefix('warehouses')}.name as wname,
                    supplier,
                    (FPI.item_nane) as iname,
                ";
                if ($this->Settings->product_batch_setting == 1 || $this->Settings->product_batch_setting == 2) {
                    $select .= "(FPI.batch_numbers) as batchs,";
                }
                $select .= "
                    (grand_total+rounding) as grand_total,
                    paid,
                    (grand_total+rounding-paid) as balance,
                    {$this->db->dbprefix('purchases')}.status,
                    {$this->db->dbprefix('purchases')}.id as id
                ";

                $this->datatables->select($select, FALSE)
