                    ->from('payments')
                    ->join('sales', 'payments.sale_id=sales.id', 'left')
                    ->join('orders', 'payments.order_id=orders.id', 'left')
                    ->join('purchases', 'payments.purchase_id=purchases.id', 'left')
                    ->join('delivery_challan', 'payments.challan_id=delivery_challan.id', 'left')
                    ->join('warehouses', 'sales.warehouse_id=warehouses.id', 'left')
                    ->group_by('payments.id');
            } else {
                $this->datatables->select("DATE_FORMAT({$this->db->dbprefix('payments')}.date, '%d/%m/%Y %T') as date, COALESCE(" . $this->db->dbprefix('sales') . ".customer, " . $this->db->dbprefix('delivery_challan') . ".customer, " . $this->db->dbprefix('orders') . ".customer) as name, " . $this->db->dbprefix('payments') . ".reference_no as payment_ref, COALESCE(" . $this->db->dbprefix('sales') . ".reference_no, " . $this->db->dbprefix('delivery_challan') . ".reference_no, " . $this->db->dbprefix('orders') . ".reference_no, " . $this->db->dbprefix('purchases') . ".reference_no) as sale_ref, COALESCE(" . $this->db->dbprefix('sales') . ".invoice_no, " . $this->db->dbprefix('delivery_challan') . ".challan_no, " . $this->db->dbprefix('orders') . ".invoice_no, " . $this->db->dbprefix('payments') . ".challan_id) as invoice_no, paid_by, {$this->db->dbprefix('payments')}.transaction_id, amount, type, {$this->db->dbprefix('payments')}.note, " . $this->db->dbprefix('purchases') . ".reference_no as purchase_ref, " . $this->db->dbprefix('orders') . ".reference_no as order_ref, {$this->db->dbprefix('payments')}.id as id")
                    ->from('payments')
                    ->join('sales', 'payments.sale_id=sales.id', 'left')
