    }
    // Customers Report: Customer deposit
    function getCustomersData($pdf = NULL, $xls = NULL, $img = NULL) {
        $this->sma->checkPermissions('customers', TRUE);
        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;
        $customer_group = $this->input->get('customer_group') ?$this->input->get('customer_group'): NULL;
        $user = $this->input->post('user');
        $customer = $this->input->post('customer');
        $biller = $this->input->post('biller');
        $warehouse = $this->input->post('warehouse');
        $filter_sale_type = $this->input->post('filter_sale_type');

        if ($start_date) {
            $start_date = $this->sma->fld($start_date);
            $end_date = $this->sma->fld($end_date);
        }
        $start_date_full = $start_date . ' 00:00:00';
        $end_date_full   = $end_date . ' 23:59:59';
        $type = $this->input->post('type') ?: 'customer';

        if ($pdf || $xls || $img) {
           
            $type = $this->input->get('type') ?: 'customer';
            $user = $this->input->get('user');
            $customer = $this->input->get('customer');
            $biller = $this->input->get('biller');
            $warehouse = $this->input->get('warehouse');
            $filter_sale_type = $this->input->get('filter_sale_type');
                        
            if ($type === 'customer') {
                $phone_select = $this->customerPhoneReportSelect($this->db->dbprefix('companies'));
                $this->db->select("
                    {$this->db->dbprefix('companies')}.id AS id,
                    company,
                    name,
                    {$phone_select},
                    email,
                    COUNT({$this->db->dbprefix('sales')}.id) AS total,
                    (COALESCE(SUM(grand_total), 0) + COALESCE(SUM(rounding), 0)) AS total_amount,
                    COALESCE(SUM(paid), 0) AS paid,
                    (COALESCE(SUM(grand_total), 0) + COALESCE(SUM(rounding), 0)) AS recharge_amount,
                    COALESCE(SUM(paid), 0) AS used_amount,
                    ((COALESCE(SUM(grand_total), 0) + COALESCE(SUM(rounding), 0)) - COALESCE(SUM(paid), 0)) AS balance,
                    (COALESCE(SUM(grand_total), 0) + COALESCE(SUM(rounding), 0)) - COALESCE(SUM(paid), 0) AS deposit_amount
                ", FALSE)
                ->from("{$this->db->dbprefix('companies')}")
                ->join("{$this->db->dbprefix('sales')}", "sales.customer_id=companies.id", 'left')
                ->where("{$this->db->dbprefix('companies')}.group_name", 'customer')
                ->where("{$this->db->dbprefix('companies')}.customer_group_name !=", 'Walk in Customer')
                ->group_by("{$this->db->dbprefix('companies')}.id");

                if (!empty($customer_group)) {
                    $this->db->where("{$this->db->dbprefix('companies')}.customer_group_id", $customer_group);
                }

            } elseif ($type === 'walkin') {
                $this->db->select("
                    'Walk-in Customers' AS name,
                    COUNT({$this->db->dbprefix('sales')}.id) AS total,
                    (COALESCE(SUM(grand_total), 0) + COALESCE(SUM(rounding), 0)) AS total_amount,
                    COALESCE(SUM(paid), 0) AS paid,
                    ((COALESCE(SUM(grand_total), 0) + COALESCE(SUM(rounding), 0)) - COALESCE(SUM(paid), 0)) AS balance,
                    SUM({$this->db->dbprefix('companies')}.deposit_amount) AS deposit_amount
                ", FALSE)
                ->from("{$this->db->dbprefix('companies')}")
                ->join("{$this->db->dbprefix('sales')}", "sales.customer_id=companies.id", 'left')
                ->where("{$this->db->dbprefix('companies')}.group_name", 'customer')
                ->where("{$this->db->dbprefix('companies')}.customer_group_name", 'Walk in Customer');
            }

            // 📅 Date filter
            if (!empty($start_date)) {
                $this->db->where("DATE({$this->db->dbprefix('sales')}.date) >=", $start_date);
                $this->db->where("DATE({$this->db->dbprefix('sales')}.date) <=", $end_date);
            }

            // // 👤 User filter
            if ($type === 'customer' && !empty($user)) {
                $this->db->where("{$this->db->dbprefix('sales')}.created_by", $user);
            }

            // // 🔍 Specific customer (by name)
            if ($type === 'customer' && !empty($customer)) {
                $this->db->like("{$this->db->dbprefix('companies')}.id", $customer);
            }

            // // 🧾 Biller
            if ($type === 'customer' && !empty($biller)) {
                $this->db->where("{$this->db->dbprefix('sales')}.biller_id", $biller);
            }

            // // 🏢 Warehouse
            if ($type === 'customer' && !empty($warehouse)) {
                $this->db->where("{$this->db->dbprefix('sales')}.warehouse_id", $warehouse);
            }

            // // 🔄 Order by Sale type (only for customer type)
            if ($type === 'customer' && $type === 'customer') {
                if (!empty($filter_sale_type)) {
                    if ($filter_sale_type === 'No_sale') {
                        $this->db->having('total', 0);
                    } elseif ($filter_sale_type === 'Top_Sale') {
                        $this->db->order_by('total_amount', 'DESC');
                    } elseif ($filter_sale_type === 'Bottom_Sale') {
                        $this->db->order_by('total_amount', 'ASC');
                    }
                }
            }

            // // Default order if no specific order set
            if ($type === 'customer' && empty($filter_sale_type)) {
                $this->db->order_by("{$this->db->dbprefix('companies')}.company", 'ASC');
            }

            // 🔎 Run query
            $q = $this->db->get();

            if ($q->num_rows() > 0) {
                foreach ($q->result() as $row) {
                    $data[] = $row;
                }
            } else {
                $data = NULL;
            }


            if (!empty($data)) {
                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);

                // Common heading
                $this->excel->getActiveSheet()->mergeCells('A1:H1');
                $this->excel->getActiveSheet()->setCellValue('A1', ucfirst($type).' Report');
                $this->excel->getActiveSheet()->getStyle("A1:H1")->applyFromArray([
                    'alignment' => ['horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER],
                    'font' => ['bold' => true, 'size' => 14]
                ]);

                $row = 2;

                if ($type == 'customer') {
                    // Headers
                    $headers = ['Company', 'Name', 'Phone', 'Email', 'Total Sales', 'Total Amount', 'Paid', 'Balance', 'Recharge', 'Used', 'Deposit'];
                    $col = 'A';
                    foreach ($headers as $header) {
                        $this->excel->getActiveSheet()->setCellValue($col.$row, $header);
                        $col++;
                    }

                    $row++;

                    // Initialize totals
                    $total_sales = $total_amount = $total_paid = $total_balance = $total_recharge = $total_used = $total_deposit_balance = 0;

                    foreach ($data as $data_row) {
                        $getDeposit = $this->reports_model->getDepositReEx($data_row->id, $start_date, $end_date);

                        $used_amount = $data_row->paid;
                        $deposit_balance = ($getDeposit['recharge_amount'] - $data_row->paid) < 0 ? 0 : ($getDeposit['recharge_amount'] - $data_row->paid);

                        // update totals
                        $total_sales           += $data_row->total;
                        $total_amount          += $data_row->total_amount;
                        $total_paid            += $data_row->paid;
                        $total_balance         += $data_row->balance;
                        $total_recharge        += $getDeposit['recharge_amount'];
                        $total_used            += $used_amount;
                        $total_deposit_balance += ($getDeposit['recharge_amount'] > 0)?($getDeposit['recharge_amount'] - $used_amount):0;

                        $this->excel->getActiveSheet()
                            ->setCellValue('A'.$row, $data_row->company)
                            ->setCellValue('B'.$row, $data_row->name)
                            ->setCellValue('C'.$row, $data_row->phone)
                            ->setCellValue('D'.$row, $data_row->email)
                            ->setCellValue('E'.$row, $this->sma->formatQuantity($data_row->total))
                            ->setCellValue('F'.$row, $this->sma->formatMoney($data_row->total_amount))
                            ->setCellValue('G'.$row, $this->sma->formatMoney($data_row->paid))
                            ->setCellValue('H'.$row, $this->sma->formatMoney($data_row->balance))
                            ->setCellValue('I'.$row, $this->sma->formatMoney($getDeposit['recharge_amount']))
                            ->setCellValue('J'.$row, $this->sma->formatMoney($used_amount))
                            ->setCellValue('K'.$row, $this->sma->formatMoney(($getDeposit['recharge_amount'] > 0)?($getDeposit['recharge_amount'] - $used_amount):0));

                        // Align E center
                        $this->excel->getActiveSheet()
                            ->getStyle('E'.$row)
                            ->getAlignment()
                            ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);

                        // Align F to K right
                        $this->excel->getActiveSheet()
                            ->getStyle('F'.$row.':K'.$row)
                            ->getAlignment()
                            ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                        $row++;
                    }

                    // Add footer row
                    $this->excel->getActiveSheet()
                        ->setCellValue('D'.$row, 'Total')
                        ->setCellValue('E'.$row, $this->sma->formatQuantity($total_sales))
                        ->setCellValue('F'.$row, $this->sma->formatMoney($total_amount))
                        ->setCellValue('G'.$row, $this->sma->formatMoney($total_paid))
                        ->setCellValue('H'.$row, $this->sma->formatMoney($total_balance))
                        ->setCellValue('I'.$row, $this->sma->formatMoney($total_recharge))
                        ->setCellValue('J'.$row, $this->sma->formatMoney($total_used))
                        ->setCellValue('K'.$row, $this->sma->formatMoney($total_deposit_balance));

                    // Style footer
                    $this->excel->getActiveSheet()
                        ->getStyle('D'.$row.':K'.$row)
                        ->getFont()
                        ->setBold(true);

                    // Align footer
                    $this->excel->getActiveSheet()
                        ->getStyle('E'.$row)
                        ->getAlignment()
                        ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);

                    $this->excel->getActiveSheet()
                        ->getStyle('F'.$row.':K'.$row)
                        ->getAlignment()
                        ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                }elseif ($type == 'walkin') {
                    // Headers for walk-in
                    $headers = ['Name', 'Total Sales', 'Total Amount', 'Paid'];
                    $col = 'A';
                    foreach ($headers as $header) {
                        $this->excel->getActiveSheet()->setCellValue($col.$row, $header);
                        $col++;
                    }
                
                    $row++;
                
                    foreach ($data as $data_row) {
                        $this->excel->getActiveSheet()
                            ->setCellValue('A'.$row, $data_row->name)
                            ->setCellValue('B'.$row, $this->sma->formatQuantity($data_row->total))
                            ->setCellValue('C'.$row, $this->sma->formatMoney($data_row->total_amount))
                            ->setCellValue('D'.$row, $this->sma->formatMoney($data_row->paid));
                    // Align B (center)
                    $this->excel->getActiveSheet()
                    ->getStyle('B'.$row)
                    ->getAlignment()
                    ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);

                    // Align C and D (right)
                    $this->excel->getActiveSheet()
                    ->getStyle('C'.$row.':D'.$row)
                    ->getAlignment()
                    ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                        $row++;
                    }
                }

                // Column widths (adjust as needed)
                foreach (range('A', 'K') as $columnID) {
                    $this->excel->getActiveSheet()->getColumnDimension($columnID)->setAutoSize(true);
                }

                $filename = ($type == 'customer' ? 'customers_report' : 'walkin_customers_report');

                $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);
                if ($pdf) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($xls) {
                    ob_clean();
                    header('Content-Type: application/vnd.ms-excel');
                    header('Content-Disposition: attachment;filename="' . $filename . '.xls"');
                    header('Cache-Control: max-age=0');
                    ob_clean();
                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($img) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save(str_replace(__FILE__, 'assets/mdata/'.$this->Customer_assets.'/uploads/pdf/customers.pdf', __FILE__));
                    redirect("reports/create_image/customers.pdf");
                    exit();
                }
            }
            $this->session->set_flashdata('error', lang('nothing_found'));
            redirect($_SERVER["HTTP_REFERER"]);
        } else {
            
            $s = "( SELECT customer_id, 
            count(" . $this->db->dbprefix('sales') . ".id) as total, 
            (COALESCE(sum(grand_total), 0) + COALESCE(sum(rounding), 0)) as total_amount, 
            COALESCE(sum(paid), 0) as paid, 
            (COALESCE(sum(grand_total), 0) + COALESCE(sum(rounding), 0) - COALESCE(sum(paid), 0)) as balance, 
            DATE_FORMAT(MAX(date), '%Y-%m-%d %T') AS last_invoice_date 
        FROM {$this->db->dbprefix('sales')}";

            // build WHERE conditions for the subquery
            $whereAdded = false;

            // date range
            if (!empty($start_date) && !empty($end_date)) {
                $s .= " WHERE ({$this->db->dbprefix('sales')}.date >= '$start_date_full' 
                        AND {$this->db->dbprefix('sales')}.date <= '$end_date_full')";
                $whereAdded = true;
            }

            // user
            if (!empty($user)) {
                $s .= $whereAdded ? " AND " : " WHERE ";
                $s .= "{$this->db->dbprefix('sales')}.created_by = '$user'";
                $whereAdded = true;
            }

            // biller
            if (!empty($biller)) {
                $s .= $whereAdded ? " AND " : " WHERE ";
                $s .= "{$this->db->dbprefix('sales')}.biller_id = '$biller'";
                $whereAdded = true;
            }

            // warehouse
            if (!empty($warehouse)) {
                $s .= $whereAdded ? " AND " : " WHERE ";
                $s .= "{$this->db->dbprefix('sales')}.warehouse_id = '$warehouse'";
                $whereAdded = true;
            }
            if ($type === 'customer') {
                if (!empty($filter_sale_type) && $filter_sale_type == 'No_sale') {
                    $this->db->where("(FS.total_amount <= 0)");
                }
            }
            
            $s .= " GROUP BY {$this->db->dbprefix('sales')}.customer_id ) FS";

            $this->load->library('datatables');

            // SELECT columns
            if ($type === 'customer') {
                $phone_select = $this->customerPhoneReportSelect('sma_companies');
                $this->datatables->select("
                    sma_companies.id AS dummy_checkbox,   
                    company, 
                    name, 
                    {$phone_select}, 
                    email,
                    FS.total, 
                    FS.total_amount, 
                    FS.paid, 
                    FS.balance,
                    sma_companies.deposit_amount AS recharge_amount, 
                    FS.paid AS used_amount,
                    (sma_companies.deposit_amount - FS.paid) AS deposit_balance,
                    FS.last_invoice_date,
                    sma_companies.id AS id
                ", FALSE);


            } elseif ($type === 'walkin') {
                $this->datatables->select("
                    SUM(FS.total) AS total,
                    SUM(FS.total_amount) AS total_amount,
                    SUM(FS.paid) AS paid,
                    SUM(FS.balance) AS balance,
                    NULL, NULL,
                    SUM(sma_companies.deposit_amount) AS deposit,
                    '' AS id
                ", FALSE);
            }

            $this->datatables->from("companies")
                ->join($s, 'FS.customer_id=companies.id');

            // outer filters
            $this->datatables->where('companies.group_name', 'customer');

            if ($type === 'customer') {
                $this->datatables->where('companies.customer_group_name !=', 'Walk in Customer');

                if (!empty($customer_group)) {
                    $this->datatables->where('companies.customer_group_id', $customer_group);
                }

                if (!empty($customer)) {
                    $this->datatables->like('companies.id', $customer);
                }
                // if ($filter_sale_type == 'No_sale') {
                //     $this->datatables->having('FS.total', 0);
                // }
                
                        // $this->datatables->order_by('companies.id');

                $this->datatables->group_by('companies.id');

            } elseif ($type === 'walkin') {
                $this->datatables->where('companies.customer_group_name', 'Walk in Customer');
            }

            $this->datatables->unset_column('id');

            $start_date_safe = urlencode(trim($start_date));
            $end_date_safe   = urlencode(trim($end_date));
            if ($type === 'customer') {
                $this->datatables->add_column(
                    "Actions",
                    "
                    <div class='action-buttons' style='display: flex; gap: 4px; justify-content: center;'>
                        <a class='tip' data-toggle='modal' data-target='#myModal2' title='Add Payment' 
                        href='" . site_url('reports/add_payment/') . "$1'>
                            <i class='fa fa-money text-primary'></i>
                        </a>
                        <a class='tip' title='View Report' 
                        href='" . site_url('reports/customer_report/') . "$1/{$start_date_safe}/{$end_date_safe}'>
                            <i class='fa fa-eye text-info'></i>
                        </a>
                        <a class='tip send-whatsapp' href='#' data-id='$1' title='Send Reminder'>
                            <i class='fa fa-bell text-warning'></i>
                        </a>
                    </div>
                    ",
                    "id"
                );
 
            }

            echo $this->datatables->generate();
        }
    }
