    function getRrgisterlogs($pdf = NULL, $xls = NULL, $img = NULL) {
        $this->sma->checkPermissions('register-report', TRUE);
        if ($this->input->get('user')) {
            $user = $this->input->get('user');
        } else {
            $user = NULL;
        }
        if ($this->input->get('start_date')) {
            $start_date = $this->input->get('start_date');
        } else {
            $start_date = NULL;
        }
        if ($this->input->get('end_date')) {
            $end_date = $this->input->get('end_date');
        } else {
            $end_date = NULL;
        }
        if ($start_date) {
            $start_date = $this->sma->fld($start_date);
            $end_date = $this->sma->fld($end_date);
        }

        if ($pdf || $xls || $img) {

            $this->db->select("
                date,
                closed_at,
                CONCAT(".$this->db->dbprefix('users').".first_name, ' ', ".$this->db->dbprefix('users').".last_name, ' (', users.email, ')') as user,
                cash_in_hand,
                total_cc_slips,
                total_cheques,
                total_cash,
                total_cc_slips_submitted,
                total_cheques_submitted,
                total_cash_submitted".
                (($this->pos_settings->display_coinage) ? ",
                withdrawal,
                bank_deposit" : "").",
                note
            ", FALSE)
            ->from("pos_register")
            ->join('users', 'users.id=pos_register.user_id', 'left')
            ->order_by('date desc');
        
            if ($user) {
                $this->db->where('pos_register.user_id', $user);
            }
            if ($start_date) {
                $this->db->where('DATE(date) BETWEEN "' . $start_date . '" and "' . $end_date . '"');
            }
        
            $q = $this->db->get();
            if ($q->num_rows() > 0) {
                foreach ($q->result() as $row) {
                    $data[] = $row;
                }
            } else {
                $data = NULL;
            }
        
            if (!empty($data)) {
        
                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);
        
                // Title
                $style = [
                    'alignment' => ['horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER],
                    'font' => ['name' => 'Arial', 'color' => ['rgb' => 'FF0000']],
                    'borders' => ['allborders' => ['style' => PHPExcel_Style_Border::BORDER_NONE]]
                ];
        
                $titleEndCol = ($this->pos_settings->display_coinage) ? 'M' : 'K';
                $this->excel->getActiveSheet()->mergeCells("A1:{$titleEndCol}1");
                $this->excel->getActiveSheet()->getStyle("A1:{$titleEndCol}1")->applyFromArray($style);
                $this->excel->getActiveSheet()->SetCellValue('A1', 'Register Report');
        
                // Headers
                $this->excel->getActiveSheet()->SetCellValue('A2', 'Open Time');
                $this->excel->getActiveSheet()->SetCellValue('B2', 'Close Time');
                $this->excel->getActiveSheet()->SetCellValue('C2', 'User');
                $this->excel->getActiveSheet()->SetCellValue('D2', 'Cash In Hand');

                $this->excel->getActiveSheet()->SetCellValue('E2', 'CC Slips');
                $this->excel->getActiveSheet()->SetCellValue('F2', 'CC Slips Submitted');

                $this->excel->getActiveSheet()->SetCellValue('G2', 'Cheques');
                $this->excel->getActiveSheet()->SetCellValue('H2', 'Cheques Submitted');

                $this->excel->getActiveSheet()->SetCellValue('I2', 'Total Cash');
                $this->excel->getActiveSheet()->SetCellValue('J2', 'Total Cash Submitted');
                
                if($this->pos_settings->display_coinage) {
                    $this->excel->getActiveSheet()->SetCellValue('K2', 'Withdrawal');
                    $this->excel->getActiveSheet()->SetCellValue('L2', 'Bank Deposit');
                    $noteCol = 'M';
                } else {
                    $noteCol = 'K';
                }
                $this->excel->getActiveSheet()->SetCellValue($noteCol.'2', 'Note');
        
                // ---------------- HEADER STYLING ---------------- //
                $headerStyle = [
                    'font' => [
                        'bold' => true,
                        'color' => ['rgb' => '000000'],
                        'size' => 11
                    ],
                    'alignment' => [
                        'horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,
                        'vertical'   => PHPExcel_Style_Alignment::VERTICAL_CENTER
                    ],
                    'fill' => [
                        'type' => PHPExcel_Style_Fill::FILL_SOLID,
                        'color' => ['rgb' => 'E8E8E8']
                    ],
                    'borders' => [
                        'allborders' => [
                            'style' => PHPExcel_Style_Border::BORDER_THIN,
                            'color' => ['rgb' => '000000']
                        ]
                    ]
                ];

                $this->excel->getActiveSheet()
                ->getStyle("A2:{$noteCol}2")
                ->applyFromArray($headerStyle);
                $this->excel->getActiveSheet()->getRowDimension(2)->setRowHeight(22);

                // ---------------- DATA ROW BORDERS + ALIGNMENT ---------------- //
                $dataStyle = [
                    'borders' => [
                        'allborders' => [
                            'style' => PHPExcel_Style_Border::BORDER_THIN,
                            'color' => ['rgb' => '000000']
                        ]
                    ],
                    'alignment' => [
                        'vertical' => PHPExcel_Style_Alignment::VERTICAL_CENTER
                    ]
                ];

                // Apply row-by-row while inserting data
                $row = 3;
                foreach ($data as $data_row) {
                    $this->excel->getActiveSheet()->SetCellValue('A'.$row, $this->sma->hrld($data_row->date));
                    $this->excel->getActiveSheet()->SetCellValue('B'.$row, $data_row->closed_at);
                    $this->excel->getActiveSheet()->SetCellValue('C'.$row, $data_row->user);

                    $this->excel->getActiveSheet()->setCellValueExplicit('D'.$row, $this->sma->formatMoney($data_row->cash_in_hand), PHPExcel_Cell_DataType::TYPE_STRING);

                    // E, F
                    $this->excel->getActiveSheet()->setCellValueExplicit('E'.$row, $this->sma->formatQuantity($data_row->total_cc_slips), PHPExcel_Cell_DataType::TYPE_STRING);
                    $this->excel->getActiveSheet()->setCellValueExplicit('F'.$row, $this->sma->formatQuantity($data_row->total_cc_slips_submitted), PHPExcel_Cell_DataType::TYPE_STRING);

                    // G, H
                    $this->excel->getActiveSheet()->setCellValueExplicit('G'.$row, $this->sma->formatQuantity($data_row->total_cheques), PHPExcel_Cell_DataType::TYPE_STRING);
                    $this->excel->getActiveSheet()->setCellValueExplicit('H'.$row, $this->sma->formatQuantity($data_row->total_cheques_submitted), PHPExcel_Cell_DataType::TYPE_STRING);

                    // I, J
                    $this->excel->getActiveSheet()->setCellValueExplicit('I'.$row, $this->sma->formatMoney($data_row->total_cash), PHPExcel_Cell_DataType::TYPE_STRING);
                    $this->excel->getActiveSheet()->setCellValueExplicit('J'.$row, $this->sma->formatMoney($data_row->total_cash_submitted), PHPExcel_Cell_DataType::TYPE_STRING);
                    
                    if($this->pos_settings->display_coinage) {
                        // K, L
                        $this->excel->getActiveSheet()->setCellValueExplicit('K'.$row, $this->sma->formatMoney($data_row->withdrawal), PHPExcel_Cell_DataType::TYPE_STRING);
                        $this->excel->getActiveSheet()->setCellValueExplicit('L'.$row, $this->sma->formatMoney($data_row->bank_deposit), PHPExcel_Cell_DataType::TYPE_STRING);
                        $noteCol = 'M';
                    } else {
                        $noteCol = 'K';
                    }
                    
                    // Note column
                    $this->excel->getActiveSheet()->SetCellValue($noteCol.$row, $data_row->note);
                    
                    $lastCol = $noteCol;
                    $this->excel->getActiveSheet()->getStyle("A{$row}:{$lastCol}{$row}")->applyFromArray($dataStyle);
                    
                    // Right-align only MONEY columns
                    $this->excel->getActiveSheet()
                        ->getStyle("D{$row}:D{$row}")  // Cash in hand
                        ->getAlignment()
                        ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $this->excel->getActiveSheet()
                        ->getStyle("I{$row}:J{$row}")  // Total cash + submitted
                        ->getAlignment()
                        ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    if($this->pos_settings->display_coinage) {
                        $this->excel->getActiveSheet()
                            ->getStyle("K{$row}:L{$row}") // Withdrawal & Bank Deposit
                            ->getAlignment()
                            ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                    }

                    // ✅ Center-align QUANTITY columns E–H
                    $this->excel->getActiveSheet()
                        ->getStyle("E{$row}:H{$row}")
                        ->getAlignment()
                        ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);

                    $row++;
                }

                // ---------------- BORDER AROUND FULL TABLE ---------------- //
                $lastRow = $row - 1;
                $this->excel->getActiveSheet()->getStyle("A2:{$lastCol}{$lastRow}")->applyFromArray([
                    'borders' => [
                        'outline' => [
                            'style' => PHPExcel_Style_Border::BORDER_MEDIUM,
                            'color' => ['rgb' => '000000']
                        ]
                    ]
                ]);
                // ---------------- ADD TOTAL ROW ---------------- //
                $tot_cash_in_hand     = 0;
                $tot_cc_slips         = 0;
                $tot_cheques          = 0;
                $tot_total_cash       = 0;
                if($this->pos_settings->display_coinage) {
                    $tot_withdrawal       = 0;
                    $tot_bank_deposit     = 0;
                }
                $tot_cc_slips_submitted = 0;
                $tot_cheques_submitted  = 0;
                $tot_cash_submitted     = 0;
                
                // calculate totals
                foreach ($data as $d) {
                    $tot_cash_in_hand     += floatval($d->cash_in_hand);
                    $tot_cc_slips         += floatval($d->total_cc_slips);
                    $tot_cheques          += floatval($d->total_cheques);
                    $tot_total_cash       += floatval($d->total_cash);
                    if($this->pos_settings->display_coinage) {
                        $tot_withdrawal       += floatval($d->withdrawal);
                        $tot_bank_deposit     += floatval($d->bank_deposit);
                    }
                    $tot_cc_slips_submitted += floatval($d->total_cc_slips_submitted);
                    $tot_cheques_submitted  += floatval($d->total_cheques_submitted);
                    $tot_cash_submitted     += floatval($d->total_cash_submitted);
                }

                // Total row position
                $totalRow = $row;

                $this->excel->getActiveSheet()->mergeCells("A{$totalRow}:C{$totalRow}");
                $this->excel->getActiveSheet()->SetCellValue("A{$totalRow}", "TOTAL");
                
                // D
                $this->excel->getActiveSheet()->setCellValueExplicit("D{$totalRow}", $this->sma->formatMoney($tot_cash_in_hand), PHPExcel_Cell_DataType::TYPE_STRING);
                
                // E, F
                $this->excel->getActiveSheet()->setCellValueExplicit("E{$totalRow}", $this->sma->formatQuantity($tot_cc_slips), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->setCellValueExplicit("F{$totalRow}", $this->sma->formatQuantity($tot_cc_slips_submitted), PHPExcel_Cell_DataType::TYPE_STRING);
                
                // G, H
                $this->excel->getActiveSheet()->setCellValueExplicit("G{$totalRow}", $this->sma->formatQuantity($tot_cheques), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->setCellValueExplicit("H{$totalRow}", $this->sma->formatQuantity($tot_cheques_submitted), PHPExcel_Cell_DataType::TYPE_STRING);
                
                // I, J
                $this->excel->getActiveSheet()->setCellValueExplicit("I{$totalRow}", $this->sma->formatMoney($tot_total_cash), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->setCellValueExplicit("J{$totalRow}", $this->sma->formatMoney($tot_cash_submitted), PHPExcel_Cell_DataType::TYPE_STRING);
                
                if($this->pos_settings->display_coinage) {
                    // K, L
                    $this->excel->getActiveSheet()->setCellValueExplicit("K{$totalRow}", $this->sma->formatMoney($tot_withdrawal), PHPExcel_Cell_DataType::TYPE_STRING);
                    $this->excel->getActiveSheet()->setCellValueExplicit("L{$totalRow}", $this->sma->formatMoney($tot_bank_deposit), PHPExcel_Cell_DataType::TYPE_STRING);
                    $totalNoteCol = 'M';
                } else {
                    $totalNoteCol = 'K';
                }
                
                // Note column
                $this->excel->getActiveSheet()->SetCellValue($totalNoteCol.$totalRow, "");
                $this->excel->getActiveSheet()
                ->getStyle("E{$totalRow}:H{$totalRow}")
                ->getAlignment()
                ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                // Styling total row
                $TotalRowStyle = [
                    'font' => [
                        'bold' => true,
                        'color' => ['rgb' => '000000']
                    ],
                    'fill' => [
                        'type' => PHPExcel_Style_Fill::FILL_SOLID,
                        'color' => ['rgb' => 'FFF2CC']  // light yellow
                    ],
                    'borders' => [
                        'allborders' => [
                            'style' => PHPExcel_Style_Border::BORDER_THIN,
                            'color' => ['rgb' => '000000']
                        ]
                    ],
                    'alignment' => [
                        'horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_RIGHT,
                        'vertical'   => PHPExcel_Style_Alignment::VERTICAL_CENTER
                    ]
                ];

                $this->excel->getActiveSheet()->getStyle("A{$totalRow}:{$totalNoteCol}{$totalRow}")
                    ->applyFromArray($TotalRowStyle);
                // ✅ Center-align quantity columns in TOTAL row (E–H)
                $this->excel->getActiveSheet()
                ->getStyle("E{$totalRow}:H{$totalRow}")
                ->getAlignment()
                ->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                // Column Sizes
                $this->excel->getActiveSheet()->getColumnDimension('A')->setWidth(25);
                $this->excel->getActiveSheet()->getColumnDimension('B')->setWidth(25);
                $this->excel->getActiveSheet()->getColumnDimension('C')->setWidth(30);
                $this->excel->getActiveSheet()->getColumnDimension('D')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('E')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('F')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('G')->setWidth(15);

                $this->excel->getActiveSheet()->getColumnDimension('H')->setWidth(18);
                $this->excel->getActiveSheet()->getColumnDimension('I')->setWidth(18);
                $this->excel->getActiveSheet()->getColumnDimension('J')->setWidth(18);

                $this->excel->getActiveSheet()->getColumnDimension('K')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('L')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('M')->setWidth(35);
        
                // ✅ NEW WIDTHS
                $this->excel->getActiveSheet()->getColumnDimension('H')->setWidth(15); // Withdrawal
                $this->excel->getActiveSheet()->getColumnDimension('I')->setWidth(15); // Bank Deposit
        
                $this->excel->getActiveSheet()->getColumnDimension('J')->setWidth(35);
        
                $filename = 'register_report';
                $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);
                if ($pdf) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($xls) {
                    //$this->excel->getActiveSheet()->getStyle('C2:C' . $row)->getAlignment()->setWrapText(true);
                    ob_clean();
                    header('Content-Type: application/vnd.ms-excel');
                    header('Content-Disposition: attachment;filename="' . $filename . '.xls"');
                    header('Cache-Control: max-age=0');
                    ob_clean();
                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($img) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save(str_replace(__FILE__, 'assets/mdata/'.$this->Customer_assets.'/uploads/pdf/register_report.pdf', __FILE__));
                    redirect("reports/create_image/register_report.pdf");
                    exit();
                }
            }
            $this->session->set_flashdata('error', lang('nothing_found'));
            redirect($_SERVER["HTTP_REFERER"]);
        } else {

            $this->load->library('datatables');
        
            $coinage = (
                $this->pos_settings->display_coinage != 0
            );
            $this->datatables
                ->select("
                    date,
                    closed_at,
                    CONCAT(
                        sma_users.first_name, ' ',
                        sma_users.last_name, '<br>',
                        sma_users.email
                    ) AS user,
                    cash_in_hand,
                    CONCAT(total_cc_slips, ' (', total_cc_slips_submitted, ')') AS cc_slips,
                    CONCAT(total_cheques, ' (', total_cheques_submitted, ')') AS cheques,
                    CONCAT(total_cash, ' (', total_cash_submitted, ')') AS total_cash,
                    " . ($coinage
                        ? "withdrawal, bank_deposit,"
                        : "note"
                    ) . "
                    note
                ", false)
                ->from('pos_register')
                ->join('users', 'users.id = pos_register.user_id', 'left');
        
        
            if ($user) {
                $this->datatables->where('pos_register.user_id', $user);
            }
        
            if ($start_date) {
                $this->datatables->where(
                    'DATE(date) BETWEEN "' . $start_date . '" AND "' . $end_date . '"'
                );
            }
     
            echo $this->datatables->generate();
        }
    }

    public function expenses($id = NULL) {
        $this->sma->checkPermissions();
        $this->data['error'] = (validation_errors()) ? validation_errors() : $this->session->flashdata('error');
        $this->data['users'] = $this->reports_model->getStaff();
        $this->data['categories'] = $this->reports_model->getExpenseCategories();
        $this->data['warehouses'] = $this->site->getAllWarehouses();
        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('expenses')));
        $meta = array('page_title' => lang('expenses'), 'bc' => $bc);
        $this->page_construct('reports/expenses', $meta, $this->data);
    }

    public function getExpenseSubCategories($category_id = NULL) {
        $this->sma->checkPermissions('expenses');
        $data = array();
        if ($category_id) {
            $q = $this->db->get_where('expense_categories', array('parent_id' => $category_id));
            if ($q->num_rows() > 0) {
                foreach ($q->result() as $row) {
                    $data[] = array('id' => $row->id, 'text' => $row->name);
                }
            }
        }
        echo !empty($data) ? json_encode($data) : FALSE;
    }

    public function getExpensesReport($pdf = NULL, $xls = NULL, $img = NULL) {
        $this->sma->checkPermissions('expenses');
        $reference_no = $this->input->get('reference_no') ? $this->input->get('reference_no') : NULL;
        $category = $this->input->get('category') ? $this->input->get('category') : NULL;
        $subcategory = $this->input->get('subcategory') ? $this->input->get('subcategory') : NULL;
        $note = $this->input->get('note') ? $this->input->get('note') : NULL;
        $warehouse = $this->input->get('warehouse') ? $this->input->get('warehouse') : NULL;
        $user = $this->input->get('user') ? $this->input->get('user') : NULL;
        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;

        if ($start_date) {
            $start_date = $this->sma->fld($start_date);
            $end_date = $this->sma->fld($end_date);
        }

        if ($pdf || $xls || $img) {

            $this->db->select("date, reference, {$this->db->dbprefix('expense_categories')}.name as category, esc.name as subcategory, amount, note, {$this->db->dbprefix('warehouses') }.name as wname, CONCAT({$this->db->dbprefix('users')}.first_name, ' ', {$this->db->dbprefix('users')}.last_name) as user, attachment, {$this->db->dbprefix('expenses')}.id as id", FALSE)->from('expenses')->join('users', 'users.id=expenses.created_by', 'left')->join('expense_categories', 'expense_categories.id=expenses.category_id', 'left')->join('expense_categories esc', 'esc.id=expenses.subcategory_id', 'left')->join('warehouses', 'warehouses.id=expenses.warehouse_id', 'left')->group_by('expenses.id');

            if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
                $this->db->where('created_by', $this->session->userdata('user_id'));
            }

            if ($note) {
                $this->db->like('note', $note, 'both');
            }
            if ($reference_no) {
                $this->db->like('reference', $reference_no, 'both');
            }
            if ($category) {
                $this->db->where('category_id', $category);
            }
            if ($subcategory) {
                $this->db->where('expenses.subcategory_id', $subcategory);
            }
            if ($warehouse) {
                $getwarehouse = str_replace("_", ",", $warehouse);
                $this->db->where('expenses.warehouse_id IN (' . $getwarehouse . ')');
            }

            if ($user) {
                $this->db->where('created_by', $user);
            }
            if ($start_date) {
                $this->db->where('DATE(date) BETWEEN "' . $start_date . '" and "' . $end_date . '"');
            }

            $q = $this->db->get();
            if ($q->num_rows() > 0) {
                foreach (($q->result()) as $row) {
                    $data[] = $row;
                }
            } else {
                $data = NULL;
            }

            if (!empty($data)) {

                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);

                $style = array('alignment' => array('horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,), 'font' => array('name' => 'Arial', 'color' => array('rgb' => 'FF0000')), 'borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_NONE, 'color' => array('rgb' => 'FF0000'))));

                $this->excel->getActiveSheet()->getStyle("A1:H1")->applyFromArray($style);
                $this->excel->getActiveSheet()->mergeCells('A1:H1');
                $this->excel->getActiveSheet()->SetCellValue('A1', 'Expenses Report');

                $this->excel->getActiveSheet()->setTitle(lang('expenses_report'));
                $this->excel->getActiveSheet()->SetCellValue('A2', lang('date'));
                $this->excel->getActiveSheet()->SetCellValue('B2', lang('reference_no'));
                $this->excel->getActiveSheet()->SetCellValue('C2', lang('category'));
                $this->excel->getActiveSheet()->SetCellValue('D2', ucfirst(lang('subcategory')));
                $this->excel->getActiveSheet()->SetCellValue('E2', lang('amount'));
                $this->excel->getActiveSheet()->SetCellValue('F2', lang('note'));
                $this->excel->getActiveSheet()->SetCellValue('G2', lang('warehouse'));
                $this->excel->getActiveSheet()->SetCellValue('H2', lang('created_by'));

                $row = 3;
                $total = 0;
                foreach ($data as $data_row) {
                    $this->excel->getActiveSheet()->SetCellValue('A' . $row, $this->sma->hrld($data_row->date));
                
                    $this->excel->getActiveSheet()->SetCellValue('B' . $row, $data_row->reference);
                    $this->excel->getActiveSheet()->getStyle('B' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    $this->excel->getActiveSheet()->SetCellValue('C' . $row, $data_row->category);
                    $this->excel->getActiveSheet()->getStyle('C' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    $this->excel->getActiveSheet()->SetCellValue('D' . $row, $data_row->subcategory);
                    $this->excel->getActiveSheet()->getStyle('D' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    $this->excel->getActiveSheet()->SetCellValue('E' . $row, $this->sma->formatMoney($data_row->amount));
                    $this->excel->getActiveSheet()->getStyle('E' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    $this->excel->getActiveSheet()->SetCellValue('F' . $row, $this->sma->clear_tags($data_row->note));
                    $this->excel->getActiveSheet()->getStyle('F' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    $this->excel->getActiveSheet()->SetCellValue('G' . $row, $data_row->wname);
                    $this->excel->getActiveSheet()->getStyle('G' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    $this->excel->getActiveSheet()->SetCellValue('H' . $row, $data_row->user);
                    $this->excel->getActiveSheet()->getStyle('H' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    $total += $data_row->amount;
                    $row++;
                }
                
                $this->excel->getActiveSheet()->SetCellValue('E' . $row, $this->sma->formatMoney($total));
                $this->excel->getActiveSheet()->getStyle('E' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                $this->excel->getActiveSheet()->getStyle("E" . $row)->getBorders()->getTop()->setBorderStyle(PHPExcel_Style_Border::BORDER_MEDIUM);

                $this->excel->getActiveSheet()->getColumnDimension('A')->setWidth(25);
                $this->excel->getActiveSheet()->getColumnDimension('B')->setWidth(25);
                $this->excel->getActiveSheet()->getColumnDimension('C')->setWidth(25);
                $this->excel->getActiveSheet()->getColumnDimension('D')->setWidth(25);
                $this->excel->getActiveSheet()->getColumnDimension('E')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('F')->setWidth(35);
                $this->excel->getActiveSheet()->getColumnDimension('G')->setWidth(25);
                $this->excel->getActiveSheet()->getColumnDimension('H')->setWidth(25);

                $filename = 'expenses_report';
                $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);
                if ($pdf) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($xls) {
                    //$this->excel->getActiveSheet()->getStyle('C2:C' . $row)->getAlignment()->setWrapText(true);
                    ob_clean();
                    header('Content-Type: application/vnd.ms-excel');
                    header('Content-Disposition: attachment;filename="' . $filename . '.xls"');
                    header('Cache-Control: max-age=0');
                    ob_clean();
                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($img) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save(str_replace(__FILE__, 'assets/mdata/'.$this->Customer_assets.'/uploads/pdf/expense.pdf', __FILE__));
                    redirect("reports/create_image/expense.pdf");
                    exit();
                }
            }
            $this->session->set_flashdata('error', lang('nothing_found'));
            redirect($_SERVER["HTTP_REFERER"]);
        } else {

            $this->load->library('datatables');
            $this->datatables->select("DATE_FORMAT(date, '%Y-%m-%d %T') as date, reference, {$this->db->dbprefix('expense_categories')}.name as category, esc.name as subcategory, amount, note, {$this->db->dbprefix('warehouses')}.name as wname, CONCAT({$this->db->dbprefix('users')}.first_name, ' ', {$this->db->dbprefix('users')}.last_name) as user, attachment, {$this->db->dbprefix('expenses')}.id as id", FALSE)->from('expenses')->join('users', 'users.id=expenses.created_by', 'left')->join('expense_categories', 'expense_categories.id=expenses.category_id', 'left')->join('expense_categories esc', 'esc.id=expenses.subcategory_id', 'left')->join('warehouses', 'warehouses.id=expenses.warehouse_id', 'left')->group_by('expenses.id');

            if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
                $this->datatables->where('created_by', $this->session->userdata('user_id'));
            }

            if ($note) {
                $this->datatables->like('note', $note, 'both');
            }
            if ($reference_no) {
                $this->datatables->like('reference', $reference_no, 'both');
            }
            if ($category) {
                $this->datatables->where('category_id', $category);
            }
            if ($subcategory) {
                $this->datatables->where('expenses.subcategory_id', $subcategory);
            }
            if ($warehouse) {
                $getwarehouse = str_replace("_", ",", $warehouse);
                $this->db->where('expenses.warehouse_id IN (' . $getwarehouse . ')');
            }
            if ($user) {
                $this->datatables->where('created_by', $user);
            }
            if ($start_date) {
                $this->datatables->where('DATE(date) BETWEEN "' . $start_date . '" and "' . $end_date . '"');
            }

            echo $this->datatables->generate();
        }
    }

