                $this->excel->getActiveSheet()->SetCellValue('D' . $row, $data_row->shipping);
                $this->excel->getActiveSheet()->SetCellValue('E' . $row, $data_row->tax1);
                $this->excel->getActiveSheet()->SetCellValue('F' . $row, $data_row->tax2);
                $this->excel->getActiveSheet()->SetCellValue('G' . $row, $data_row->total);

                            $total_discount += $data_row->discount;
                            $total_shipping += $data_row->shipping;
                            $total_tax1     += $data_row->tax1;
                            $total_tax2     += $data_row->tax2;
                            $total_total    += $data_row->total;

                            $row++;
                            $sr++;
                        }
                        // ================= TOTAL ROW =================
            $this->excel->getActiveSheet()->mergeCells('A' . $row . ':B' . $row);
            $this->excel->getActiveSheet()->SetCellValue('A' . $row, lang('Total'));
