            $this->excel->getActiveSheet()->SetCellValue('G' . $row, $this->sma->formatMoney($total_total));

            // Make footer bold
            $this->excel->getActiveSheet()->getStyle('A' . $row . ':G' . $row)->applyFromArray(['font' => ['bold' => true],'borders' => ['allborders' => ['style' => PHPExcel_Style_Border::BORDER_THIN] ] ]);
            $row++; // move to next row
            $this->excel->getActiveSheet()->getColumnDimension('A')->setWidth(10);
