            $user = $this->session->userdata('user_id');
        }

        if ($pdf || $xls || $img) {

            /*
              (SELECT  CONCAT('(',ifnull( `sma_purchase_items_tax`.`attr_per`,0),'%)',ifnull(format(sum(`sma_purchase_items_tax`.`tax_amount`),2),0)) FROM   `sma_purchase_items_tax` WHERE  `sma_purchase_items_tax`.`attr_code` = 'CGST' and `sma_purchase_items_tax`.`purchase_id` = `sma_purchases`.`id`) as CGST,
              (SELECT CONCAT('(',ifnull( `sma_purchase_items_tax`.`attr_per`,0),'%)',ifnull(format(sum(`sma_purchase_items_tax`.`tax_amount`),2),0)) FROM   `sma_purchase_items_tax` WHERE  `sma_purchase_items_tax`.`attr_code` = 'SGST' and `sma_purchase_items_tax`.`purchase_id` = `sma_purchases`.`id`) as SGST,
              (SELECT  CONCAT('(',ifnull( `sma_purchase_items_tax`.`attr_per`,0),'%)',ifnull(format(sum(`sma_purchase_items_tax`.`tax_amount`),2),0)) FROM   `sma_purchase_items_tax` WHERE  `sma_purchase_items_tax`.`attr_code` = 'IGST' and `sma_purchase_items_tax`.`purchase_id` = `sma_purchases`.`id`) as IGST,
             */

            $this->db->select("" . $this->db->dbprefix('purchases') . ".date, reference_no, " . $this->db->dbprefix('warehouses') . ".name as wname, supplier,IF(comp.gstn_no IS NULL or comp.gstn_no = '', '-', comp.gstn_no) as gstn_no,
            (SELECT  IF(sma_purchase_items.hsn_code ='' OR sma_purchase_items.hsn_code is null , '', (GROUP_CONCAT( CONCAT(sma_purchase_items.hsn_code,' (',FORMAT(sma_purchase_items.quantity,2),')')SEPARATOR ',') ) )
              as hsn_code FROM   `sma_purchase_items` WHERE   `sma_purchase_items`.`purchase_id` = `sma_purchases`.`id`) as hsn_code,
              cgst AS CGST, sgst AS SGST, igst AS IGST, grand_total, (grand_total - total_tax ) as tax_able_amount, 
 (SELECT (GROUP_CONCAT(DISTINCT CONCAT(' ' , format(tax,2),'%'))) as tax_rate  FROM `sma_purchase_items` WHERE `sma_purchase_items`.`purchase_id` = `sma_purchases`.`id` ) as tax_rate,(SELECT  CONCAT(format(sum(item_tax),2), '')  FROM `sma_purchase_items` WHERE `sma_purchase_items`.`purchase_id` = `sma_purchases`.`id` ) as tax_amt, paid, (grand_total-paid) as balance, {$this->db->dbprefix('purchases')}.status, {$this->db->dbprefix('purchases')}.id as id", FALSE)->from('purchases')->join('companies comp', 'purchases.supplier_id=comp.id', 'left')->join('warehouses', 'warehouses.id=purchases.warehouse_id', 'left');

// paid, " . $this->db->dbprefix('purchases') . ".status", FALSE)->from('purchases')->join('companies comp', 'purchases.supplier_id=comp.id', 'left')->join('warehouses', 'warehouses.id=purchases.warehouse_id', 'left')->group_by('purchases.id')->order_by('purchases.date desc');

            if ($this->session->userdata('view_right') == '0') {
                if ($user) {
                    $this->db->where('purchases.created_by', $user);
                }
            }
            if ($supplier) {
                $this->db->where('purchases.supplier_id', $supplier);
            }
            if ($warehouse) {
                $getwarehouse = str_replace("_", ",", $warehouse);
                $this->db->where('purchases.warehouse_id IN(' . $getwarehouse . ')');
            }
            if ($reference_no) {
                $this->db->like('purchases.reference_no', $reference_no, 'both');
            }
            if ($start_date) {
                //$this->db->where(DATE('.$this->db->dbprefix('purchases') . '.date) BETWEEN "' . $start_date . '" and "' . $end_date . '"');
                $this->db->where('DATE(' . $this->db->dbprefix('purchases') . '.date) >= "' . $start_date . '"');
                $this->db->where('DATE(' . $this->db->dbprefix('purchases') . '.date) <= "' . $end_date . '"');
            }
            if ($gstn_opt) {
                switch ($gstn_opt) {
                    case '-1':
                        $this->db->where("comp.gstn_no IS NULL OR comp.gstn_no = '' ");
                        break;

                    case '1':
                        $this->db->where("comp.gstn_no IS NOT NULL and comp.gstn_no != '' ");
                        break;

                    default:

