                    $this->excel->getActiveSheet()->SetCellValue('N' . $row,$this->sma->formatMoney($data_row->paid));
                    $this->excel->getActiveSheet()->getStyle('N' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    $this->excel->getActiveSheet()->SetCellValue('O' . $row,$this->sma->formatMoney(($data_row->grand_total - $data_row->paid)));
                    $this->excel->getActiveSheet()->getStyle('O' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    $this->excel->getActiveSheet()->SetCellValue('P' . $row, $data_row->status);
