            if ($start_date) {
                $this->datatables->where('DATE(' . $this->db->dbprefix('purchases') . '.date) BETWEEN "' . $start_date . '" and "' . $end_date . '"');
            }
            if ($gstn_opt) {
                switch ($gstn_opt) {
