    function getWarehouseSalesReport($pdf = NULL, $xls = NULL, $img = NULL) {
        $this->sma->checkPermissions('sales', TRUE);

        $start_date = $start_dmy = $this->input->get('start_date') ? $this->input->get('start_date') : date('d/m/Y');
        $end_date = $end_dmy = $this->input->get('end_date') ? $this->input->get('end_date') : date('d/m/Y');
        $report_type = $this->input->get('report_type') ? $this->input->get('report_type') : 1;
        $passwarehouse = ($this->input->get('warehouse')) ? str_replace("_", ",", $this->input->get('warehouse')) : '';


        if ($start_date) {
            $start_date = $this->sma->fld($start_date);
            $end_date = $this->sma->fld($end_date);
        }
        if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
            $user = $this->session->userdata('user_id');
        }

        if ($pdf || $xls || $img) {
            if ($this->input->get('warehouse')) {
                $getwarehouse = str_replace("_", ",", $this->input->get('warehouse'));
            }
            // "sum(grand_total) as net_sale, "
            $this->db->select($this->db->dbprefix('warehouses') .
                            ".id as warehouse_id, " . $this->db->dbprefix('warehouses') .
                            ".name as warehouse, "
                            . "sum(total) as net_total , "
                            . "sum(total_discount) discount, "
                            . "sum(rounding) as rounding, "
                            . "sum(shipping) as shipping, "
                            . "sum(total) as net_sale, "
                            . "sum(total_tax) as tax, "
                            . "count(reference_no) total_bills ", FALSE)
                    ->from('sales')
                    ->join('warehouses', 'warehouses.id=sales.warehouse_id', 'left');
            // ->group_by('sales.warehouse_id');


            if ($start_date) {
                $this->db->where('DATE(' . $this->db->dbprefix('sales') . '.date) BETWEEN "' . $start_date . '" AND "' . $end_date . '"');
            }

            if ($getwarehouse) {
                $this->db->where('sales.warehouse_id IN (' . $getwarehouse . ')');
            }

            if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
                $this->db->where('sales.created_by', $user);
            }
            $this->db->where('sales.sale_status!="returned"');
            $this->db->group_by('sales.warehouse_id');

            $q = $this->db->get();

            if ($q->num_rows() > 0) {
                foreach (($q->result()) as $row) {
                    $data[] = $row;
                }
            } else {
                $data = NULL;
            }

            if (!empty($data)) {
                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);
                $this->excel->getActiveSheet()->mergeCells('A1:I1');
                $this->excel->getActiveSheet()->SetCellValue('A1', 'Warehouse Sales Reports');

                $this->excel->getActiveSheet()->setTitle(lang('warehouse_sales_report'));
                $this->excel->getActiveSheet()->SetCellValue('A2', lang('Branch Name (Warehouses)'));
                $this->excel->getActiveSheet()->SetCellValue('B2', lang('Gross_Sale'));
                $this->excel->getActiveSheet()->SetCellValue('C2', lang('Discount'));
                $this->excel->getActiveSheet()->SetCellValue('D2', lang('Due Amount'));
                $this->excel->getActiveSheet()->SetCellValue('E2', lang('Return  Amount'));
                $this->excel->getActiveSheet()->SetCellValue('F2', lang('Net_Sale'));
                $this->excel->getActiveSheet()->SetCellValue('G2', lang('Cash'));
                $this->excel->getActiveSheet()->SetCellValue('H2', lang('Without Cash'));
                $this->excel->getActiveSheet()->SetCellValue('I2', lang('Total_Tax'));
                $this->excel->getActiveSheet()->SetCellValue('J2', lang('Total Invoices'));
            //                $this->excel->getActiveSheet()->SetCellValue('I2', lang('Items Sold'));

                $row = 3;
                $total_gross_sale = 0;
                $total_discount = 0;
                $total_net_sale = 0;
                $calculate_total_tax = 0;
                $cal_total_bills = 0;
                $total_sold_items = 0;
                $total_due = 0;
                $total_return = 0;
                $total_sales = 0;
                $total_withcash = 0;
                $total_withoutcash = 0;
                foreach ($data as $data_row) {
                    $WithCash = 0;
                    $WithoutCash = 0;
                    $Warehouse_id = $data_row->warehouse_id;
                    $SqlCash = "SELECT p.amount, p.paid_by FROM sma_sales s inner join sma_payments p on s.id=p.sale_id where s.warehouse_id='$Warehouse_id' "; //and  p.paid_by='cash'
                    if ($start_date) {
                        $SqlCash .= " and DATE(s.date) BETWEEN '$start_date' AND '$end_date' ";
                    }
                    $Rescash = $this->db->query($SqlCash);
                    foreach ($Rescash->result() as $rowcash) {
                        if ($rowcash->paid_by == 'cash') {
                            $WithCash += $rowcash->amount;
                        } else {
                            $WithoutCash += $rowcash->amount;
                        }
                    }
                    $net_total = $data_row->net_total;

                    $gross_sale = $data_row->net_total + $data_row->discount + $data_row->tax;

                    /* --- 18-03-19 --- */
                    $duesales = $this->reports_model->getreport($start_date, $end_date, 'due', $data_row->warehouse_id);
                    $returnsales = $this->reports_model->getreport($start_date, $end_date, 'return', $data_row->warehouse_id);
                    $partialamt = $this->reports_model->getreportbalance($start_date, $end_date, $data_row->warehouse_id);
                    $pendingamount = $this->reports_model->getreport($start_date, $end_date, 'pending', $data_row->warehouse_id);
                    $tax = $data_row->tax + $returnsales->tax;
                    $net_sale = ($data_row->net_sale + $data_row->shipping + $data_row->rounding ) + ($returnsales->net_sale + $returnsales->rounding) + $tax;
                    $discount = $data_row->discount + $returnsales->total_discount;

                    $total_dueamt = $duesales->total + $duesales->total_discount + $partialamt + $pendingamount->total;
                    $total_returnAmt = str_replace('-', '', $returnsales->total); // + str_replace('-', '', $returnsales->total_discount);
                    $total_sales = $data_row->Total_sales + $total_returnAmt;
                    $total_netamt = $total_sales - $data_row->discount - $total_dueamt - $total_returnAmt;
                    /* ---- 18-03-19 --- */

                    $this->excel->getActiveSheet()->SetCellValue('A' . $row, $data_row->warehouse);

                    $this->excel->getActiveSheet()->SetCellValue('B' . $row, $this->sma->formatMoney($gross_sale));
                    $this->excel->getActiveSheet()->getStyle('B' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $this->excel->getActiveSheet()->SetCellValue('C' . $row, $this->sma->formatMoney($discount));
                    $this->excel->getActiveSheet()->getStyle('C' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $this->excel->getActiveSheet()->SetCellValue('D' . $row, $this->sma->formatMoney($total_dueamt));
                    $this->excel->getActiveSheet()->getStyle('D' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $this->excel->getActiveSheet()->SetCellValue('E' . $row, $this->sma->formatMoney($total_returnAmt));
                    $this->excel->getActiveSheet()->getStyle('E' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $this->excel->getActiveSheet()->SetCellValue('F' . $row, $this->sma->formatMoney($net_sale));
                    $this->excel->getActiveSheet()->getStyle('F' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $this->excel->getActiveSheet()->SetCellValue('G' . $row, $this->sma->formatMoney($WithCash));
                    $this->excel->getActiveSheet()->getStyle('G' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $this->excel->getActiveSheet()->SetCellValue('H' . $row, $this->sma->formatMoney($WithoutCash));
                    $this->excel->getActiveSheet()->getStyle('H' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $this->excel->getActiveSheet()->SetCellValue('I' . $row, $this->sma->formatMoney($tax));
                    $this->excel->getActiveSheet()->getStyle('I' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $this->excel->getActiveSheet()->SetCellValue('J' . $row, $this->sma->formatMoney($data_row->total_bills));
                    $this->excel->getActiveSheet()->getStyle('J' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    //$this->excel->getActiveSheet()->SetCellValue('I' . $row, round($data_row->sold_items));


                    $warehouses[$data_row->warehouse_id] = $data_row->warehouse;

                    $total_gross_sale += $gross_sale;
                    $total_discount += $discount;
                    $total_net_sale += $net_sale;
                    $total_total_tax += $tax;
                    $total_total_bills += $data_row->total_bills;
                    // $total_sold_items += $data_row->sold_items;
                    $total_due += $total_dueamt;
                    $total_retrun += $total_returnAmt;
                    $total_withcash += $WithCash;
                    $total_withoutcash += $WithoutCash;
                    $row++;
                }//end foreach.

                $total_row = $row++;

                $this->excel->getActiveSheet()->setCellValueExplicit('A' . $total_row, 'Total', PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('A' . $total_row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->setCellValueExplicit('B' . $total_row, $this->sma->formatMoney($total_gross_sale), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('B' . $total_row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->setCellValueExplicit('C' . $total_row, $this->sma->formatMoney($total_discount), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('C' . $total_row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->setCellValueExplicit('D' . $total_row, $this->sma->formatMoney($total_due), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('D' . $total_row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->setCellValueExplicit('E' . $total_row, $this->sma->formatMoney($total_retrun), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('E' . $total_row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->setCellValueExplicit('F' . $total_row, $this->sma->formatMoney($total_net_sale), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('F' . $total_row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->setCellValueExplicit('G' . $total_row, $this->sma->formatMoney($total_withcash), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('G' . $total_row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->setCellValueExplicit('H' . $total_row, $this->sma->formatMoney($total_withoutcash), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('H' . $total_row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->setCellValueExplicit('I' . $total_row, $this->sma->formatMoney($total_total_tax), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('I' . $total_row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->setCellValueExplicit('J' . $total_row, $this->sma->formatMoney($total_total_bills), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('J' . $total_row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                //$this->excel->getActiveSheet()->SetCellValue('I' . $total_row, round($total_sold_items));

                $this->excel->getActiveSheet()->getColumnDimension('A')->setWidth(40);
                $this->excel->getActiveSheet()->getColumnDimension('B')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('C')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('D')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('E')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('F')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('G')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('H')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('I')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('J')->setWidth(15);
                // $this->excel->getActiveSheet()->getColumnDimension('I')->setWidth(15);

                if ($report_type == 1) {
                    //Warehouse Balance Items Reports   

                    $wdata = $this->reports_model->warehouseProductsStock1($getwarehouse, $start_date, $end_date);
                    $whproducts = $wdata['products'];
                    $warehouses = $wdata['warehouse'];

                    $wcount = count($warehouses);
                    $colw = 'A';
                    for ($i = -1; $i <= $wcount; $i++) {
                        $colw++;
                    }
                    //Report Heading
