                        ),
                        'borders' => array(
                            'allborders' => array(
                                'style' => PHPExcel_Style_Border::BORDER_THIN)
                        )
                    );
                    $this->excel->getActiveSheet()->getStyle('A' . $row2 . ":$col_t" . $row2)->applyFromArray($styleHeading);
                    $this->excel->getActiveSheet()->getStyle('A2:J2')->applyFromArray($styleHeading);
                    $this->excel->getActiveSheet()->getStyle('A' . $total_row . ":J" . $total_row)->applyFromArray($styleHeading);


                    //Report Data Items
