                            );
                            $this->excel->getActiveSheet()->getStyle($col_i . $row2)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                            
                        }//end foreach.
                    }//end if.               
                }//end if.    
                elseif ($report_type == 2) {
