                            <th style="text-align: left;">Total</th>
                            <th style="text-align: right;">' . $this->sma->formatMoney($total_gross_sale) . '</th>
                            <th style="text-align: right;">' . $this->sma->formatMoney($total_discount, 2) . '</th>
                            <th style="text-align: right;">' . $this->sma->formatMoney($total_due, 2) . '</th>
                            <th style="text-align: right;">' . $this->sma->formatMoney($total_return, 2) . '</th>
                            <th style="text-align: right;">' . $this->sma->formatMoney($total_net_sale, 2) . '</th>
                            <th style="text-align: right;">' . $this->sma->formatMoney($total_withcash, 2) . '</th>
                            <th style="text-align: right;">' . $this->sma->formatMoney($total_withoutcash, 2) . '</th>
                            <th style="text-align: right;">' . $this->sma->formatMoney($calculate_total_tax, 2) . '</th>
                            <th style="text-align: right;">' . $this->sma->formatMoney($cal_total_bills) . '</th>
                            <th></th>
                        </tr>
                    </tfoot>

                    </table>';

            //Warehouse Balance warehouse Product Stock 
            if ($report_type == 1) {
                $wdata = $this->reports_model->warehouseProductsStock1($passwarehouse, $start_date, $end_date);

                $wps = $wdata['products'];
                $ws = $wdata['warehouse'];
                $datatable = '<h2>Daily stock warehouses comparison</h2>';
                $str_wp = 'wpq';
            }//end if.
            //Sold-out Warehouse Items Reports
            elseif ($report_type == 2) {
