            if (is_array($ws)) {
                foreach ($ws as $whn) {
                    $datatable .= "<th>$whn</th>";
                }
            }

            $datatable .= '<th>Total</th> 
            </tr>
          </thead>
        <tbody>';

            $total = array();
            $totalstock = 0;
            if (is_array($wps)) {
                foreach ($wps as $pid => $wpdata) {

                    $datatableRow = '<tr>               
                <td>' . $wpdata['name'] . '</td>
                <td>' . $wpdata['VarientName'] . '</td>
                <td>' . $wpdata['code'] . '</td>';
                    $stock = 0;
                    if (is_array($ws)) {
                        foreach ($ws as $wid => $whn) {
                            // $qty = ($wpdata[$str_wp][$wid]) ? $this->sma->formatQuantity($wpdata[$str_wp][$wid]) : 0;
                            $qty = isset($wpdata[$str_wp][$wid]) && $this->sma->formatQuantity($wpdata[$str_wp][$wid]) != 0 
                                    ? $this->sma->formatQuantity($wpdata[$str_wp][$wid]) 
