    /**
     * 
     * @param type $pdf
     * @param type $xls
     */
    public function getTaxReports($pdf = NULL, $xls = NULL) {
        $this->sma->checkPermissions('tax-report', TRUE);

        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;


        if ($pdf || $xls) {

            $GSTRate = $this->reports_model->salesGSTRateReports($start_date, $end_date);

            if (!empty($GSTRate)) {
                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);

                $style = array('alignment' => array('horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,), 'font' => array('name' => 'Arial', 'color' => array('rgb' => 'FF0000')), 'borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_NONE, 'color' => array('rgb' => 'FF0000'))));

                $this->excel->getActiveSheet()->getStyle("A1:H1")->applyFromArray($style);
                $this->excel->getActiveSheet()->mergeCells('A1:H1');
                $this->excel->getActiveSheet()->SetCellValue('A1', 'Tax Report');


                $this->excel->getActiveSheet()->setTitle(lang('Tax Report'));

                // Headings
                $this->excel->getActiveSheet()->SetCellValue('A2', lang('Sr. No.'));
                $this->excel->getActiveSheet()->SetCellValue('B2', lang('Date'));
                $this->excel->getActiveSheet()->SetCellValue('C2', lang('GST rate'));
                $this->excel->getActiveSheet()->SetCellValue('D2', lang('Taxable Amt.'));
                $this->excel->getActiveSheet()->SetCellValue('E2', lang('SGST'));
                $this->excel->getActiveSheet()->SetCellValue('F2', lang('CGST'));
                $this->excel->getActiveSheet()->SetCellValue('G2', lang('IGST'));
                $this->excel->getActiveSheet()->SetCellValue('H2', lang('Total GST'));
                $this->excel->getActiveSheet()->SetCellValue('I2', lang('Sales Amt.'));
                
                $row = 3;
                $totalbasic = $totalSGST = $totalCGST = $totalIGST = $totalGST = $totalsales = 0;

                $sum_multiline_values = function ($value) {
                    $lines = explode("\n", $value);
                    $total = 0;
                    foreach ($lines as $line) {
                        $clean = (float)str_replace(',', '', trim($line));
                        $total += $clean;
                    }
                    return $total;
                };

                   // Function to handle multi-line formatting
                   $format_multiline_money = function ($field_value) {
                    $lines = explode("\n", $field_value);
                    $formatted = array_map(function ($line) {
                        return $this->sma->formatMoney(str_replace(',', '', trim($line)));
                    }, $lines);
                    return implode("\n", $formatted);
                };
                foreach ($GSTRate as $key => $data_row) {
                    // Row number
                    $this->excel->getActiveSheet()->SetCellValue('A' . $row, $key + 1);
                    $this->excel->getActiveSheet()->getStyle('A' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    // Date Column
                    $this->excel->getActiveSheet()->SetCellValue('B' . $row, date('d/m/Y', strtotime($data_row['sale_date'])));
                    $this->excel->getActiveSheet()->getStyle('B' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);

                
                    $formatted_tax_rate = $data_row['tax_rate'];
                    $this->excel->getActiveSheet()->getStyle('C' . $row)->getAlignment()->setWrapText(true);
                    $this->excel->getActiveSheet()->SetCellValue('C' . $row, $formatted_tax_rate);
                    $this->excel->getActiveSheet()->getStyle('C' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                    // Basic Amount
                    $formatted_basic = $format_multiline_money($data_row['basic_amount']);
                    $this->excel->getActiveSheet()->getStyle('D' . $row)->getAlignment()->setWrapText(true);
                    $this->excel->getActiveSheet()->SetCellValue('D' . $row, $formatted_basic);
                    $this->excel->getActiveSheet()->getStyle('D' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    // SGST
                    $formatted_sgst = $format_multiline_money($data_row['sgst']);
                    $this->excel->getActiveSheet()->getStyle('E' . $row)->getAlignment()->setWrapText(true);
                    $this->excel->getActiveSheet()->SetCellValue('E' . $row, $formatted_sgst);
                    $this->excel->getActiveSheet()->getStyle('E' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    // CGST
                    $formatted_cgst = $format_multiline_money($data_row['cgst']);
                    $this->excel->getActiveSheet()->getStyle('F' . $row)->getAlignment()->setWrapText(true);
                    $this->excel->getActiveSheet()->SetCellValue('F' . $row, $formatted_cgst);
                    $this->excel->getActiveSheet()->getStyle('F' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    // IGST
                    $formatted_igst = $format_multiline_money($data_row['igst']);
                    $this->excel->getActiveSheet()->getStyle('G' . $row)->getAlignment()->setWrapText(true);
                    $this->excel->getActiveSheet()->SetCellValue('G' . $row, $formatted_igst);
                    $this->excel->getActiveSheet()->getStyle('G' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    // Total GST
                    $formatted_total_gst = $format_multiline_money($data_row['total_gst']);
                    $this->excel->getActiveSheet()->getStyle('H' . $row)->getAlignment()->setWrapText(true);
                    $this->excel->getActiveSheet()->SetCellValue('H' . $row, $formatted_total_gst);
                    $this->excel->getActiveSheet()->getStyle('H' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    // Total Sales
                    $formatted_sales = $format_multiline_money($data_row['total_sales']);
                    $this->excel->getActiveSheet()->getStyle('I' . $row)->getAlignment()->setWrapText(true);
                    $this->excel->getActiveSheet()->SetCellValue('I' . $row, $formatted_sales);
                    $this->excel->getActiveSheet()->getStyle('I' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                    $totalbasic  += $sum_multiline_values($data_row['basic_amount']);
                    $totalSGST   += $sum_multiline_values($data_row['sgst']);
                    $totalCGST   += $sum_multiline_values($data_row['cgst']);
                    $totalIGST   += $sum_multiline_values($data_row['igst']);
                    $totalGST    += $sum_multiline_values($data_row['total_gst']);
                    $totalsales  += $sum_multiline_values($data_row['total_sales']);
                    $row++;
                }
                
                // Total Row
                $this->excel->getActiveSheet()->SetCellValue("A" . $row, "");
                $this->excel->getActiveSheet()->SetCellValue("C" . $row, "Total");
                
                $this->excel->getActiveSheet()->SetCellValue("D" . $row, $this->sma->formatMoney($totalbasic));
                $this->excel->getActiveSheet()->getStyle("D" . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                $this->excel->getActiveSheet()->SetCellValue("E" . $row, $this->sma->formatMoney($totalSGST));
                $this->excel->getActiveSheet()->getStyle("E" . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                $this->excel->getActiveSheet()->SetCellValue("F" . $row, $this->sma->formatMoney($totalCGST));
                $this->excel->getActiveSheet()->getStyle("F" . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                $this->excel->getActiveSheet()->SetCellValue("G" . $row, $this->sma->formatMoney($totalIGST));
                $this->excel->getActiveSheet()->getStyle("G" . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                $this->excel->getActiveSheet()->SetCellValue("H" . $row, $this->sma->formatMoney($totalGST));
                $this->excel->getActiveSheet()->getStyle("H" . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                $this->excel->getActiveSheet()->SetCellValue("I" . $row, $this->sma->formatMoney($totalsales));
                $this->excel->getActiveSheet()->getStyle("I" . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                // Set Column Widths
                $this->excel->getActiveSheet()->getColumnDimension('A')->setWidth(10);
                $this->excel->getActiveSheet()->getColumnDimension('B')->setWidth(18);
                $this->excel->getActiveSheet()->getColumnDimension('C')->setWidth(18);
                $this->excel->getActiveSheet()->getColumnDimension('D')->setWidth(18);
                $this->excel->getActiveSheet()->getColumnDimension('E')->setWidth(18);
                $this->excel->getActiveSheet()->getColumnDimension('F')->setWidth(18);
                $this->excel->getActiveSheet()->getColumnDimension('G')->setWidth(18);
                $this->excel->getActiveSheet()->getColumnDimension('H')->setWidth(18);
                $this->excel->getActiveSheet()->getColumnDimension('I')->setWidth(18);

                
                // (Optional) Make Header Bold
                $this->excel->getActiveSheet()->getStyle('A2:I2')->getFont()->setBold(true);
                
                // (Optional) Merge Title Row
                $this->excel->getActiveSheet()->mergeCells('A1:I1');
                $this->excel->getActiveSheet()->SetCellValue('A1', lang('Tax Report'));
                $this->excel->getActiveSheet()->getStyle('A1')->getFont()->setBold(true);
                $this->excel->getActiveSheet()->getStyle('A1')->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                $lastRow = $row; // Row number after loop ends

                $styleArray = [
                    'borders' => [
                        'allborders' => [
                            'style' => PHPExcel_Style_Border::BORDER_THIN,
                            'color' => ['argb' => 'FF000000'], // Black border
                        ],
                    ],
                ];
                $this->excel->getActiveSheet()->getStyle("A{$row}:I{$row}")->getFont()->setBold(true);
                // Apply border to the entire data range (from A2 to K$lastRow)
                $this->excel->getActiveSheet()->getStyle('A2:I' . $lastRow)->applyFromArray($styleArray);

                $filename = 'Tax Report';
                $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);

                if ($pdf) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save('php://output');
                    exit();
                }

                if ($xls) {
                    ob_clean();
                    header('Content-Type: application/vnd.ms-excel');
                    header('Content-Disposition: attachment;filename="' . $filename . '.xls"');
                    header('Cache-Control: max-age=0');
                    ob_clean();
                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                    $objWriter->save('php://output');
                    exit();
                }
            }

            $this->session->set_flashdata('error', lang('nothing_found'));
            redirect($_SERVER["HTTP_REFERER"]);
        } else {

            $this->load->library('datatables');

            $subquery = "(SELECT 
                DATE(s.date) as sale_date,
                ROUND(si.tax, 2) as tax_rate,
                SUM(si.invoice_unit_price * si.quantity) as basic_amount,
                SUM(si.sgst) as sgst,
                SUM(si.cgst) as cgst,
                SUM(si.igst) as igst,
                SUM(si.sgst + si.cgst + si.igst) as total_gst,
                (SUM(si.invoice_unit_price * si.quantity) + SUM(si.sgst + si.cgst + si.igst)) AS total_sales
             FROM sma_sale_items si
             JOIN sma_sales s ON s.id = si.sale_id
             WHERE si.gst_rate > 0" .
             ($start_date && $end_date ? " AND DATE(s.date) BETWEEN '{$start_date}' AND '{$end_date}'" : "") . "
             GROUP BY DATE(s.date), ROUND(si.tax, 2)) AS sub";
            
            // Final query that groups by sale_date and concatenates each column
            $this->datatables
                ->select("sale_date,
                    GROUP_CONCAT(CONCAT(tax_rate, '%') ORDER BY tax_rate SEPARATOR '<br>') AS tax_rate,
                    GROUP_CONCAT(basic_amount ORDER BY tax_rate SEPARATOR '<br>') AS basic_amount,
                    GROUP_CONCAT(sgst ORDER BY tax_rate SEPARATOR '<br>') AS sgst,
                    GROUP_CONCAT(cgst ORDER BY tax_rate SEPARATOR '<br>') AS cgst,
                    GROUP_CONCAT(igst ORDER BY tax_rate SEPARATOR '<br>') AS igst,
                    GROUP_CONCAT(total_gst ORDER BY tax_rate SEPARATOR '<br>') AS total_gst,
                    GROUP_CONCAT(total_sales ORDER BY tax_rate SEPARATOR '<br>') AS total_sales
                    ")
                ->from($subquery)
                ->group_by("sale_date");
            echo $this->datatables->generate();
        }
    }

