            }
            $this->session->set_flashdata('error', lang('nothing_found'));
            redirect($_SERVER["HTTP_REFERER"]);
        } else {

            $this->load->library('datatables');
            $this->datatables->select("DATE_FORMAT(sma_sales.date, '%Y-%m-%d %T') as date,sma_sales.invoice_no,
            sma_sales.reference_no as reference_no,biller,customer,state,
            IF(comp.gstn_no IS NULL or comp.gstn_no = '', '-', comp.gstn_no) as gstn_no,
            grand_total + rounding, (grand_total - total_tax ) as tax_able_amount,paid,
            (grand_total + rounding - paid) as balance, sma_payments.paid_by, payment_status,
            {$this->db->dbprefix('sales')}.id as id", FALSE)
                    ->add_column('HsnCode', '')
                    ->add_column('qty', '')
                    ->add_column('units', '')
                    ->add_column('CGST', '', '')
                    ->add_column('SGST', '')
                    ->add_column('IGST', '')
                    ->add_column('TaxableAmont', '')
                    ->from('sales')
                    ->join('companies comp', 'sales.customer_id=comp.id', 'left')
                    ->join('sma_payments ', 'sales.id=sma_payments.sale_id', 'left')
                    ->join('warehouses', 'warehouses.id=sales.warehouse_id', 'left');
            if ($this->Owner || $this->Admin) {
                if ($user) {
                    $this->datatables->where('sales.created_by', $user);
                }
            } else {
                if ($this->session->userdata('view_right') == '0') {
                    if ($user) {
                        $this->datatables->where('sales.created_by', $user);
                    }
                }
            }
            if ($biller) {
                $this->datatables->where('sales.biller_id', $biller);
            }
            if ($customer) {
                $this->datatables->where('sales.customer_id', $customer);
            }
            if ($warehouse) {
                $getwarehouse = str_replace("_", ",", $warehouse);
                $this->datatables->where('sales.warehouse_id IN(' . $getwarehouse . ')');
            }
            if ($reference_no) {
                $this->datatables->like('sales.reference_no', $reference_no, 'both');
            }
            if ($start_date) {
                $this->datatables->where('DATE(' . $this->db->dbprefix('sales') . '.date) BETWEEN "' . $start_date . '" and "' . $end_date . '"');
            } else {
                $this->datatables->where('DATE(' . $this->db->dbprefix('sales') . '.date) BETWEEN "' . (date('Y') - 2) . date('-m') . date('-d ') . '00:00:00' . '" and "' . date('Y-m-d H:i:s') . '"');
            }

            if ($gstn_opt) {
                switch ($gstn_opt) {
                    case '-1':
                        $this->datatables->where("comp.gstn_no IS NULL OR comp.gstn_no = '' ");
                        break;

                    case '1':
                        $this->datatables->where("comp.gstn_no IS NOT NULL and comp.gstn_no != '' ");
                        break;

                    default:

                        break;
                }
            }
            if ($gstn_no) {
                $this->datatables->where("comp.gstn_no = '" . $gstn_no . "' ");
            }
            if ($SalesIds) {
                $this->datatables->where('sales.id in (' . $SalesIds . ')');
            }
            $this->datatables->group_by('sales.id');
            echo $this->datatables->generate();
        }
    }

    /** @return json for sales_item 12-21-2019 */
    public function getSalesItemsGst() {
        $id = $this->input->get('id');
        $return_option = array();
        $return_option['hsn_code'] = $this->reports_model->getSalesHsunt($id, 'hsn_code'); //HSN CODE 
        $return_option['qty'] = $this->reports_model->getSalesQty($id, 'quantity'); //Quatity 
        $return_option['units'] = $this->reports_model->getSalesHsunt($id, 'product_unit_code'); //Units
        $return_option['tax'] = $this->reports_model->getSalesTax($id); //Units
        $datacgst = $this->reports_model->getSalesAsGst($id, 'cgst'); //CGST 
        foreach ($datacgst as $dataitem1 => $tax1) {//sumgst
            $arr1[] = $tax1->sumgst;
        }
        $return_option['CGST'] = implode(", ", $arr1);

        $datasgst = $this->reports_model->getSalesAsGst($id, 'cgst'); //SGST 
        //print_r($datasgst);
        foreach ($datasgst as $dataitem2 => $tax2) {//sumgst
            $arr2[] = $tax2->sumgst;
        }
        $return_option['SGST'] = implode(", ", $arr2);

        $dataigst = $this->reports_model->getSalesAsGst($id, 'igst'); //IGST 
        foreach ($dataigst as $dataitem3 => $tax3) {//sumgst
            $arr3[] = $tax3->sumgst;
        }
        $return_option['IGST'] = implode(", ", $arr3);


        echo json_encode($return_option);
    }

    /** 23-1-2020* */
    /*     * Invoice Sales List For WarehouseSales Report 1-28-2020* */

    public function get_sales_invoice() {
        $start_date = trim($_GET['startdate']);
        $end_date = trim($_GET['enddata']);
        $warehouse_id = $_GET['warehouse'];

        $sale_data = $this->reports_model->getSalesInvoice($start_date, $end_date, $warehouse_id);
        // print_r($sale_data);
        ?>
        <div class="table-responsive" style="max-height: 400px; overflow-y: auto;">
            <table class="table table-bordered">
                <thead>
                    <tr>
                        <th>Date</th>
                        <th>Invoice No</th>
                        <th>Customer</th>
                        <th>Gross Sale</th>
                        <th>Discount</th>
                        <th>Net Sales</th>
                        <th>Tax Amount</th>
                        <th>Received Amt</th>
                        <th>Balance Amt</th>
                    </tr>
                </thead>
                <tbody>
                    <?php
                    $totalItems = $totalTax = $totaldiscount = $total = 0;
                    foreach ($sale_data as $key => $item) {
                        $totalItems += $item->qty;
                        $totalTax += $item->tax;
                        $totaldiscount += $item->discount;
                        $total += $item->net_total;
                        $gross = $item->net_total + $item->discount + $item->tax;
                        $netsale = $gross - $item->discount;
                        //$resales = $this->reports_model->getreturnsales($start_date,$end_date,$item->invoice_no);
                        $received_amt = $item->paid;
                        $balance_amt = ($netsale - $received_amt) + $item->rounding;
                        ?>
                        <tr>
                            <td><?= $item->date ?></td>
                            <td><?= $item->invoice_no ?></td>
                            <td><?= $item->customer ?></td>
                            <td><?= $this->sma->formatMoney($gross) ?></td>
                            <td><?= $this->sma->formatMoney($item->discount) ?></td>
                            <td><?= $this->sma->formatMoney($netsale) ?></td>
                            <td><?= $this->sma->formatMoney($item->tax ? number_format($item->tax, 2) : 0) ?></td>
                            <td><?= $this->sma->formatMoney($received_amt) ?></td>
                            <td><?= $this->sma->formatMoney($balance_amt) ?></td>
                        </tr>
                    <?php } ?>
                </tbody>
                 <!-- <tfoot>
                     <tr>
                         <th colspan="4">Totals</th>
                         <th><?= number_format($totalItems, 2) ?></th> 
                         <th>(Items)</th> 
                         <th></th> 
                         <th><?= $this->sma->formatMoney($totalTax) ?></th> 
                         <th><?= $this->sma->formatMoney($totaldiscount) ?></th> 
                         <th><?= $this->sma->formatMoney($total) ?></th>
                     </tr>
                 </tfoot>-->
            </table>
        </div>

        <?php
    }

    public function getChallansReport($pdf = NULL, $xls = NULL, $img = NULL) {
        $this->sma->checkPermissions('sales', TRUE);
        $start = '';
        $limit = '';
        $product = $this->input->get('product') ? $this->input->get('product') : NULL;
        $user = $this->input->get('user') ? $this->input->get('user') : NULL;
        $customer = $this->input->get('customer') ? $this->input->get('customer') : NULL;
        $biller = $this->input->get('biller') ? $this->input->get('biller') : NULL;
        $warehouse = $this->input->get('warehouse') ? $this->input->get('warehouse') : NULL;
        $reference_no = $this->input->get('reference_no') ? $this->input->get('reference_no') : NULL;
        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;
        $serial = $this->input->get('serial') ? $this->input->get('serial') : NULL;
        $warehouse_id = $this->session->userdata('warehouse_id');
        $user_id = $this->session->userdata('user_id');

        $strtlimit = $this->input->get('strtlimit') ? $this->input->get('strtlimit') : NULL;
        $limt = explode("-", $strtlimit);
        if ($limt) {
            $start = $limt[0];
            $limit = $limt[1];
        }
        if ($start_date) {
            $start_date = DateTime::createFromFormat('d/m/Y', trim($start_date))->format('Y-m-d') . ' 00:00:00';
            $end_date   = DateTime::createFromFormat('d/m/Y', trim($end_date))->format('Y-m-d') . ' 23:59:59';
        }
        if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
            $user = $this->session->userdata('user_id');
        }

        if ($pdf || $xls || $img) {

            /* $this->db->select("date,reference_no, biller, customer, GROUP_CONCAT(CONCAT(" . $this->db->dbprefix('order_items') . ".product_name, ' (', " . $this->db->dbprefix('sale_items') . ".quantity, ')') SEPARATOR '\n') as iname, grand_total, paid, payment_status", FALSE)->from('sales')->join('sale_items', 'sale_items.sale_id=sales.id', 'left')->join('warehouses', 'warehouses.id=sales.warehouse_id', 'left')->group_by('sales.id')->order_by('sales.date desc'); */

            $this->db->select("delivery_challan.id as challan_id, delivery_challan.date as date, delivery_challan.reference_no, delivery_challan.challan_no, delivery_challan.invoice_no, delivery_challan.biller, delivery_challan.customer, delivery_challan.grand_total, delivery_challan.paid, delivery_challan.rounding, delivery_challan.challan_status, delivery_challan.payment_status, GROUP_CONCAT(DISTINCT sma_payments.paid_by SEPARATOR ', ') as paid_by", FALSE)->from('delivery_challan')->join('sma_payments', 'sma_payments.challan_id = delivery_challan.id', 'left');

            /* $this->db->select("sales.id as sale_id,sales.date as date,sales.reference_no, sales.biller, sales.customer, sales.grand_total, sales.paid, sales.rounding,sales.payment_status", FALSE)->from('sales')->group_by('sales.id')->order_by('sales.date desc'); */

            if ($this->Owner || $this->Admin) {
                if ($this->input->get('user')) {
                    $this->db->where('delivery_challan.created_by', $this->input->get('user'));
                }
            } else {
                if ($this->session->userdata('view_right') == '0') {
                    if ($user) {
                        $this->db->where('delivery_challan.created_by', $user);
                    }
                }
            }
            // Product filter will be handled after initial query
            $product_filtered_challans = [];
            if ($product) {
                // Get challan IDs that contain the specific product
                $this->db->select('DISTINCT challan_id')->from('delivery_challan_items')->where('product_id', $product);
                $product_query = $this->db->get();
                if ($product_query->num_rows() > 0) {
                    foreach ($product_query->result() as $prow) {
                        $product_filtered_challans[] = $prow->challan_id;
                    }
                }
                if (!empty($product_filtered_challans)) {
                    $this->db->where_in('delivery_challan.id', $product_filtered_challans);
                } else {
                    // No challans found with this product, return empty result
                    $this->db->where('delivery_challan.id', 0);
                }
            }
            $this->db->order_by('delivery_challan.date desc');
            
            // Handle serial filter separately
            $serial_filtered_challans = [];
            if ($serial) {
                $this->db->select('DISTINCT challan_id')->from('delivery_challan_items')->like('serial_no', $serial);
                $serial_query = $this->db->get();
                if ($serial_query->num_rows() > 0) {
                    foreach ($serial_query->result() as $srow) {
                        $serial_filtered_challans[] = $srow->challan_id;
                    }
                }
                if (!empty($serial_filtered_challans)) {
                    $this->db->where_in('delivery_challan.id', $serial_filtered_challans);
                } else {
                    // No challans found with this serial, return empty result
                    $this->db->where('delivery_challan.id', 0);
                }
            }
            if ($biller) {
                $this->db->where('delivery_challan.biller_id', $biller);
            }
            if ($customer) {
                $this->db->where('delivery_challan.customer_id', $customer);
            }
            if ($warehouse) {
                $getwarehouse = str_replace("_", ",", $warehouse);
                $this->db->where('delivery_challan.warehouse_id IN(' . $getwarehouse . ')');
            }
            if ($reference_no) {
                $this->db->like('delivery_challan.reference_no', $reference_no, 'both');
            }
            if ($start_date) {
                $this->db->where($this->db->dbprefix('delivery_challan') . '.date BETWEEN "' . $start_date . '" and "' . $end_date . '"');
            }

            if ($limit != '' && $start != '') {
                $this->db->limit($limit, $start);
            }
            $this->db->group_by('delivery_challan.id');
            $q = $this->db->get();
            $data_sales = [];
            $products = '';
            if ($q->num_rows() > 0) {
                foreach (($q->result()) as $row) {
                    if (!in_array($row->challan_id, $data_sales)) {
                        $data_sales[] = $row->challan_id;
                    }

                    $id = $row->challan_id;
                    $data[$id]['date'] = $row->date;

                    $data[$id]['reference_no'] = $row->reference_no;
                    $data[$id]['invoice_no'] = $row->invoice_no;
                    $data[$id]['challan_no'] = $row->challan_no;
                    $data[$id]['biller'] = $row->biller;
                    $data[$id]['customer'] = $row->customer;
                    $data[$id]['grand_total'] = $row->grand_total + $row->rounding;
                    $data[$id]['paid'] = $row->paid;
                    $data[$id]['balance'] = $row->grand_total + $row->rounding - $row->paid;
                    $data[$id]['challan_status'] = $row->challan_status;
                    $data[$id]['payment_status'] = $row->payment_status;
                    $data[$id]['paid_by'] = $row->paid_by ? $row->paid_by : 'N/A';
                    //$data[] = $row;
                    //   print_r($data);exit;
                }//forloop

                if ($product) {
                    $products = $product;
                }
                $uniqueSalesIds = array_unique($data_sales);

                $ChallansItems = $this->reports_model->getDeliveryChallanItemsByChallanIds($uniqueSalesIds, $products);

                if (is_array($ChallansItems)) {
                    foreach ($ChallansItems as $key => $SaleItemsRow) {
                        //Sales Items Details
                        $data[$SaleItemsRow->sale_id]['items'][$SaleItemsRow->items_id]['name'] = $SaleItemsRow->product_name;
                        $data[$SaleItemsRow->sale_id]['items'][$SaleItemsRow->items_id]['quantity'] = $SaleItemsRow->quantity;
                        $data[$SaleItemsRow->sale_id]['items'][$SaleItemsRow->items_id]['unit_price'] = $SaleItemsRow->unit_price;
                        $data[$SaleItemsRow->sale_id]['items'][$SaleItemsRow->items_id]['variantname'] = ($SaleItemsRow->variant_name) ? $SaleItemsRow->variant_name : '';
                    }//end foreach
                }//end if
            } else {
                $data = NULL;
            }

            if (!empty($data)) {

                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);
                $style = array('alignment' => array('horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,), 'font' => array('name' => 'Arial', 'color' => array('rgb' => 'FF0000')), 'borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_NONE, 'color' => array('rgb' => 'FF0000'))));

                $this->excel->getActiveSheet()->getStyle("A1:P1")->applyFromArray($style);
                $this->excel->getActiveSheet()->mergeCells('A1:P1');
                $this->excel->getActiveSheet()->SetCellValue('A1', 'Challans Report');
                $this->excel->getActiveSheet()->setTitle(lang('challans_report'));
                $this->excel->getActiveSheet()->SetCellValue('A2', lang('date'));
                $this->excel->getActiveSheet()->SetCellValue('B2', lang('reference_no'));
                $this->excel->getActiveSheet()->SetCellValue('C2', lang('challan_no'));
                $this->excel->getActiveSheet()->SetCellValue('D2', lang('invoice_no'));
                $this->excel->getActiveSheet()->SetCellValue('E2', lang('biller'));
                $this->excel->getActiveSheet()->SetCellValue('F2', lang('customer'));
                $this->excel->getActiveSheet()->SetCellValue('G2', lang('product'));
                $this->excel->getActiveSheet()->SetCellValue('H2', lang('Variant'));
                $this->excel->getActiveSheet()->SetCellValue('I2', lang('quantity'));
                $this->excel->getActiveSheet()->SetCellValue('J2', lang('Price'));
                $this->excel->getActiveSheet()->SetCellValue('K2', lang('grand_total'));
                $this->excel->getActiveSheet()->SetCellValue('L2', lang('paid'));
                $this->excel->getActiveSheet()->SetCellValue('M2', lang('balance'));
                $this->excel->getActiveSheet()->SetCellValue('N2', lang('status'));
                $this->excel->getActiveSheet()->SetCellValue('O2', lang('payment_status'));
                $this->excel->getActiveSheet()->SetCellValue('P2', lang('paid_by'));

                $row = 3;
                $total = 0;
                $paid = 0;
                $balance = 0;
                foreach ($data as $sale_id => $salesdata) {
                    $data_row = (object) $salesdata;
                    $this->excel->getActiveSheet()->SetCellValue('A' . $row, $this->sma->hrld($data_row->date));
                    $this->excel->getActiveSheet()->SetCellValue('B' . $row, $data_row->reference_no);
                    $this->excel->getActiveSheet()->SetCellValue('C' . $row, $data_row->challan_no);
                    $this->excel->getActiveSheet()->getStyle('C' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                    $this->excel->getActiveSheet()->SetCellValue('D' . $row, $data_row->invoice_no);
                    $this->excel->getActiveSheet()->getStyle('D' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                    $this->excel->getActiveSheet()->SetCellValue('E' . $row, $data_row->biller);
                    $this->excel->getActiveSheet()->SetCellValue('F' . $row, $data_row->customer);
                    // $this->excel->getActiveSheet()->SetCellValue('F' . $row, $data_row->iname);
                    $rowitems = $row;
                    if (!empty($data_row->items)) {
                        foreach ($data_row->items as $saleitem_id => $salesItemsData) {
                            $sales_items_data = (object) $salesItemsData;
                            $this->excel->getActiveSheet()->SetCellValue('G' . $row, $sales_items_data->name);
                            $this->excel->getActiveSheet()->getStyle('G' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                        
                            $this->excel->getActiveSheet()->SetCellValue('H' . $row, $sales_items_data->variantname);
                            $this->excel->getActiveSheet()->getStyle('H' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                        
                            $this->excel->getActiveSheet()->SetCellValueExplicit('I' . $row, $this->sma->formatQuantity($sales_items_data->quantity), PHPExcel_Cell_DataType::TYPE_STRING);
                            $this->excel->getActiveSheet()->getStyle('I' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                        
                            $this->excel->getActiveSheet()->SetCellValueExplicit('J' . $row, $this->sma->formatMoney($sales_items_data->unit_price), PHPExcel_Cell_DataType::TYPE_STRING);
                            $this->excel->getActiveSheet()->getStyle('J' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                        
                            $row++;
                        }//end foreach
                        $this->excel->getActiveSheet()->SetCellValueExplicit('K' . $rowitems, $this->sma->formatMoney($data_row->grand_total), PHPExcel_Cell_DataType::TYPE_STRING);
                        $this->excel->getActiveSheet()->getStyle('K' . $rowitems)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                        $this->excel->getActiveSheet()->SetCellValueExplicit('L' . $rowitems, $this->sma->formatMoney($data_row->paid), PHPExcel_Cell_DataType::TYPE_STRING);
                        $this->excel->getActiveSheet()->getStyle('L' . $rowitems)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                        $this->excel->getActiveSheet()->SetCellValueExplicit('M' . $rowitems, $this->sma->formatMoney($data_row->balance), PHPExcel_Cell_DataType::TYPE_STRING);
                        $this->excel->getActiveSheet()->getStyle('M' . $rowitems)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                        $this->excel->getActiveSheet()->SetCellValue('N' . $rowitems, lang($data_row->challan_status));
                        $this->excel->getActiveSheet()->getStyle('N' . $rowitems)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);

                        $this->excel->getActiveSheet()->SetCellValue('O' . $rowitems, lang($data_row->payment_status));
                        $this->excel->getActiveSheet()->getStyle('O' . $rowitems)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);

                        $this->excel->getActiveSheet()->SetCellValue('P' . $rowitems, $data_row->paid_by);
                        $this->excel->getActiveSheet()->getStyle('P' . $rowitems)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                    }//end if.

                    $total += $data_row->grand_total;
                    $paid += $data_row->paid;
                    $balance += $data_row->balance;
                    //$row++;
                }
                $this->excel->getActiveSheet()->getStyle("J" . $row . ":L" . $row)->getBorders()->getTop()->setBorderStyle(PHPExcel_Style_Border::BORDER_MEDIUM);

                $this->excel->getActiveSheet()->SetCellValueExplicit('K' . $row, $this->sma->formatMoney($total), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('K' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->SetCellValueExplicit('L' . $row, $this->sma->formatMoney($paid), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('L' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->SetCellValueExplicit('M' . $row, $this->sma->formatMoney($balance), PHPExcel_Cell_DataType::TYPE_STRING);
                $this->excel->getActiveSheet()->getStyle('M' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->getColumnDimension('A')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('B')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('C')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('D')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('E')->setWidth(30);
                $this->excel->getActiveSheet()->getColumnDimension('F')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('G')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('H')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('I')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('J')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('K')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('L')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('M')->setWidth(20);
                $filename = 'challans_report';
                $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);
                if ($pdf) {

                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($xls) {
                    $this->excel->getActiveSheet()->getStyle('E2:E' . $row)->getAlignment()->setWrapText(TRUE);
                    ob_clean();
                    header('Content-Type: application/vnd.ms-excel');
                    header('Content-Disposition: attachment;filename="' . $filename . '.xls"');
                    header('Cache-Control: max-age=0');
                    ob_clean();
                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($img) {

                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save(str_replace(__FILE__, 'assets/mdata/'.$this->Customer_assets.'/uploads/pdf/challans_report.pdf', __FILE__));
                    redirect("reports/create_image/challans_report.pdf");
                    exit();
                }
            }
            $this->session->set_flashdata('error', lang('nothing_found'));
            // redirect($_SERVER["HTTP_REFERER"]);
        } else {

            $si = "( SELECT 
                {$this->db->dbprefix('delivery_challan_items')}.challan_id,
                {$this->db->dbprefix('delivery_challan_items')}.product_id,
                {$this->db->dbprefix('delivery_challan_items')}.serial_no,

                GROUP_CONCAT(
                    CONCAT(
                        {$this->db->dbprefix('delivery_challan_items')}.product_name,
                        IF(
                            {$this->db->dbprefix('product_variants')}.name IS NOT NULL 
                            AND {$this->db->dbprefix('product_variants')}.name != '', 
                            CONCAT(' (', {$this->db->dbprefix('product_variants')}.name, ')'), 
                            ''
                        ),
                        ' (', {$this->db->dbprefix('delivery_challan_items')}.subtotal, ')',
                        ' - ', {$this->db->dbprefix('delivery_challan_items')}.quantity
                    )
                    SEPARATOR '\n'
                ) AS item_nane

                FROM {$this->db->dbprefix('delivery_challan_items')} ";

            $si .= "LEFT JOIN {$this->db->dbprefix('product_variants')} ON {$this->db->dbprefix('delivery_challan_items')}.option_id = {$this->db->dbprefix('product_variants')}.id";

            $si .= " left Join {$this->db->dbprefix('delivery_challan')} ON {$this->db->dbprefix('delivery_challan')}.id = {$this->db->dbprefix('delivery_challan_items')}.challan_id ";

            if ($product) {
                $si .= " WHERE {$this->db->dbprefix('delivery_challan_items')}.product_id = {$product} ";
            }

            $si .= " GROUP BY {$this->db->dbprefix('delivery_challan_items')}.challan_id ) FSI";
            $this->load->library('datatables');

            // $this->datatables->select("DATE_FORMAT(date, '%Y-%m-%d %T') as date, reference_no, challan_no, invoice_no, biller, customer, warehouses.name ,  FSI.item_nane as iname, grand_total+rounding, paid, (grand_total+rounding -paid) as balance, payment_status, {$this->db->dbprefix('delivery_challan')}.id as id, (SELECT GROUP_CONCAT(CONCAT(attr_name, ': ', tax_amount) ORDER BY attr_name SEPARATOR ', ') FROM {$this->db->dbprefix('delivery_challan_items_tax')} WHERE challan_id = {$this->db->dbprefix('delivery_challan')}.id) as tax_details", FALSE)
            $this->datatables->select("DATE_FORMAT(date, '%Y-%m-%d %T') as date, reference_no, challan_no, invoice_no, biller, customer, warehouses.name ,  FSI.item_nane as iname, grand_total+rounding, paid, (grand_total+rounding -paid) as balance, delivery_challan.challan_status, payment_status, (SELECT GROUP_CONCAT(DISTINCT paid_by SEPARATOR ', ') FROM {$this->db->dbprefix('payments')} WHERE reference_no = {$this->db->dbprefix('delivery_challan')}.reference_no) as paid_by, {$this->db->dbprefix('delivery_challan')}.id as id, (SELECT GROUP_CONCAT(CONCAT(attr_name, ': ', tax_amount) ORDER BY attr_name SEPARATOR ', ') FROM {$this->db->dbprefix('delivery_challan_items_tax')} WHERE challan_id = {$this->db->dbprefix('delivery_challan')}.id) as tax_details", FALSE)
                    ->from('delivery_challan')
                    ->join($si, 'FSI.challan_id=delivery_challan.id', 'right')
                    ->join('warehouses', 'warehouses.id = delivery_challan.warehouse_id', 'left');
            // ->group_by('orders.id');

            if ($this->Owner || $this->Admin) {
                if ($this->input->get('user')) {
                    $this->datatables->where('delivery_challan.created_by', $this->input->get('user'));
                }
            } else {
                if ($this->session->userdata('view_right') == '0') {
                    if ($user) {
                        $this->datatables->where('delivery_challan.created_by', $user);
                    }
                }
            }
            if ($product) {
                $this->datatables->where('FSI.product_id', $product, FALSE);
            }
            if ($serial) {
                $this->datatables->like('FSI.serial_no', $serial, FALSE);
            }
            if ($biller) {
                $this->datatables->where('delivery_challan.biller_id', $biller);
            }
            if ($customer) {
                $this->datatables->where('delivery_challan.customer_id', $customer);
            }
            if ($warehouse) {
                $getwarehouse = str_replace("_", ",", $warehouse);
                $this->datatables->where('delivery_challan.warehouse_id IN (' . $getwarehouse . ')');
            }
            if (!$this->Owner || $this->Admin) {
                if (($this->session->userdata('view_right') == '1')) {
                    if ($warehouse_id) {
                        $arrWr = explode(',', $warehouse_id);
                        $this->datatables->where_in('warehouse_id', $arrWr);
                    } 
                }else{
                    $this->datatables->where('delivery_challan.created_by', $user_id);
                }
            }
            if ($reference_no) {
                $this->datatables->like('delivery_challan.reference_no', $reference_no, 'both');
            }
            if ($start_date) {
                $this->datatables->where($this->db->dbprefix('delivery_challan') . '.date BETWEEN "' . $start_date . '" and "' . $end_date . '"');
            }


            echo $this->datatables->generate();
        }
    }

    public function challans() {
        $this->sma->checkPermissions('sales');
        $this->data['error'] = (validation_errors()) ? validation_errors() : $this->session->flashdata('error');
        $this->data['users'] = $this->reports_model->getStaff();
        $this->data['salecount'] = $this->getCountChallans();
        $this->data['warehouses'] = $this->site->getAllWarehouses();
        $this->data['billers'] = $this->site->getAllCompanies('biller');
        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('sales_report')));
        $meta = array('page_title' => lang('challan_report'), 'bc' => $bc);
        $this->page_construct('reports/challans', $meta, $this->data);
    }

    public function getCountChallans() {

        $this->sma->checkPermissions('sales', TRUE);
        $product = $this->input->get('product') ? $this->input->get('product') : NULL;
        $user = $this->input->get('user') ? $this->input->get('user') : NULL;
        $customer = $this->input->get('customer') ? $this->input->get('customer') : NULL;
        $biller = $this->input->get('biller') ? $this->input->get('biller') : NULL;
        $warehouse = $this->input->get('warehouse') ? $this->input->get('warehouse') : NULL;
        $reference_no = $this->input->get('reference_no') ? $this->input->get('reference_no') : NULL;
        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;
        $serial = $this->input->get('serial') ? $this->input->get('serial') : NULL;

        if ($start_date) {
            $start_date = $this->sma->fld($start_date);
            $end_date = $this->sma->fld($end_date);
        }
        if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
            $user = $this->session->userdata('user_id');
        }
        $this->db->select("delivery_challan.id", FALSE)->from('delivery_challan')
                ->join('delivery_challan_items', 'delivery_challan_items.challan_id=delivery_challan.id', 'left')
                ->join('warehouses', 'warehouses.id=delivery_challan.warehouse_id', 'left')
                ->group_by('delivery_challan.id')
                ->order_by('delivery_challan.date desc');

        if ($this->Owner || $this->Admin) {
            if ($this->input->get('user')) {
                $this->db->where('delivery_challan.created_by', $this->input->get('user'));
            }
        } else {
            if ($this->session->userdata('view_right') == '0') {
                if ($user) {
                    $this->db->where('delivery_challan.created_by', $user);
                }
            }
        }
        if ($product) {
            $this->db->where('delivery_challan_items.product_id', $product);
        }
        if ($serial) {
            $this->db->like('delivery_challan_items.serial_no', $serial);
        }
        if ($biller) {
            $this->db->where('delivery_challan.biller_id', $biller);
        }
        if ($customer) {
            $this->db->where('delivery_challan.customer_id', $customer);
        }
        if ($warehouse) {
            $getwarehouse = str_replace("_", ",", $warehouse);
            $this->db->where('delivery_challan.warehouse_id IN(' . $getwarehouse . ')');
        }
        if ($reference_no) {
            $this->db->like('delivery_challan.reference_no', $reference_no, 'both');
        }
        if ($start_date) {
            $this->db->where('DATE(' . $this->db->dbprefix('delivery_challan') . '.date) BETWEEN "' . $start_date . '" and "' . $end_date . '"');
        }


        $q = $this->db->get();
        if ($q->num_rows() > 0) {

            $data = $q->num_rows();

            return $data;
        }

        return FALSE;
    }

    /**
     * Uprban Piper Daily Reports
     * @param type $warehouse_id
     * @param type $year
     * @param type $month
     * @param type $pdf
     * @param type $user_id
     */
    public function daily_sales_up($warehouse_id = NULL, $year = NULL, $month = NULL, $pdf = NULL, $user_id = NULL) {
        $this->sma->checkPermissions();
        if ($warehouse_id != NULL) {
            $warehouse_id = $warehouse_id;
        } else if (!$this->Owner && !$this->Admin && $this->session->userdata('warehouse_id')) {
            $warehouse_id = str_replace(",", "_", $this->session->userdata('warehouse_id'));
        }

        $this->data['sel_warehouse'] = $warehouse_id ? (strpos($warehouse_id, '_') !== false) ? NULL : $this->site->getWarehouseByID($warehouse_id) : NULL;


        if (!$year) {
            $year = date('Y');
        }
        if (!$month) {
            $month = date('m');
        }
        if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
            $user_id = $this->session->userdata('user_id');
        }
        $this->data['error'] = (validation_errors()) ? validation_errors() : $this->session->flashdata('error');
        $key = $this->data['sel_warehouse'] ? array_keys($this->data['sel_warehouse']) : 0; //Use to get Id on sel_warehouse 
        //$config = array('show_next_prev' => TRUE, 'next_prev_url' => site_url('reports/daily_sales/' . ($this->data['sel_warehouse']? $this->data['sel_warehouse']->id : 0)), 'month_type' => 'long', 'day_type' => 'long');

        $config = array('show_next_prev' => TRUE, 'next_prev_url' => site_url('reports/daily_sales_up/' . ($this->data['sel_warehouse'] ? $key[0] : 0)), 'month_type' => 'long', 'day_type' => 'long');

        $config['template'] = '{table_open}<div class="table-responsive"><table border="0" cellpadding="0" cellspacing="0" class="table table-bordered dfTable">{/table_open}
		{heading_row_start}<tr>{/heading_row_start}
		{heading_previous_cell}<th><a href="{previous_url}">&lt;&lt;</a></th>{/heading_previous_cell}
		{heading_title_cell}<th colspan="{colspan}" id="month_year">{heading}</th>{/heading_title_cell}
		{heading_next_cell}<th><a href="{next_url}">&gt;&gt;</a></th>{/heading_next_cell}
		{heading_row_end}</tr>{/heading_row_end}
		{week_row_start}<tr>{/week_row_start}
		{week_day_cell}<td class="cl_wday">{week_day}</td>{/week_day_cell}
		{week_row_end}</tr>{/week_row_end}
		{cal_row_start}<tr class="days">{/cal_row_start}
		{cal_cell_start}<td class="day">{/cal_cell_start}
		{cal_cell_content}
		<div class="day_num">{day}</div>
		<div class="content">{content}</div>
		{/cal_cell_content}
		{cal_cell_content_today}
		<div class="day_num highlight">{day}</div>
		<div class="content">{content}</div>
		{/cal_cell_content_today}
		{cal_cell_no_content}<div class="day_num">{day}</div>{/cal_cell_no_content}
		{cal_cell_no_content_today}<div class="day_num highlight">{day}</div>{/cal_cell_no_content_today}
		{cal_cell_blank}&nbsp;{/cal_cell_blank}
		{cal_cell_end}</td>{/cal_cell_end}
		{cal_row_end}</tr>{/cal_row_end}
		{table_close}</table></div>{/table_close}';

        $this->load->library('calendar', $config);
        $sales = $user_id ? $this->reports_model->getStaffDailySalesUP($user_id, $year, $month, $warehouse_id) : $this->reports_model->getDailySalesUP($year, $month, $warehouse_id);
        $sales_w = $user_id ? $this->reports_model->getStaffDailySalesUP_w($user_id, $year, $month, $warehouse_id) : $this->reports_model->getDailySalesUP_w($year, $month, $warehouse_id);

        if (!empty($sales)) {
            foreach ($sales as $sale) {
                $daily_sale[$sale->date] = "<table class='table table-bordered table-hover table-striped table-condensed data' style='margin:0;'><tr><td>" . lang("discount") . "</td><td>" . $this->sma->formatMoney($sale->discount) . "</td></tr><tr><td>" . lang("shipping") . "</td><td>" . $this->sma->formatMoney($sale->shipping) . "</td></tr><tr style='cursor: pointer' onClick='getsaleitemstaxes(" . $year . "," . $month . "," . $sale->date . ")'><td>" . lang("product_tax") . " <i class='fa fa-list-alt' aria-hidden='true'></i></td><td>" . $this->sma->formatMoney($sale->tax1) . "</td></tr><tr><td>" . lang("order_tax") . "</td><td>" . $this->sma->formatMoney($sale->tax2) . "</td></tr><tr><td>" . lang("total") . "</td><td>" . $this->sma->formatMoney($sale->total) . "</td></tr><tr><td>Items</td><td onClick='getsaleitems(" . $year . "," . $month . "," . $sale->date . ")'><i class='fa fa-list-alt' aria-hidden='true'></i></td></tr></table>";
            }
        } else {
            $daily_sale = array();
        }

        $this->data['calender'] = $this->calendar->generate($year, $month, $daily_sale);
        $this->data['year'] = $year;
        $this->data['month'] = $month;

        if ($pdf) {
            $sales_pdf = array();
            //foreach($sales as $data_row)
            foreach ($sales_w as $data_row) {//because of warehouse show
                $sales_pdf[$data_row->date] = $data_row;
            }
            sort($sales_pdf);

            $this->load->library('excel');
            $this->excel->setActiveSheetIndex(0);
            $style = array('alignment' => array('horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,), 'borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN, 'color' => array('rgb' => 'DDDDDD'))));
            $styleright = array('alignment' => array('horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_RIGHT,));
            $this->excel->getActiveSheet()->getStyle("A1:H1")->applyFromArray($style);

            $this->excel->getActiveSheet()->mergeCells('A1:H1');
            $this->excel->getActiveSheet()->getStyle("A1:H1")->applyFromArray($style);

            $this->excel->getActiveSheet()->mergeCells('A1:H1');
            $this->excel->getActiveSheet()->SetCellValue('A1', lang('Daily Sales Report ') . date("M-Y", mktime(0, 0, 0, $month, 1, $year)));
            $this->excel->getActiveSheet()->SetCellValue('A2', lang('Srr.No'));
            $this->excel->getActiveSheet()->SetCellValue('B2', lang('Date'));
            $this->excel->getActiveSheet()->SetCellValue('C2', lang('Discount'));
            $this->excel->getActiveSheet()->SetCellValue('D2', lang('Shipping'));
            $this->excel->getActiveSheet()->SetCellValue('E2', lang('Product Tax'));
            $this->excel->getActiveSheet()->SetCellValue('F2', lang('Order Tax'));
            $this->excel->getActiveSheet()->SetCellValue('G2', lang('Total'));
            $this->excel->getActiveSheet()->SetCellValue('H2', lang('Warehouse'));
            $row = 3;

            $sr = 1;
            foreach ($sales_pdf as $data_row) {
                $this->excel->getActiveSheet()->SetCellValue('A' . $row, $sr);
                $this->excel->getActiveSheet()->SetCellValue('B' . $row, $data_row->date . '/' . $month . '/' . $year);
                $this->excel->getActiveSheet()->SetCellValue('C' . $row, $this->sma->formatMoney($data_row->discount));
                $this->excel->getActiveSheet()->SetCellValue('D' . $row, $this->sma->formatMoney($data_row->shipping));
                $this->excel->getActiveSheet()->SetCellValue('E' . $row, $this->sma->formatMoney($data_row->tax1));
                $this->excel->getActiveSheet()->SetCellValue('F' . $row, $this->sma->formatMoney($data_row->tax2));
                $this->excel->getActiveSheet()->SetCellValue('G' . $row, $this->sma->formatMoney($data_row->total));
                $this->excel->getActiveSheet()->SetCellValue('H' . $row, $data_row->warehouse);

                $row++;
                $sr++;
            }
            $this->excel->getActiveSheet()->getColumnDimension('A')->setWidth(10);
            $this->excel->getActiveSheet()->getColumnDimension('B')->setWidth(15);
            $this->excel->getActiveSheet()->getColumnDimension('C')->setWidth(20);
            $this->excel->getActiveSheet()->getColumnDimension('D')->setWidth(20);
            $this->excel->getActiveSheet()->getColumnDimension('E')->setWidth(30);
            $this->excel->getActiveSheet()->getColumnDimension('F')->setWidth(15);
            $this->excel->getActiveSheet()->getColumnDimension('G')->setWidth(15);
            $this->excel->getActiveSheet()->getColumnDimension('H')->setWidth(15);

            $this->excel->getActiveSheet()->getStyle("A2:H2" . ($row - 1))->applyFromArray($styleright);

            $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);
            $filename = 'daily_sales_report';

            if ($pdf == 'pdf') {
                $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                $rendererLibrary = 'MPDF';
                $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                    die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                }

                header('Content-Type: application/pdf');
                header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                header('Cache-Control: max-age=0');

                $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                $objWriter->save('php://output');
                exit();
            } elseif ($pdf == 'xls') {
                $this->excel->getActiveSheet()->getStyle('E2:E' . $row)->getAlignment()->setWrapText(TRUE);
                ob_clean();
                header('Content-Type: application/vnd.ms-excel');
                header('Content-Disposition: attachment;filename="' . $filename . '.xls"');
                header('Cache-Control: max-age=0');
                ob_clean();
                $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                $objWriter->save('php://output');
                exit();
            } elseif ($pdf == 'img') {
                $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                $rendererLibrary = 'MPDF';
                $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                    die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                }

                header('Content-Type: application/pdf');
                header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                header('Cache-Control: max-age=0');

                $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                $objWriter->save(str_replace(__FILE__, 'assets/mdata/'.$this->Customer_assets.'/uploads/pdf/daily_sales_report.pdf', __FILE__));
                redirect("reports/create_image/daily_sales_report.pdf");
            }
        }


        $this->data['warehouses'] = $this->site->getAllWarehouses();
        $this->data['warehouse_id'] = $this->session->userdata('warehouse_id');
        //$this->data['sel_warehouse'] = $warehouse_id ? $this->site->getWarehouseByID($warehouse_id) : NULL;
        $this->data['active_warehouse_id'] = $warehouse_id == '' ? 0 : $warehouse_id;
        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('Daily_Sales_Urban_Piper_Report')));
        $meta = array('page_title' => lang('Urban Piper Report'), 'bc' => $bc);
        $this->page_construct('reports/daily_up', $meta, $this->data);
    }

    /*  daily Urbin_piper 1-4-2020 */

    public function daily_Urbin_piper() {
        $date = $_GET['date'];
        $warehouse_id = $_GET['active_warehouse_id'];
        if (empty($date))
            return FALSE;

        $sale_data = $this->reports_model->getDailyUrbinpiper($date);
        ?>
        <div class="table-responsive">
            <table class="table table-bordered">
                <thead>
                    <tr>
                        <th>Invoice</th>
                        <th>Channel</th>
                        <th>Total Amount</th>
                    </tr>
