        $si = "(
            SELECT
                si.sale_id,
                si.quantity,
                si.product_id,
                si.serial_no,
                si.product_name,
                si.batch_number,
                COALESCE(p_direct.code, '') AS code,
                COALESCE(p_direct.article_code, '') AS article_code,
                (
                    SELECT cst.purchase_unit_cost
                    FROM {$this->db->dbprefix('costing')} cst
                    JOIN {$this->db->dbprefix('purchase_items')} pit
                        ON pit.id = cst.purchase_item_id
                    WHERE pit.product_id = si.product_id
                      AND (pit.option_id = si.option_id OR pit.option_id IS NULL)
                    ORDER BY cst.id DESC
                    LIMIT 1
                ) AS cost,
                p_direct.price,
                COALESCE(b_direct.name, '') AS brand,
                COALESCE(c_direct.name, '') AS categories,
                (
                    SELECT name
                    FROM {$this->db->dbprefix('categories')}
                    WHERE id = p_direct.subcategory_id
                ) AS subcatgory,
                p_direct.brand AS brand_id,
                p_direct.category_id AS category_id,
                p_direct.subcategory_id AS subcategory_id,
                COALESCE(pv.name, '') AS sizevarient,
                si.item_tax,
                si.item_discount,
                si.tax,
                si.unit_price,
                si.real_unit_price,
                si.invoice_total_net_unit_price,
                si.net_unit_price,
                (
                    COALESCE(
                        (
                            SELECT cst.purchase_unit_cost
                            FROM {$this->db->dbprefix('costing')} cst
                            JOIN {$this->db->dbprefix('purchase_items')} pit
                                ON pit.id = cst.purchase_item_id
                            WHERE pit.product_id = si.product_id
                              AND (pit.option_id = si.option_id OR pit.option_id IS NULL)
                            ORDER BY cst.id DESC
                            LIMIT 1
                        ), 0
                    ) * si.quantity
                ) AS total_cost
            FROM {$this->db->dbprefix('sale_items')} si
            LEFT JOIN {$this->db->dbprefix('product_variants')} pv ON si.option_id = pv.id
            LEFT JOIN {$this->db->dbprefix('products')} p_direct ON si.product_id = p_direct.id
            LEFT JOIN {$this->db->dbprefix('categories')} c_direct ON p_direct.category_id = c_direct.id
            LEFT JOIN {$this->db->dbprefix('brands')} b_direct ON p_direct.brand = b_direct.id
        ) FSI";
        
        
        if ($pdf || $xls || $img) {
            $this->db->select("
                DATE_FORMAT(date, '%Y-%m-%d') as date,
                FSI.code as barcode,
                FSI.product_name as product_name,
                FSI.categories,
                FSI.subcatgory,
                FSI.brand,
                FSI.article_code as style_Code,
                FSI.sizevarient as sizevarient,
                CASE WHEN FSI.batch_number IS NULL OR FSI.batch_number = '' OR FSI.batch_number = 'N/A'
                    THEN '' ELSE FSI.batch_number END AS batch_number,
                FSI.quantity as quantity,

                IF({$this->db->dbprefix('sales')}.sale_status='returned',
                    -(FSI.total_cost),
                    FSI.total_cost
                ) AS purchasecost,

                FSI.invoice_total_net_unit_price as selling_price,
                FSI.item_discount as discount,
                FSI.item_tax as taxamt,
                FSI.tax as taxrate,

                IF({$this->db->dbprefix('sales')}.sale_status='returned',
                    -(abs(FSI.invoice_total_net_unit_price) - abs(FSI.item_discount) - FSI.cost),
                    FSI.invoice_total_net_unit_price - FSI.item_discount - FSI.cost
                ) AS grossprofit,

                IF({$this->db->dbprefix('sales')}.sale_status='returned',
                    -(abs(FSI.invoice_total_net_unit_price) - abs(FSI.item_discount)
                        - FSI.cost - abs(FSI.item_tax)
                    ),
                    FSI.invoice_total_net_unit_price - FSI.item_discount
                        - FSI.cost - FSI.item_tax
                ) AS netprofite,

                {$this->db->dbprefix('sales')}.id as id
            ", FALSE)
            ->from('sales')
            ->join($si, 'FSI.sale_id=sales.id', 'left')
