    function load_product_varient_purchase_report() {
        $Data['Type'] = 'Variant';
        $Data['category'] = $this->input->get('category') ? $this->input->get('category') : NULL;
        $Data['brand'] = $this->input->get('brand') ? $this->input->get('brand') : NULL;
        $Data['warehouse'] = $warehouse = $this->input->get('warehouse') ? $this->input->get('warehouse') : NULL;
        $Data['v'] = $this->input->get('v') ? $this->input->get('v') : NULL;
        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;
        if ($start_date) {
            $Data['start_date'] = $start_date = $this->sma->fld($start_date);
            $Data['end_date'] = $end_date = $this->sma->fld($end_date);
        }
        if ($Data['v'] == 'export') {
            $strtlimit = $this->input->get('strtlimit') ? $this->input->get('strtlimit') : NULL;
            $limt = explode("-", $strtlimit);
            if ($limt) {
                $Data['start'] = $start = $limt[0];
                $Data['limit'] = $limit = $limt[1];
            }
            //echo $start.' '.$limit; exit;
        }

        //$Query = "select p.name, p.code, c.name as cat_name, b.name as brand_name, p.quantity as qty, (p.quantity * p.cost) as product_cost from sma_products p inner join sma_categories c on p.category_id=c.id inner join sma_brands b on b.id=p.brand inner join sma_warehouses_products_variants wpv on p.id=wpv.product_id group by wpv.product_id ";

        $total = $this->reports_model->count_product_varient_purchase_data($Data, isset($_REQUEST['search']) ? $_REQUEST['search'] : "");
        $data = array();
        $dtStart = isset($_REQUEST['start']) ? $_REQUEST['start'] : "";
        $dtLength = isset($_REQUEST['length']) ? $_REQUEST['length'] : "";
        if ($dtLength === -1 || $dtLength === '-1') {
            $dtStart = '';
            $dtLength = '';
        }
        $Result = $this->reports_model->load_product_varient_purchase_data($Data, $dtStart, $dtLength, isset($_REQUEST['search']) ? $_REQUEST['search'] : "");
        $dataArray = array();
        if ($Result->num_rows() > 0) {
            $Res = $Result->result_array();
            foreach ($Res as $key => $value) {
                $ProductId = $value['product_id'];
                $row_data['product_id'] = $value['product_id'];
                $row_data['name'] = $value['name'];
                $row_data['code'] = $value['code'];
                $row_data['cat_name'] = $value['cat_name'];
                $row_data['color_name'] = $value['color_name'];
                $row_data['brand_name'] = $value['brand_name'];

                // Aggregate distinct batch numbers for this product (exclude empty / 'N/A')
                $batchSql = "SELECT GROUP_CONCAT(DISTINCT NULLIF(NULLIF(ssi.batch_number,''),'N/A') 
                  ORDER BY ssi.batch_number SEPARATOR ', ') AS batch_numbers
              FROM {$this->db->dbprefix('purchase_items')} ssi
              JOIN {$this->db->dbprefix('purchases')} s ON s.id = ssi.purchase_id
              WHERE ssi.product_id = ?";
                $batchBinds = [$ProductId];
                if ($warehouse) {
                    $batchSql .= " AND ssi.warehouse_id = ?";
                    $batchBinds[] = $warehouse;
                }
                if (!empty($Data['start_date'])) {
                    $batchSql .= " AND DATE(s.date) BETWEEN ? AND ?";
                    $batchBinds[] = $Data['start_date'];
                    $batchBinds[] = $Data['end_date'];
                }
                $batchRow = $this->db->query($batchSql, $batchBinds)->row_array();
                $row_data['batch_numbers'] = isset($batchRow['batch_numbers']) ? $batchRow['batch_numbers'] : '';

                $i = 1;
                $VarientName = $this->reports_model->getVarientName('Variant');
                $TotalQty = 0;
                if (!empty($VarientName)) {
                    foreach ($VarientName as $key_varient_name => $value_varient_name) {
                        $Sql = "SELECT pv.product_id, p.name AS p_name, SUM(ssi.subtotal) AS varient_cost, 
                                        pv.name, pv.cost, pv.price, SUM(ssi.quantity) AS quantity
                                FROM sma_products p
                                INNER JOIN sma_product_variants pv ON p.id=pv.product_id
                                INNER JOIN sma_purchase_items ssi ON pv.id=ssi.option_id
                                INNER JOIN sma_purchases s ON s.id=ssi.purchase_id
                                WHERE p.id='$ProductId' 
                                AND pv.name='" . $value_varient_name['name'] . "'";

                        if ($warehouse) {
                            $Sql .= " AND ssi.warehouse_id='$warehouse' ";
                        }
                        if ($Data['start_date']) {
                            $Sql .= " AND DATE(s.date) BETWEEN '" . $Data['start_date'] . "' 
                                    AND '" . $Data['end_date'] . "'";
                        }
                        $Sql .= " GROUP BY ssi.option_id ";
                        $Res = $this->db->query($Sql);
                        $Row = $Res->result_array();
                        if (!empty($Row)) {
                            foreach ($Row as $varient_key => $varient_value) {
                                $row_data['v_' . $value_varient_name['id']] = ($varient_value['quantity']);
                                $TotalQty += $varient_value['quantity'];
                            }
                        } else {
                            $row_data['v_' . $value_varient_name['id']] = 0;
                        }
                    }
                }
                $row_data['qty_product_cost'] = ($TotalQty);
                $dataArray[] = $row_data;
                }
                }
                if ($Data['v'] == 'export') {

                    $segment = $this->uri->segment(3) ? $this->uri->segment(3) : '';
                
                    $this->load->library('excel');
                    $sheet = $this->excel->setActiveSheetIndex(0);
                
                    /* -------------------------------
                       HEADER TITLE
                    --------------------------------*/
                    $headerStyle = [
                        'alignment' => ['horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER],
                        'font'      => ['name' => 'Arial', 'color' => ['rgb' => 'FF0000']]
                    ];
                
                    $sheet->mergeCells('A1:AZ1');
                    $sheet->setCellValue('A1', 'Products Variant Item Report');
                    $sheet->getStyle('A1')->applyFromArray($headerStyle);
                
                    /* -------------------------------
                       HEADER COLUMNS
                    --------------------------------*/
                    $headers = ['Product Name', 'Code', 'Category', 'Color Name', 'Brand'];
                
                    if ($this->Settings->product_batch_setting == 1 || $this->Settings->product_batch_setting == 2) {
                        $headers[] = 'Batch No.';
                    }
                
                    $headers[] = 'Qty';
                
                    if (!empty($VarientName)) {
                        foreach ($VarientName as $v) {
                            $headers[] = $v['name'];
                        }
                    }
                
                    // write headers
                    $colLetters = [];
                    for ($i = 0; $i < count($headers); $i++) {
                        $colLetters[] = PHPExcel_Cell::stringFromColumnIndex($i);
                        $sheet->setCellValue($colLetters[$i] . '2', $headers[$i]);
                        $sheet->getStyle($colLetters[$i] . '2')->getFont()->setBold(true);
                    }
                
                    /* ---------------------------------
                       CLASSIFY COLUMNS FOR ALIGNMENT
                    ----------------------------------*/
                    $textCols = [];      // LEFT alignment
                    $centerCols = [];    // Qty + Variant Qtys = CENTER alignment
                
                    // fixed text columns
                    $textCols[] = $colLetters[0]; // Product Name
                    $textCols[] = $colLetters[1]; // Code
                    $textCols[] = $colLetters[2]; // Category
                    $textCols[] = $colLetters[3]; // Color
                    $textCols[] = $colLetters[4]; // Brand
                
                    $idx = 5;
                
                    if ($this->Settings->product_batch_setting == 1 || $this->Settings->product_batch_setting == 2) {
                        $textCols[] = $colLetters[$idx]; // Batch
                        $idx++;
                    }
                
                    // Qty column
                    $centerCols[] = $colLetters[$idx];
                    $idx++;
                
                    // Variant qty columns
                    for ($i = 0; $i < count($VarientName); $i++, $idx++) {
                        $centerCols[] = $colLetters[$idx];
                    }
                
                    /* ---------------------------------
                       FILL ROWS
                    ----------------------------------*/
                    $row = 3;
                    foreach ($dataArray as $d) {
                
                        $c = 0;
                
                        // Text columns
                        $sheet->setCellValue($colLetters[$c++] . $row, $d['name']);
                        $sheet->setCellValue($colLetters[$c++] . $row, $d['code']);
                        $sheet->setCellValue($colLetters[$c++] . $row, $d['cat_name']);
                        $sheet->setCellValue($colLetters[$c++] . $row, $d['color_name']);
                        $sheet->setCellValue($colLetters[$c++] . $row, $d['brand_name']);
                
                        // Batch column
                        if ($this->Settings->product_batch_setting == 1 || $this->Settings->product_batch_setting == 2) {
                            $sheet->setCellValue($colLetters[$c++] . $row, $d['batch_numbers']);
                        }
                
                        // Qty
                        $sheet->setCellValueExplicit(
                            $colLetters[$c] . $row,
                            $this->sma->formatQuantity($d['qty_product_cost']),
                            PHPExcel_Cell_DataType::TYPE_STRING
                        );
                        $c++;
                
                        // Variant Qty columns
                        if (!empty($VarientName)) {
                            foreach ($VarientName as $v) {
                                $qty = isset($d['v_' . $v['id']]) ? $d['v_' . $v['id']] : 0;
                                $sheet->setCellValueExplicit(
                                    $colLetters[$c] . $row,
                                    $this->sma->formatQuantity($qty),
                                    PHPExcel_Cell_DataType::TYPE_STRING
                                );
                                $c++;
                            }
                        }
                
                        $row++;
                    }
                
                
                    /* ---------------------------------
                       APPLY ALIGNMENT DYNAMICALLY
                    ----------------------------------*/
                
                    // left align text columns
                    foreach ($textCols as $col) {
                        $sheet->getStyle("{$col}3:{$col}{$row}")
                              ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                    }
                
                    // center align Qty + Variant Qty columns
                    foreach ($centerCols as $col) {
                        $sheet->getStyle("{$col}3:{$col}{$row}")
                              ->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                    }
                
                    /* ---------------------------------
                       EXPORT OUTPUT (PDF/XLS/IMG)
                    ----------------------------------*/
                
                    $filename = 'purchase_products_varient_item_report';
                
                    if ($segment == 'xls') {
                        ob_clean();
                        header('Content-Type: application/vnd.ms-excel');
                        header('Content-Disposition: attachment;filename="' . $filename . '.xls"');
                        header('Cache-Control: max-age=0');
                        $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                        $objWriter->save('php://output');
                        exit();
                    }
                }
                else {
            $DataArray = array('draw' => $_REQUEST['draw'], 'recordsTotal' => $total, 'recordsFiltered' => $total, 'data' => $dataArray);
            echo json_encode($DataArray);
        }
    }

