            function Product_wise_Sale_Report()
            {
                $this->data['error'] = (validation_errors()) ? validation_errors() : $this->session->flashdata('error');

                $cc = $this->data['customers'] = $this->reports_model->getCustomerFromsales();
                $p = $this->data['products'] = $this->reports_model->getProductFromsalesItem();

                foreach ($p as $p_c) {
                    $d[]=$this->reports_model->getProductQuantity($p_c->product_code);
                }
