            function products_transactions() {

                $this->sma->checkPermissions();
                $this->data['error'] = (validation_errors() ? validation_errors() : $this->session->flashdata('error'));
                $this->data['categories'] = $this->site->getAllCategories();
                $this->data['brands'] = $this->site->getAllBrands();
                $this->data['warehouses'] = $this->site->getAllWarehouses();
                // Set default date range to today if no dates are provided
                $today = date('d/m/Y');
                if (!$this->input->post('start_date') && !$this->input->post('end_date')) {
                    $this->data['start_date'] = $today;
                    $this->data['end_date'] = $today;
                    $dt = "Today";
                } else {
                    $this->data['start_date'] = $this->input->post('start_date');
                    $this->data['end_date'] = $this->input->post('end_date');
                    if ($this->input->post('start_date') == $this->input->post('end_date')) {
                        $dt = $this->input->post('start_date') == $today ? "Today" : $this->input->post('start_date');
                    } else {
                        $dt = "From " . $this->input->post('start_date') . " to " . $this->input->post('end_date');
                    }
                }
                $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('Products_Transactions_Report')));
                $meta = array('page_title' => lang('Products_Transactions_Report'), 'bc' => $bc);
                $this->page_construct('reports/products_transactions', $meta, $this->data);
            }

            function getProductsTransactionsReport() {
                $this->sma->checkPermissions('products', TRUE);
                $product = isset($_REQUEST['product']) ? $_REQUEST['product'] : NULL;
                $category = isset($_REQUEST['category']) ? $_REQUEST['category'] : NULL;
                $brand = isset($_REQUEST['brand']) ? $_REQUEST['brand'] : NULL;
                $subcategory = isset($_REQUEST['subcategory']) ? $_REQUEST['subcategory'] : NULL;
                $user = $this->site->getUser();
                $all_warehouses = $this->site->getAllwarehouses($user->id);
                $warehouse_ids = isset($_REQUEST['warehouse']) ? $_REQUEST['warehouse'] : array_map(function ($warehouse) {
                    return $warehouse->id;
                }, $all_warehouses);   
                if (count($warehouse_ids) > 1) {
                    $warehouse = implode(',', $warehouse_ids);
                }else{
                    $warehouse = $warehouse_ids;
                }
            
                
                
                // $start_date_raw = isset($_GET['start_date']) ? trim($_GET['start_date']) : date("d/m/Y");
                // $start_date_raw = isset($_POST['start_date']) ? trim($_POST['start_date']) : date("d/m/Y");

                // Set default date range to today if no dates are provided
                $today = date('d/m/Y');
                if ((!isset($_GET['start_date']) || empty($_GET['start_date'])) && (!isset($_POST['start_date']) || empty($_POST['start_date']))) {
                    $start_date_raw = $today;
                    $end_date_raw = $today;
                } else {
                    if (!empty($_GET['start_date'])) {
                        $start_date_raw = isset($_GET['start_date']) ? trim($_GET['start_date']) : '';
                    } else {
                        $start_date_raw = isset($_POST['start_date']) ? trim($_POST['start_date']) : '';
                    }
                    if (!empty($_GET['end_date'])) {
                        $end_date_raw = isset($_GET['end_date']) ? trim($_GET['end_date']) : '';
                    } else {
                        $end_date_raw = isset($_POST['end_date']) ? trim($_POST['end_date']) : '';
                    }
                }
                
                $with_or_without_gst = isset($_REQUEST['with_or_without_gst']) ? $_REQUEST['with_or_without_gst'] : NULL;
                $purchase_date_filter = isset($_REQUEST['purchase_date_filter']) ? $_REQUEST['purchase_date_filter'] : NULL;
                $start_date = $start_date_raw?DateTime::createFromFormat('d/m/Y', $start_date_raw):'';
                $end_date = $end_date_raw?DateTime::createFromFormat('d/m/Y', $end_date_raw):'';
                $start_date_str = $start_date?$start_date->format('Y-m-d'):'';
                $end_date_str = $end_date?$end_date->format('Y-m-d'):'';
                
                $products_where = [];
                if (!empty($product)) {
                    $products_where[] = " prd.id= '$product' ";
                } else {
                    if (!empty($brand)) {
                        $products_where[] = " prd.brand = '$brand' ";
                    } else {
                        if (!empty($category))
                            $products_where[] = " prd.category_id = '$category' ";
                        if (!empty($subcategory))
                            $products_where[] = " prd.subcategory_id = '$subcategory' ";
                    }
                }

                if (!empty($products_where)) {
                    $product_subquery = "SELECT id FROM sma_products prd WHERE " . join(' AND ', $products_where);
                    $sale_where[] = " s.product_id IN ($product_subquery) ";
                    $purchase_where[] = " prd.id IN ($product_subquery) ";
                }

                if ($start_date_str) {
                    // if ($purchase_date_filter) {
                        // $purchase_where[] = " DATE(p.transaction_date) BETWEEN '{$start_date_str}' AND '{$end_date_str}'";
                    // }
                    // $purchase_where[] = " DATE(p.transaction_date) BETWEEN '{$start_date_str}' AND '{$end_date_str}'";
                    if (count($warehouse_ids) > 1) {
                        // Build the WHERE condition if $warehouse_ids is not empty
                        $sale_purchase_where ="DATE(s.date) BETWEEN '{$start_date_str}' AND '{$end_date_str}' AND (s.warehouse_id IN ($warehouse) OR s.warehouse_id = '*All')";
                        $sale_where = "DATE(s.date) BETWEEN '{$start_date_str}' AND '{$end_date_str}' AND (warehouse_id IN ($warehouse) OR warehouse_id = '*All')";
                        $warehouse_where = "(warehouse_id IN ($warehouse) OR warehouse_id = '*All')";
                        $warehouse_where_for_p = "AND(p.warehouse_id IN ($warehouse) OR p.warehouse_id = '*All')";
                        $warehouse_where_for_p2 = "(p.warehouse_id IN ($warehouse) OR p.warehouse_id = '*All')";
                        $sale_where_count[] = "DATE(s.date) BETWEEN '{$start_date_str}' AND '{$end_date_str}' AND (s.warehouse_id IN ($warehouse) OR s.warehouse_id = '*All')";
                    } else {
