                                    pv.id AS variant_id,
                                    COALESCE(purchase_data.purchase_qty, 0) AS purchase_qty,
                                    COALESCE(adj.adjustment_qty, 0) AS adjustment_qty,
                                    SUM(p.transfer_qty) AS transfer_qty,
                                    COALESCE(p1.total_quantity_balance, 0) AS quantity_balance,
                                    SUM(p.quantity_balance) AS quantity_balance_cal,
                                    SUM(IF(p.transfer_id IS NULL, (p.subtotal - p.item_tax), 0)) AS purchase_cost,
                                    SUM(IF(p.transfer_id IS NULL, p.subtotal, 0)) AS purchase_cost_include_tax,
                                    (COALESCE(p1.total_quantity_balance, 0) * COALESCE(p1.net_unit_cost, 0)) AS balance_stock_value,
                                    (COALESCE(p1.total_quantity_balance, 0) * COALESCE(p1.unit_cost, 0)) AS balance_stock_value_include_tax,
                                    SUM(p.quantity_balance * COALESCE(p.net_unit_cost, 0)) AS balance_stock_value_cal,
