                                        </tr>
                                    </thead>';
                                $tableRow = '';
                                foreach ($transactionData as $rowdata) {
                                    $rowdata = (array) $rowdata;
                                    
                                    // Check for empty or null values and set to 0 if necessary
                                    $purchase_cost = ($with_or_without_gst == 'without_gst') 
                                        ? (isset($rowdata['purchase_cost']) && $rowdata['purchase_cost'] !== '' ? $rowdata['purchase_cost'] : 0) 
                                        : (isset($rowdata['purchase_cost_include_tax']) && $rowdata['purchase_cost_include_tax'] !== '' ? $rowdata['purchase_cost_include_tax'] : 0);
                                
                                    $stock_value = ($with_or_without_gst == 'without_gst') 
                                        ? (isset($rowdata['balance_stock_value']) && $rowdata['balance_stock_value'] !== '' ? $rowdata['balance_stock_value'] : 0) 
                                        : (isset($rowdata['balance_stock_value_include_tax']) && $rowdata['balance_stock_value_include_tax'] !== '' ? $rowdata['balance_stock_value_include_tax'] : 0);
                                
                                    $stock_value_cal = ($with_or_without_gst == 'without_gst') 
                                        ? (isset($rowdata['balance_stock_value_cal']) && $rowdata['balance_stock_value_cal'] !== '' ? $rowdata['balance_stock_value_cal'] : 0) 
                                        : (isset($rowdata['balance_stock_value_include_tax_cal']) && $rowdata['balance_stock_value_include_tax_cal'] !== '' ? $rowdata['balance_stock_value_include_tax_cal'] : 0);
                                
                                    $sold_value = ($with_or_without_gst == 'without_gst') 
                                        ? (isset($rowdata['total_Sale_amount']) && $rowdata['total_Sale_amount'] !== '' ? $rowdata['total_Sale_amount'] : 0) 
                                        : (isset($rowdata['total_Sale_amount_include_tax']) && $rowdata['total_Sale_amount_include_tax'] !== '' ? $rowdata['total_Sale_amount_include_tax'] : 0);
                                
                                    $profit_loss = ($sold_value + $stock_value_cal) - $purchase_cost;
                                    
                                    $class_profit_loss = $profit_loss >= 0 ? 'text-default' : 'text-danger';

                                    $row  = '<tr>';

                                    $row .= '<td class="text-left">' . $rowdata['product_code'] . '</td>';
                                    $row .= '<td class="text-left">' . $rowdata['product_name'] . '</td>';
                                    $row .= '<td class="text-left">' . $rowdata['pv_name'] . '</td>';

                                    /* (A) Purchase Qty */
                                    $row .= '<td class="text-center qty text-bold" data-value="' . $rowdata['purchase_qty'] . '">' 
                                        . $rowdata['purchase_qty'] . '</td>';

                                    /* (B) Adjustment Qty */
                                    $row .= '<td class="text-center qty" data-value="' . $rowdata['adjustment_qty'] . '">' 
                                        . $rowdata['adjustment_qty'] . '</td>';

                                    /* (C) Transfer Request Qty */
                                    $row .= '<td class="text-center qty" data-value="' . $rowdata['request_quantity'] . '">' 
                                        . $rowdata['request_quantity'] . '</td>';

                                    /* (D) Transfer Qty */
                                    $row .= '<td class="text-center qty" data-value="' . $rowdata['transfer_qty'] . '">' 
                                        . $rowdata['transfer_qty'] . '</td>';

                                    /* (A+B) Purchase Cost */
                                    $row .= '<td class="text-right money" data-value="' . $purchase_cost . '">' 
                                        . $purchase_cost . '</td>';

                                    /* Sold Qty */
                                    $row .= '<td class="text-center qty text-success" data-value="' . $rowdata['sold_qty'] . '">' 
                                        . $rowdata['sold_qty'] . '</td>';

                                    /* Sold Value */
                                    $row .= '<td class="text-right money text-success" data-value="' . $sold_value . '">' 
                                        . $sold_value . '</td>';

                                    /* Stock Qty */
                                    $row .= '<td class="text-center qty text-primary" data-value="' . $rowdata['quantity_balance'] . '">' 
                                        . $rowdata['quantity_balance'] . '</td>';

                                    /* Stock Value */
                                    $row .= '<td class="text-right money text-primary" data-value="' . $stock_value_cal . '">' 
                                        . $stock_value_cal . '</td>';

                                    /* Profit / Loss */
                                    $row .= '<td class="text-right money ' . $class_profit_loss . '" data-value="' . $profit_loss . '">' 
                                        . $profit_loss . '</td>';

                                    $row .= '</tr>';
                                    
                                
                                    $tableRow .= $row;
                                }

