                if ($_GET['export'] == 'img') {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save(str_replace(__FILE__, 'assets/mdata/'.$this->Customer_assets.'/uploads/pdf/products_ledgers.pdf', __FILE__));
                    redirect("reports/create_image/products_ledgers.pdf");
                    exit();
                }
            }
            $this->session->set_flashdata('error', lang('nothing_found'));
            redirect($_SERVER["HTTP_REFERER"]);
        } else {

            if (is_array($transactionData)) {

                $totalRows = $countData->total_data;
                $totalPages = ceil($totalRows / $per_page_rows);

                $pagignation = $this->sma->ajax_pagignations($totalPages, $page);

                $tableHeader = '<table class="table table-striped table-bordered table-condensed table-hover dfTable reports-table" style="margin-bottom:5px;">
                            <thead>                               
                            <tr> 
                                <th>Date</th>
                                <th>Products Code</th>
                                <th>Products Name</th>
                                <th>Varient Name</th>
                                <th>Action</th>
                                <th>Quantity</th>
                                <th>Qty. CR</th>
                                <th>Qty. DR</th>
                                <th>Warehouse</th>
                                <th>In Stock</th>
                                <th>Status</th>
                                <th>User</th>                                 
                            </tr>
                            </thead>
                            <tbody>';

                $tableRow = '';
                foreach ($transactionData as $rowdata) {
                    $rowdata = (array) $rowdata;

                    $class_qty_color = $rowdata['quantity'] > 0 ? 'text-default' : 'text-danger';

                    $row = '<tr><td>' . $rowdata['date'] . '</td>';
                    $row .= '<td>' . $rowdata['product_code'] . '</td>';
                    $row .= '<td>' . $rowdata['product_name'] . '</td>';
                    $row .= '<td>' . $rowdata['varient_name'] . '</td>';
                    $row .= '<td>' . $rowdata['action'] . '</td>';
                    $row .= '<td class="text-center ' . $class_qty_color . '">' . $this->sma->formatQuantity($rowdata['quantity']) . '</td>'; // 6th column
                    $row .= '<td class="text-center">' . $this->sma->formatQuantity($rowdata['cr']) . '</td>'; // 7th column
                    $row .= '<td class="text-center">' . $this->sma->formatQuantity($rowdata['dr']) . '</td>'; // 8th column
                    $row .= '<td>' . $rowdata['warehouse_code'] . '</td>';

                    if ($rowdata['action'] == 'purchase' && $rowdata['status'] == "ordered") {
                        $row .= '<td class="text-center text-danger"><del>' . $this->sma->formatQuantity($rowdata['in_stock']) . '</del></td>'; // 10th column
                    } else {
                        $balance = $this->sma->formatQuantity($rowdata['in_stock']);
                        $row .= '<td class="text-center">' . $balance . '</td>'; // 10th column
                    }

                    $row .= '<td>' . $rowdata['status'] . '</td>';
                    $row .= '<td>' . $rowdata['created_by'] . '</td>';
                    $row .= '</tr>';


                    $tableRow .= $row;

                    $qty_Total += $rowdata['quantity'];
                    $cr_Total += $rowdata['cr'];
                    $dr_Total += $rowdata['dr'];
                    $instock_Total += $balance;
                }//end foreach.

                $tableFooter = '</tbody>
                                <tfoot class="dtFilter">
                                <tr>                                 
                                    <th></th>
                                    <th></th>
                                    <th></th>
                                    <th></th>
                                    <th></th>
                                    <th style="text-align: center;">' . $this->sma->formatQuantity($qty_Total) . '</th>
                                    <th style="text-align: center;">' . $this->sma->formatQuantity($cr_Total) . '</th>
                                    <th style="text-align: center;">' . $this->sma->formatQuantity($dr_Total) . '</th>
                                    <th></th>                                 
                                    <th style="text-align: center;">' . $this->sma->formatQuantity($instock_Total) . '</th>
                                    <th></th>
                                    <th></th>
                                </tr>
                                </tfoot>
                            </table>';
            }

            echo  $tableHeader . $tableRow . $tableFooter . $pagignation;
        }//end else
    }

    public function load_ajax_reports() {

        $postData = $_POST;
        switch ($_POST['action']) {
            case "ProductsTransactionsReport":
                $this->getProductsTransactionsReport($postData);

                break;

            case "ProductsLedgers":
                $this->getProductsLedgers($postData);

                break;

            case "CustomerLedgers":
                $this->getCustomerLedger($postData);

                break;
            case "CustomerLedgersV1":
                $this->getCustomerLedgerV1($postData);

                break;
            case "CustomerDepositLadger":
                $this->getCustomerDepositLedger($postData);
                break;
            default:
                break;
        }
    }

    /**
     * Transfer Request Reports
     */
        public function transfer_request() {
        $this->sma->checkPermissions('transfer_request');
        $this->data['error'] = (validation_errors() ? validation_errors() : $this->session->flashdata('error'));
        $this->data['categories'] = $this->site->getAllCategories();

        $fwarehouse = $this->input->post('warehouse') ? $this->input->post('warehouse') : NULL;

        if ($fwarehouse) {
            $warehouses = $this->site->getWarehouseByID($fwarehouse);
        } else {
            $warehouses = $this->site->getAllWarehouses();
        }
       
        $user = $this->ion_auth->user($id)->row();
        $this->data['warehouses_id']     =  $user->warehouse_id;
            $warehouse_id = explode(",", $user->warehouse_id);
            if (!$this->Owner && !$this->Admin) {
                $warehouses = $this->reports_model->getWarehouse($warehouse_id);
            }
       
        $this->data['warehouses'] = $warehouses;
        $this->data['all_warehouses'] = $this->site->getAllWarehouses();
        $this->data['brands'] = $this->site->getAllBrands();
        $this->data['users'] = $this->reports_model->getStaff();

        //$this->data['warehouses'] = $this->site->getAllWarehouses(); 
        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('Transfer_Request_Report')));
        $meta = array('page_title' => lang('Transfer Request'), 'bc' => $bc);
        $this->page_construct('reports/transfer_request', $meta, $this->data);
    }

    /**
     * Get Transfer Request Reports
     * @param type $pdf
     * @param type $xls
     * @param type $img
     */
    function gettransfer_request($pdf = NULL, $xls = NULL, $img = NULL) {
        $product = $this->input->get('product') ? $this->input->get('product') : NULL;
        $category = $this->input->get('category') ? $this->input->get('category') : NULL;
        $subcategory = $this->input->get('subcategory') ? $this->input->get('subcategory') : NULL;
        $brand = $this->input->get('brand') ? $this->input->get('brand') : NULL;
        $fwarehouse = $this->input->get('warehouse') ? $this->input->get('warehouse') : NULL;
        $user = $this->input->get('user') ? $this->input->get('user') : NULL;
        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;

        if ($fwarehouse) {
            $warehouse = explode('_', $fwarehouse);
            $warehouses = $this->reports_model->getWarehouse($warehouse);
        } else {
            $warehouses = $this->site->getAllWarehouses();
        }



        if ($pdf || $xls || $img) {
            $this->db->select("
                sma_products.code as product_code,
                sma_products.name as product_name,
                sma_product_variants.name as varient,
                sma_categories.name as category,
                scategory.name as subcategory,
                sma_brands.name as brand,
                ROUND(SUM(sma_transfer_request_items.request_quantity), 2) as quantity,
                sma_transfer_request_items.product_id,
                sma_transfer_request_items.option_id
            ");

            $this->db->from('sma_transfer_request_items');

            $this->db->join(
                'sma_transfer_request',
                'sma_transfer_request_items.transfer_request_id = sma_transfer_request.id',
                'left'
            );
            $this->db->join(
                'sma_product_variants',
                'sma_product_variants.id = sma_transfer_request_items.option_id',
                'left'
            );
            $this->db->join(
                'sma_products',
                'sma_products.id = sma_transfer_request_items.product_id',
                'left'
            );
            $this->db->join(
                'sma_categories',
                'sma_categories.id = sma_products.category_id',
                'left'
            );
            $this->db->join(
                'sma_categories as scategory',
                'scategory.id = sma_products.subcategory_id',
                'left'
            );
            $this->db->join(
                'sma_brands',
                'sma_brands.id = sma_products.brand',
                'left'
            );

                    
            if ($product) $this->db->where('sma_products.id', $product);
            if ($category) $this->db->where('sma_categories.id', $category);
            if ($subcategory) $this->db->where('scategory.id', $subcategory);
            if ($brand) $this->db->where('sma_brands.id', $brand);
            if ($user) $this->db->where('sma_transfer_request.created_by', $user);

            if ($fwarehouse) {
                $warehouse = explode('_', $fwarehouse);
                $this->db->where_in('sma_transfer_request_items.warehouse_id', $warehouse);
            }

            if ($start_date) {
                $start_date = $this->sma->fld($start_date);
                $end_date = $end_date ? $this->sma->fld($end_date) : date('Y-m-d');
                $this->db->where("DATE(sma_transfer_request.date) BETWEEN '{$start_date}' AND '{$end_date}'");
            }

            $this->db->where_in(
                'sma_transfer_request.status',
                ['pending', 'completed', 'cancelled']
            );

            $this->db->group_by(
                'sma_transfer_request_items.product_id,
                sma_transfer_request_items.option_id'
            );
            $this->db->order_by('sma_products.name', 'ASC');

            $data = $this->db->get()->result();

        
        
            if (!empty($data)) {
        
                /* Dynamic column letters after G */
                $colLetters = range('A','Z'); // supports up to 26 warehouses
                $this->load->library('excel');
                $sheet = $this->excel->setActiveSheetIndex(0);
        
                /* Determine last header column dynamically */
                $lastHeaderCol = $colLetters[6 + count($warehouses)]; // A-F = 6 cols, G = 7th
        
                /* Header Title */
                $sheet->mergeCells("A1:{$lastHeaderCol}1");
                $sheet->setCellValue("A1", "Transfer Request Report");

                $sheet->getStyle("A1")->applyFromArray([
                    'font' => [
                        'bold' => true,
                        'size' => 16,
                        'color' => ['rgb' => 'FF0000']
                    ],
                    'alignment' => [
                        'horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER
                    ]
                ]);
                      
                /* Header labels */
                $sheet->setCellValue("A2", "Code");
                $sheet->setCellValue("B2", "Product Name");
                $sheet->setCellValue("C2", "Variant");
                $sheet->setCellValue("D2", "Category");
                $sheet->setCellValue("E2", "Subcategory");
                $sheet->setCellValue("F2", "Brand");
                $sheet->setCellValue("G2", "Total Request Qty");
        
                /* Dynamic warehouse headers */
                foreach ($warehouses as $i => $wh) {
                    $sheet->setCellValue($colLetters[7 + $i] . '2', $wh->name);
                }
        
                /* Make entire header row bold */
                $sheet->getStyle("A2:{$lastHeaderCol}2")->applyFromArray([
                    'font' => ['bold' => true],
                    'borders' => [
                        'allborders' => [
                            'style' => PHPExcel_Style_Border::BORDER_THIN
                        ]
                    ],
                    'alignment' => [
                        'horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER
                    ]
                ]);                
        
                $row = 3;
        
                /* BODY rows */
                foreach ($data as $data_row) {
        
                    $sheet->setCellValueExplicit("A{$row}", $data_row->product_code, PHPExcel_Cell_DataType::TYPE_STRING);
                    $sheet->getStyle("A{$row}")->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                    $sheet->setCellValue("B{$row}", $data_row->product_name);
                    $sheet->setCellValue("C{$row}", $data_row->varient);
                    $sheet->getStyle("C{$row}")->applyFromArray([
                        'alignment' => [
                            'horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_LEFT,
                        ],
                    ]);
                    $sheet->setCellValue("D{$row}", $data_row->category);
                    $sheet->setCellValue("E{$row}", $data_row->subcategory);
                    $sheet->setCellValue("F{$row}", $data_row->brand);
        
                    /* Qty as REAL NUMBER (no green triangle) */
                    $sheet->setCellValueExplicit("G{$row}", $this->sma->formatQuantity($data_row->quantity), PHPExcel_Cell_DataType::TYPE_STRING);
                    $sheet->getStyle("G{$row}")->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
        
                    /* Warehouse dynamic QTY */
                    foreach ($warehouses as $i => $wh) {
                        $qty = $this->reports_model->warehouseqty_variant(
                            $data_row->product_id, 
                            $data_row->option_id, 
                            $wh->id,
                            $start_date,
                            $end_date
                        );
        
                        $col = $colLetters[7 + $i];
                        $sheet->setCellValueExplicit("{$col}{$row}", $this->sma->formatQuantity($qty), PHPExcel_Cell_DataType::TYPE_STRING);
                        $sheet->getStyle("{$col}{$row}")->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                    }
                    $total_quantity += $data_row->quantity;
                    $row++;
                }
        
                /* FOOTER TOTAL ROW */
                $totalRow = $row;
                $sheet->mergeCells("A{$totalRow}:F{$totalRow}");
                $sheet->setCellValue("A{$totalRow}", "TOTAL");
                $sheet->getStyle("A{$totalRow}")->getAlignment()->setHorizontal('right');
                $sheet->getStyle("A{$totalRow}:{$lastHeaderCol}{$totalRow}")->getFont()->setBold(true);
        
                /* Total total-request-qty */
                $sheet->setCellValueExplicit("G{$totalRow}", $this->sma->formatQuantity($total_quantity), PHPExcel_Cell_DataType::TYPE_STRING);
                $sheet->getStyle("G{$totalRow}")->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
        
                /* Total warehouse qty */
                foreach ($warehouses as $i => $wh) {
                    $sumW = 0;
                    foreach ($data as $d) {
                        $sumW += $this->reports_model->warehouseqty_variant(
                            $d->product_id, 
                            $d->option_id, 
                            $wh->id,
                            $start_date,
                            $end_date
                        );
                    }
                    $warehouseCol = $colLetters[7 + $i];
                    $sheet->setCellValueExplicit("{$warehouseCol}{$totalRow}", $this->sma->formatQuantity($sumW), PHPExcel_Cell_DataType::TYPE_STRING);
                    $sheet->getStyle("{$warehouseCol}{$totalRow}")->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                }
                $sheet->getStyle("A2:{$lastHeaderCol}{$totalRow}")->applyFromArray([
                    'borders' => [
                        'allborders' => [
                            'style' => PHPExcel_Style_Border::BORDER_THIN
                        ]
                    ]
                ]);
                
                /* Column width */
                $widths = [15,20,20,20,25,25,15];
                foreach ($widths as $i => $w) {
                    $sheet->getColumnDimension($colLetters[$i])->setWidth($w);
                }
        
                foreach ($warehouses as $i => $wh) {
                    $sheet->getColumnDimension($colLetters[7 + $i])->setWidth(15);
                }
        
                /* Center-align all quantity columns (G onwards) */
                $sheet->getStyle("G3:{$lastHeaderCol}{$totalRow}")
                      ->getAlignment()->setHorizontal('center');
        
                /* Export */
                $filename = "Transfer_reports";
        
                if ($xls) {
                    header("Content-Type: application/vnd.ms-excel");
                    header("Content-Disposition: attachment;filename=\"{$filename}.xls\"");
                    header("Cache-Control: max-age=0");
        
                    $writer = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                    $writer->save('php://output');
                    exit;
                }
            }
        
            $this->session->set_flashdata('error', lang('nothing_found'));
            redirect($_SERVER["HTTP_REFERER"]);
        }
        
        else {
            $this->load->library('datatables');
            $this->load->helper('reports');
            $this->datatables->select('sma_products.code as code, sma_products.name as product_name, sma_product_variants.name as variant, sma_categories.name as category, scategory.name as subcategory, sma_brands.name as brand, ROUND(SUM(sma_transfer_request_items.request_quantity),2) as quantity, sma_transfer_request_items.product_id, sma_transfer_request_items.option_id');

            $this->datatables->from('sma_transfer_request_items');

            $this->datatables->Join('sma_transfer_request', 'sma_transfer_request_items.transfer_request_id = sma_transfer_request.id ', 'RIGHT');
            $this->datatables->Join('sma_product_variants', 'sma_product_variants.id = sma_transfer_request_items.option_id ', 'LEFT');
            $this->datatables->Join('sma_products', 'sma_products.id = sma_transfer_request_items.product_id', 'LEFT');
            $this->datatables->Join('sma_categories', 'sma_categories.id = sma_products.category_id', 'LEFT');
            $this->datatables->Join('sma_categories as scategory', 'scategory.id = sma_products.subcategory_id', 'LEFT');

            $this->datatables->Join('sma_brands ', 'sma_brands.id = sma_products.brand', 'LEFT');

            if ($product) {
                $this->datatables->where('sma_products.id', $product);
            }

            if ($category) {
                $this->datatables->where('sma_categories.id', $category);
            }

            if ($subcategory) {
                $this->datatables->where('scategory.id', $subcategory);
            }

            if ($brand) {
                $this->datatables->where('sma_brands.id', $brand);
            }

            if ($user) {
                $this->datatables->where('sma_transfer_request.created_by', $user);
            }


            if ($fwarehouse) {
                $fwarehouse = explode('_', $fwarehouse);
                $this->datatables->where_in('sma_transfer_request_items.warehouse_id', $fwarehouse);
            }
            
            if ($start_date) {
                $start_date = $this->sma->fld($start_date);
                $end_date = $end_date ? $this->sma->fld($end_date) : date('Y-m-d');
                $this->datatables->where("DATE(sma_transfer_request.date) BETWEEN '{$start_date}' AND '{$end_date}'");
            }
            
            $this->db->where_in('sma_transfer_request.status', ['pending', 'completed', 'cancelled']);
            $this->datatables->group_by('sma_transfer_request_items.product_id, sma_transfer_request_items.option_id');

            foreach ($warehouses as $warehousesitem) {
                $this->datatables->add_column(
                    $warehousesitem->id,
                    '$1',
                    'warehouseqty_trans_req(sma_transfer_request_items.product_id, sma_transfer_request_items.option_id, ' . $warehousesitem->id . ', ' . $start_date . ', ' . $end_date . ')'
                );
            }
            


            $this->datatables->unset_column('sma_transfer_request_items.product_id');
            $this->datatables->unset_column('sma_transfer_request_items.option_id');
            echo $this->datatables->generate();
        }
    }

    public function deposit() {
        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('Deposit_Recharge_Report')));
        $meta = array('page_title' => lang('Deposit_Recharge_Report'), 'bc' => $bc);
        $this->page_construct('reports/deposit', $meta, $this->data);
