    public function get_deposit_report($pdf = NULL, $xls = NULL, $img = NULL) {
        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;


        if ($pdf || $xls || $img) {


            $this->db->select('sma_deposits.date,sma_companies.name,sma_companies.phone,sma_companies.cf1,sma_companies.cf2, sma_deposits.amount,sma_deposits.super_cash,sma_deposits.paid_by, sma_deposits.note, CONCAT(sma_users.first_name, sma_users.last_name) as created_by,sma_deposits.id');
//            $this->db->from('sma_deposits');
            $this->db->join('sma_companies', 'sma_companies.id = sma_deposits.company_id', 'left');
            $this->db->join('sma_users', 'sma_users.id = sma_deposits.created_by', 'left');
            if ($start_date && $end_date) {
                $this->db->where('sma_deposits.date ' . ' BETWEEN "' . $start_date . '" and "' . $end_date . '"');
            }
            $this->db->order_by('sma_deposits.id', 'ASC');
            $data = $this->db->get('sma_deposits')->result();

            if (!empty($data)) {
                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);
                $style = array('alignment' => array('horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,), 'font' => array('name' => 'Arial', 'color' => array('rgb' => 'FF0000')), 'borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_NONE, 'color' => array('rgb' => 'FF0000'))));

                $this->excel->getActiveSheet()->getStyle("A1:L1")->applyFromArray($style);
                $this->excel->getActiveSheet()->mergeCells('A1:L1');
                $this->excel->getActiveSheet()->SetCellValue('A1', $this->Settings->site_name);

                $this->excel->getActiveSheet()->getStyle("A2:L2")->applyFromArray($style);
                $this->excel->getActiveSheet()->mergeCells('A2:L2');
                $report_title = 'Deposit Report';
                if ($start_date && $end_date) {
                    $report_title .= ' (' . $start_date . ' To ' . $end_date . ')';
                }
                $this->excel->getActiveSheet()->SetCellValue('A2', $report_title);
                $this->excel->getActiveSheet()->setTitle(lang('Deposit Recharge Report'));

                $this->excel->getActiveSheet()->SetCellValue('A3', lang('Sr no'));
                $this->excel->getActiveSheet()->SetCellValue('B3', lang('Date'));
                $this->excel->getActiveSheet()->SetCellValue('C3', lang('Customer Name'));
                $this->excel->getActiveSheet()->SetCellValue('D3', lang('Phone No'));
                $this->excel->getActiveSheet()->SetCellValue('E3', lang('Card No'));
                $this->excel->getActiveSheet()->SetCellValue('F3', lang('Room No'));
                $this->excel->getActiveSheet()->SetCellValue('G3', lang('Amount'));
                $this->excel->getActiveSheet()->SetCellValue('H3', lang('Super Cash'));
                $this->excel->getActiveSheet()->SetCellValue('I3', lang('Total Amount'));
                $this->excel->getActiveSheet()->SetCellValue('J3', lang('Paid By'));
                $this->excel->getActiveSheet()->SetCellValue('K3', lang('Note'));
                $this->excel->getActiveSheet()->SetCellValue('L3', lang('Created By'));

                $row = 4;

                foreach ($data as $data_row) {

                    $this->excel->getActiveSheet()->SetCellValue('A' . $row, ++$sr);
