                $row = 10;
                $TotalDabit = $TotalCredit = $Totalbalance = 0;
                foreach ($transactionData as $rowdata) {
                    if ($rowdata['paid_by']) {
                
                        if ($rowdata['invoice_no'] && $rowdata['paid_by'] == "deposit") {
                            $dabit = $rowdata['grand_total'];
                            $TotalDabit += $dabit;
                            $Totalbalance -= $dabit;
