                        {$tableRow .= '<td class="text-right"> '. $this->sma->formatMoney(0) .' </td>';
                        $tableRow .= '<td class="text-right"> ' . $this->sma->formatMoney($credit) . '</td>';}
                    $tableRow .= '<td class="text-right"> ' . $this->sma->formatMoney($Totalbalance) . '</td>';
                    $tableRow .= '</tr>';
                }
                

                if ($rowdata['amount'] && $rowdata['super_cash'] > 0) {
                    $credit = $rowdata['super_cash'];
                    $TotalCredit += $credit;
                    $Totalbalance += $credit;
                    $tableRow .= '<tr>';
                    $tableRow .= '<td class="text-center"> ' . date('M d', strtotime($rowdata['date'])) . '</td>';
                    $tableRow .= '<td style="padding-left: 30px;"> SC/' . $rowdata['id'] . '</td>';
                    $tableRow .= '<td style="padding-left: 30px;"> ' . strtoupper($rowdata['paid_by']) . ' RECIVED BY ' . strtoupper($rowdata['name']) . '</td>';
                    $tableRow .= '<td class="text-right"> '. number_format(0,2) .' </td>';
                    $tableRow .= '<td class="text-right"> ' . number_format($credit, 2) . '</td>';
                    $tableRow .= '<td class="text-right"> ' . number_format($Totalbalance, 2) . '</td>';
                    $tableRow .= '</tr>';
                }
                
            }//end foreach.

            $tableFooter = '</tbody>
                                <tfoot class="dtFilter">
                                <tr>                                 
                                    <th colspan="3"> &nbsp; Total</th>
                                    
                                    <th class="text-right">' . $this->sma->formatMoney($TotalDabit) . ' </th>
                                    <th class="text-right">' . $this->sma->formatMoney($TotalCredit) . '</th>
                                    <th class="text-right">' . $this->sma->formatMoney($Totalbalance) . '</th>
                                </tr>
                                </tfoot>
                            </table>';


            echo $pagignation . $tableHeader . $tableRow . $tableFooter . $pagignation;
        }
    }

