        $this->data['toWarehouses']      = $this->transfers_model->getToWarehouses();
        // $this->data['product']        = $this->transfers_model->product();
        $this->data['categories'] = $this->site->getAllCategories();
        $this->data['brands'] = $this->site->getAllBrands();
        $this->data['transferStatus']    = $this->transfers_model->transferStatus();
        $this->data['Users']             = $this->transfers_model->getUsers();
        $this->data['refNo']             = $this->transfers_model->getRefNo();
        //  $bc = array(array('link' => base_url(), 'page' => lang('home')),'page' => lang('reports')), array('link' => '#', 'page' => lang('transferReport'));
        // //  $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('transfers/request'), 'page' => lang('Transfer Report')), array('link' => '#', 'page' => lang('transferReport')));
        //  $meta = array('page_title' => lang('Transfer Report'), 'bc' => $bc);
        // $this->page_construct('reports/transfer_report', $meta, $this->data);
        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('Transfer Report')));
        $meta = array('page_title' => lang('Transfer Report'), 'bc' => $bc);
        $this->page_construct('reports/transfer_report', $meta, $this->data);
    }
    public function add_payment($id = null) {
        $this->sma->checkPermissions('payments', true);
        $this->load->helper('security');
        if ($this->input->get('id')) {
            $id = $this->input->get('id');
        }

        $this->data['dueSales']=$dueSales = $this->reports_model->getTotalsSale($id);
        $this->data['customer_id'] = $id;
        $id = '';
        $grand_total = '';
        $rounding = '';
        $paid = '';
        $invoice_amount = '';

        foreach ($dueSales as  $dueSale) {
            $id = $dueSale->id;
            $grand_total += $dueSale->grand_total;
            $rounding  += $dueSale->rounding;
            $paid  += $dueSale->paid;
            $invoice_amount  = $dueSale->grand_total;
            // $sales= $this->reports_model->getSalesDueTotals($dueSale->id);
        }
       
        $sale = $this->reports_model->getInvoiceByID($id);
        if ($sale->payment_status == 'paid' && $sale->grand_total == $sale->paid) {
            $this->session->set_flashdata('error', lang("sale_already_paid"));
            $this->sma->md();
        }
        $this->form_validation->set_rules('amount-paid', lang("amount"), 'required');
        $this->form_validation->set_rules('paid_by', lang("paid_by"), 'required');
        $this->form_validation->set_rules('userfile', lang("attachment"), 'xss_clean');
        if ($this->form_validation->run() == true) {

            
           $invoice_amount =  $this->input->post('invoice_amount');
           $customer_id        =  $this->input->post('customer_id');
           $dueSales = $this->reports_model->getTotalsSale($customer_id);
            if ($this->input->post('paid_by') == 'deposit') {
                $sale = $this->sales_model->getInvoiceByID($this->input->post('sale_id'));
                $customer_id = $sale->customer_id;
                if (!$this->site->check_customer_deposit($customer_id, $this->input->post('amount-paid'))) {
                    $this->session->set_flashdata('error', lang("amount_greater_than_deposit"));
                    redirect($_SERVER["HTTP_REFERER"]);
                }
            } else {
                $customer_id = null;
            }
            if ($this->Owner || $this->Admin) {
                $date = $this->sma->fld(trim($this->input->post('date')));
            } else {
                $date = date('Y-m-d H:i:s');
            }
        
            $payment = array(
                'date'         => $date,
                'sale_id'      => $this->input->post('sale_id'),
                'reference_no' => $this->input->post('reference_no') ? $this->input->post('reference_no') : $this->site->getReference('pay'),
                'amount'       => $this->input->post('amount-paid'),
                'paid_by'      => $this->input->post('paid_by'),
                'cheque_no'    => $this->input->post('cheque_no'),
                'cc_no'        => $this->input->post('paid_by') == 'gift_card' ? $this->input->post('gift_card_no') : $this->input->post('pcc_no'),
                'cc_holder'    => $this->input->post('pcc_holder'),
                'cc_month'     => $this->input->post('pcc_month'),
                'cc_year'      => $this->input->post('pcc_year'),
                'cc_type'      => $this->input->post('pcc_type'),
                'note'         => $this->input->post('note'),
                'transaction_id' => $this->input->post('transaction_id'),
                'created_by'   => $this->session->userdata('user_id'),
                'type'         => 'received',
            );

            if ($_FILES['userfile']['size'] > 0) {
                $this->load->library('upload');
                $config['upload_path'] = $this->digital_upload_path;
                $config['allowed_types'] = $this->digital_file_types;
                $config['max_size'] = $this->allowed_file_size;
                $config['overwrite'] = false;
                $config['encrypt_name'] = true;
                $this->upload->initialize($config);
                if (!$this->upload->do_upload()) {
                    $error = $this->upload->display_errors();
                    $this->session->set_flashdata('error', $error);
                    redirect($_SERVER["HTTP_REFERER"]);
                }
                $photo = $this->upload->file_name;
                $payment['attachment'] = $photo;
            }

            //$this->sma->print_arrays($payment);
        } elseif ($this->input->post('add_payment')) {
            $this->session->set_flashdata('error', validation_errors());
            redirect($_SERVER["HTTP_REFERER"]);
        }

        if ($this->form_validation->run() == true && $this->reports_model->addPayment($payment, $customer_id, $invoice_amount,$dueSales)) {
            $this->session->set_flashdata('message', lang("payment_added"));
            redirect($_SERVER["HTTP_REFERER"]);
        } else {

            $this->data['error'] = (validation_errors() ? validation_errors() : $this->session->flashdata('error'));
            if ($sale->sale_status == 'returned' && $sale->paid == $sale->grand_total) {
                $this->session->set_flashdata('warning', lang('payment_was_returned'));
                $this->sma->md();
            }
            $this->data['inv'] = $sale;
            $this->data['total'] = $grand_total;
            $this->data['rounding'] = $rounding;
            $this->data['paid'] = $paid;
            $this->data['sales_id'] = $id;
            $this->data['invoice_amounts'] = $invoice_amount;
            $this->data['dueSales'] = $dueSales;
            $this->data['payment_ref'] = ''; //$this->site->getReference('pay');
            $this->data['modal_js'] = $this->site->modal_js();
            $this->load->view($this->theme . 'reports/add_payment', $this->data);
        }
    }
  
    function term_wise_sale_report() {
        // $this->sma->checkPermissions();
        $this->data['error'] = (validation_errors() ? validation_errors() : $this->session->flashdata('error'));
        $this->data['warehouses'] = $this->site->getAllWarehouses();

        /* fetch default warehouse directly */
        $setting = $this->db->select('default_warehouse')->get('settings')->row();
        $default_warehouse_id = !empty($setting->default_warehouse)
            ? (int)$setting->default_warehouse
            : 0;

        if (!empty($this->data['warehouses']) && $default_warehouse_id) {

            $defaultWarehouse = null;
            $others = [];

            foreach ($this->data['warehouses'] as $warehouse) {
                if ((int)$warehouse->id === $default_warehouse_id) {
                    $defaultWarehouse = $warehouse;
                } else {
                    $others[] = $warehouse;
                }
            }

            if ($defaultWarehouse) {
                array_unshift($others, $defaultWarehouse);
                $this->data['warehouses'] = $others;
            }
        }

        $this->data['categories'] = $this->site->getAllCategories();
        $this->data['brands'] = $this->site->getAllBrands();
        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('Term_Wise_Sales_Report')));
        $meta = array('page_title' => lang('Term_Wise_Sales_Report'), 'bc' => $bc);
        
        $this->page_construct('reports/term_wise_sale_report', $meta, $this->data);
    }
    function termWiseSaleReports($pdf = NULL, $xls = NULL, $img = NULL) {
        $this->load->library('datatables'); 
        $startDate_term1 = $this->input->get('startDate_term1') ? $this->input->get('startDate_term1') : '-';
        $endDate_term1 = $this->input->get('endDate_term1') ? $this->input->get('endDate_term1') : '-';
        $startDate_term2 = $this->input->get('startDate_term2') ? $this->input->get('startDate_term2') : '-';
        $endDate_term2 = $this->input->get('endDate_term2') ? $this->input->get('endDate_term2') : '-';
        $product = $this->input->get('product') ? $this->input->get('product') : NULL;
        $category = $this->input->get('category') ? $this->input->get('category') : NULL;
        $brand = $this->input->get('brand') ? $this->input->get('brand') : NULL;
        $subcategory = $this->input->get('subcategory') ? $this->input->get('subcategory') : NULL;
        $warehouses = $this->input->get('warehouse') ? $this->input->get('warehouse') : '';
        $view_sale_count_warehouse_wise = $this->input->get('view_sale_count_warehouse_wise') ? 1 : 0;
        
        // Handle Select All option - mutually exclusive logic
        if (is_array($warehouses) && in_array('all', $warehouses)) {
            // If "all" is selected, ignore all other selections and get all warehouses
            $all_warehouses = $this->site->getAllWarehouses();
            $warehouses = [];
            foreach ($all_warehouses as $warehouse) {
                $warehouses[] = $warehouse->id;
            }
        } else {
            // Filter out any non-numeric values and validate individual selections
            if (is_array($warehouses)) {
                $warehouses = array_filter($warehouses, function($w) {
                    return is_numeric($w) && $w > 0;
                });
            }
        }

        // Add filters if set
        $where_primary = "";
        $where_other   = "";
        if ($product) {
            $where_primary .= " AND sma_products.id = '$product' ";
            $where_other   .= " AND p.id = '$product' ";
        }
        if ($category) {
            // primary category query
            $where_primary .= " AND sma_products.category_id = '$category' ";

            // other category query
            $where_other   .= " AND pc.category_id = '$category' ";
        }
        if ($subcategory) {
            $where_primary .= " AND sma_products.subcategory_id = '$subcategory' ";
            $where_other   .= " AND p.subcategory_id = '$subcategory' ";
        }
        if ($brand) {
            $where_primary .= " AND sma_products.brand = '$brand' ";
            $where_other   .= " AND p.brand = '$brand' ";
        }
        // $startDate_term1 = $this->input->get('startDate_term1') ? $this->input->get('startDate_term1') : NULL;
        // $endDate_term1 = $this->input->get('endDate_term1') ? $this->input->get('endDate_term1') : NULL;
        // $startDate_term2 = $this->input->get('startDate_term2') ? $this->input->get('startDate_term2') : NULL;
        // $endDate_term2 = $this->input->get('endDate_term2') ? $this->input->get('endDate_term2') : NULL;

        if ($pdf || $xls || $img) {
            
            // Performance optimization: prepare warehouse filter
            $warehouse_ids = '';
            if (!empty($warehouses)) {
                $valid_warehouses = array_filter($warehouses, function($w) {
                    return is_numeric($w) && $w > 0;
                });
                if (!empty($valid_warehouses)) {
                    $warehouse_ids = implode(',', $valid_warehouses);
                }
            }
            
            // Fallback to default warehouse if none selected
            if (empty($warehouse_ids)) {
                $warehouse_ids = $this->session->userdata('warehouse_id');
                if (empty($warehouse_ids)) {
                    $all_warehouses = $this->site->getAllWarehouses();
                    $warehouse_ids = implode(',', array_column($all_warehouses, 'id'));
                }
            }
            
            // Add performance indexes hint
            $warehouse_filter = "AND w.id IN ($warehouse_ids)";
            $this->db->query("SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION'");
            if($startDate_term1!= '-' || $startDate_term2!= '-')
            {
                if ($this->data['Settings']->other_category_for_product == 0) {
                    $fetch_data = $this->db->query("
                        SELECT 
                            sma_products.code AS product_code,
                            sma_categories.name AS category_name,
                            sma_products.name AS product_name,
                            CASE 
                                WHEN sma_product_variants.name IS NULL THEN '-'
                                ELSE sma_product_variants.name
                            END AS variant_name,
                            sma_warehouses.name AS warehouse_name,
                            COALESCE(
                                (
                                    SELECT 
                                        GROUP_CONCAT(DISTINCT NULLIF(NULLIF(sma_purchase_items.batch_number, ''), 'N/A') ORDER BY sma_purchase_items.batch_number SEPARATOR ', ')
                                    FROM sma_purchase_items
                                    WHERE sma_purchase_items.product_id = sma_products.id
                                    AND (
                                        sma_product_variants.id IS NULL 
                                        OR sma_purchase_items.option_id = sma_product_variants.id
                                    )
                                    AND sma_purchase_items.warehouse_id = sma_warehouses.id
                                ),
                                '-'
                            ) AS batch_numbers,
                            CASE
                                WHEN sma_product_variants.name IS NOT NULL THEN
                                    COALESCE(
                                        (
                                            SELECT SUM(sma_warehouses_products_variants.quantity)
                                            FROM sma_warehouses_products_variants
                                            WHERE sma_warehouses_products_variants.product_id = sma_products.id
                                            AND sma_warehouses_products_variants.option_id = sma_product_variants.id
                                            AND sma_warehouses_products_variants.warehouse_id = sma_warehouses.id
                                        ), 0
                                    )
                                ELSE
                                    COALESCE(
                                        (
                                            SELECT SUM(sma_warehouses_products.quantity)
                                            FROM sma_warehouses_products
                                            WHERE sma_warehouses_products.product_id = sma_products.id
                                            AND sma_warehouses_products.warehouse_id = sma_warehouses.id
                                        ), 0
                                    )
                            END AS current_stock,
                            CASE
                            WHEN sma_product_variants.name IS NULL THEN
                                COALESCE(
                                    (
                                        SELECT SUM(sma_sale_items.quantity)
                                        FROM sma_sale_items
                                        JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                        WHERE sma_sale_items.product_id = sma_products.id
                                        AND sma_sales.date BETWEEN '$startDate_term1' AND '$endDate_term1'
                                        AND sma_sale_items.warehouse_id = sma_warehouses.id
                                    ), 0
                                )
                            ELSE
                                COALESCE(
                                    (
                                        SELECT SUM(sma_sale_items.quantity)
                                        FROM sma_sale_items
                                        JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                        WHERE sma_sale_items.product_id = sma_products.id
                                        AND sma_sale_items.option_id = sma_product_variants.id
                                        AND sma_sales.date BETWEEN '$startDate_term1' AND '$endDate_term1'
                                        AND sma_sale_items.warehouse_id = sma_warehouses.id
                                    ), 0
                                )
                        END AS sales_term1,
                        CASE
                            WHEN sma_product_variants.name IS NULL THEN
                                COALESCE(
                                    (
                                        SELECT SUM(sma_sale_items.quantity)
                                        FROM sma_sale_items
                                        JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                        WHERE sma_sale_items.product_id = sma_products.id
                                        AND sma_sales.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                                        AND sma_sale_items.warehouse_id = sma_warehouses.id
                                    ), 0
                                )
                            ELSE
                                COALESCE(
                                    (
                                        SELECT SUM(sma_sale_items.quantity)
                                        FROM sma_sale_items
                                        JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                        WHERE sma_sale_items.product_id = sma_products.id
                                        AND sma_sale_items.option_id = sma_product_variants.id
                                        AND sma_sales.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                                        AND sma_sale_items.warehouse_id = sma_warehouses.id
                                    ), 0
                                )
                        END AS sales_term2,
                        CASE
                            WHEN sma_product_variants.name IS NOT NULL THEN 
                                GREATEST(
                                    0,
                                    COALESCE(
                                        (
                                            SELECT SUM(sma_warehouses_products_variants.quantity)
                                            FROM sma_warehouses_products_variants
                                            WHERE sma_warehouses_products_variants.product_id = sma_products.id
                                            AND sma_warehouses_products_variants.option_id = sma_product_variants.id
                                            AND sma_warehouses_products_variants.warehouse_id = sma_warehouses.id
                                        ), 0
                                    ) - COALESCE(
                                        (
                                            SELECT SUM(sma_sale_items.quantity)
                                            FROM sma_sale_items
                                            JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                            WHERE sma_sale_items.product_id = sma_products.id
                                            AND sma_sale_items.option_id = sma_product_variants.id
                                            AND sma_sales.date BETWEEN '$startDate_term1' AND '$endDate_term1'
                                        ), 0
                                    )
                                )
                            ELSE
                                GREATEST(
                                    0,
                                    COALESCE(
                                        (
                                            SELECT SUM(sma_warehouses_products.quantity)
                                            FROM sma_warehouses_products
                                            WHERE sma_warehouses_products.product_id = sma_products.id
                                            AND sma_warehouses_products.warehouse_id = sma_warehouses.id
                                        ), 0
                                    ) - COALESCE(
                                        (
                                            SELECT SUM(sma_sale_items.quantity)
                                            FROM sma_sale_items
                                            JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                            WHERE sma_sale_items.product_id = sma_products.id
                                            AND sma_sales.date BETWEEN '$startDate_term1' AND '$endDate_term1'
                                        ), 0
                                    )
                                )
                        END AS excess_inventory,
                        CASE
                            WHEN 
                                (CASE
                                    WHEN sma_product_variants.name IS NULL THEN
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_sale_items.quantity)
                                                FROM sma_sale_items
                                                JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                                WHERE sma_sale_items.product_id = sma_products.id
                                                AND sma_sales.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                                                AND sma_sale_items.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                    ELSE
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_sale_items.quantity)
                                                FROM sma_sale_items
                                                JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                                WHERE sma_sale_items.product_id = sma_products.id
                                                AND sma_sale_items.option_id = sma_product_variants.id
                                                AND sma_sales.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                                                AND sma_sale_items.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                END) > 
                                (CASE
                                    WHEN sma_product_variants.name IS NOT NULL THEN
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_warehouses_products_variants.quantity)
                                                FROM sma_warehouses_products_variants
                                                WHERE sma_warehouses_products_variants.product_id = sma_products.id
                                                AND sma_warehouses_products_variants.option_id = sma_product_variants.id
                                                AND sma_warehouses_products_variants.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                    ELSE
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_warehouses_products.quantity)
                                                FROM sma_warehouses_products
                                                WHERE sma_warehouses_products.product_id = sma_products.id
                                                AND sma_warehouses_products.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                END) 
                            THEN 
                                (CASE
                                    WHEN sma_product_variants.name IS NULL THEN
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_sale_items.quantity)
                                                FROM sma_sale_items
                                                JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                                WHERE sma_sale_items.product_id = sma_products.id
                                                AND sma_sales.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                                                AND sma_sale_items.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                    ELSE
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_sale_items.quantity)
                                                FROM sma_sale_items
                                                JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                                WHERE sma_sale_items.product_id = sma_products.id
                                                AND sma_sale_items.option_id = sma_product_variants.id
                                                AND sma_sales.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                                                AND sma_sale_items.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                END) - 
                                (CASE
                                    WHEN sma_product_variants.name IS NOT NULL THEN
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_warehouses_products_variants.quantity)
                                                FROM sma_warehouses_products_variants
                                                WHERE sma_warehouses_products_variants.product_id = sma_products.id
                                                AND sma_warehouses_products_variants.option_id = sma_product_variants.id
                                                AND sma_warehouses_products_variants.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                    ELSE
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_warehouses_products.quantity)
                                                FROM sma_warehouses_products
                                                WHERE sma_warehouses_products.product_id = sma_products.id
                                                AND sma_warehouses_products.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                END)
                            ELSE 0
                        END AS shortage_of_inventory
                        FROM 
                            sma_products
                        LEFT JOIN sma_categories ON sma_products.category_id = sma_categories.id
                        LEFT JOIN sma_product_variants 
                            ON sma_products.id = sma_product_variants.product_id
                            AND sma_product_variants.group_id = 1
                        LEFT JOIN sma_warehouses_products_variants ON sma_products.id = sma_warehouses_products_variants.product_id 
                            AND sma_product_variants.id = sma_warehouses_products_variants.option_id
                        LEFT JOIN sma_warehouses_products ON sma_products.id = sma_warehouses_products.product_id
                        LEFT JOIN sma_sale_items ON sma_products.id = sma_sale_items.product_id 
                            AND sma_product_variants.id = sma_sale_items.option_id
                        INNER JOIN sma_warehouses ON sma_warehouses.id IN ($warehouse_ids) -- Ensure only warehouses in the specified list
                        LEFT JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                        WHERE 1=1 $where_primary
                        GROUP BY 
                            sma_products.id, 
                            sma_product_variants.id, 
                            sma_warehouses.id
                        ORDER BY 
                            sma_products.code ASC, 
                            sma_products.name ASC, 
                            sma_warehouses.name ASC
                    ");
                $query = $fetch_data->result();
            }       
            else{
                $query = $this->db->query("
                        SELECT
                            p.code AS product_code,
                            p.category_id AS primary_category,
                            si.category_id AS sale_category,
                            cat.name AS category_name,
                            p.name AS product_name,
                            IFNULL(v.name, '-') AS variant_name,
                            w.name AS warehouse_name,

                            -- stock (unchanged logic, just guarded)
                            CASE
                                WHEN pc.category_id = p.category_id THEN
                                    CASE
                                        WHEN v.id IS NOT NULL THEN
                                            COALESCE((
                                                SELECT SUM(wpv.quantity)
                                                FROM sma_warehouses_products_variants wpv
                                                WHERE wpv.product_id = p.id
                                                AND wpv.option_id = v.id
                                                AND wpv.warehouse_id = w.id
                                            ), 0)
                                        ELSE
                                            COALESCE((
                                                SELECT SUM(wp.quantity)
                                                FROM sma_warehouses_products wp
                                                WHERE wp.product_id = p.id
                                                AND wp.warehouse_id = w.id
                                            ), 0)
                                    END
                                ELSE 0
                            END AS current_stock,

                            -- sales_term1 (your logic untouched)
                            COALESCE((
                                SELECT SUM(s.quantity)
                                FROM sma_sale_items s
                                JOIN sma_sales sa ON sa.id = s.sale_id
                                WHERE s.product_id = p.id
                                AND (v.id IS NULL OR s.option_id = v.id)
                                AND COALESCE(s.category_id, p.category_id) = pc.category_id
                                AND s.warehouse_id = w.id
                                AND sa.date BETWEEN '$startDate_term1' AND '$endDate_term1'
                            ), 0) AS sales_term1,

                            -- sales_term2
                            COALESCE((
                                SELECT SUM(s.quantity)
                                FROM sma_sale_items s
                                JOIN sma_sales sa ON sa.id = s.sale_id
                                WHERE s.product_id = p.id
                                AND (v.id IS NULL OR s.option_id = v.id)
                                AND COALESCE(s.category_id, p.category_id) = pc.category_id
                                AND s.warehouse_id = w.id
                                AND sa.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                            ), 0) AS sales_term2

                        FROM
                        (
                            -- 🔥 PRODUCT × CATEGORY EXPANSION
                            SELECT p.id AS product_id, p.category_id AS category_id
                            FROM sma_products p

                            UNION ALL

                            SELECT p.id, c.id
                            FROM sma_products p
                            JOIN sma_categories c
                                ON FIND_IN_SET(c.id, p.other_categories)
                        ) pc

                        JOIN sma_products p ON p.id = pc.product_id
                        JOIN sma_categories cat ON cat.id = pc.category_id

                        LEFT JOIN sma_product_variants v
                            ON v.product_id = p.id
                            AND v.group_id = 1

                        INNER JOIN sma_warehouses w
                            ON w.id IN ($warehouse_ids)

                        LEFT JOIN sma_sale_items si
                            ON si.product_id = p.id
                            AND si.category_id = pc.category_id
                            AND (v.id IS NULL OR si.option_id = v.id)
   
                        WHERE 1=1 $where_other -- ✅ your existing category filter stays untouched

                        GROUP BY
                            p.id,
                            pc.category_id,
                            v.id,
                            w.id

                        ORDER BY
                            pc.category_id;
                    ");
          
            
                $termwise_result = $query->result();
                
                // Check if primary_category and sale_category are different
                // If they are, set current_stock, excess_inventory, and shortage_of_inventory to 0
                // This is to ensure that the report only shows data for products that are in the same category for both primary and sale categories
                $termwise_result = array_map(function($row) { 
                    if ($row->primary_category != $row->sale_category)
                    { 
                        // Do NOT reset current stock
                        $row->sales_term1 = 0;
                        $row->sales_term2 = 0;
                        $row->excess_inventory = 0;
                        $row->shortage_of_inventory = 0;
                    }

                    return $row;
                }, $termwise_result);
                $query = $termwise_result;

            }
                
                // $q = $this->db->query($fetch_data);
                // $query = $fetch_data->result();
                    $data = array();
                
                    if (count($query) > 0) {
                        if (!$view_sale_count_warehouse_wise) {
                            $grouped_results = [];
                            foreach ($query as $row) {
                                $key = $row->product_code . '_' . $row->variant_name . '_' . $row->category_name;
                                if (!isset($grouped_results[$key])) {
                                    $grouped_results[$key] = clone $row;
                                } else {
                                    $grouped_results[$key]->current_stock += $row->current_stock;
                                    $grouped_results[$key]->sales_term1 += $row->sales_term1;
                                    $grouped_results[$key]->sales_term2 += $row->sales_term2;
                                    if (isset($row->batch_numbers) && $row->batch_numbers != '-' && $row->batch_numbers != '') {
                                        if (isset($grouped_results[$key]->batch_numbers) && $grouped_results[$key]->batch_numbers != '-' && $grouped_results[$key]->batch_numbers != '') {
                                            $batches1 = array_map('trim', explode(',', $grouped_results[$key]->batch_numbers));
                                            $batches2 = array_map('trim', explode(',', $row->batch_numbers));
                                            $grouped_results[$key]->batch_numbers = implode(', ', array_unique(array_merge($batches1, $batches2)));
                                        } else {
                                            $grouped_results[$key]->batch_numbers = $row->batch_numbers;
                                        }
                                    }
                                }
                            }
                            $query = array_values($grouped_results);
                        }

                        foreach ($query as $row) {
                            array_push($data, $row);
                        }
                    } else {
                        $data = NULL;  // No data found
                    }
                
                    if (!empty($data)) {

                        $this->load->library('excel');
                        $this->excel->setActiveSheetIndex(0);
                    
                        $sheet = $this->excel->getActiveSheet();
                        $sheet->setTitle(lang('Term Wise Sale Report'));
                    
                        // --- Header Title ---
                        $style = [
                            'alignment' => ['horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER],
                            'font' => ['name' => 'Arial', 'bold' => true, 'color' => ['rgb' => 'FF0000']],
                            'borders' => ['allborders' => ['style' => PHPExcel_Style_Border::BORDER_NONE]],
                        ];
                        $sheet->mergeCells('A1:K1');
                        $sheet->getStyle('A1:K1')->applyFromArray($style);
                        $sheet->setCellValue('A1', 'Term Wise Sale Report');
                    
                        $sheet->setCellValue('A2', lang('product_code'));
                        $sheet->setCellValue('B2', lang('category_name'));
                        $sheet->setCellValue('C2', lang('product_name'));
                        $sheet->setCellValue('D2', lang('variant_name'));
                        
                        $colIndex = 'E';
                        if ($view_sale_count_warehouse_wise) {
                            $sheet->setCellValue($colIndex++ . '2', lang('warehouse'));
                        }
                    
                        if ($this->data['Settings']->product_batch_setting == 1 || $this->data['Settings']->product_batch_setting == 2) {
                            $sheet->setCellValue($colIndex++ . '2', lang('batch_no'));
                        }
                    
                        $sheet->setCellValue($colIndex++ . '2', lang('current_stock'));
                        $sheet->setCellValue($colIndex++ . '2', lang('term_1_sale'));
                        $sheet->setCellValue($colIndex++ . '2', lang('term_2_sale'));
                        // Optional:
                        // $sheet->setCellValue($colIndex++ . '2', lang('excess_inventory'));
                        // $sheet->setCellValue($colIndex++ . '2', lang('shortage_inventory'));
                    
                        // --- Data Rows ---
                        $row = 3;
                        $total_current_stock = $total_sales_term1 = $total_sales_term2 = $total_excess_inventory = $total_shortage_inventory = 0;
                    
                        foreach ($data as $data_row) {
                            $col = 'A';
                            $sheet->setCellValueExplicit($col++ . $row, $data_row->product_code, PHPExcel_Cell_DataType::TYPE_STRING);
                            $sheet->setCellValueExplicit($col++ . $row, $data_row->category_name, PHPExcel_Cell_DataType::TYPE_STRING);
                            $sheet->setCellValueExplicit($col++ . $row, $data_row->product_name, PHPExcel_Cell_DataType::TYPE_STRING);
                            $sheet->setCellValueExplicit($col++ . $row, $data_row->variant_name, PHPExcel_Cell_DataType::TYPE_STRING);
                            
                            if ($view_sale_count_warehouse_wise) {
                                $sheet->setCellValueExplicit($col++ . $row, $data_row->warehouse_name, PHPExcel_Cell_DataType::TYPE_STRING);
                            }
                    
                            // --- Batch Column (conditional) ---
                            if ($this->data['Settings']->product_batch_setting == 1 || $this->data['Settings']->product_batch_setting == 2) {
                                $batchValue = !empty($data_row->batch_numbers) ? $data_row->batch_numbers : '-';
                                $sheet->setCellValueExplicit($col++ . $row, $batchValue, PHPExcel_Cell_DataType::TYPE_STRING);
                            }
                    
                            // --- Quantities ---
                            $sheet->setCellValueExplicit($col . $row, $this->sma->formatQuantity($data_row->current_stock), PHPExcel_Cell_DataType::TYPE_STRING);
                            $sheet->getStyle($col++ . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                            $total_current_stock += $data_row->current_stock;
                    
                            $sheet->setCellValueExplicit($col . $row, $this->sma->formatQuantity($data_row->sales_term1), PHPExcel_Cell_DataType::TYPE_STRING);
                            $sheet->getStyle($col++ . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                            $total_sales_term1 += $data_row->sales_term1;
                    
                            $sheet->setCellValueExplicit($col . $row, $this->sma->formatQuantity($data_row->sales_term2), PHPExcel_Cell_DataType::TYPE_STRING);
                            $sheet->getStyle($col++ . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                            $total_sales_term2 += $data_row->sales_term2;
                    
                            // Optional excess/shortage
                            // $sheet->setCellValueExplicit($col++ . $row, $this->sma->formatQuantity($data_row->excess_inventory), PHPExcel_Cell_DataType::TYPE_STRING);
                            // $sheet->setCellValueExplicit($col++ . $row, $this->sma->formatQuantity($data_row->shortage_of_inventory), PHPExcel_Cell_DataType::TYPE_STRING);
                    
                            $row++;
                        }
                    
                        // --- Totals Row ---
                        $totalCol = 'D';
                        if ($view_sale_count_warehouse_wise) {
                            $totalCol++;
                        }
                        $sheet->setCellValueExplicit($totalCol . $row, 'Total', PHPExcel_Cell_DataType::TYPE_STRING);

                        $stockCol = $totalCol;
                        if ($this->data['Settings']->product_batch_setting == 1 || $this->data['Settings']->product_batch_setting == 2) {
                            $stockCol++;
                        }
                        $stockCol++;
                        
                        $t1Col = $stockCol;
                        $t1Col++;
                        $t2Col = $t1Col;
                        $t2Col++;

                        $sheet->setCellValueExplicit($stockCol . $row, $this->sma->formatQuantity($total_current_stock), PHPExcel_Cell_DataType::TYPE_STRING);
                        $sheet->setCellValueExplicit($t1Col . $row, $this->sma->formatQuantity($total_sales_term1), PHPExcel_Cell_DataType::TYPE_STRING);
                        $sheet->setCellValueExplicit($t2Col . $row, $this->sma->formatQuantity($total_sales_term2), PHPExcel_Cell_DataType::TYPE_STRING);

                        $lastCol = $totalCol;
                        $sheet->getStyle("E$row:$lastCol$row")->getFont()->setBold(true);
                        $sheet->getStyle("E$row:$lastCol$row")->getBorders()->getTop()->setBorderStyle(PHPExcel_Style_Border::BORDER_MEDIUM);
                        $sheet->getStyle("E$row:$lastCol$row")->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);

                        $sheet->getStyle("E$row:$t2Col$row")->getFont()->setBold(true);
                        $sheet->getStyle("E$row:$t2Col$row")->getBorders()->getTop()->setBorderStyle(PHPExcel_Style_Border::BORDER_MEDIUM);
                    
                        // --- Column Widths ---
                        $widths = [
                            'A' => 20, 'B' => 25, 'C' => 25, 'D' => 18, 'E' => 18,
                            'F' => 22, 'G' => 20, 'H' => 20, 'I' => 20, 'J' => 20, 'K' => 20
                        ];
                        foreach ($widths as $col => $w) {
                            $sheet->getColumnDimension($col)->setWidth($w);
                        }
                    
                        // --- File Output ---
                        $filename = 'Term_Wise_Sale_Report';
                        $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);
                    
                        if ($pdf) {
                            $styleArray = ['borders' => ['allborders' => ['style' => PHPExcel_Style_Border::BORDER_THIN]]];
                            $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                            $sheet->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    
                            require_once(APPPATH . "third_party/MPDF/mpdf.php");
                            $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                            $rendererLibrary = 'MPDF';
