                    }
                    
            }
            else{
                $this->session->set_flashdata('error', lang('nothing_found'));
                redirect($_SERVER["HTTP_REFERER"]);
            }
            // redirect($_SERVER["HTTP_REFERER"]);
        } else {
            
            // Handle warehouse selection - default to all warehouses if none selected
            if (!empty($warehouses)) {
                $valid_warehouses = array_filter($warehouses, function($w) {
                    return is_numeric($w) && $w > 0;
                });
                if (!empty($valid_warehouses)) {
                    $warehouse_ids = implode(',', $valid_warehouses);
                } else {
                    $warehouse_ids = '';
                }
            } else {
                $warehouse_ids = '';
            }
            
            // Fallback to all warehouses if none selected
            if (empty($warehouse_ids)) {
                $warehouse_ids = $this->session->userdata('warehouse_id');
                if (empty($warehouse_ids)) {
                    $all_warehouses = $this->site->getAllWarehouses();
                    $warehouse_ids = implode(',', array_column($all_warehouses, 'id'));
                }
            }
            if($startDate_term1!= '-' || $startDate_term2!= '-')
            {
                if ($this->data['Settings']->other_category_for_product == 0) {
                        $query = $this->db->query("
                        SELECT 
                            sma_products.code AS product_code,
                            sma_categories.name AS category_name,
                            sma_products.name AS product_name,
                            CASE 
                                WHEN sma_product_variants.name IS NULL THEN '-'
                                ELSE sma_product_variants.name
                            END AS variant_name,
                            sma_warehouses.name AS warehouse_name,
                            COALESCE(
                                (
                                    SELECT 
                                        GROUP_CONCAT(DISTINCT NULLIF(NULLIF(sma_purchase_items.batch_number, ''), 'N/A') ORDER BY sma_purchase_items.batch_number SEPARATOR ', ')
                                    FROM sma_purchase_items
                                    WHERE sma_purchase_items.product_id = sma_products.id
                                    AND (
                                        sma_product_variants.id IS NULL 
                                        OR sma_purchase_items.option_id = sma_product_variants.id
                                    )
                                    AND sma_purchase_items.warehouse_id = sma_warehouses.id
                                ),
                                '-'
                            ) AS batch_numbers,
                            CASE
                                WHEN sma_product_variants.name IS NOT NULL THEN
                                    COALESCE(
                                        (
                                            SELECT SUM(sma_warehouses_products_variants.quantity)
                                            FROM sma_warehouses_products_variants
                                            WHERE sma_warehouses_products_variants.product_id = sma_products.id
                                            AND sma_warehouses_products_variants.option_id = sma_product_variants.id
                                            AND sma_warehouses_products_variants.warehouse_id = sma_warehouses.id
                                        ), 0
                                    )
                                ELSE
                                    COALESCE(
                                        (
                                            SELECT SUM(sma_warehouses_products.quantity)
                                            FROM sma_warehouses_products
                                            WHERE sma_warehouses_products.product_id = sma_products.id
                                            AND sma_warehouses_products.warehouse_id = sma_warehouses.id
                                        ), 0
                                    )
                            END AS current_stock,
                            CASE
                            WHEN sma_product_variants.name IS NULL THEN
                                COALESCE(
                                    (
                                        SELECT SUM(sma_sale_items.quantity)
                                        FROM sma_sale_items
                                        JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                        WHERE sma_sale_items.product_id = sma_products.id
                                        AND sma_sales.date BETWEEN '$startDate_term1' AND '$endDate_term1'
                                        AND sma_sale_items.warehouse_id = sma_warehouses.id
                                    ), 0
                                )
                            ELSE
                                COALESCE(
                                    (
                                        SELECT SUM(sma_sale_items.quantity)
                                        FROM sma_sale_items
                                        JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                        WHERE sma_sale_items.product_id = sma_products.id
                                        AND sma_sale_items.option_id = sma_product_variants.id
                                        AND sma_sales.date BETWEEN '$startDate_term1' AND '$endDate_term1'
                                        AND sma_sale_items.warehouse_id = sma_warehouses.id
                                    ), 0
                                )
                        END AS sales_term1,
                        CASE
                            WHEN sma_product_variants.name IS NULL THEN
                                COALESCE(
                                    (
                                        SELECT SUM(sma_sale_items.quantity)
                                        FROM sma_sale_items
                                        JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                        WHERE sma_sale_items.product_id = sma_products.id
                                        AND sma_sales.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                                        AND sma_sale_items.warehouse_id = sma_warehouses.id
                                    ), 0
                                )
                            ELSE
                                COALESCE(
                                    (
                                        SELECT SUM(sma_sale_items.quantity)
                                        FROM sma_sale_items
                                        JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                        WHERE sma_sale_items.product_id = sma_products.id
                                        AND sma_sale_items.option_id = sma_product_variants.id
                                        AND sma_sales.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                                        AND sma_sale_items.warehouse_id = sma_warehouses.id
                                    ), 0
                                )
                        END AS sales_term2,
                        CASE
                            WHEN sma_product_variants.name IS NOT NULL THEN 
                                GREATEST(
                                    0,
                                    COALESCE(
                                        (
                                            SELECT SUM(sma_warehouses_products_variants.quantity)
                                            FROM sma_warehouses_products_variants
                                            WHERE sma_warehouses_products_variants.product_id = sma_products.id
                                            AND sma_warehouses_products_variants.option_id = sma_product_variants.id
                                            AND sma_warehouses_products_variants.warehouse_id = sma_warehouses.id
                                        ), 0
                                    ) - COALESCE(
                                        (
                                            SELECT SUM(sma_sale_items.quantity)
                                            FROM sma_sale_items
                                            JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                            WHERE sma_sale_items.product_id = sma_products.id
                                            AND sma_sale_items.option_id = sma_product_variants.id
                                            AND sma_sales.date BETWEEN '$startDate_term1' AND '$endDate_term1'
                                        ), 0
                                    )
                                )
                            ELSE
                                GREATEST(
                                    0,
                                    COALESCE(
                                        (
                                            SELECT SUM(sma_warehouses_products.quantity)
                                            FROM sma_warehouses_products
                                            WHERE sma_warehouses_products.product_id = sma_products.id
                                            AND sma_warehouses_products.warehouse_id = sma_warehouses.id
                                        ), 0
                                    ) - COALESCE(
                                        (
                                            SELECT SUM(sma_sale_items.quantity)
                                            FROM sma_sale_items
                                            JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                            WHERE sma_sale_items.product_id = sma_products.id
                                            AND sma_sales.date BETWEEN '$startDate_term1' AND '$endDate_term1'
                                        ), 0
                                    )
                                )
                        END AS excess_inventory,
                        CASE
                            WHEN 
                                (CASE
                                    WHEN sma_product_variants.name IS NULL THEN
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_sale_items.quantity)
                                                FROM sma_sale_items
                                                JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                                WHERE sma_sale_items.product_id = sma_products.id
                                                AND sma_sales.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                                                AND sma_sale_items.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                    ELSE
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_sale_items.quantity)
                                                FROM sma_sale_items
                                                JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                                WHERE sma_sale_items.product_id = sma_products.id
                                                AND sma_sale_items.option_id = sma_product_variants.id
                                                AND sma_sales.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                                                AND sma_sale_items.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                END) > 
                                (CASE
                                    WHEN sma_product_variants.name IS NOT NULL THEN
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_warehouses_products_variants.quantity)
                                                FROM sma_warehouses_products_variants
                                                WHERE sma_warehouses_products_variants.product_id = sma_products.id
                                                AND sma_warehouses_products_variants.option_id = sma_product_variants.id
                                                AND sma_warehouses_products_variants.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                    ELSE
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_warehouses_products.quantity)
                                                FROM sma_warehouses_products
                                                WHERE sma_warehouses_products.product_id = sma_products.id
                                                AND sma_warehouses_products.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                END) 
                            THEN 
                                (CASE
                                    WHEN sma_product_variants.name IS NULL THEN
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_sale_items.quantity)
                                                FROM sma_sale_items
                                                JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                                WHERE sma_sale_items.product_id = sma_products.id
                                                AND sma_sales.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                                                AND sma_sale_items.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                    ELSE
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_sale_items.quantity)
                                                FROM sma_sale_items
                                                JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                                                WHERE sma_sale_items.product_id = sma_products.id
                                                AND sma_sale_items.option_id = sma_product_variants.id
                                                AND sma_sales.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                                                AND sma_sale_items.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                END) - 
                                (CASE
                                    WHEN sma_product_variants.name IS NOT NULL THEN
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_warehouses_products_variants.quantity)
                                                FROM sma_warehouses_products_variants
                                                WHERE sma_warehouses_products_variants.product_id = sma_products.id
                                                AND sma_warehouses_products_variants.option_id = sma_product_variants.id
                                                AND sma_warehouses_products_variants.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                    ELSE
                                        COALESCE(
                                            (
                                                SELECT SUM(sma_warehouses_products.quantity)
                                                FROM sma_warehouses_products
                                                WHERE sma_warehouses_products.product_id = sma_products.id
                                                AND sma_warehouses_products.warehouse_id = sma_warehouses.id
                                            ), 0
                                        )
                                END)
                            ELSE 0
                        END AS shortage_of_inventory
                        FROM 
                            sma_products
                        LEFT JOIN sma_categories ON sma_products.category_id = sma_categories.id
                        LEFT JOIN sma_product_variants 
                            ON sma_products.id = sma_product_variants.product_id
                            AND sma_product_variants.group_id = 1
                        LEFT JOIN sma_warehouses_products_variants ON sma_products.id = sma_warehouses_products_variants.product_id 
                            AND sma_product_variants.id = sma_warehouses_products_variants.option_id
                        LEFT JOIN sma_warehouses_products ON sma_products.id = sma_warehouses_products.product_id
                        LEFT JOIN sma_sale_items ON sma_products.id = sma_sale_items.product_id 
                            AND sma_product_variants.id = sma_sale_items.option_id
                        INNER JOIN sma_warehouses ON sma_warehouses.id IN ($warehouse_ids) -- Ensure only warehouses in the specified list
                        LEFT JOIN sma_sales ON sma_sale_items.sale_id = sma_sales.id
                        WHERE 1=1 $where_primary
                        GROUP BY 
                            sma_products.id, 
                            sma_product_variants.id, 
                            sma_warehouses.id
                        ORDER BY 
                            sma_products.code ASC, 
                            sma_products.name ASC, 
                            sma_warehouses.name ASC
                    ");
                    $termwise_result = $query->result();
                }
                else{
                    $query = $this->db->query("
                        SELECT
                            p.code AS product_code,
                            p.category_id AS primary_category,
                            si.category_id AS sale_category,
                            cat.name AS category_name,
                            p.name AS product_name,
                            IFNULL(v.name, '-') AS variant_name,
                            w.name AS warehouse_name,

                            -- stock (unchanged logic, just guarded)
                            CASE
                                WHEN pc.category_id = p.category_id THEN
                                    CASE
                                        WHEN v.id IS NOT NULL THEN
                                            COALESCE((
                                                SELECT SUM(wpv.quantity)
                                                FROM sma_warehouses_products_variants wpv
                                                WHERE wpv.product_id = p.id
                                                AND wpv.option_id = v.id
                                                AND wpv.warehouse_id = w.id
                                            ), 0)
                                        ELSE
                                            COALESCE((
                                                SELECT SUM(wp.quantity)
                                                FROM sma_warehouses_products wp
                                                WHERE wp.product_id = p.id
                                                AND wp.warehouse_id = w.id
                                            ), 0)
                                    END
                                ELSE 0
                            END AS current_stock,

                            -- sales_term1 (your logic untouched)
                            COALESCE((
                                SELECT SUM(s.quantity)
                                FROM sma_sale_items s
                                JOIN sma_sales sa ON sa.id = s.sale_id
                                WHERE s.product_id = p.id
                                AND (v.id IS NULL OR s.option_id = v.id)
                                AND COALESCE(s.category_id, p.category_id) = pc.category_id
                                AND s.warehouse_id = w.id
                                AND sa.date BETWEEN '$startDate_term1' AND '$endDate_term1'
                            ), 0) AS sales_term1,

                            -- sales_term2
                            COALESCE((
                                SELECT SUM(s.quantity)
                                FROM sma_sale_items s
                                JOIN sma_sales sa ON sa.id = s.sale_id
                                WHERE s.product_id = p.id
                                AND (v.id IS NULL OR s.option_id = v.id)
                                AND COALESCE(s.category_id, p.category_id) = pc.category_id
                                AND s.warehouse_id = w.id
                                AND sa.date BETWEEN '$startDate_term2' AND '$endDate_term2'
                            ), 0) AS sales_term2

                        FROM
                        (
                            -- 🔥 PRODUCT × CATEGORY EXPANSION
                            SELECT p.id AS product_id, p.category_id AS category_id
                            FROM sma_products p

                            UNION ALL

                            SELECT p.id, c.id
                            FROM sma_products p
                            JOIN sma_categories c
                                ON FIND_IN_SET(c.id, p.other_categories)
                        ) pc

                        JOIN sma_products p ON p.id = pc.product_id
                        JOIN sma_categories cat ON cat.id = pc.category_id

                        LEFT JOIN sma_product_variants v
                            ON v.product_id = p.id
                            AND v.group_id = 1

                        INNER JOIN sma_warehouses w
                            ON w.id IN ($warehouse_ids)

                        LEFT JOIN sma_sale_items si
                            ON si.product_id = p.id
                            AND (
                                    si.category_id = pc.category_id
                                    OR (
                                        si.category_id IS NULL
                                        AND pc.category_id = p.category_id
                                        AND p.other_categories IS NULL
                                    )
                                )
                            AND (v.id IS NULL OR si.option_id = v.id)
   
                        WHERE 1=1 $where_other -- ✅ your existing category filter stays untouched

                        GROUP BY
                            p.id,
                            pc.category_id,
                            v.id,
                            w.id

                        ORDER BY
                            
                            pc.category_id;


                    ");

                    $termwise_result = $query->result();
                    // Check if primary_category and sale_category are different
                    // If they are, set current_stock, excess_inventory, and shortage_of_inventory to 0
                    // This is to ensure that the report only shows data for products that are in the same category for both primary and sale categories
                    $termwise_result = array_map(function($row) {

                    // Only reset sales logic if needed
                    if ($row->primary_category != $row->sale_category)
                    {
                        $row->sales_term1 = 0;
                        $row->sales_term2 = 0;
                        $row->excess_inventory = 0;
                        $row->shortage_of_inventory = 0;
                    }

                    // DO NOT reset current stock

                    return $row;
                }, $termwise_result);
                }
                /*
                    If u want to add excess inventory and shortage inv col

                        <th>' . lang("Excess Inventory") . '</th>
                        <th>' . lang("Shortage of Inventory") . '</th>


                        <td class="text-center">' . $this->sma->formatQuantity($row->excess_inventory) . '</td>
                        <td class="text-center">' . $this->sma->formatQuantity($row->shortage_of_inventory) . '</td>

                        <th id="total_excess_inventory"></th>
                        <th id="total_shortage_of_inventory"></th>
                */
                if (!$view_sale_count_warehouse_wise) {
                    $grouped_results = [];
                    foreach ($termwise_result as $row) {
                        $key = $row->product_code . '_' . $row->variant_name . '_' . $row->category_name;
                        if (!isset($grouped_results[$key])) {
                            $grouped_results[$key] = clone $row;
                        } else {
                            $grouped_results[$key]->current_stock += $row->current_stock;
                            $grouped_results[$key]->sales_term1 += $row->sales_term1;
                            $grouped_results[$key]->sales_term2 += $row->sales_term2;
                            if (isset($row->batch_numbers) && $row->batch_numbers != '-' && $row->batch_numbers != '') {
                                if (isset($grouped_results[$key]->batch_numbers) && $grouped_results[$key]->batch_numbers != '-' && $grouped_results[$key]->batch_numbers != '') {
                                    $batches1 = array_map('trim', explode(',', $grouped_results[$key]->batch_numbers));
                                    $batches2 = array_map('trim', explode(',', $row->batch_numbers));
                                    $grouped_results[$key]->batch_numbers = implode(', ', array_unique(array_merge($batches1, $batches2)));
                                } else {
                                    $grouped_results[$key]->batch_numbers = $row->batch_numbers;
                                }
                            }
                        }
                    }
                    $termwise_result = array_values($grouped_results);
                }

                        $datatable = '<div>
                        <table id="PrData1" class="table table-striped table-bordered table-condensed table-hover dfTable reports-table" style="margin-bottom:5px;">
                            <thead>
                                <tr class="active">
                                    <th>' . lang("product_code") . '</th>
                                    <th>' . lang("Category Name") . '</th>
                                    <th>' . lang("product_name") . '</th>
                                    <th>' . lang("Variant Name (Size)") . '</th>';
                                    if ($view_sale_count_warehouse_wise) {
                                        $datatable .= '<th>' . lang("Warehouse") . '</th>';
                                    }
                    
                    if ($this->data['Settings']->product_batch_setting == 1 || $this->data['Settings']->product_batch_setting == 2) {
                        $datatable .= '<th>' . lang("Batch No.") . '</th>';
                    }
                    
                    $datatable .= '
                                    <th>' . lang("Current Stock") . '</th>
                                    <th>' . lang("Term 1 Sale") . '</th>
                                    <th>' . lang("Term 2 Sale") . '</th>
                                </tr>
                            </thead>
                            <tbody>';
                            
                    foreach ($termwise_result as $row) {
                        $datatable .= '<tr>
                            <td>' . htmlspecialchars($row->product_code) . '</td>
                            <td>' . htmlspecialchars($row->category_name) . '</td>
                            <td>' . htmlspecialchars($row->product_name) . '</td>
                            <td>' . htmlspecialchars($row->variant_name) . '</td>';
                            
                        if ($view_sale_count_warehouse_wise) {
                            $datatable .= '<td>' . htmlspecialchars($row->warehouse_name) . '</td>';
                        }
                    
                        if ($this->data['Settings']->product_batch_setting == 1 || $this->data['Settings']->product_batch_setting == 2) {
                            $batch = !empty($row->batch_numbers) ? htmlspecialchars($row->batch_numbers) : '-';
                            $datatable .= '<td class="text-left">' . $batch . '</td>';
                        }
                    
                        $datatable .= '
                            <td class="text-center">' . $this->sma->formatQuantity($row->current_stock) . '</td>
                            <td class="text-center">' . $this->sma->formatQuantity($row->sales_term1) . '</td>
                            <td class="text-center">' . $this->sma->formatQuantity($row->sales_term2) . '</td>
                        </tr>';
                    }
                    
                    $colspan = $view_sale_count_warehouse_wise ? 5 : 4;
                    $datatable .= '</tbody>
                            <tfoot>
                                <tr>
                                    <th colspan="' . $colspan . '" style="text-align:right;">' . lang("Total") . ':</th>';
                    
                    if ($this->data['Settings']->product_batch_setting == 1 || $this->data['Settings']->product_batch_setting == 2) {
                        $datatable .= '<th></th>'; // Empty total cell for Batch column
                    }
                    
                    $datatable .= '
                                    <th id="total_current_stock"></th>
                                    <th id="total_sales_term1"></th>
                                    <th id="total_sales_term2"></th>
                                </tr>
                            </tfoot>
                        </table>
                    </div>';
                    
                echo $datatable;
            }
        }
    }
    function get_product_ids_for_all_trans($start_date_str, $end_date_str, $warehouse_where, $sale_where, $warehouse_where_for_p, $category = null, $brand = null, $subcategory = null){
        // Purchase Transactions
        $purchase_codes = "SELECT DISTINCT purchase_data.product_id
                   FROM sma_view_products_transactions AS purchase_data
                   WHERE 
                       $warehouse_where
                       AND DATE(transaction_date) BETWEEN '$start_date_str' AND '$end_date_str'
                       AND EXISTS (SELECT 1 FROM sma_products prd WHERE prd.id = purchase_data.product_id";
        if ($category) {
            $purchase_codes .= " AND prd.category_id = '$category'";
        }
        if ($brand) {
            $purchase_codes .= " AND prd.brand = '$brand'";
        }
        if ($subcategory) {
            $purchase_codes .= " AND prd.subcategory_id = '$subcategory'";
        }
        $purchase_codes .= ")";

        $purchase_products_code = $this->db->query($purchase_codes)->result();
               
               $product_ids = array_map(function($purchase_products_code) {
                   return $purchase_products_code->product_id;
               }, $purchase_products_code);
               $implode_purchase_code = implode(',', $product_ids);

        // Sales Transactions
        $sale_codes = "SELECT DISTINCT s.product_id
                   FROM sma_view_products_sales AS s
                   WHERE 
                       $warehouse_where AND 
                       $sale_where
                       AND EXISTS (SELECT 1 FROM sma_products prd WHERE prd.id = s.product_id";
        if ($category) {
            $sale_codes .= " AND prd.category_id = '$category'";
        }
        if ($brand) {
            $sale_codes .= " AND prd.brand = '$brand'";
        }
        if ($subcategory) {
            $sale_codes .= " AND prd.subcategory_id = '$subcategory'";
        }
        $sale_codes .= ")";

        $sale_products_code = $this->db->query($sale_codes)->result();
               
               $product_ids = array_map(function($sale_products_code) {
                   return $sale_products_code->product_id;
               }, $sale_products_code);
               $implode_sale_code = implode(',', $product_ids);
            
        // Adjustment Transactions
        $adjustment_codes = "SELECT DISTINCT adj.product_id
        FROM sma_adjustment_items AS adj
        WHERE 
        adjustment_id IN 
        (SELECT id FROM sma_adjustments WHERE DATE(date) BETWEEN '$start_date_str' AND '$end_date_str')
        AND EXISTS (SELECT 1 FROM sma_products prd WHERE prd.id = adj.product_id";
        if ($category) {
            $adjustment_codes .= " AND prd.category_id = '$category'";
        }
        if ($brand) {
            $adjustment_codes .= " AND prd.brand = '$brand'";
        }
        if ($subcategory) {
            $adjustment_codes .= " AND prd.subcategory_id = '$subcategory'";
        }
        $adjustment_codes .= ")
        GROUP BY adj.product_id, adj.option_id";
        $adjustment_products_code = $this->db->query($adjustment_codes)->result();
            
            $product_ids = array_map(function($adjustment_products_code) {
                return $adjustment_products_code->product_id;
            }, $adjustment_products_code);
            $implode_adjustment_code = implode(',', $product_ids);
    
        // Transfers Transactions
        $transfer_request_codes = "SELECT DISTINCT p.product_id
        FROM sma_transfer_request_items AS p
        WHERE 
        $warehouse_where_for_p
        AND DATE(p.date) BETWEEN '$start_date_str' AND '$end_date_str'
        AND EXISTS (SELECT 1 FROM sma_products prd WHERE prd.id = p.product_id";
        if ($category) {
            $transfer_request_codes .= " AND prd.category_id = '$category'";
        }
        if ($brand) {
            $transfer_request_codes .= " AND prd.brand = '$brand'";
        }
        if ($subcategory) {
            $transfer_request_codes .= " AND prd.subcategory_id = '$subcategory'";
        }
        $transfer_request_codes .= ")";
        $transfer_request_code = $this->db->query($transfer_request_codes)->result();
            
            $product_ids = array_map(function($row) {
                return $row->product_id;
            }, $transfer_request_code);
            $implode_transfer_request_code = implode(',', $product_ids);


        // merge arrays
        // Convert the comma-separated strings into arrays
            $sale_codes_array = explode(',', $implode_sale_code);
            $purchase_codes_array = explode(',', $implode_purchase_code);
            $transfer_codes_array = explode(',', $implode_transfer_request_code);
            $adjustment_codes_array = explode(',', $implode_adjustment_code);


            // Merge the two arrays and remove duplicates
            $merged_product_ids = array_unique(array_merge($sale_codes_array, $purchase_codes_array, $transfer_codes_array, $adjustment_codes_array));

            // Remove any empty values (in case any string was empty)
            $merged_product_ids = array_filter($merged_product_ids);

            // Convert back to a comma-separated string
            $final_merged_ids = implode(',', $merged_product_ids);
            return $final_merged_ids;


    }
       
    /**
     * Dynamic BI report loader by ID or by slug built from manu_name and name.
     * Slug format in menu: strtolower( sanitize((manu_name||'') + '_' + name) ) with non [a-zA-Z0-9_] -> '_'
     */
    public function bi($slug = NULL) {
        // $this->sma->checkPermissions('index', TRUE);
        $table = 'bi_reports';
        if (!$this->db->table_exists($table)) {
            show_404();
        }
        $has_report_url = $this->db->field_exists('report_url', $table);
        $select = 'id, name, manu_name, links' . ($has_report_url ? ', report_url' : '');

        $row = NULL;
        // Normalize incoming slug: lower, collapse multiple underscores, trim underscores
        $slug_in = strtolower((string)$slug);
        $slug_in = preg_replace('/_+/', '_', $slug_in);
        $slug_in = trim($slug_in, '_');

        if (!empty($slug_in) && ctype_digit((string)$slug_in)) {
            $q = $this->db->select($select)
                         ->from($table)
                         ->where('id', (int)$slug_in)
                         ->where('is_active', 1)
                         ->get();
            $row = $q->num_rows() ? $q->row() : NULL;
        } else {
            $q = $this->db->select($select)
                         ->from($table)
                         ->where('is_active', 1)
                         ->get();
            if ($q->num_rows()) {
                foreach ($q->result() as $r) {
                    $manu = isset($r->manu_name) ? $r->manu_name : '';
                    $name = isset($r->name) ? $r->name : '';
                    // Build two possible slugs: manu+name and manu-only to support current menu links
                    $built1 = strtolower(preg_replace('/[^a-zA-Z0-9_]+/', '_', trim($manu . '_' . $name)));
                    $built1 = preg_replace('/_+/', '_', $built1);
                    $built1 = trim($built1, '_');
                    $built2 = strtolower(preg_replace('/[^a-zA-Z0-9_]+/', '_', trim($manu)));
                    $built2 = preg_replace('/_+/', '_', $built2);
                    $built2 = trim($built2, '_');
                    if ($built1 === $slug_in || $built2 === $slug_in) {
                        $row = $r;
                        break;
                    }
                }
            }
        }

        if (!$row) {
            show_404();
        }

        $title = !empty($row->name) ? $row->name : lang('BI Reports');
        $bc = array(
            array('link' => base_url(), 'page' => lang('home')),
            array('link' => site_url('reports'), 'page' => lang('reports')),
            array('link' => '#', 'page' => $title)
        );
        $meta = array('page_title' => $title, 'bc' => $bc);

        if (!empty($row->links)) {
            $lnk = (string)$row->links;
            if (preg_match('/^https?:\/\//i', $lnk)) {
                $this->data['report_url'] = $lnk;
                $this->page_construct('reports/bi_report', $meta, $this->data);
                return;
            }
            redirect(site_url($lnk));
            return;
        }
        if ($has_report_url && !empty($row->report_url)) {
            $this->data['report_url'] = $row->report_url;
            $this->page_construct('reports/bi_report', $meta, $this->data);
            return;
        }
        show_404();
    }

    public function bi_manage() {
        if (!$this->Owner && !$this->Admin) {
            show_error('Access denied', 403);
        }
        $table = 'bi_reports';
        if (!$this->db->table_exists($table)) {
            show_404();
        }
        $this->form_validation->set_rules('manu_name', 'Menu Name', 'trim|required');
        $this->form_validation->set_rules('name', 'Report Name', 'trim|required');
        $this->form_validation->set_rules('links', 'Internal Link', 'trim');
        $this->form_validation->set_rules('report_url', 'External URL', 'trim');
        $this->form_validation->set_rules('is_active', 'Active', 'trim');

        if ($this->form_validation->run() == TRUE) {
            $data = array(
                'manu_name' => $this->input->post('manu_name', TRUE),
                'name' => $this->input->post('name', TRUE),
                'links' => $this->input->post('links', TRUE) ?: NULL,
                'is_active' => $this->input->post('is_active') ? 1 : 0,
            );
            if ($this->db->field_exists('report_url', $table)) {
                $data['report_url'] = $this->input->post('report_url', TRUE) ?: NULL;
            }
            $this->db->insert($table, $data);
            $this->session->set_flashdata('message', 'BI report saved');
            redirect(site_url('reports/bi_manage'));
            return;
        }

        $q = $this->db->select('id, manu_name, name, links' . ($this->db->field_exists('report_url', $table) ? ', report_url' : '') . ', is_active')
                       ->from($table)
                       ->order_by('id', 'DESC')
                       ->get();
        $this->data['bi_items'] = $q->num_rows() ? $q->result() : array();

        $bc = array(
            array('link' => base_url(), 'page' => lang('home')),
            array('link' => site_url('reports'), 'page' => lang('reports')),
            array('link' => '#', 'page' => 'Manage BI Reports')
        );
        $meta = array('page_title' => 'Manage BI Reports', 'bc' => $bc);
        $this->page_construct('reports/bi_manage', $meta, $this->data);
    }
