    function getRes_dashReport($pdf = NULL, $xls = NULL, $img = NULL) {
        $this->sma->checkPermissions('sales', TRUE);

        $start_date = $start_dmy = $this->input->get('start_date') ? $this->input->get('start_date') : date('d/m/Y');
        $end_date = $end_dmy = $this->input->get('end_date') ? $this->input->get('end_date') : date('d/m/Y');
        $time_slot_id = $this->input->get('time_slot') ? $this->input->get('time_slot') : NULL;
        
        $start_time = NULL;
        $end_time = NULL;
        if ($time_slot_id) {
            $slot = $this->db->get_where('sma_business_time_slot', ['id' => $time_slot_id])->row();
            if ($slot) {
                $start_time = $slot->start_time; // e.g., '07:00:00'
                $end_time = $slot->end_time;     // e.g., '11:30:00'
            }
        }
        
        // $report_type = $this->input->get('report_type') ? $this->input->get('report_type') : 1;
        $warehouse = $this->input->get('warehouse') ? $this->input->get('warehouse') : NULL;
        $passwarehouse = $warehouse ? str_replace("_", ",", $warehouse) : '';
        $created_by = $this->input->get('created_by');

        if ($start_date) {
            $start_date = $this->sma->fld($start_date);
            $end_date = $this->sma->fld($end_date);
        }
        if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
            $user = $this->session->userdata('user_id');
        }
        $order_types = $this->reports_model->getOrderTypeSummary($start_date, $end_date, $passwarehouse, $created_by, $start_time, $end_time);
        
        $sale_sources = $this->reports_model->getSourceSummary($start_date, $end_date, $passwarehouse, $created_by, $start_time, $end_time);
        $start_date_only = date('Y-m-d', strtotime($start_date));
        $end_date_only = date('Y-m-d', strtotime($end_date));
        if ($pdf || $xls || $img) {
            if ($this->input->get('warehouse')) {
                $getwarehouse = str_replace("_", ",", $this->input->get('warehouse'));
            }
            // "sum(grand_total) as net_sale, "
            $this->db->select($this->db->dbprefix('warehouses') .
                            ".id as warehouse_id, " . $this->db->dbprefix('warehouses') .
                            ".name as warehouse, "
                            ."SUM(COALESCE((grand_total + rounding), 0)) AS GrossSale,"
                            ."SUM(IF(sale_status='returned',abs(grand_total) + abs(rounding),0)) as return_amt,"
                            ."SUM(IF(sale_status!='returned', total_discount ,0)) as total_discount,"
                            ." SUM( COALESCE(grand_total + rounding, 0 ) ) AS NetSale,"
                            . "sum(total) as net_total , "
                            . "sum(total_discount) discount, "
                            . "sum(rounding) as rounding, "
                            . "sum(shipping) as shipping, "
                            . "sum(total) as net_sale, "
                            . "sum(total_tax) as tax, "
                            . "count(reference_no) total_bills ", FALSE)
                    ->from('sales')
                    ->join('warehouses', 'warehouses.id=sales.warehouse_id', 'left');
            // ->group_by('sales.warehouse_id');


            if ($time_slot_id) {
                $this->db->where('DATE(' . $this->db->dbprefix('sales') . '.date) >=', $start_date);
                $this->db->where('DATE(' . $this->db->dbprefix('sales') . '.date) <=', $end_date);
                if ($start_time && $end_time) {
                    $this->db->where("TIME(" . $this->db->dbprefix('sales') . ".date) >=", $start_time);
                    $this->db->where("TIME(" . $this->db->dbprefix('sales') . ".date) <=", $end_time);
                }
            }
            else{
                $this->db->where('(' . $this->db->dbprefix('sales') . '.date) >=', $start_date);
                $this->db->where('(' . $this->db->dbprefix('sales') . '.date) <=', $end_date);
            }

            if ($getwarehouse) {
                $this->db->where('sales.warehouse_id IN (' . $getwarehouse . ')');
            }

            if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
                // $where .= " AND created_by = " . $this->session->userdata('user_id');
                $this->db->where('sales.created_by = (' . $this->session->userdata('user_id') . ')');

            } else {
                if ($created_by) {
                    // $where .= " AND created_by = " . (int) $created_by;
                    $this->db->where('sales.created_by IN (' . $created_by . ')');
                }
            }
            // $this->db->where('sales.sale_status!="returned"');
            $this->db->group_by('sales.warehouse_id');

            $q = $this->db->get();

            if ($q->num_rows() > 0) {
                foreach (($q->result()) as $row) {
                    $data[] = $row;
                }
            } else {
                $data = NULL;
            }

            if (!empty($data)) {
                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);
                $this->excel->getActiveSheet()->mergeCells('A1:I1');
                $this->excel->getActiveSheet()->SetCellValue('A1', 'Warehouse Sales Reports');

                $this->excel->getActiveSheet()->setTitle(lang('warehouse_sales_report'));
                $this->excel->getActiveSheet()->SetCellValue('A2', lang('Branch Name (Warehouses)'));
                $this->excel->getActiveSheet()->SetCellValue('B2', lang('Gross_Sale'));
                $this->excel->getActiveSheet()->SetCellValue('C2', lang('Discount'));
                $this->excel->getActiveSheet()->SetCellValue('D2', lang('Due Amount'));
                $this->excel->getActiveSheet()->SetCellValue('E2', lang('Refund'));
                $this->excel->getActiveSheet()->SetCellValue('F2', lang('Net_Sale'));
                $this->excel->getActiveSheet()->SetCellValue('G2', lang('Cash'));
                $this->excel->getActiveSheet()->SetCellValue('H2', lang('Online Payments'));
                $this->excel->getActiveSheet()->SetCellValue('I2', lang('Debit Card'));
                $this->excel->getActiveSheet()->SetCellValue('J2', lang('Total_Tax'));
                $this->excel->getActiveSheet()->SetCellValue('K2', lang('Total Invoices'));
            //                $this->excel->getActiveSheet()->SetCellValue('I2', lang('Items Sold'));

                $row = 3;
                $total_gross_sale = 0;
                $total_discount = 0;
                $total_net_sale = 0;
                $calculate_total_tax = 0;
                $cal_total_bills = 0;
                $total_sold_items = 0;
                $total_due = 0;
                $total_return = 0;
                $total_sales = 0;
                $total_withcash = 0;
                $total_withoutcash = 0;
                foreach ($data as $data_row) {
                    $WithCash = 0;
                    $OnlinePayment = 0;
                    $DebitCardPayment = 0;
                    $Warehouse_id = $data_row->warehouse_id;
                    $SqlCash = "SELECT p.amount, p.paid_by FROM sma_sales s inner join sma_payments p on s.id=p.sale_id where s.warehouse_id='$Warehouse_id' and p.paid_by!='gift_card'";
                    if ($start_date) {
                        $SqlCash .= " and (s.date)>= '$start_date' AND (s.date)<='$end_date' ";
                        if ($start_time && $end_time) {
                            $SqlCash .= " AND TIME(s.date) BETWEEN '$start_time' AND '$end_time' ";
                        }
                    }
                    // Apply created_by filter
                    if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
                        $SqlCash .= " AND s.created_by = " . (int) $this->session->userdata('user_id');
                    } else {
                        if ($created_by) {
                            $SqlCash .= " AND s.created_by = " . (int) $created_by;
                        }
                    }
                    $Rescash = $this->db->query($SqlCash);
                    $SqlCashOnline = "SELECT s.grand_total, s.source 
                  FROM sma_sales s 
                  WHERE s.warehouse_id = '$Warehouse_id' 
                    AND s.source LIKE 'up_%'";

                    if ($start_date) {
                        $SqlCashOnline .= " AND (s.date) >= '$start_date' AND (s.date) <= '$end_date' ";
                        if ($start_time && $end_time) {
                            $SqlCashOnline .= " AND TIME(s.date) BETWEEN '$start_time' AND '$end_time' ";
                        }
                    }

                    // Apply created_by filter
                    if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
                        $SqlCashOnline .= " AND s.created_by = " . (int) $this->session->userdata('user_id');
                    } else {
                        if ($created_by) {
                            $SqlCashOnline .= " AND s.created_by = " . (int) $created_by;
                        }
                    }

                    $RescashOnline = $this->db->query($SqlCashOnline);
                    foreach ($Rescash->result() as $rowcash) {
                        switch (strtoupper($rowcash->paid_by)) {
                            case 'CASH':
                                $WithCash += $rowcash->amount;
                                break;
                            case 'CCAVENUE':
                                $OnlinePayment += $rowcash->amount;
                                break;
                            case 'DC':
                                $DebitCardPayment += $rowcash->amount;
                                break;
                        }
                    }
                     foreach ($RescashOnline->result() as $rowcash) {
                        if (stripos($rowcash->source, 'up_') === 0) {
                            $OnlinePayment += $rowcash->grand_total;
                        }
                    }
                    $net_total = $data_row->net_total;

                    $gross_sale = $data_row->GrossSale+ $data_row->return_amt + $data_row->total_discount;

                    /* --- 18-03-19 --- */
                    $duesales = $this->reports_model->getreport($start_date, $end_date, 'due', $data_row->warehouse_id, $start_time, $end_time, $created_by);
                    $returnsales = $this->reports_model->getreport($start_date, $end_date, 'return', $data_row->warehouse_id, $start_time, $end_time, $created_by);
                    $partialamt = $this->reports_model->getreportbalance($start_date, $end_date, $data_row->warehouse_id, $start_time, $end_time, $created_by);
                    $pendingamount = $this->reports_model->getreport($start_date, $end_date, 'pending', $data_row->warehouse_id, $start_time, $end_time, $created_by);
                    $tax = $data_row->tax + $returnsales->tax;
                    $net_sale = $data_row->NetSale;
                    $discount = $data_row->discount;

                    $total_dueamt = $duesales->total + $duesales->total_discount + $partialamt + $pendingamount->total;
                    $total_returnAmt = str_replace('-', '', $returnsales->total); // + str_replace('-', '', $returnsales->total_discount);
                    $total_sales = $data_row->Total_sales + $total_returnAmt;
                    $total_netamt = $total_sales - $data_row->discount - $total_dueamt - $total_returnAmt;
                    /* ---- 18-03-19 --- */

                    $this->excel->getActiveSheet()->SetCellValue('A' . $row, $data_row->warehouse);
                    $this->excel->getActiveSheet()->SetCellValue('B' . $row, $this->sma->formatMoney($gross_sale));
                    $this->excel->getActiveSheet()->SetCellValue('C' . $row, $this->sma->formatMoney($discount));
                    $this->excel->getActiveSheet()->SetCellValue('D' . $row, $this->sma->formatMoney($total_dueamt));
                    $this->excel->getActiveSheet()->SetCellValue('E' . $row, $this->sma->formatMoney($total_returnAmt));
                    $this->excel->getActiveSheet()->SetCellValue('F' . $row, $this->sma->formatMoney($net_sale));
                    $this->excel->getActiveSheet()->SetCellValue('G' . $row, $this->sma->formatMoney($WithCash));
