            $sql = "SELECT w.id as warehouse_id,  w.name as warehouse , 
            SUM(COALESCE((s.grand_total + s.rounding), 0)) AS GrossSale,
            SUM(IF(s.sale_status='returned',abs(s.grand_total) + abs(s.rounding),0)) as return_amt,
            SUM(IF(s.sale_status!='returned', s.total_discount ,0)) as total_discount,
                SUM( COALESCE( s.grand_total + s.rounding, 0 ) ) AS NetSale,
                sum(s.total) net_total, 
                sum(s.total_discount) as  discount, 
                sum(s.total) as net_sale,
                sum(s.rounding) as rounding,
                sum(s.shipping) as shipping,
                sum(s.total_tax) as tax, 
