                $total_gross_sale = 0;
                $total_discount = 0;
                $total_net_sale = 0;
                $calculate_total_tax = 0;
                $cal_total_bills = 0;
                $total_sold_items = 0;
                $total_due = 0;
                $total_return = 0;
                $total_sales = 0;
                $total_withcash = 0;
                $total_withoutcash = 0;


                foreach ($q->result() as $row) {
                    $WithCash = 0;
                    $OnlinePayment = 0;
                    $DebitCardPayment = 0;
                    $Warehouse_id = $row->warehouse_id;
                    $SqlCash = "SELECT p.amount, p.paid_by FROM sma_sales s inner join sma_payments p on s.id=p.sale_id where s.warehouse_id='$Warehouse_id' and p.paid_by!='gift_card'"; //and  p.paid_by='cash' 
                    if ($start_date) {
                        $SqlCash .= " and (s.date)>= '$start_date' AND (s.date)<='$end_date' ";
                    }
                    // Apply created_by filter
                    if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
                        $SqlCash .= " AND s.created_by = " . (int) $this->session->userdata('user_id');
                    } else {
                        if ($created_by) {
                            $SqlCash .= " AND s.created_by = " . (int) $created_by;
                        }
                    }
                    $Rescash = $this->db->query($SqlCash);
                    $SqlCashOnline = "SELECT s.grand_total, s.source 
                  FROM sma_sales s 
                  WHERE s.warehouse_id = '$Warehouse_id' 
                    AND s.source LIKE 'up_%'";

                    // if ($time_slot_id) {
                    //     $SqlCashOnline .= " AND (s.date) >= '$start_date' AND (s.date) <= '$end_date' ";
                    // }
                    // if ($start_time) {
                    //     $SqlCashOnline .= " AND DATE(s.date) >= '$start_date' AND DATE(s.date) <= '$end_date' ";
                    //     $SqlCashOnline .= " AND TIME(s.date) >= '$start_time' AND TIME(s.date) <= '$end_time' ";
                    // }
                    if ($time_slot_id) {
                        if ($start_date && $end_date) {
                            // $where .= " WHERE date(s.date) >= '{$start_date}' AND date(s.date) <= '{$end_date}' ";
                            $SqlCashOnline .= " AND date(s.date) >= '$start_date' AND date(s.date) <= '$end_date' ";
                        }
            
                        if (!empty($start_time) && !empty($end_time)) {
                            // $where .= " AND TIME(s.date) >= '{$start_time}' AND TIME(s.date) <= '{$end_time}' ";
                            $SqlCashOnline .= " AND TIME(s.date) >= '$start_time' AND TIME(s.date) <= '$end_time' ";
                        }
            
                    }
                    else{
                        // $where .= " WHERE (s.date) >= '{$start_date}' AND (s.date) <= '{$end_date}' ";    
                        $SqlCashOnline .= " AND (s.date) >= '$start_date' AND (s.date) <= '$end_date' ";
                    }
                    // Apply created_by filter
                    if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
                        $SqlCashOnline .= " AND s.created_by = " . (int) $this->session->userdata('user_id');
                    } else {
                        if ($created_by) {
                            $SqlCashOnline .= " AND s.created_by = " . (int) $created_by;
                        }
                    }

                    $RescashOnline = $this->db->query($SqlCashOnline);
                    
                    foreach ($Rescash->result() as $rowcash) {
                        switch (strtoupper($rowcash->paid_by)) {
                            case 'CASH':
                                $WithCash += $rowcash->amount;
                                break;
                            case 'CCAVENUE':
                                $OnlinePayment += $rowcash->amount;
                                break;
                            case 'DC':
                                $DebitCardPayment += $rowcash->amount;
                                break;
                        }
                    }
                    foreach ($RescashOnline->result() as $rowcash) {
                        if (stripos($rowcash->source, 'up_') === 0) {
                            $OnlinePayment += $rowcash->grand_total;
                        }
                    }
                    $net_total = $row->net_total;

                    $gross_sale = $row->GrossSale+ $row->return_amt + $row->total_discount;

                    $duesales = $this->reports_model->getreport($start_date, $end_date, 'due', $row->warehouse_id, $start_time, $end_time, $created_by);
                    $returnsales = $this->reports_model->getreport($start_date, $end_date, 'return', $row->warehouse_id, $start_time, $end_time, $created_by);
                    $partialamt = $this->reports_model->getreportbalance($start_date, $end_date, $row->warehouse_id, $start_time, $end_time, $created_by);
                    $pendingamount = $this->reports_model->getreport($start_date, $end_date, 'pending', $row->warehouse_id, $start_time, $end_time, $created_by);
                    $tax = $row->tax + $returnsales->tax;
                    //$net_sale   = $row->net_sale+$returnsales->net_sale+$tax;
                    $net_sale = $row->NetSale;

                    $total_dueamt = $duesales->total + $duesales->total_discount + $partialamt + $pendingamount->total; //
                    $total_returnAmt = str_replace('-', '', $returnsales->total); // + str_replace('-', '', $returnsales->total_discount);
                    // $total_returnAmt;
                    $discount = $row->discount;
                    $total_sales = $row->Total_sales + $total_returnAmt;

                    echo '<tr> <td>' . $row->warehouse . '</td>';
                    echo '<td align="right">' . $this->sma->formatMoney($gross_sale) . '</td>';
                    echo '<td align="right">' . $this->sma->formatMoney($discount) . '</td>';
                    echo '<td align="right">' . $this->sma->formatMoney($total_dueamt) . '</td>';
                    echo '<td align="right">' . (($total_returnAmt != 0) ?  $this->sma->formatMoney($total_returnAmt) : 0) . '</td>';
                    echo '<td align="right">' . $this->sma->formatMoney($net_sale) . '</td>'; // $row->net_sale - $total_dueamt
                    echo '<td align="right">' . $this->sma->formatMoney($WithCash) . '</td>';
                    echo '<td align="right">' . $this->sma->formatMoney($OnlinePayment) . '</td>';
                    echo '<td align="right">' . $this->sma->formatMoney($DebitCardPayment) . '</td>';
                    echo '<td align="right">' . $this->sma->formatMoney($tax) . '</td>';
                    echo '<td align="center">' .number_format($row->total_bills) . '</td>';

                    echo '<td onclick="getsaleitems(\'' . $start_date . '\',\'' . $end_date . '\', \'' . $row->warehouse_id . '\', \'' . $row->warehouse . '\')"><i class="fa fa-list-alt" aria-hidden="true"></i></td></tr>';

                    $total_gross_sale += $gross_sale;
                    $total_discount += $discount;
                    $total_due += $total_dueamt;
                    $total_return += $total_returnAmt;
                    $total_net_sale += $net_sale;
                    $calculate_total_tax += $tax;
                    $cal_total_bills += $row->total_bills;
                    $total_withcash += $WithCash;
                    $total_online += $OnlinePayment;
                    $total_debitcard += $DebitCardPayment;
                    $warehouses[$row->warehouse_id] = $row->warehouse;
                }
            }//end num
            else {
                echo ' <tr><td colspan="7" class="dataTables_empty">No Record Found</td></tr>';
            }
            echo '   </tbody>
                        <tfoot>
                        <tr>
                            <th>Total</th>
                            <th class="right">' . $this->sma->formatMoney($total_gross_sale) . '</th>
                            <th class="right">' . $this->sma->formatMoney($total_discount) . '</th>
                            <th class="right">' . $this->sma->formatMoney($total_due) . '</th>
                            <th class="right">' . $this->sma->formatMoney($total_return) . '</th>
                            <th class="right">' . $this->sma->formatMoney($total_net_sale) . '</th>    
                            <th class="right">' . $this->sma->formatMoney($total_withcash) . '</th>                            
                            <th class="right">' . $this->sma->formatMoney($total_online) . '</th>                             
                            <th class="right">' . $this->sma->formatMoney($total_debitcard) . '</th>                             
                            <th class="right">' . $this->sma->formatMoney($calculate_total_tax) . '</th>
                            <th class="center">' .number_format($cal_total_bills) . '</th>
                            <th></th>
                        </tr>
                        </tfoot>
                    </table>';

                    // Order Type Summary
                    $orderTypeTable = '<h2>Order Types</h2>';
                    $orderTypeTable .= '<table class="table table-bordered"><thead>
                    <tr><th>Order Type</th><th>Orders</th><th>Total Value</th></tr></thead><tbody>';

                    if ($order_types) {
                        foreach ($order_types as $ot) {
                            $orderTypeTable .= '<tr>
                                <td>' . $ot->order_type_name . '</td>
                                <td align="center">' . number_format($ot->orders) . '</td>
                                <td align="right">' . $this->sma->formatMoney($ot->total_value) . '</td>
                            </tr>';
                            $totalOrders = array_sum(array_map(function($ot) { return $ot->orders; }, $order_types));
                            $totalValue  = array_sum(array_map(function($ot) { return $ot->total_value; }, $order_types));
                        }
                    } else {
                        $orderTypeTable .= '<tr><td colspan="3" class="text-center">No records found</td></tr>';
                    }

                    $orderTypeTable .= '</tbody>
                        <tfoot>
                            <tr>
                                <th>Total</th>
                                <th class="center">' . number_format($totalOrders) . '</th>
                                <th class="right">' . $this->sma->formatMoney($totalValue) . '</th>
                            </tr>
                        </table>';

                    // echo $orderTypeTable;

                    // Sale Source Summary
                    $saleSourceTable = '<h2>Sales Source</h2>';
                    $saleSourceTable .= '<table class="table table-bordered"><thead>
                    <tr><th>Source</th><th>Orders</th><th>Total Value</th></tr></thead><tbody>';

                    if ($sale_sources) {
                        foreach ($sale_sources as $src) {
                            $saleSourceTable .= '<tr>
                                <td>' . $src->source_name . '</td>
                                <td align="center">' . number_format($src->orders) . '</td>
                                <td align="right">' . $this->sma->formatMoney($src->total_value) . '</td>
                            </tr>';
                            $totalSource += $src->orders;
                            $totalValueSource += $src->total_value;
                        }
                    } else {
                        $saleSourceTable .= '<tr><td colspan="3" class="text-center">No records found</td></tr>';
                    }

                    $saleSourceTable .= '</tbody>
                        <tfoot>
                            <tr>
                                <th>Total</th>
                                <th class="center">' . number_format($totalSource) . '</th>
                                <th class="right">' . $this->sma->formatMoney($totalValueSource) . '</th>
                            </tr>
                        </tfoot>
                        </table>';
                    // echo $saleSourceTable;
                    echo '<div class="row" style="margin-top:30px;">';
                    echo '<div class="col-md-6">' . $orderTypeTable . '</div>';
                    echo '<div class="col-md-6">' . $saleSourceTable . '</div>';
                    echo '</div>';

                $wps = $this->reports_model->warehouseSalesItems($start_date , $end_date , $passwarehouse, $start_time, $end_time);

                $ws = $warehouses;
                $datatable = '<h2>Sold-out Location-wise Items Reports</h2>';
                $str_wp = 'wh';
            // }//end elseif.

            $datatable .= '<div><table id="warehouses_products" class="table table-striped table-bordered" style="width:100%">
            <thead>
                <tr>
                <th>Product Name</th>
                <th>Variant Name</th>
                <th>Code</th>';

            if (is_array($ws)) {
                foreach ($ws as $whn) {
                    $datatable .= "<th>$whn</th>";
                }
            }

            $datatable .= '<th>Total</th> 
            </tr>
          </thead>
        <tbody>';

            $total = array();
            $totalstock = 0;
            if (is_array($wps)) {
                foreach ($wps as $pid => $wpdata) {

                    $datatableRow = '<tr>               
                <td>' . $wpdata['name'] . '</td>
                <td>' . $wpdata['VarientName'] . '</td>
                <td>' . $wpdata['code'] . '</td>';
                    $stock = 0;
                    if (is_array($ws)) {
                        foreach ($ws as $wid => $whn) {
                            // $qty = ($wpdata[$str_wp][$wid]) ? $this->sma->formatQuantity($wpdata[$str_wp][$wid]) : 0;
                            $qty = isset($wpdata[$str_wp][$wid]) && $this->sma->formatQuantity($wpdata[$str_wp][$wid]) != 0 
                                    ? number_format($wpdata[$str_wp][$wid]) 
                                    : 0;

                            $datatableRow .= '<td align="center">' . $qty . '</td>';
                            $stock += $qty;
                            $total[$whn] += $qty;
                        }//end foreach.
                    }//end if.

                    $datatableRow .= '<td align="center"><b>' . $stock . '</b></td>
            </tr>';

                    if ($stock >= 0) {
                        $datatable .= $datatableRow;
                    }
                    $totalstock = $totalstock + $stock;
                }//end foreach
            } //end if

            $datatable .= '</tbody>
        <tfoot>
            <tr>
                <th>Total</th>
                <th></th>
                <th></th>';
            if (is_array($ws)) {
                foreach ($ws as $whn) {
                    $datatable .= "<th class='center'></th>";
                }
            }
            $datatable .= '<th class="center"></th>
            </tr>
        </tfoot>
        </table></div>';


            echo "<div>" . $datatable . "</div>";
        }
    }
    function cash_transaction() {
        $this->sma->checkPermissions('cash-transaction-report');
        $this->data['error'] = (validation_errors()) ? validation_errors() : $this->session->flashdata('error');
        $this->data['users'] = $this->reports_model->getStaff();
        $this->data['warehouses'] = $this->site->getAllWarehouses();
        $this->data['transaction_types'] = $this->site->get_all_transaction_types();
        $this->data['currency'] = $this->reports_model->get_currency();
        $bc = array(array('link' => base_url(), 'page' => lang('home')), array('link' => site_url('reports'), 'page' => lang('reports')), array('link' => '#', 'page' => lang('cash_transaction_report')));
        $meta = array('page_title' => lang('cash_transaction_report'), 'bc' => $bc);
        $this->page_construct('reports/cash_transaction', $meta, $this->data);
    }
    function getCashTransactionReport($pdf = NULL, $xls = NULL, $img = NULL) {
        $this->sma->checkPermissions('cash-transaction-report', TRUE);

        $user = $this->input->get('user') ? $this->input->get('user') : NULL;
        $warehouse = $this->input->get('warehouse') ? $this->input->get('warehouse') : NULL;
        $start_date = $this->input->get('start_date') ? $this->input->get('start_date') : NULL;
        $end_date = $this->input->get('end_date') ? $this->input->get('end_date') : NULL;
        $transaction_type = $this->input->get('transaction_type') ? $this->input->get('transaction_type') : NULL;
        $amount_filter = $this->input->get('amount_filter') ? $this->input->get('amount_filter') : NULL;
        $amount_value = $this->input->get('amount_value') ? $this->input->get('amount_value') : NULL;
        $amount_value_to = $this->input->get('amount_value_to') ? $this->input->get('amount_value_to') : NULL;
        $currency = $this->input->get('currency') ? $this->input->get('currency') : NULL;
        if ($start_date) {
            $start_date = $this->sma->fld($start_date);
            $end_date = $this->sma->fld($end_date);
        }
        if (!$this->Owner && !$this->Admin && !$this->session->userdata('view_right')) {
            $user = $this->session->userdata('user_id');
        }

        if ($pdf || $xls || $img) {
            $this->load->library('datatables');
            $this->load->helper('reports');
           $this->db->select(" DATE_FORMAT(sma_coinage_transactions_master.datetime, '%Y-%m-%d %H:%i:%s') AS transaction_date, CONCAT('CT-', DATE_FORMAT(sma_coinage_transactions_master.datetime, '%Y%m%d'),'-', LPAD(sma_coinage_transactions_master.id, 4, '0')) AS reference_no,sma_users.username, sma_warehouses.name AS location_name, sma_coinage_transactions_master.transaction_type,sma_coinage_transactions_master.amount,

            CONCAT(
                IF(
                    SUM(LOWER(TRIM(sma_coinage_transactions.currency_type)) IN ('bill','bills')) > 0,
                    CONCAT(
                        'Bills:', '\n',
                        GROUP_CONCAT(
                            IF(
                                LOWER(TRIM(sma_coinage_transactions.currency_type)) IN ('bill','bills'),
                                CONCAT(
                                    sma_coinage_transactions.currency_value,
                                    ' x ',
                                    sma_coinage_transactions.count,
                                    ' = ',
                                    (sma_coinage_transactions.currency_value * sma_coinage_transactions.count)
                                ), NULL ) ORDER BY sma_coinage_transactions.currency_value DESC SEPARATOR '\n' ), '\n\n' ), '' ),

                IF(
                    SUM(LOWER(TRIM(sma_coinage_transactions.currency_type)) IN ('note','notes')) > 0,
                    CONCAT(
                        'Notes:', '\n',
                        GROUP_CONCAT(
                            IF(
                                LOWER(TRIM(sma_coinage_transactions.currency_type)) IN ('note','notes'),
                                CONCAT(
                                    sma_coinage_transactions.currency_value,
                                    ' x ',
                                    sma_coinage_transactions.count,
                                    ' = ',
                                    (sma_coinage_transactions.currency_value * sma_coinage_transactions.count)
                                ), NULL ) ORDER BY sma_coinage_transactions.currency_value DESC SEPARATOR '\n' ),  '\n\n' ), '' ),

                IF(
                    SUM(LOWER(TRIM(sma_coinage_transactions.currency_type)) IN ('coin','coins')) > 0,
                    CONCAT(
                        'Coins:', '\n',
                        GROUP_CONCAT(
                            IF(
                                LOWER(TRIM(sma_coinage_transactions.currency_type)) IN ('coin','coins'),
                                CONCAT(
                                    sma_coinage_transactions.currency_value,
                                    ' x ',
                                    sma_coinage_transactions.count,
                                    ' = ',
                                    (sma_coinage_transactions.currency_value * sma_coinage_transactions.count)
                                ), NULL ) ORDER BY sma_coinage_transactions.currency_value DESC SEPARATOR '\n' ) ), '' ) ) AS denominations,sma_coinage_transactions_master.note", FALSE);
            $this->db->from('sma_coinage_transactions_master');
            $this->db->Join('sma_users', 'sma_users.id = sma_coinage_transactions_master.user_id ', 'LEFT');
            $this->db->Join('sma_warehouses', 'sma_warehouses.id = sma_coinage_transactions_master.location_id ', 'LEFT');
            $this->db->join('sma_coinage_transactions', 'sma_coinage_transactions.master_id = sma_coinage_transactions_master.id', 'LEFT');
            $this->db->join('sma_coinage','sma_coinage.id = sma_coinage_transactions.coinage_id','LEFT');
            $this->db->where('sma_coinage_transactions.count >', 0);
            $this->db->group_by('sma_coinage_transactions_master.id');


            if ($user) {
                $this->db->where('sma_coinage_transactions_master.user_id', $user);
            }
            if ($warehouse) {
                $getwarehouse = str_replace("_", ",", $warehouse);
                $this->db->where('sma_coinage_transactions_master.location_id IN (' . $getwarehouse . ')');
            }
            if (!empty($transaction_type)) {
                // If coming as comma-separated string (from DataTable URL)
                if (is_string($transaction_type)) {
                    $transaction_type = explode(',', $transaction_type);
                }
                // Remove empty values just in case
                $transaction_type = array_filter($transaction_type);
                if (!empty($transaction_type)) {
                    $this->db->where_in('sma_coinage_transactions_master.transaction_type', $transaction_type );
                }
            }
            if (!empty($currency)) {
                // If coming as comma-separated string
                if (is_string($currency)) {
                    $currency = explode(',', $currency);
                }

                // Clean values: remove _Bills, _Coins, _Note
                $currency = array_map(function ($val) {
                    // Remove suffix after underscore
                    $val = explode('_', $val)[0];
                    return trim($val);
                }, $currency);

                // Remove empty values
                $currency = array_filter($currency);

                if (!empty($currency)) {
                    $this->datatables->where_in(
                        'sma_coinage_transactions.currency_value',
                        $currency
                    );
                }
            }
            if ($start_date) {
                $this->db->where('DATE(sma_coinage_transactions_master.datetime) >=', $start_date);
                $this->db->where('DATE(sma_coinage_transactions_master.datetime) <=', $end_date);
            }
            if ($amount_filter && $amount_value) {
                if ($amount_filter == 'greater') {
                    $this->db->where('sma_coinage_transactions_master.amount >', $amount_value);
                } elseif ($amount_filter == 'less') {
                    $this->db->where('sma_coinage_transactions_master.amount <', $amount_value);
                } elseif ($amount_filter == 'between' && $amount_value_to) {
                    $this->db->where('sma_coinage_transactions_master.amount BETWEEN ' . floatval($amount_value) . ' AND ' . floatval($amount_value_to));
                }
            }

            $q = $this->db->get();
            if ($q->num_rows() > 0) {
                foreach (($q->result()) as $row) {
                    $data[] = $row;
                }
            } else {
                $data = NULL;
            }

            if (!empty($data)) {
                $this->load->library('excel');
                $this->excel->setActiveSheetIndex(0);

                $style = array(
                    'alignment' => array('horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER),
                    'font' => array('name' => 'Arial', 'color' => array('rgb' => 'FF0000')),
                    'borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_NONE))
                );

                $this->excel->getActiveSheet()->getStyle("A1:H1")->applyFromArray($style);
                $this->excel->getActiveSheet()->mergeCells('A1:H1');
                $this->excel->getActiveSheet()->SetCellValue('A1', 'Cash Transaction Report');
                $this->excel->getActiveSheet()->setTitle('Cash Transaction Report');

                $this->excel->getActiveSheet()->SetCellValue('A2', lang('date_time'));
                $this->excel->getActiveSheet()->SetCellValue('B2', lang('user'));
                $this->excel->getActiveSheet()->SetCellValue('C2', lang('location'));
                $this->excel->getActiveSheet()->SetCellValue('D2', lang('transaction_type'));
                $this->excel->getActiveSheet()->SetCellValue('E2', lang('amount'));
                $this->excel->getActiveSheet()->SetCellValue('F2', lang('Denominations'));
                $this->excel->getActiveSheet()->SetCellValue('G2', lang('note'));

                $row = 3;
                $total_amount = 0;
                foreach ($data as $data_row) {
                    $clean_note = strip_tags($data_row->note);
                    $this->excel->getActiveSheet()->SetCellValue('A' . $row, $data_row->transaction_date);
                    $this->excel->getActiveSheet()->SetCellValue('B' . $row, $data_row->username . ' ' . $data_row->last_name);
                    $this->excel->getActiveSheet()->SetCellValue('C' . $row, $data_row->location_name);
                    $this->excel->getActiveSheet()->SetCellValue('D' . $row, $data_row->transaction_type);
                    $this->excel->getActiveSheet()->SetCellValue('E' . $row, $this->sma->formatMoney($data_row->amount));
                    $this->excel->getActiveSheet()->SetCellValue('F' . $row, $data_row->denominations);
                    $this->excel->getActiveSheet()->getStyle('F' . $row)->getAlignment()->setWrapText(true);
                    $this->excel->getActiveSheet()->getRowDimension($row)->setRowHeight(-1);
                    $this->excel->getActiveSheet()->getStyle('F' . $row)->getBorders()->getAllBorders()->setBorderStyle(PHPExcel_Style_Border::BORDER_MEDIUM);
                    $this->excel->getActiveSheet()->SetCellValue('G' . $row, html_entity_decode($clean_note));
                    $total_amount += $data_row->amount;
                    $row++;
                }

                $this->excel->getActiveSheet()->getStyle("E" . $row)->getBorders()->getAllBorders()->setBorderStyle(PHPExcel_Style_Border::BORDER_MEDIUM);
                $this->excel->getActiveSheet()->SetCellValue('E' . $row, $this->sma->formatMoney($total_amount));

                $this->excel->getActiveSheet()->getColumnDimension('A')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('B')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('C')->setWidth(20);
                $this->excel->getActiveSheet()->getColumnDimension('D')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('E')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('F')->setWidth(15);
                $this->excel->getActiveSheet()->getColumnDimension('G')->setWidth(30);
                $this->excel->getActiveSheet()->getColumnDimension('H')->setWidth(20);

                $filename = 'cash_transaction_report';
                $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);

                $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);

                if ($pdf) {
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($xls) {
                    ob_clean();
                    header('Content-Type: application/vnd.ms-excel');
                    header('Content-Disposition: attachment;filename="' . $filename . '.xls"');
                    header('Cache-Control: max-age=0');
                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                    $objWriter->save('php://output');
                    exit();
                }
                if ($img) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save(str_replace(__FILE__, 'assets/mdata/'.$this->Customer_assets.'/uploads/pdf/cash_transaction_report.pdf', __FILE__));
                    redirect("reports/create_image/cash_transaction_report.pdf");
                    exit();
                }
            }
            $this->session->set_flashdata('error', lang('nothing_found'));
            redirect($_SERVER["HTTP_REFERER"]);
        }else {

            $this->load->library('datatables');
            $this->load->helper('reports');
            $this->datatables->select(" DATE_FORMAT(sma_coinage_transactions_master.datetime, '%Y-%m-%d %H:%i:%s') AS transaction_date, sma_users.username AS user, sma_warehouses.name AS location_name, sma_coinage_transactions_master.transaction_type, sma_coinage_transactions_master.amount,
            CONCAT(
                IF( SUM(LOWER(TRIM(sma_coinage_transactions.currency_type)) IN ('bill','bills')) > 0,
                    CONCAT(
                        '<b>Bills</b><br>',
                        GROUP_CONCAT(
                            IF(
                                LOWER(TRIM(sma_coinage_transactions.currency_type)) IN ('bill','bills'),
                                CONCAT(
                                    sma_coinage_transactions.currency_value,
                                    ' x ',
                                    sma_coinage_transactions.count,
                                    ' = ',
                                    (sma_coinage_transactions.currency_value * sma_coinage_transactions.count)
                                ),  NULL ) ORDER BY sma_coinage_transactions.currency_value DESC SEPARATOR '<br>' ), '<br><br>' ), '' ),
                IF( SUM(LOWER(TRIM(sma_coinage_transactions.currency_type)) IN ('note','notes')) > 0,
                    CONCAT(
                        '<b>Note</b><br>',
                        GROUP_CONCAT(
                            IF(
                                LOWER(TRIM(sma_coinage_transactions.currency_type)) IN ('note','notes'),
                                CONCAT(
                                    sma_coinage_transactions.currency_value,
                                    ' x ',
                                    sma_coinage_transactions.count,
                                    ' = ',
                                    (sma_coinage_transactions.currency_value * sma_coinage_transactions.count)
                                ),  NULL ) ORDER BY sma_coinage_transactions.currency_value DESC SEPARATOR '<br>' ), '<br><br>' ), '' ),            
                IF( SUM(LOWER(TRIM(sma_coinage_transactions.currency_type)) IN ('coin','coins')) > 0,
                    CONCAT(
                        '<b>Coins</b><br>',
                        GROUP_CONCAT(
                            IF(
                                LOWER(TRIM(sma_coinage_transactions.currency_type)) IN ('coin','coins'),
                                CONCAT(
                                    sma_coinage_transactions.currency_value,
                                    ' x ',
                                    sma_coinage_transactions.count,
                                    ' = ',
                                    (sma_coinage_transactions.currency_value * sma_coinage_transactions.count)
                                ), NULL ) ORDER BY sma_coinage_transactions.currency_value DESC SEPARATOR '<br>') ),  ''  ) ) AS denominations,sma_coinage_transactions_master.note", FALSE);
            $this->datatables->from('sma_coinage_transactions_master');
            $this->datatables->Join('sma_users', 'sma_users.id = sma_coinage_transactions_master.user_id ', 'LEFT');
            $this->datatables->Join('sma_warehouses', 'sma_warehouses.id = sma_coinage_transactions_master.location_id ', 'LEFT');
            $this->datatables->join('sma_coinage_transactions', 'sma_coinage_transactions.master_id = sma_coinage_transactions_master.id', 'LEFT');
            $this->datatables->join('sma_coinage','sma_coinage.id = sma_coinage_transactions.coinage_id','LEFT');
            $this->datatables->where('sma_coinage_transactions.count >', 0);
            $this->datatables->group_by('sma_coinage_transactions_master.id');

            /* USER FILTER */
            if ($this->Owner || $this->Admin) {
                if ($user) {
                    $this->datatables->where('sma_coinage_transactions_master.user_id', $user);
                }
            } else {
                if ($this->session->userdata('view_right') == '0') {
                    if ($user) {
                        $this->datatables->where('sma_coinage_transactions_master.user_id', $user);
                    } else {
                        $this->datatables->where('sma_coinage_transactions_master.user_id', $this->session->userdata('user_id'));
                    }
                }else{
                    if ($user) {
                        $this->datatables->where('sma_coinage_transactions_master.user_id', $user);
                    }
                }
            }

            /* WAREHOUSE FILTER */
            if ($warehouse) {
                $warehouse_list = str_replace("_", ",", $warehouse);
                $this->datatables->where("sma_coinage_transactions_master.location_id IN ($warehouse_list)");
            }

            /* TRANSACTION TYPE */
            // if ($transaction_type) {
            //     $this->datatables->where('sma_coinage_transactions_master.transaction_type', $transaction_type);
            // }
            if (!empty($transaction_type)) {
                // If coming as comma-separated string (from DataTable URL)
                if (is_string($transaction_type)) {
                    $transaction_type = explode(',', $transaction_type);
                }
                // Remove empty values just in case
                $transaction_type = array_filter($transaction_type);
                if (!empty($transaction_type)) {
                    $this->db->where_in('sma_coinage_transactions_master.transaction_type', $transaction_type );
                }
            }
            if (!empty($currency)) {
                if (is_string($currency)) {
                    $currency = explode(',', $currency);
                }
                $currency = array_map(function ($val) {
                    $val = explode('_', $val)[0];
                    return trim($val);
                }, $currency);
                $currency = array_filter($currency);
                if (!empty($currency)) {
                    $this->datatables->where_in(
                        'sma_coinage_transactions.currency_value',
                        $currency
                    );
                }
            }

            /* DATE FILTER */
            if ($start_date) {
                $this->datatables->where('DATE(sma_coinage_transactions_master.datetime) >=', $start_date);
                $this->datatables->where('DATE(sma_coinage_transactions_master.datetime) <=', $end_date);
            }

            /* AMOUNT FILTER */
            if ($amount_filter && $amount_value) {
                if ($amount_filter == 'greater') {
                    $this->datatables->where('sma_coinage_transactions_master.amount >', $amount_value);
                } elseif ($amount_filter == 'less') {
                    $this->datatables->where('sma_coinage_transactions_master.amount <', $amount_value);
                } elseif ($amount_filter == 'between' && $amount_value_to) {
                    $this->datatables->where(
                        "sma_coinage_transactions_master.amount BETWEEN " . floatval($amount_value) . " AND " . floatval($amount_value_to),
                        NULL,
                        FALSE
                    );
                }
            }
            echo $this->datatables->generate();
        }
    }

    public function customer_ledger_v1()
    {
        // $this->sma->checkPermissions();

        // 1️⃣ FIRST load customers
        $this->data['customers'] = $this->reports_model->getCustomerCompanies();

        // 2️⃣ THEN find selected customer
        $selected_customer = null;
        if (!empty($_POST['customer'])) {
            foreach ($this->data['customers'] as $c) {
                if ($c->id == $_POST['customer']) {
                    $selected_customer = $c;
                    break;
                }
            }
        }
        $this->data['selected_customer'] = $selected_customer;

        // 3️⃣ Load CF labels
        $this->data['cf_labels'] = $this->reports_model->getCustomerCustomFieldLabels();

        $this->data['biller'] = $this->site->getCompanyByID($this->pos_settings->default_biller);

        $meta = [
            'page_title' => lang('Customer_Ledgers'),
            'bc' => $bc
        ];

        $this->page_construct('reports/customer_ledger_v1', $meta, $this->data);
    }

    /**
     * Get Customer Ledger
     */
    public function getCustomerLedgerV1($pdf = NULL, $xls = NULL, $img = NULL) {

        // error_reporting(E_ALL);
        // ini_set('display_errors', 1);
        
        $search = trim($this->input->post('sSearch'));
    
        $export = isset($_GET['export']) ? $_GET['export'] : null;
        $pdf = ($export === 'pdf');
        $xls = ($export === 'xls');
        $img = ($export === 'img');

        // $this->sma->checkPermissions('products', TRUE);
        $customer_id = isset($_REQUEST['customer']) ? $_REQUEST['customer'] : NULL;
        $start_date  = isset($_REQUEST['start_date']) ? $_REQUEST['start_date'] : NULL;
        $end_date    = isset($_REQUEST['end_date']) ? $_REQUEST['end_date'] : NULL;

        $startDate = NULL;
        $enddate   = NULL;

        if ($start_date) {
            $startDate = trim($this->sma->fld($start_date));
            $enddate   = trim($end_date ? $this->sma->fld($end_date) : date('Y-m-d'));
        }
       

        // $transactionData = $this->reports_model->getCustomerLedger($customer_id, $startDate, $enddate);
        $transactionData = $this->reports_model->getCustomerLedgerV1($customer_id, $startDate, $enddate);
        if ($search !== '') {

            $search = strtolower($search);
            $transactionData = array_filter($transactionData, function ($row) use ($search) {
                // Build voucher text exactly as UI
                $voucher = '';
                if (isset($row['source_table']) && $row['source_table'] === 'sma_deposits') {
                    if (isset($row['paid_by']) && $row['paid_by'] === 'supercash') {
                        $voucher = 'SC/' . (isset($row['deposit_id']) ? $row['deposit_id'] : '');
                    } else {
                        $voucher = isset($row['deposit_id']) ? (string) $row['deposit_id'] : '';
                    }
                } else {
                    $voucher = 'Invoice No. ' . (isset($row['invoice_no']) ? $row['invoice_no'] : '');
                    if (isset($row['sale_status']) && $row['sale_status'] === 'returned') {
                        $voucher .= ' (Returned)';
                    }

                }
                
                // Build particulars text exactly as UI
                $particulars = '';
                if (isset($row['wallet_desc'])) {
                    switch ($row['wallet_desc']) {
                        case 'Amount Paid':
                            $particulars = 'debited against invoice';
                            break;
                        case 'Add Amount':
                            $particulars = 'deposit recharged';
                            break;
                        case 'Supercash received':
                        case 'Super Cash Added':
                            $particulars = 'supercash received';
                            break;
                        default:
                            $particulars = 'credited against sale return';
                            break;
                    }
                }
                
                // Search in all relevant fields
                $dateStr = isset($row['date']) ? strtolower($row['date']) : '';
                $voucherStr = strtolower($voucher);
                $particularsStr = $particulars;
                $walletDescStr = isset($row['wallet_desc']) ? strtolower($row['wallet_desc']) : '';
                
                return (
                    strpos($dateStr, $search) !== false ||
                    strpos($voucherStr, $search) !== false ||
                    strpos($particularsStr, $search) !== false ||
                    strpos($walletDescStr, $search) !== false
                );
            });
            // reindex array
            $transactionData = array_values($transactionData);
        }

        /**
         * Server-side sorting: Read DataTables sort parameters
         * If user clicks column header, sort by that column
         * Default: Date DESC (latest first) with full datetime (HH:mm:ss)
         */
        $sortingCols = intval($this->input->post('iSortingCols'));
        $sortColumn = -1;
        $sortDir = 'desc';
        
        // Check if DataTables sent sort parameters
        if ($sortingCols > 0) {
            $sortColumn = intval($this->input->post('iSortCol_0'));
            $sortDir = $this->input->post('sSortDir_0');
            $sortDir = ($sortDir === 'asc') ? 'asc' : 'desc';
        }
        
        // If no sort column specified or invalid, default to Date DESC
        if ($sortColumn < 0 || $sortColumn > 6) {
            $sortColumn = 0;
            $sortDir = 'asc';
        }
        // FORCE date-wise ascending order (ledger requirement)
        // $sortColumn = 0; // Date column
        // $sortDir    = 'asc';

        if (!empty($transactionData)) {
            usort($transactionData, function ($a, $b) use ($sortColumn, $sortDir) {
                $result = 0;
                
                switch ($sortColumn) {
                    case 0: // Date - Sort by full datetime (YYYY-MM-DD HH:ii:ss)
                        // Convert to timestamp for proper datetime comparison including time
                        $dateA = isset($a['date']) ? $a['date'] : '';
                        $dateB = isset($b['date']) ? $b['date'] : '';
                        $timeA = $dateA ? strtotime($dateA) : 0;
                        $timeB = $dateB ? strtotime($dateB) : 0;
                        if ($timeA == $timeB) {
                            $result = 0;
                        } else {
                            $result = ($timeA < $timeB) ? -1 : 1;
                        }
                        break;
                    
                    case 1: // Voucher No - String sort
                        $voucherA = (isset($a['source_table']) && $a['source_table'] === 'sma_deposits') 
                            ? ((isset($a['paid_by']) && $a['paid_by'] === 'supercash') ? 'SC/' . (isset($a['deposit_id']) ? $a['deposit_id'] : '') : (isset($a['deposit_id']) ? $a['deposit_id'] : ''))
                            : 'Invoice No. ' . (isset($a['invoice_no']) ? $a['invoice_no'] : '');
                        $voucherB = (isset($b['source_table']) && $b['source_table'] === 'sma_deposits') 
                            ? ((isset($b['paid_by']) && $b['paid_by'] === 'supercash') ? 'SC/' . (isset($b['deposit_id']) ? $b['deposit_id'] : '') : (isset($b['deposit_id']) ? $b['deposit_id'] : ''))
                            : 'Invoice No. ' . (isset($b['invoice_no']) ? $b['invoice_no'] : '');
                        $result = strcmp($voucherA, $voucherB);
                        break;
                    
                    case 2: // Particulars - String sort
                        $walletA = isset($a['wallet_desc']) ? $a['wallet_desc'] : '';
                        $walletB = isset($b['wallet_desc']) ? $b['wallet_desc'] : '';
                        $result = strcmp($walletA, $walletB);
                        break;
                    
                    case 3: // Opening Balance - Numeric sort
                        $openA = isset($a['opening_balance']) ? floatval($a['opening_balance']) : 0;
                        $openB = isset($b['opening_balance']) ? floatval($b['opening_balance']) : 0;
                        if ($openA == $openB) {
                            $result = 0;
                        } else {
                            $result = ($openA < $openB) ? -1 : 1;
                        }
                        break;
                    
                    case 4: // Debit - Numeric sort (calculate first)
                        $debitA = 0;
                        $debitB = 0;
                        if (isset($a['paid_by']) && $a['paid_by'] && isset($a['invoice_no']) && $a['invoice_no'] && in_array($a['paid_by'], ['deposit', 'supercash']) && isset($a['sale_status']) && $a['sale_status'] !== 'returned' && isset($a['grand_total'])) {
                            $debitA = abs($a['grand_total']);
                        }
                        if (isset($b['paid_by']) && $b['paid_by'] && isset($b['invoice_no']) && $b['invoice_no'] && in_array($b['paid_by'], ['deposit', 'supercash']) && isset($b['sale_status']) && $b['sale_status'] !== 'returned' && isset($b['grand_total'])) {
                            $debitB = abs($b['grand_total']);
                        }
                        if ($debitA == $debitB) {
                            $result = 0;
                        } else {
                            $result = ($debitA < $debitB) ? -1 : 1;
                        }
                        break;
                    
                    case 5: // Credit - Numeric sort (calculate first)
                        $creditA = 0;
                        $creditB = 0;
                        if (isset($a['paid_by']) && $a['paid_by']) {
                            if (isset($a['invoice_no']) && $a['invoice_no'] && isset($a['paid_by']) && in_array($a['paid_by'], ['deposit', 'supercash']) && isset($a['sale_status']) && $a['sale_status'] === 'returned' && isset($a['grand_total'])) {
                                $creditA = abs($a['grand_total']);
                            } else {
                                $creditA = (isset($a['super_cash']) && !empty($a['super_cash']) && $a['super_cash'] > 0 && isset($a['amount'])) 
                                    ? ($a['amount'] - $a['super_cash']) 
                                    : (isset($a['amount']) ? $a['amount'] : 0);
                            }
                        }
                        if (isset($b['paid_by']) && $b['paid_by']) {
                            if (isset($b['invoice_no']) && $b['invoice_no'] && isset($b['paid_by']) && in_array($b['paid_by'], ['deposit', 'supercash']) && isset($b['sale_status']) && $b['sale_status'] === 'returned' && isset($b['grand_total'])) {
                                $creditB = abs($b['grand_total']);
                            } else {
                                $creditB = (isset($b['super_cash']) && !empty($b['super_cash']) && $b['super_cash'] > 0 && isset($b['amount'])) 
                                    ? ($b['amount'] - $b['super_cash']) 
                                    : (isset($b['amount']) ? $b['amount'] : 0);
                            }
                        }
                        if ($creditA == $creditB) {
                            $result = 0;
                        } else {
                            $result = ($creditA < $creditB) ? -1 : 1;
                        }
                        break;
                    
                    case 6: // Balance - Numeric sort
                        $closeA = isset($a['closing_balance']) ? floatval($a['closing_balance']) : 0;
                        $closeB = isset($b['closing_balance']) ? floatval($b['closing_balance']) : 0;
                        if ($closeA == $closeB) {
                            $result = 0;
                        } else {
                            $result = ($closeA < $closeB) ? -1 : 1;
                        }
                        break;
                    
                    default: // Default: Date DESC (latest first) with full datetime
                        $dateA = isset($a['date']) ? $a['date'] : '';
                        $dateB = isset($b['date']) ? $b['date'] : '';
                        $timeA = $dateA ? strtotime($dateA) : 0;
                        $timeB = $dateB ? strtotime($dateB) : 0;
                        if ($timeA == $timeB) {
                            $result = 0;
                        } else {
                            $result = ($timeA < $timeB) ? 1 : -1; // DESC
                        }
                        break;
                }
                
                // Apply sort direction
                return ($sortDir === 'asc') ? $result : -$result;
            });
        }

        if ($pdf || $xls || $img) {
            $sortColumn = 0; // Date column
            $sortDir    = 'asc';
            if (empty($transactionData)) {
                $this->session->set_flashdata('error', lang('nothing_found'));
                redirect($_SERVER["HTTP_REFERER"]);
            }

            $this->load->library('excel');
            $this->excel->setActiveSheetIndex(0);
            $sheet = $this->excel->getActiveSheet();

            /* ================= STYLES ================= */
            $headerStyle = [
                'font' => ['bold' => true, 'color' => ['rgb' => 'FF0000']],
                'alignment' => ['horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER],
                'borders' => ['allborders' => ['style' => PHPExcel_Style_Border::BORDER_THIN]]
            ];

            $leftStyle = [
                'alignment' => ['horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_LEFT],
                'borders' => ['allborders' => ['style' => PHPExcel_Style_Border::BORDER_THIN]]
            ];

            $rightStyle = [
                'alignment' => ['horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_RIGHT],
                'borders' => ['allborders' => ['style' => PHPExcel_Style_Border::BORDER_THIN]]
            ];

            /* ================= HEADER ================= */
            $site_name = $this->Settings->site_name;
            
            $sheet->mergeCells('A1:G1');
            $sheet->setCellValue('A1', $site_name);
            $sheet->getStyle('A1')->applyFromArray($headerStyle);
            
            $report_title = 'Customer Ledgers';
            if (!empty($customer_id)) {
                $customer_details = $this->reports_model->getCustomerName($customer_id);
                if ($customer_details) {
                    $report_title .= ' - ' . $customer_details->name;
                }
            }
            if (!empty($_REQUEST['start_date'])) {
                $report_title .= ' (' . $_REQUEST['start_date'] . ' To ' . $_REQUEST['end_date'] . ')';
            }
            $sheet->mergeCells('A2:G2');
            $sheet->setCellValue('A2', $report_title);
            $sheet->getStyle('A2')->applyFromArray($headerStyle);

            $headers = [
                'Date',
                'Voucher No',
                'Particulars',
                'Opening Balance',
                'Debit',
                'Credit',
                'Balance'
            ];

            $col = 'A';
            $row = 3;
            foreach ($headers as $h) {
                $sheet->setCellValue($col.$row, $h);
                $col++;
            }
            $sheet->getStyle('A3:G3')->applyFromArray($headerStyle);
            $row++;

            /* ================= DATA ================= */
            $TotalDebit  = 0;
            $TotalCredit = 0;

            foreach ($transactionData as $rowdata) {

                /* ---- SAME DEBIT / CREDIT LOGIC ---- */
                $dabit  = 0;
                $credit = 0;

                if ($rowdata['paid_by']) {

                    if ($rowdata['invoice_no'] && in_array($rowdata['paid_by'], ['deposit','supercash'])) {

                        if ($rowdata['sale_status'] === 'returned') {
                            $credit = abs($rowdata['grand_total']);
                            $TotalCredit += $credit;
                        } else {
                            $dabit = abs($rowdata['grand_total']);
                            $TotalDebit += $dabit;
                        }

                    } else {

                        if (!empty($rowdata['super_cash']) && $rowdata['super_cash'] > 0) {
                            $credit = $rowdata['amount'] - $rowdata['super_cash'];
                        } else {
                            $credit = $rowdata['amount'];
                        }
                        $TotalCredit += $credit;
                    }
                }

                /* ---- VOUCHER ---- */
                if ($rowdata['source_table'] === 'sma_deposits') {
                    $voucher = ($rowdata['paid_by'] === 'supercash')
                        ? 'SC/' . $rowdata['deposit_id']
                        : $rowdata['deposit_id'];
                } else {
                    $voucher = 'Invoice No. ' . $rowdata['invoice_no'];
                    if ($rowdata['sale_status'] === 'returned') {
                        $voucher .= ' (Returned)';
                    }
                }

                /* ---- PARTICULARS ---- */
                if ($rowdata['source_table'] === 'sma_deposits') {

                    if ($rowdata['paid_by'] === 'supercash') {
                        $particulars = 'Supercash received';
                    } else {
                        $particulars = 'Deposit recharged';
                    }

                } else {

                    if ($rowdata['sale_status'] === 'returned') {
                        $particulars = 'Credited against sale return';
                    } else {
                        $particulars = 'Debited against invoice';
                    }
                }

                /* ---- WRITE ROW ---- */
                $sheet->setCellValue('A'.$row, $rowdata['date']);
                $sheet->setCellValue('B'.$row, $voucher);
                $sheet->setCellValue('C'.$row, $particulars);
                $sheet->setCellValue('D'.$row, $this->sma->formatMoney($rowdata['opening_balance']));
                $sheet->setCellValue('E'.$row, $this->sma->formatMoney($dabit));
                $sheet->setCellValue('F'.$row, $this->sma->formatMoney($credit));
                $sheet->setCellValue('G'.$row, $this->sma->formatMoney($rowdata['closing_balance']));

                $sheet->getStyle('A'.$row.':C'.$row)->applyFromArray($leftStyle);
                $sheet->getStyle('D'.$row.':G'.$row)->applyFromArray($rightStyle);

                $row++;
            }

            /* ================= TOTAL ROW ================= */
            // $sheet->mergeCells('A'.$row.':D'.$row);
            // $sheet->setCellValue('A'.$row, 'Total');
            // $sheet->setCellValue('E'.$row, $this->sma->formatMoney($TotalDebit));
            // $sheet->setCellValue('F'.$row, $this->sma->formatMoney($TotalCredit));

            // $sheet->getStyle('A'.$row.':G'.$row)->getFont()->setBold(true);
            // $sheet->getStyle('A'.$row.':G'.$row)->applyFromArray($rightStyle);

            /* ================= WIDTH ================= */
            foreach (['A'=>18,'B'=>22,'C'=>35,'D'=>18,'E'=>15,'F'=>15,'G'=>18] as $c=>$w) {
                $sheet->getColumnDimension($c)->setWidth($w);
            }

            /* ================= EXPORT ================= */
            $filename = 'customer_ledger_v1';

            if ($xls) {
                ob_clean();
                header('Content-Type: application/vnd.ms-excel');
                header('Content-Disposition: attachment;filename="'.$filename.'.xls"');
                header('Cache-Control: max-age=0');
                PHPExcel_IOFactory::createWriter($this->excel, 'Excel5')->save('php://output');
                exit;
            }

            if ($pdf) {
                $sheet->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                require_once(APPPATH.'third_party/MPDF/mpdf.php');
                PHPExcel_Settings::setPdfRenderer(
                    PHPExcel_Settings::PDF_RENDERER_MPDF,
                    APPPATH.'third_party/MPDF'
                );
                header('Content-Type: application/pdf');
                header('Content-Disposition: attachment;filename="'.$filename.'.pdf"');
                header('Cache-Control: max-age=0');
                PHPExcel_IOFactory::createWriter($this->excel, 'PDF')->save('php://output');
                exit;
            }
        }else{
                
            $start  = intval($this->input->post('iDisplayStart'));
            $length = intval($this->input->post('iDisplayLength'));
            $secho  = intval($this->input->post('sEcho'));

            $recordsTotal    = count($transactionData);
            // echo "<pre>";
            // print_r($recordsTotal);
            $recordsFiltered = $recordsTotal;

            if ($length == -1) {
                // Show all records – DO NOT slice
                $pagedData = $transactionData;
            } else {
                $pagedData = array_slice($transactionData, $start, $length);
            }

            $data = [];

            foreach ($pagedData as $rowdata) {

                /* ------------------ DEBIT / CREDIT (EXACT SAME LOGIC) ------------------ */
                $dabit  = 0;
                $credit = 0;

                if ($rowdata['paid_by']) {

                    if ($rowdata['invoice_no'] && in_array($rowdata['paid_by'], ['deposit', 'supercash'])) {

                        if ($rowdata['sale_status'] === 'returned') {
                            $credit = abs($rowdata['grand_total']);
                        } else {
                            $dabit = abs($rowdata['grand_total']);
                        }

                    } else {

                        if (!empty($rowdata['super_cash']) && $rowdata['super_cash'] > 0) {
                            $credit = $rowdata['amount'] - $rowdata['super_cash'];
                        } else {
                            $credit = $rowdata['amount'];
                        }
                    }
                }

                /* ------------------ VOUCHER NO (UNCHANGED) ------------------ */
                if ($rowdata['source_table'] === 'sma_deposits') {

                    if ($rowdata['paid_by'] === 'supercash') {
                        $voucher = 'SC/' . $rowdata['deposit_id'];
                    } else {
                        $voucher = $rowdata['deposit_id'];
                    }

                } else {

                    $voucher = 'Invoice No. ' . $rowdata['invoice_no'];
                    if ($rowdata['sale_status'] === 'returned') {
                        $voucher .= ' (Returned)';
                    }
                }

                /* ------------------ PARTICULARS (UNCHANGED) ------------------ */
                if ($rowdata['source_table'] === 'sma_deposits') {

                    if ($rowdata['paid_by'] === 'supercash') {
                        $particulars = 'Supercash received';
                    } else {
                        $particulars = 'Deposit recharged';
                    }

                } else {

                    if ($rowdata['sale_status'] === 'returned') {
                        $particulars = 'Credited against sale return';
                    } else {
                        $particulars = 'Debited against invoice';
                    }
                }

                /* ------------------ PUSH ROW (ORDER MATCHES UI) ------------------ */
                $data[] = [
                    $rowdata['date'],
                    $voucher,
                    $particulars,
                    $this->sma->formatMoney($rowdata['opening_balance']),
                    $this->sma->formatMoney($dabit),
                    $this->sma->formatMoney($credit),
                    $this->sma->formatMoney($rowdata['closing_balance'], 2)
                ];
            }
            $secho = intval($this->input->post('sEcho'));
            echo json_encode([
                "sEcho"                => $secho,
                "iTotalRecords"        => $recordsTotal,
                "iTotalDisplayRecords" => $recordsTotal,
                "aaData"               => $data
            ]);
            exit;

            }
    }  
