    /**
     * ============================================================================
     * GET SELECTED PRODUCTS DATA FOR PURCHASE ORDER CREATION
     * ============================================================================
     * 
     * PURPOSE:
     * This method processes selected products from quantity alerts report and
     * formats them into purchase order items ready for the purchase order form.
     * 
     * BUSINESS LOGIC FLOW:
     * 1. Receive selected items array with product_id and variant_id
     * 2. For each item, fetch product details from database
     * 3. Check if product has variants (group_id = 1)
     * 4. If variant selected: Add only that specific variant to PO
     * 5. If no variant: Add product as single item (if product has no variants)
     * 6. Format item with all required PO fields (cost, tax, units, etc.)
     * 7. Return formatted items array for purchase order form
     * 
     * KEY BUSINESS RULES:
     * - Products WITH variants: Only selected variant is added (not all variants)
     * - Products WITHOUT variants: Product added as single item
     * - Each item gets default quantity of 1 (user can change in PO form)
     * - Cost comes from product cost or variant-specific cost
     * - Tax rates inherited from product settings
     * - Batch tracking handled if enabled in settings
     * 
     * INPUT:
     * - items: JSON array of {product_id, variant_id} objects
     * - supplier_id: Selected supplier ID
     * 
     * OUTPUT:
     * - JSON response with status and formatted items array
     * ============================================================================
     */
    function getSelectedProductsData() {
        // Check user permissions for quantity alerts
        $this->sma->checkPermissions('quantity_alerts', TRUE);
        
        // ========================================================================
        // STEP 1: RECEIVE AND VALIDATE INPUT DATA
        // ========================================================================
        // Business Logic: Decode JSON items array from frontend
        // Expected format: [{"product_id": 123, "variant_id": 45}, ...]
        $items = json_decode($this->input->post('items', TRUE), TRUE);
        $supplier_id = $this->input->post('supplier_id', TRUE);
        // Validation: Ensure we have items and supplier_id
        if (empty($items) || !$supplier_id) {
            $this->sma->send_json(array('status' => 'error', 'message' => lang('invalid_request')));
            return;
        }
        
        // Load required models for product and purchase operations
        $this->load->model('purchases_model');
        $this->load->model('products_model');
        
        // Initialize array to store formatted purchase order items
        $poitems = array();
        
        // ========================================================================
        // STEP 2: PROCESS EACH SELECTED ITEM
        // ========================================================================
        // Business Logic: Loop through each selected product/variant combination
        foreach ($items as $item) {
            // Extract product_id and variant_id from item
            $product_id = isset($item['product_id']) ? intval($item['product_id']) : 0;
            $selected_variant_id = isset($item['variant_id']) ? intval($item['variant_id']) : 0;
            $qty = isset($item['qty']) ? intval($item['qty']) : 0;
            
            // Skip if product_id is invalid
            if (!$product_id) {
                continue;
            }
            
            // ========================================================================
            // STEP 3: FETCH PRODUCT DATA FROM DATABASE
            // ========================================================================
            // Business Logic: Get complete product information including:
            // - Product details (name, code, cost, price, etc.)
            // - Product variants (group_id = 1 for size/variant, group_id = 2 for color)
            // - Product settings (tax, units, batch tracking, etc.)
            $row = $this->purchases_model->getProductByID($product_id);
            if (!$row) {
                // Product not found, skip to next item
                continue;
            }
            
            // Get product object (duplicate call for consistency with existing code)
            $product = $this->purchases_model->getProductByID($product_id);
            
            // Get primary variants (group_id = 1) - e.g., Size variants (S, M, L, XL)
            // Business Rule: Only variants with group_id = 1 are used for purchase orders
            $options = $this->purchases_model->getProductOptionsBygroupId($product_id, 1);
            
            // Get color variants (group_id = 2) - e.g., Color variants (Red, Blue, Green)
            // Business Rule: Color variants are secondary and used for display/labeling
            $options_color = $this->purchases_model->getProductOptionsBygroupId($product_id, 2);
            
            // ========================================================================
            // STEP 4: HANDLE PRODUCTS WITH VARIANTS
            // ========================================================================
            // Business Logic: Products can have variants (e.g., T-Shirt in sizes S, M, L)
            // When user selects "T-Shirt - S", only that variant should be added to PO
            // NOT all variants of the product
            if ($options && count($options) > 0) {
                
                // ====================================================================
                // STEP 4a: VALIDATE VARIANT SELECTION
                // ====================================================================
                // Business Rule: Products with variants REQUIRE a variant_id to be selected
                // User must select a specific variant row (e.g., "T-Shirt - S"), not just the product
                if ($selected_variant_id > 0) {
                    
                    // ================================================================
                    // STEP 4b: FIND THE SELECTED VARIANT
                    // ================================================================
                    // Business Logic: Search through all variants to find the one that matches
                    // the selected variant_id from the frontend
                    $selected_variant = null;
                    foreach ($options as $variant) {
                        if ($variant->id == $selected_variant_id) {
                            $selected_variant = $variant;
                            break;
                        }
                    }
                    
                    // ================================================================
                    // STEP 4c: PROCESS SELECTED VARIANT
                    // ================================================================
                    // Business Logic: If variant found, prepare it for purchase order
                    // If not found, skip this item (variant may have been deleted)
                    if ($selected_variant) {
                        $option_id = $selected_variant->id;
                        $opt = $selected_variant;
                    } else {
                        // Selected variant not found, skip this item
                        continue;
                    }
                } else {
                    // ================================================================
                    // BUSINESS RULE: Products with variants require variant selection
                    // ================================================================
                    // If product has variants but no variant_id was provided,
                    // skip this item (user must select a specific variant row)
                    continue;
                }
                
                // ====================================================================
                // STEP 5: BUILD PURCHASE ORDER ITEM FOR VARIANT PRODUCT
                // ====================================================================
                // Business Logic: Create a complete purchase order item with all required fields
                if (isset($option_id) && isset($opt)) {
                    
                    // ================================================================
                    // STEP 5a: GET COLOR VARIANT (SECONDARY VARIANT)
                    // ================================================================
                    // Business Logic: Products can have color variants (group_id = 2)
                    // Use first available color if exists, otherwise set to empty
                    // This is for display/labeling purposes only
                    if (!empty($options_color)) {
                        $opt_color = $options_color[0];
                        $option_color_id = $opt_color->id;
                        $option_color_name = $opt_color->name;
                    } else {
                        $opt_color = json_decode('{}');
                        $option_color_id = 0;
                        $option_color_name = '';
                    }
                    
                    // ================================================================
                    // STEP 5b: CLONE PRODUCT DATA FOR VARIANT
                    // ================================================================
                    // Business Logic: Create a copy of product data to modify for variant
                    // This preserves original product data while allowing variant-specific changes
                    $variant_row = clone $row;
                    
                    // ================================================================
                    // STEP 5c: CONFIGURE BATCH TRACKING (IF ENABLED)
                    // ================================================================
                    // Business Logic: If batch tracking is enabled in settings,
                    // fetch batch information for this variant
                    // Batch tracking is used for expiry dates and batch numbers
                    $batchoption = $productbatches = false;
                    $variant_row->batch = false;
                    $variant_row->batch_number = '';
                    $variant_row->cost = $variant_row->cost;
                    $variant_row->real_unit_cost = $variant_row->cost;
                    $variant_row->base_unit_cost = $variant_row->cost;
                    $variant_row->expiry = '';
                    
                    if ($this->Settings->product_batch_setting) {
                        // Get batch option based on variant and storage type
                        $batch_option = ($option_id && $product->storage_type == 'packed') ? $option_id : 0;
                        $productbatches = $this->products_model->getProductVariantsBatch($product_id);
                        
                        // If batches exist for this variant, use first batch
                        if (isset($productbatches[$batch_option]) && !empty($productbatches[$batch_option])) {
                            $batch = $productbatches[$batch_option];
                            $firstKey = key($batch);
                            $batchoption = $batch;
                            $variant_row->batch = $batchoption[$firstKey]->id;
                            $variant_row->batch_number = $batchoption[$firstKey]->batch_no;
                            $variant_row->cost = $batchoption[$firstKey]->cost;
                            $variant_row->real_unit_cost = $batchoption[$firstKey]->cost;
                            $variant_row->base_unit_cost = $batchoption[$firstKey]->cost;
                            $variant_row->expiry = ($batchoption[$firstKey]->expiry != '' && $batchoption[$firstKey]->expiry !== '0000-00-00') ? $batchoption[$firstKey]->expiry : '';
                        }
                    }
                    
                    // ================================================================
                    // STEP 5d: SET VARIANT-SPECIFIC PROPERTIES
                    // ================================================================
                    // Business Logic: Set variant information on the row object
                    // These properties identify which variant this item represents
                    $variant_row->option = $option_id;                    // Primary variant ID (size)
                    $variant_row->option_color = $option_color_id;         // Secondary variant ID (color)
                    $variant_row->option_color_name = $option_color_name;  // Color name for display
                    $variant_row->supplier_part_no = '';                  // Supplier part number (empty by default)
                    $variant_row->item_tax_method = $variant_row->tax_method; // Tax calculation method
                    
                    // ================================================================
                    // STEP 5e: APPLY VARIANT-SPECIFIC COST
                    // ================================================================
                    // Business Logic: Variants can have their own cost different from product base cost
                    // If variant has a cost set, use it; otherwise use product base cost
                    if (isset($opt->cost) && $opt->cost != 0) {
                        $variant_row->cost = $opt->cost;
                        $variant_row->base_unit_cost = $opt->cost;
                        $variant_row->real_unit_cost = $opt->cost;
                    }
                    
                    // ================================================================
                    // STEP 5f: CONFIGURE UNIT AND QUANTITY INFORMATION
                    // ================================================================
                    // Business Logic: Set up unit conversions and default quantities
                    // Purchase orders support unit conversions (e.g., Box to Pieces)
                    $unitData = $this->purchases_model->getUnitById($variant_row->unit);
                    $variant_row->unit_lable = $unitData->name;                    // Unit label for display
                    $variant_row->base_quantity = 1;                               // Base quantity (default: 1)
                    $variant_row->base_unit = $variant_row->unit;                  // Base unit ID
                    $variant_row->unit = $variant_row->purchase_unit ? $variant_row->purchase_unit : $variant_row->unit; // Purchase unit (if different from base)
                    $variant_row->new_entry = 1;                                  // Flag: new entry (not from existing PO)
                    $variant_row->qty = 1;                                        // Default quantity: 1 (user can change in PO form)
                    $variant_row->oqty = 1;                                       // Original quantity: 1
                    $variant_row->received = 0;                                   // Received quantity: 0 (not received yet)
                    $variant_row->real_unit_cost = $variant_row->cost;            // Real unit cost
                    $variant_row->quantity_balance = '';                           // Quantity balance (empty for new items)
                    $variant_row->discount = '0';                                  // Discount: 0 (user can add in PO form)
                    $variant_row->image = $product->image;                         // Product image
                    
                    // ================================================================
                    // STEP 5g: REMOVE UNNECESSARY FIELDS
                    // ================================================================
                    // Business Logic: Remove fields not needed for purchase order items
                    // This keeps the data structure clean and reduces payload size
                    unset($variant_row->details, $variant_row->product_details, $variant_row->price, $variant_row->file, 
                          $variant_row->supplier1price, $variant_row->supplier2price, $variant_row->supplier3price, 
                          $variant_row->supplier4price, $variant_row->supplier5price, 
                          $variant_row->supplier1_part_no, $variant_row->supplier2_part_no, $variant_row->supplier3_part_no, 
                          $variant_row->supplier4_part_no, $variant_row->supplier5_part_no);
                    
                    // ================================================================
                    // STEP 5h: GET TAX AND UNIT INFORMATION
                    // ================================================================
                    // Business Logic: Fetch tax rate and unit conversion data
                    // These are needed for purchase order calculations
                    $units = $this->site->getUnitsByBUID($variant_row->base_unit); // Unit conversion data
                    $tax_rate = $this->site->getTaxRateByID($variant_row->tax_rate); // Tax rate object
                    
                    // ================================================================
                    // STEP 5i: CREATE UNIQUE ITEM IDENTIFIER
                    // ================================================================
                    // Business Logic: Create unique ID for this item in purchase order
                    // Format: product_id + variant_id (e.g., "12345" for product 123, variant 45)
                    $row_id = $variant_row->id . $option_id;
                    
                    // Build display label: "Product Name Variant Name Color (CODE)"
                    $color = (!empty($options_color)) ? $options_color[0]->name : '';
                    $label = $variant_row->name . ' ' . $opt->name . ' ' . $color . " (" . $variant_row->code . ")";
                    
                    // Generate unique timestamp-based ID for this item instance
                    $c = str_replace(".", "", microtime(true));
                    
                    // Ensure batchs is an array or false (not null) for JSON encoding
                    if ($batchoption === false || $batchoption === null) {
                        $batchoption = false;
                    }
                    
                    // ================================================================
                    // STEP 5j: BUILD FINAL ITEM DATA ARRAY
                    // ================================================================
                    // Business Logic: Create complete item data structure for purchase order
                    // This structure matches what the purchase order form expects
                    $item_data = array(
                        'id' => $c,                                    // Unique item instance ID
                        'item_id' => $row_id,                          // Item identifier (product_id + variant_id)
                        'image' => $product->image,                     // Product image URL
                        'label' => $label,                              // Display label for item
                        'row' => $variant_row,                          // Complete product/variant data object
                        'tax_rate' => $tax_rate,                        // Tax rate information
                        'units' => $units,                             // Unit conversion data
                        'options' => $options ? $options : false,      // All available variants (for dropdown in PO form)
                        'option_batches' => $productbatches ? $productbatches : false, // Batch options if available
                        'batchs' => $batchoption,                      // Selected batch information
                        'primary_variant' => $product->primary_variant, // Primary variant ID
                        'options_color' => $options_color ? $options_color : false // Color variants
                    );
                    
                    // Add item to purchase order items array
                    // Key: row_id ensures unique items (same product+variant won't duplicate)
                    $poitems[$row_id] = $item_data;
                }
            } else {
                // ====================================================================
                // STEP 6: HANDLE PRODUCTS WITHOUT VARIANTS
                // ====================================================================
                // Business Logic: Products without variants are added as single items
                // No variant selection needed - product is added directly
                $option_id = 0;
                $opt = json_decode('{}');
                $opt->cost = 0;
                
                // Get color options
                if (!empty($options_color)) {
                    $opt_color = $options_color[0];
                    $option_color_id = $opt_color->id;
                    $option_color_name = $opt_color->name;
                } else {
                    $opt_color = json_decode('{}');
                    $option_color_id = 0;
                    $option_color_name = '';
                }
                
                // Batch configuration
                $batchoption = $productbatches = false;
                $row->batch = false;
                $row->batch_number = '';
                $row->cost = $row->cost;
                $row->real_unit_cost = $row->cost;
                $row->base_unit_cost = $row->cost;
                $row->expiry = '';
                
                if ($this->Settings->product_batch_setting) {
                    $batch_option = ($option_id && $product->storage_type == 'packed') ? $option_id : 0;
                    $productbatches = $this->products_model->getProductVariantsBatch($product_id);
                    if (isset($productbatches[$batch_option]) && !empty($productbatches[$batch_option])) {
                        $batch = $productbatches[$batch_option];
                        $firstKey = key($batch);
                        $batchoption = $batch;
                        $row->batch = $batchoption[$firstKey]->id;
                        $row->batch_number = $batchoption[$firstKey]->batch_no;
                        $row->cost = $batchoption[$firstKey]->cost;
                        $row->real_unit_cost = $batchoption[$firstKey]->cost;
                        $row->base_unit_cost = $batchoption[$firstKey]->cost;
                        $row->expiry = ($batchoption[$firstKey]->expiry != '' && $batchoption[$firstKey]->expiry !== '0000-00-00') ? $batchoption[$firstKey]->expiry : '';
                    }
                }
                
                // Set product properties
                $row->option = $option_id;
                $row->option_color = $option_color_id;
                $row->option_color_name = $option_color_name;
                $row->supplier_part_no = '';
                $row->item_tax_method = $row->tax_method;
                
                $unitData = $this->purchases_model->getUnitById($row->unit);
                $row->unit_lable = $unitData->name;
                $row->base_quantity = 1;
                $row->base_unit = $row->unit;
                $row->unit = $row->purchase_unit ? $row->purchase_unit : $row->unit;
                $row->new_entry = 1;
                $row->qty = 1;
                $row->oqty = 1;
                $row->received = 0;
                $row->real_unit_cost = $row->cost;
                $row->quantity_balance = '';
                $row->discount = '0';
                $row->image = $product->image;
                
                unset($row->details, $row->product_details, $row->price, $row->file, $row->supplier1price, $row->supplier2price, $row->supplier3price, $row->supplier4price, $row->supplier5price, $row->supplier1_part_no, $row->supplier2_part_no, $row->supplier3_part_no, $row->supplier4_part_no, $row->supplier5_part_no);
                
                $units = $this->site->getUnitsByBUID($row->base_unit);
                $tax_rate = $this->site->getTaxRateByID($row->tax_rate);
                
                $row_id = $row->id . $row->option;
                $color = (!empty($options_color)) ? $options_color[0]->name : '';
                $label = $row->name . ' ' . $color . " (" . $row->code . ")";
                
                $c = str_replace(".", "", microtime(true));
                
                // Ensure batchs is an array or false (not null)
                if ($batchoption === false || $batchoption === null) {
                    $batchoption = false;
                }
                
                $item_data = array(
                    'id' => $c,
                    'item_id' => $row_id,
                    'image' => $product->image,
                    'label' => $label,
                    'row' => $row,
                    'tax_rate' => $tax_rate,
                    'units' => $units,
                    'options' => $options ? $options : false,
                    'option_batches' => $productbatches ? $productbatches : false,
                    'batchs' => $batchoption,
                    'primary_variant' => $product->primary_variant,
                    'options_color' => $options_color ? $options_color : false
                );
                
                // Add item to purchase order items array
                $poitems[$row_id] = $item_data;
            }
        }
        
        // ========================================================================
        // STEP 7: VALIDATE AND RETURN RESULTS
        // ========================================================================
        // Business Logic: Ensure we have items to return, otherwise show error
        // Validation: Check if any items were successfully added
        if (empty($poitems)) {
            $this->sma->send_json(array(
                'status' => 'error', 
                'message' => 'No items could be added to the purchase order. Please ensure you have selected valid products with variants.'
            ));
            return;
        }
        
        // ========================================================================
        // STEP 8: RETURN SUCCESS RESPONSE WITH FORMATTED ITEMS
        // ========================================================================
        // Business Logic: Return JSON response with status and formatted items
        // Frontend will store these in localStorage and redirect to PO form
        // Response format: {"status": "success", "items": {...}}
        // Items array structure: {item_id: {id, item_id, image, label, row, tax_rate, units, ...}}
        $this->sma->send_json(array('status' => 'success', 'items' => $poitems));
    }
    ////////////////////////////////////////////////////////////////
    /**
     * Same phone display as customers list: hide system-generated customer numbers.
     *
     * @param string $tableAlias e.g. sma_companies
     * @return string
     */
    private function customerPhoneReportSelect($tableAlias = null) {
        $alias = $tableAlias ? $tableAlias : $this->db->dbprefix('companies');
        if ($this->db->field_exists('is_system_generated', 'companies')) {
            return "CASE WHEN IFNULL({$alias}.is_system_generated, 0) = 1 THEN '' ELSE {$alias}.phone END AS phone";
        }
        return "{$alias}.phone AS phone";
    }
    public function transaction_history() {
