    public function getTransactionHistory() {
        $this->sma->checkPermissions('index', TRUE);
        $this->load->library('datatables');
        
        $this->datatables
            ->select("
                {$this->db->dbprefix('products_transaction_history')}.id as id,
                {$this->db->dbprefix('products_transaction_history')}.action_id as action_id,
                {$this->db->dbprefix('products_transaction_history')}.transaction_date,
                {$this->db->dbprefix('products_transaction_history')}.action,
                {$this->db->dbprefix('products')}.name as product_name,
                {$this->db->dbprefix('product_variants')}.name as variant_name,
                {$this->db->dbprefix('warehouses')}.name as warehouse_name,
                supplier.name as supplier_name,
                biller.name as biller_name,
                customer.name as customer_name,
                {$this->db->dbprefix('products_transaction_history')}.qty_before_transaction,
                {$this->db->dbprefix('products_transaction_history')}.quantity,
                {$this->db->dbprefix('products_transaction_history')}.balance_qty,
                {$this->db->dbprefix('products_transaction_history')}.price,
                {$this->db->dbprefix('products_transaction_history')}.net_price,
                {$this->db->dbprefix('products_transaction_history')}.cost,
                {$this->db->dbprefix('products_transaction_history')}.net_cost,
                {$this->db->dbprefix('products_transaction_history')}.mrp,
                {$this->db->dbprefix('products_transaction_history')}.net_mrp,
                {$this->db->dbprefix('tax_rates')}.name as tax_name,
                {$this->db->dbprefix('products_transaction_history')}.total_tax_amt,
                {$this->db->dbprefix('products_transaction_history')}.total_paid,
                {$this->db->dbprefix('users')}.username as created_by_user
            ")
            ->from('products_transaction_history')
            ->join('products', 'products.id = products_transaction_history.product_id', 'left')
            ->join('product_variants', 'product_variants.id = products_transaction_history.option_id', 'left')
            ->join('warehouses', 'warehouses.id = products_transaction_history.warehouse_id', 'left')
            ->join('companies as supplier', 'supplier.id = products_transaction_history.supplier_id', 'left')
            ->join('companies as biller', 'biller.id = products_transaction_history.biller_id', 'left')
            ->join('companies as customer', 'customer.id = products_transaction_history.customer_id', 'left')
            ->join('tax_rates', 'tax_rates.id = products_transaction_history.tax_rate_id', 'left')
            ->join('users', 'users.id = products_transaction_history.created_by', 'left');
            
        echo $this->datatables->generate();

    }



