                $this->excel->getActiveSheet()->SetCellValue('I2', lang('VAT'));
                $this->excel->getActiveSheet()->SetCellValue('J2', lang('Surcharge'));
                $this->excel->getActiveSheet()->SetCellValue('K2', lang('Total Tax'));
                $this->excel->getActiveSheet()->SetCellValue('L2', lang('Sales Amt'));

                $row = 3;
                $totalBasicAmt = 0;
                $totalcgst = 0;
                $totalsgst = 0;
                $totaligst = 0;
                $totalvat = 0;
                $totalsurcharge = 0;
                $totalgst = 0;
                $totalsales = 0;
                $totalQty = 0;


                foreach ($GSTRate as $data_row) {
                    $this->excel->getActiveSheet()->SetCellValue('A' . $row, $data_row->hsn_code);
                    $this->excel->getActiveSheet()->getStyle('A' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                
                    $this->excel->getActiveSheet()->SetCellValue('B' . $row, $data_row->product_unit_code);
                    $this->excel->getActiveSheet()->getStyle('B' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);
                    
