                    $this->excel->getActiveSheet()->getStyle('C' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                
                    $this->excel->getActiveSheet()->SetCellValue('D' . $row, $data_row->tax_rate);
                    $this->excel->getActiveSheet()->getStyle('D' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);
                
                    $this->excel->getActiveSheet()->SetCellValue('E' . $row, $this->sma->formatMoney($data_row->basic_amount));
                    $this->excel->getActiveSheet()->getStyle('E' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    $this->excel->getActiveSheet()->SetCellValue('F' . $row, $this->sma->formatMoney($data_row->cgst));
                    $this->excel->getActiveSheet()->getStyle('F' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    $this->excel->getActiveSheet()->SetCellValue('G' . $row, $this->sma->formatMoney($data_row->sgst));
                    $this->excel->getActiveSheet()->getStyle('G' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    $this->excel->getActiveSheet()->SetCellValue('H' . $row, $this->sma->formatMoney($data_row->igst));
                    $this->excel->getActiveSheet()->getStyle('H' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $this->excel->getActiveSheet()->SetCellValue('I' . $row, $this->sma->formatMoney($data_row->vat));
                    $this->excel->getActiveSheet()->getStyle('I' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                    $this->excel->getActiveSheet()->SetCellValue('J' . $row, $this->sma->formatMoney($data_row->surcharge));
                    $this->excel->getActiveSheet()->getStyle('J' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    $this->excel->getActiveSheet()->SetCellValue('K' . $row, $this->sma->formatMoney($data_row->total_gst));
                    $this->excel->getActiveSheet()->getStyle('K' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    $this->excel->getActiveSheet()->SetCellValue('L' . $row, $this->sma->formatMoney($data_row->total_sales));
                    $this->excel->getActiveSheet()->getStyle('L' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);
                
                    $totalBasicAmt += $data_row->basic_amount;
                    $totalcgst += $data_row->cgst;
                    $totalsgst += $data_row->sgst;
                    $totaligst += $data_row->igst;
                    $totalvat += $data_row->vat;
                    $totalsurcharge += $data_row->surcharge;
                    $totalgst += $data_row->total_gst;
                    $totalsales += $data_row->total_sales;
                    $totalQty += $data_row->quantity;

                    $row++;
                }
                $lastRow = $row; // This is the row after loop (i.e., total row)
                $borderRange = 'A2:L' . $lastRow;
                $this->excel->getActiveSheet()->getStyle($borderRange)->applyFromArray([
                    'borders' => [
                        'allborders' => [
                            'style' => PHPExcel_Style_Border::BORDER_THIN,
                            'color' => ['rgb' => '000000']
                        ]
                    ]
                ]);
                
                //$this->excel->getActiveSheet()->getStyle("C" . $row . ":H" . $row)->getBorders()->getTop()->setBorderStyle(PHPExcel_Style_Border::BORDER_MEDIUM);
                $this->excel->getActiveSheet()->SetCellValue('B' . $row, "Total");
                $this->excel->getActiveSheet()->getStyle('B' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);

                $this->excel->getActiveSheet()->SetCellValue('C' . $row, ($totalQty));
                $this->excel->getActiveSheet()->getStyle('C' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_CENTER);

                $this->excel->getActiveSheet()->SetCellValue('E' . $row, $this->sma->formatMoney($totalBasicAmt));
                $this->excel->getActiveSheet()->getStyle('E' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->SetCellValue('F' . $row, $this->sma->formatMoney($totalcgst));
                $this->excel->getActiveSheet()->getStyle('F' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->SetCellValue('G' . $row, $this->sma->formatMoney($totalsgst));
                $this->excel->getActiveSheet()->getStyle('G' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->SetCellValue('H' . $row, $this->sma->formatMoney($totaligst));
                $this->excel->getActiveSheet()->getStyle('H' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->SetCellValue('I' . $row, $this->sma->formatMoney($totalvat));
                $this->excel->getActiveSheet()->getStyle('I' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->SetCellValue('J' . $row, $this->sma->formatMoney($totalsurcharge));
                $this->excel->getActiveSheet()->getStyle('J' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->SetCellValue('K' . $row, $this->sma->formatMoney($totalgst));
                $this->excel->getActiveSheet()->getStyle('K' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $this->excel->getActiveSheet()->SetCellValue('L' . $row, $this->sma->formatMoney($totalsales));
                $this->excel->getActiveSheet()->getStyle('L' . $row)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);

                $filename = 'Hsn_Code_Tax_Report';
                $this->excel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);

                if ($pdf) {
                    $styleArray = array('borders' => array('allborders' => array('style' => PHPExcel_Style_Border::BORDER_THIN)));
                    $this->excel->getDefaultStyle()->applyFromArray($styleArray);
                    $this->excel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
                    require_once(APPPATH . "third_party" . DIRECTORY_SEPARATOR . "MPDF" . DIRECTORY_SEPARATOR . "mpdf.php");
                    $rendererName = PHPExcel_Settings::PDF_RENDERER_MPDF;
                    $rendererLibrary = 'MPDF';
                    $rendererLibraryPath = APPPATH . 'third_party' . DIRECTORY_SEPARATOR . $rendererLibrary;
                    if (!PHPExcel_Settings::setPdfRenderer($rendererName, $rendererLibraryPath)) {
                        die('Please set the $rendererName: ' . $rendererName . ' and $rendererLibraryPath: ' . $rendererLibraryPath . ' values' . PHP_EOL . ' as appropriate for your directory structure');
                    }

                    header('Content-Type: application/pdf');
                    header('Content-Disposition: attachment;filename="' . $filename . '.pdf"');
                    header('Cache-Control: max-age=0');

                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'PDF');
                    $objWriter->save('php://output');
                    exit();
                }

                if ($xls) {
                    ob_clean();
                    header('Content-Type: application/vnd.ms-excel');
                    header('Content-Disposition: attachment;filename="' . $filename . '.xls"');
                    header('Cache-Control: max-age=0');
                    ob_clean();
                    $objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');
                    $objWriter->save('php://output');
                    exit();
                }
            }
            $this->session->set_flashdata('error', lang('nothing_found'));
            redirect($_SERVER["HTTP_REFERER"]);
        } else {

            $this->load->library('datatables');
            $this->datatables->select(
                'sma_sale_items.hsn_code as hsn_code,'
            . 'sma_sale_items.product_unit_code as product_unit_code,'
            . 'ROUND(SUM(sma_sale_items.quantity), 0) as quantity,'
            . 'COALESCE('
            . '    (SELECT tr.name FROM sma_tax_rates tr'
            . '     WHERE tr.rate = (CASE WHEN sit.has_vat > 0 THEN sit.vat_rate ELSE sma_sale_items.tax END)'
            . '       AND ((sit.has_vat > 0 AND tr.name LIKE \'%VAT%\')'
            . '            OR (COALESCE(sit.has_vat, 0) = 0 AND tr.name LIKE \'%GST%\'))'
            . '     LIMIT 1),'
            . '    CONCAT(ROUND(CASE WHEN sit.has_vat > 0 THEN sit.vat_rate ELSE sma_sale_items.tax END, 2), \'%\', IF(sit.has_vat > 0, \'VAT\', \'GST\'))'
            . ') as tax_rate,'
            . 'SUM(sma_sale_items.invoice_unit_price * sma_sale_items.quantity) as basic_amount,'
            . 'SUM(CASE WHEN sit.has_vat > 0 THEN 0 ELSE COALESCE(sit.raw_cgst, sma_sale_items.cgst) END) as cgst,'
            . 'SUM(CASE WHEN sit.has_vat > 0 THEN 0 ELSE COALESCE(sit.raw_sgst, sma_sale_items.sgst) END) as sgst,'
            . 'SUM(CASE WHEN sit.has_vat > 0 THEN 0 ELSE COALESCE(sit.raw_igst, sma_sale_items.igst) END) as igst,'
            . 'SUM(COALESCE(sit.vat, 0)) as vat,'
            . 'SUM(COALESCE(sit.surcharge, 0)) as surcharge,'
            . 'SUM(
                (CASE WHEN sit.has_vat > 0 THEN 0 ELSE COALESCE(sit.raw_cgst, sma_sale_items.cgst) END) +
                (CASE WHEN sit.has_vat > 0 THEN 0 ELSE COALESCE(sit.raw_sgst, sma_sale_items.sgst) END) +
                (CASE WHEN sit.has_vat > 0 THEN 0 ELSE COALESCE(sit.raw_igst, sma_sale_items.igst) END) +
                COALESCE(sit.vat, 0) +
                COALESCE(sit.surcharge, 0)
              ) as total_gst,'
            . 'SUM(
                (sma_sale_items.invoice_unit_price * sma_sale_items.quantity) +
                (CASE WHEN sit.has_vat > 0 THEN 0 ELSE COALESCE(sit.raw_cgst, sma_sale_items.cgst) END) +
                (CASE WHEN sit.has_vat > 0 THEN 0 ELSE COALESCE(sit.raw_sgst, sma_sale_items.sgst) END) +
                (CASE WHEN sit.has_vat > 0 THEN 0 ELSE COALESCE(sit.raw_igst, sma_sale_items.igst) END) +
                COALESCE(sit.vat, 0) +
                COALESCE(sit.surcharge, 0)
              ) as total_sales'
            );
        
            $this->datatables->from('sma_sale_items');
            $this->datatables->join('(
                SELECT 
                    item_id,
                    SUM(CASE WHEN attr_code = \'CGST\' THEN tax_amount ELSE 0 END) as raw_cgst,
                    SUM(CASE WHEN attr_code = \'SGST\' THEN tax_amount ELSE 0 END) as raw_sgst,
                    SUM(CASE WHEN attr_code = \'IGST\' THEN tax_amount ELSE 0 END) as raw_igst,
                    SUM(CASE WHEN attr_code NOT IN (\'CGST\', \'SGST\', \'IGST\') THEN tax_amount ELSE 0 END) as vat,
                    MAX(CASE WHEN attr_code NOT IN (\'CGST\', \'SGST\', \'IGST\') THEN attr_per ELSE 0 END) as vat_rate,
                    SUM(surcharge) as surcharge,
                    SUM(CASE WHEN attr_code NOT IN (\'CGST\', \'SGST\', \'IGST\') THEN 1 ELSE 0 END) as has_vat
                FROM sma_sales_items_tax
                GROUP BY item_id
            ) sit', 'sit.item_id = sma_sale_items.id', 'left');
            $this->datatables->where('sma_sale_items.hsn_code != " "');
        
            if (isset($start_date) && isset($end_date)) {
                $this->datatables->join('sma_sales', 'sma_sales.id = sma_sale_items.sale_id');
                $this->db->where('DATE(' . $this->db->dbprefix('sales') . '.date) BETWEEN "' . $start_date . '" AND "' . $end_date . '"');
            }
        
            $this->datatables->group_by([
                'sma_sale_items.hsn_code',
                'ROUND(CASE WHEN sit.has_vat > 0 THEN sit.vat_rate ELSE sma_sale_items.tax END, 2)',
                'sma_sale_items.product_unit_code'
            ]);
        
            echo $this->datatables->generate();
        }
    }

